INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f5c711f-ebf4-4e7c-add1-3702325489c3', '冬至後過吳張二子檀溪別業', '冬至後過吳張二子檀溪別業', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["卜築因自然，檀溪不更穿。","園廬二友接，水竹數家連。","直與南山對，非關選地偏。","草堂時偃曝，蘭枻日周旋。","外事情都遠，中流性所便。","閑垂太公釣，興發子猷船。","余亦幽棲者，經過竊慕焉。","梅花殘臘月，柳色半春天。","鳥泊隨陽雁，魚藏縮項鯿。","停杯問山簡，何似習池邊。"]', '["卜築因自然，檀溪不更穿。","园廬二友接，水竹數家連。","直與南山对，非关選地偏。","草堂时偃曝，蘭枻日周旋。","外事情都远，中流性所便。","闲垂太公釣，兴發子猷船。","余亦幽棲者，經過竊慕焉。","梅花殘臘月，柳色半春天。","鸟泊隨陽雁，鱼藏縮項鯿。","停杯问山簡，何似習池邊。"]', '诗', 'shi', '', NULL, '冬至後過吳張二子檀溪別業 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b73bc857-289d-4b8a-b1f4-f49b51eaae23', '韓大使東齋會岳上人諸學士', '韓大使东斋會岳上人諸学士', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["郡守虛陳榻，林間召楚材。","山川祈雨畢，雲物喜晴開。","抗禮尊縫掖，臨流揖渡杯。","徒攀朱仲李，誰薦和羹梅。","翰墨緣情製，高深以意裁。","滄洲趣不遠，何必問蓬萊。"]', '["郡守虛陳榻，林间召楚材。","山川祈雨畢，云物喜晴开。","抗禮尊縫掖，臨流揖渡杯。","徒攀朱仲李，誰薦和羹梅。","翰墨緣情製，高深以意裁。","滄洲趣不远，何必问蓬萊。"]', '诗', 'shi', '', NULL, '韓大使東齋會岳上人諸學士 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56d4bead-dc1a-46d3-a927-219029cce60f', '上巳日澗南園期王山人陳七諸公不至', '上巳日澗南园期王山人陳七諸公不至', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["搖艇候明發，花源弄晚春。","在山懷綺季，臨漢憶荀陳。","上巳期三月，浮杯興十旬。","坐歌空有待，行樂恨無鄰。","日晚蘭亭北，煙開曲水濱。","浴蠶逢姹女，采艾值幽人。","石壁堪題序，沙場好解紳。","羣公望不至，虛擲此芳晨。"]', '["搖艇候明發，花源弄晚春。","在山懷綺季，臨漢憶荀陳。","上巳期三月，浮杯兴十旬。","坐歌空有待，行乐恨無鄰。","日晚蘭亭北，煙开曲水濱。","浴蠶逢姹女，采艾值幽人。","石壁堪題序，沙場好解紳。","羣公望不至，虛擲此芳晨。"]', '诗', 'shi', '', NULL, '上巳日澗南園期王山人陳七諸公不至 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1a361f1-4112-403d-a52d-e3331caa52b0', '齒坐呈山南諸隱', '齒坐呈山南諸隐', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["習公有遺坐，高在白雲陲。","樵子不見識，山僧賞自知。","以余爲好事，攜手一來窺。","竹露閑夜滴，松風清晝吹。","從來抱微尚，況復感前規。","於此無奇策，蒼生奚以爲。"]', '["習公有遺坐，高在白云陲。","樵子不见識，山僧賞自知。","以余爲好事，携手一来窺。","竹露闲夜滴，松风清晝吹。","從来抱微尚，況复感前規。","於此無奇策，蒼生奚以爲。"]', '诗', 'shi', '', NULL, '齒坐呈山南諸隱 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab7dc33f-eee5-4a87-961f-1e1606cf7549', '來闍黎新亭作', '来闍黎新亭作', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["八解禪林秀，三明給苑才。","地偏香界遠，心淨水亭開。","傍險山查立，尋幽石逕回。","瑞花長自下，靈藥豈須栽。","碧網交紅樹，清泉盡綠苔。","戲魚聞法聚，閑鳥誦經來。","棄象玄應悟，忘言理必該。","靜中何所得，吟詠也徒哉。"]', '["八解禪林秀，三明給苑才。","地偏香界远，心淨水亭开。","傍險山查立，尋幽石逕回。","瑞花长自下，靈藥豈須栽。","碧網交紅樹，清泉尽綠苔。","戲鱼闻法聚，闲鸟誦經来。","棄象玄應悟，忘言理必該。","静中何所得，吟詠也徒哉。"]', '诗', 'shi', '', NULL, '來闍黎新亭作 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14f2da14-aaf6-41e0-8f4e-6252eeb6043d', '西山尋辛諤', '西山尋辛諤', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["漾舟尋水便，因訪故人居。","落日清川裏，誰言獨羨魚。","石潭窺洞徹，沙岸歷紆徐。","竹嶼見垂釣，茅齋聞讀書。","款言忘景夕，清興屬涼初。","回也一瓢飲，賢哉常晏如。"]', '["漾舟尋水便，因訪故人居。","落日清川裏，誰言独羨鱼。","石潭窺洞徹，沙岸歷紆徐。","竹嶼见垂釣，茅斋闻读书。","款言忘景夕，清兴屬涼初。","回也一瓢饮，賢哉常晏如。"]', '诗', 'shi', '', NULL, '西山尋辛諤 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e5d7a31-e3ec-495d-a383-33bc585b976f', '題長安主人壁', '題长安主人壁', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["久廢南山田，叨陪東閣賢。","欲隨平子去，猶未獻甘泉。","枕籍琴書滿，褰帷遠岫連。","我來如昨日，庭樹忽鳴蟬。","促織驚寒女，秋風感長年。","授衣當九月，無褐竟誰憐。"]', '["久廢南山田，叨陪东閣賢。","欲隨平子去，猶未獻甘泉。","枕籍琴书满，褰帷远岫連。","我来如昨日，庭樹忽鳴蟬。","促织驚寒女，秋风感长年。","授衣當九月，無褐竟誰怜。"]', '诗', 'shi', '', NULL, '題長安主人壁 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c01f9163-b9a6-4673-962c-80aac7ede94e', '行出東山望漢川', '行出东山望漢川', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["異縣非吾土，連山盡綠篁。","平田出郭少，盤坂入雲長。","萬壑歸於漢，千峰劃彼蒼。","猿聲亂楚峽，人語帶巴鄉。","石上攢椒樹，藤間綴蜜房。","雪餘春未煖，嵐解晝初陽。","征馬疲登頓，歸帆愛渺茫。","坐欣沿溜下，信宿見維桑。"]', '["異縣非吾土，連山尽綠篁。","平田出郭少，盤坂入云长。","万壑归於漢，千峰劃彼蒼。","猿声亂楚峽，人語带巴乡。","石上攢椒樹，藤间綴蜜房。","雪餘春未煖，嵐解晝初陽。","征马疲登頓，归帆愛渺茫。","坐欣沿溜下，信宿见維桑。"]', '诗', 'shi', '', NULL, '行出東山望漢川 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a39cd422-7092-479b-9131-7fcb40531622', '夜泊宣城界', '夜泊宣城界', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["西塞沿江島，南陵問驛樓。","湖平津濟闊，風止客帆收。","去去懷前浦，茫茫泛夕流。","石逢羅剎礙，山泊敬亭幽。","火識梅根冶，煙迷楊葉洲。","離家復水宿，相伴賴沙鷗。"]', '["西塞沿江島，南陵问驛楼。","湖平津濟闊，风止客帆收。","去去懷前浦，茫茫泛夕流。","石逢羅剎礙，山泊敬亭幽。","火識梅根冶，煙迷楊葉洲。","離家复水宿，相伴賴沙鷗。"]', '诗', 'shi', '', NULL, '夜泊宣城界 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8f6bc70-e056-460f-9ad3-f0b53f20f1fe', '下灨石', '下灨石', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["灨石三百里，沿洄千嶂間。","沸聲常活活，洊勢亦潺潺。","跳沫魚龍沸，垂藤猿狖攀。","榜人苦奔峭，而我忘險難。","放溜情彌愜，登艫目自閑。","暝帆何處宿，遙指落星灣。"]', '["灨石三百里，沿洄千嶂间。","沸声常活活，洊勢亦潺潺。","跳沫鱼龙沸，垂藤猿狖攀。","榜人苦奔峭，而我忘險难。","放溜情彌愜，登艫目自闲。","暝帆何处宿，遙指落星灣。"]', '诗', 'shi', '', NULL, '下灨石 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b18a462a-cc8a-4e4e-924d-7c4752ca1c73', '初年樂城館中臥疾懷歸作', '初年乐城館中臥疾懷归作', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["異縣天隅僻，孤帆海畔過。","往來鄉信斷，留滯客情多。","臘月聞雷震，東風感歲和。","蟄蟲驚戶穴，巢鵲眄庭柯。","徒對芳尊酒，其如伏枕何。","歸嶼理舟楫，江海正無波。"]', '["異縣天隅僻，孤帆海畔過。","往来乡信斷，留滯客情多。","臘月闻雷震，东风感歲和。","蟄蟲驚戶穴，巢鵲眄庭柯。","徒对芳尊酒，其如伏枕何。","归嶼理舟楫，江海正無波。"]', '诗', 'shi', '', NULL, '初年樂城館中臥疾懷歸作 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5461fb74-6384-4ca7-a500-5e5995c78515', '醉後贈馬四', '醉後贈马四', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["四海重然諾，吾嘗聞白眉。","秦城遊俠客，相得半酣時。"]', '["四海重然諾，吾嘗闻白眉。","秦城游俠客，相得半酣时。"]', '诗', 'shi', '', NULL, '醉後贈馬四 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('950b73a7-fe4b-4602-8464-1879af1808c0', '贈王九', '贈王九', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["日暮田家遠，山中勿久淹。","歸人須早去，稚子望陶潛。"]', '["日暮田家远，山中勿久淹。","归人須早去，稚子望陶潛。"]', '诗', 'shi', '', NULL, '贈王九 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc934d30-29bf-4462-ba32-38021191e2fd', '登峴山亭寄晉陵張少府', '登峴山亭寄晉陵張少府', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["峴首風湍急，雲帆若鳥飛。","憑軒試一問，張翰欲來歸。"]', '["峴首风湍急，云帆若鸟飞。","憑軒試一问，張翰欲来归。"]', '诗', 'shi', '', NULL, '登峴山亭寄晉陵張少府 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9377b2a8-066c-4fc7-8f1f-2a04bffa75b9', '送朱大入秦', '送朱大入秦', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["遊人武陵去，寶劒直千金。","分手脫相贈，平生一片心。"]', '["游人武陵去，寶劒直千金。","分手脫相贈，平生一片心。"]', '诗', 'shi', '', NULL, '送朱大入秦 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7947239-6143-493d-8fc9-d2512a70151d', '送友人之京', '送友人之京', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["君登青雲去，予望青山歸。","雲山從此別，淚濕薜蘿衣。"]', '["君登青云去，予望青山归。","云山從此別，泪濕薜蘿衣。"]', '诗', 'shi', '', NULL, '送友人之京 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('771d396c-e668-4b45-ac81-74b9b7dc4ad4', '送張郎中遷京', '送張郎中遷京', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["碧溪常共賞，朱邸忽遷榮。","豫有相思意，聞君琴上聲。"]', '["碧溪常共賞，朱邸忽遷榮。","豫有相思意，闻君琴上声。"]', '诗', 'shi', '', NULL, '送張郎中遷京 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c17cf6be-bfee-4fef-8357-aa8090f62ddd', '同張將薊門觀燈', '同張將薊门观灯', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["異俗非鄉俗，新年改故年。","薊門看火樹，疑是燭龍然。"]', '["異俗非乡俗，新年改故年。","薊门看火樹，疑是燭龙然。"]', '诗', 'shi', '', NULL, '同張將薊門觀燈 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d50e6d9c-f94f-46e5-95e3-24e745f58681', '張郎中梅園中', '張郎中梅园中', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["綺席鋪蘭杜，珠盤折芰荷。","故園留不住，應是戀絃歌。"]', '["綺席鋪蘭杜，珠盤折芰荷。","故园留不住，應是戀絃歌。"]', '诗', 'shi', '', NULL, '張郎中梅園中 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7aad8ae-2aec-488d-810a-788fba40d1f1', '北澗泛舟', '北澗泛舟', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["北澗流恆滿，浮舟觸處通。","沿洄自有趣，何必五湖中。"]', '["北澗流恆满，浮舟觸处通。","沿洄自有趣，何必五湖中。"]', '诗', 'shi', '', NULL, '北澗泛舟 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb168b3b-d104-4df7-9868-1e1225ddb941', '春曉', '春晓', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["春眠不覺曉，處處聞啼鳥。","夜來風雨聲，花落知多少。"]', '["春眠不覺晓，处处闻啼鸟。","夜来风雨声，花落知多少。"]', '诗', 'shi', '', NULL, '春曉 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a84fa6e-4dd0-4e4e-a236-a159949b27ca', '洛中訪袁拾遺不遇', '洛中訪袁拾遺不遇', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["洛陽訪才子，江嶺作流人。","聞說梅花早，何如北地春。"]', '["洛陽訪才子，江嶺作流人。","闻说梅花早，何如北地春。"]', '诗', 'shi', '', NULL, '洛中訪袁拾遺不遇 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05214923-ffd7-46bf-8d9a-184baed55542', '尋菊花潭主人不遇', '尋菊花潭主人不遇', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["行至菊花潭，村西日已斜。","主人登高去，雞犬空在家。"]', '["行至菊花潭，村西日已斜。","主人登高去，雞犬空在家。"]', '诗', 'shi', '', NULL, '尋菊花潭主人不遇 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c385476-c68a-4ba6-8c8d-ae240d544d6e', '檀溪尋故人', '檀溪尋故人', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["花伴成龍竹，池分躍馬溪。","田園人不見，疑向洞中棲。"]', '["花伴成龙竹，池分躍马溪。","田园人不见，疑向洞中棲。"]', '诗', 'shi', '', NULL, '檀溪尋故人 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a1025ff-9245-4515-89e8-6383d60fd8c1', '揚子津望京口', '揚子津望京口', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["北固臨京口，夷山近海濱。","江風白浪起，愁殺渡頭人。"]', '["北固臨京口，夷山近海濱。","江风白浪起，愁殺渡头人。"]', '诗', 'shi', '', NULL, '揚子津望京口 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80d1c689-314f-4fa0-86a6-20aca2182425', '同儲十二洛陽道中作', '同儲十二洛陽道中作', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["珠彈繁華子，金羈遊俠人。","酒酣白日暮，走馬入紅塵。"]', '["珠彈繁华子，金羈游俠人。","酒酣白日暮，走马入紅塵。"]', '诗', 'shi', '', NULL, '同儲十二洛陽道中作 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6632feca-d12b-48d4-b90f-5274c1fecaff', '初下浙江舟中口號', '初下浙江舟中口號', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["八月觀潮罷，三江越海潯。","回瞻魏闕路，空復子牟心。"]', '["八月观潮罷，三江越海潯。","回瞻魏闕路，空复子牟心。"]', '诗', 'shi', '', NULL, '初下浙江舟中口號 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bed9b02-991e-4e28-b631-86640147a712', '宿建德江', '宿建德江', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["移舟泊煙渚，日暮客愁新。","野曠天低樹，江清月近人。"]', '["移舟泊煙渚，日暮客愁新。","野曠天低樹，江清月近人。"]', '诗', 'shi', '', NULL, '宿建德江 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebb3d970-b5b1-4891-bc8d-fe0088ca52b1', '問舟子', '问舟子', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["向夕問舟子，前程復幾多。","灣頭正堪泊，淮裏足風波。"]', '["向夕问舟子，前程复幾多。","灣头正堪泊，淮裏足风波。"]', '诗', 'shi', '', NULL, '問舟子 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64a2c649-a3cf-4553-8d46-679cb69c3acf', '戲題', '戲題', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["客醉眠未起，主人呼解酲。","已言雞黍熟，復道甕頭清。"]', '["客醉眠未起，主人呼解酲。","已言雞黍熟，复道甕头清。"]', '诗', 'shi', '', NULL, '戲題 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5346afe3-87f7-42fe-ac8c-894c2f4bdd20', '涼州詞 一', '涼州词 一', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["渾成紫檀金屑文，作得琵琶聲入雲。","胡地迢迢三萬里，那堪馬上送明君。"]', '["渾成紫檀金屑文，作得琵琶声入云。","胡地迢迢三万里，那堪马上送明君。"]', '诗', 'shi', '', NULL, '涼州詞 一 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e41ffa4-7782-43d7-986a-6feacb837dae', '涼州詞 二', '涼州词 二', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["異方之樂令人悲，羌笛胡笳不用吹。","坐看今夜關山月，思殺邊城游俠兒。"]', '["異方之乐令人悲，羌笛胡笳不用吹。","坐看今夜关山月，思殺邊城游俠兒。"]', '诗', 'shi', '', NULL, '涼州詞 二 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba5d5923-d1ff-4b93-879a-55944d3b1489', '送新安張少府歸秦中', '送新安張少府归秦中', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["試登秦嶺望秦川，遙憶青門春可憐。","仲月送君從此去，瓜時須及邵平田。"]', '["試登秦嶺望秦川，遙憶青门春可怜。","仲月送君從此去，瓜时須及邵平田。"]', '诗', 'shi', '', NULL, '送新安張少府歸秦中 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fe885f2-1527-4702-8696-86d3b452022a', '送杜十四之江南', '送杜十四之江南', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["荆吳相接水爲鄉，君去春江正淼茫。","日暮征帆何處泊，天涯一望斷人腸。"]', '["荆吳相接水爲乡，君去春江正淼茫。","日暮征帆何处泊，天涯一望斷人腸。"]', '诗', 'shi', '', NULL, '送杜十四之江南 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f0628cb-dfea-492b-b3a0-e81b609699b1', '渡浙江問舟中人', '渡浙江问舟中人', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["潮落江平未有風，扁舟共濟與君同。","時時引領望天末，何處青山是越中。"]', '["潮落江平未有风，扁舟共濟與君同。","时时引領望天末，何处青山是越中。"]', '诗', 'shi', '', NULL, '渡浙江問舟中人 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b598d5c-f1c6-40d0-9780-9dee106fa04c', '初秋', '初秋', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["不覺初秋夜漸長，清風習習重淒涼。","炎炎暑退茅齋靜，堦下叢莎有露光。"]', '["不覺初秋夜漸长，清风習習重淒涼。","炎炎暑退茅斋静，堦下叢莎有露光。"]', '诗', 'shi', '', NULL, '初秋 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bcc1566-337f-4c07-8de1-ffa9beb74b63', '過融上人蘭若', '過融上人蘭若', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["山頭禪室挂僧衣，窗外無人水鳥飛。","黃昏半在下山路，却聽泉聲戀翠微。"]', '["山头禪室挂僧衣，窗外無人水鸟飞。","黄昏半在下山路，却听泉声戀翠微。"]', '诗', 'shi', '', NULL, '過融上人蘭若 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7da0fb7-2297-4d2d-8b2f-57ec832449ea', '句', '句', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["微雲淡河漢，疎雨滴梧桐。","逐逐懷良馭，蕭蕭顧樂鳴。"]', '["微云淡河漢，疎雨滴梧桐。","逐逐懷良馭，蕭蕭顧乐鳴。"]', '诗', 'shi', '', NULL, '句 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cb1e0d4-689a-4519-9ee2-68d8bd8c7c74', '古風 一', '古风 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["大雅久不作，吾衰竟誰陳。","王風委蔓草，戰國多荆榛。","龍虎相啖食，兵戈逮狂秦。","正聲何微茫，哀怨起騷人。","揚馬激頹波，開流蕩無垠。","廢興雖萬變，憲章亦已淪。","自從建安來，綺麗不足珍。","聖代復元古，垂衣貴清真。","羣才屬休明，乘運共躍鱗。","文質相炳煥，衆星羅秋旻。","我志在刪述，垂輝暎千春。","希聖如有立，絕筆於獲麟。"]', '["大雅久不作，吾衰竟誰陳。","王风委蔓草，戰国多荆榛。","龙虎相啖食，兵戈逮狂秦。","正声何微茫，哀怨起騷人。","揚马激頹波，开流蕩無垠。","廢兴雖万变，憲章亦已淪。","自從建安来，綺丽不足珍。","聖代复元古，垂衣貴清真。","羣才屬休明，乘運共躍鱗。","文質相炳煥，衆星羅秋旻。","我志在刪述，垂輝暎千春。","希聖如有立，絕笔於獲麟。"]', '诗', 'shi', '', NULL, '古風 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52d3ace3-2199-48f3-9128-0559fcbeb1cb', '古風 二', '古风 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["蟾蜍薄太清，蝕此瑤臺月。","圓光虧中天，金魄遂淪沒。","螮蝀入紫微，大明夷朝暉。","浮雲隔兩曜，萬象昏陰霏。","蕭蕭長門宮，昔是今已非。","桂蠹花不實，天霜下嚴威。","沈歎終永夕，感我涕沾衣。"]', '["蟾蜍薄太清，蝕此瑤台月。","圓光虧中天，金魄遂淪沒。","螮蝀入紫微，大明夷朝暉。","浮云隔兩曜，万象昏陰霏。","蕭蕭长门宮，昔是今已非。","桂蠹花不實，天霜下嚴威。","沈歎終永夕，感我涕沾衣。"]', '诗', 'shi', '', NULL, '古風 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00e799f2-e320-4a2c-8690-531df44c0abc', '古風 三', '古风 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秦皇掃六合，虎視何雄哉。","飛劒決浮雲，諸侯盡西來。","明斷自天啓，大略駕羣才。","收兵鑄金人，函谷正東開。","銘功會稽嶺，騁望瑯琊臺。","刑徒七十萬，起土驪山隈。","尚採不死藥，茫然使心哀。","連弩射海魚，長鯨正崔嵬。","額鼻象五嶽，揚波噴雲雷。","鬐鬣蔽青天，何由覩蓬萊。","徐[巿]載秦女，樓船幾時迥。","但見三泉下，金棺葬寒灰。"]', '["秦皇掃六合，虎視何雄哉。","飞劒決浮云，諸侯尽西来。","明斷自天啓，大略駕羣才。","收兵鑄金人，函谷正东开。","銘功會稽嶺，騁望瑯琊台。","刑徒七十万，起土驪山隈。","尚採不死藥，茫然使心哀。","連弩射海鱼，长鯨正崔嵬。","額鼻象五嶽，揚波噴云雷。","鬐鬣蔽青天，何由覩蓬萊。","徐[巿]載秦女，楼船幾时迥。","但见三泉下，金棺葬寒灰。"]', '诗', 'shi', '', NULL, '古風 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ea59ee7-8464-4981-82f6-f386332a2c4f', '古風 四', '古风 四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["鳳飛九千仞，五章備綵珍。","銜書且虛歸，空入周與秦。","橫絕歷四海，所居未得鄰。","吾營紫河車，千載落風塵。","藥物秘海嶽，採鉛青溪濱。","時登大樓山，舉手望仙真。","羽駕滅去影，飆車絕廻輪。","尚恐丹液遲，志願不及申。","徒霜鏡中髮，羞彼鶴上人。","桃李何處開，此花非我春。","唯應清都境，長與韓衆親。"]', '["鳳飞九千仞，五章備綵珍。","銜书且虛归，空入周與秦。","橫絕歷四海，所居未得鄰。","吾營紫河车，千載落风塵。","藥物秘海嶽，採鉛青溪濱。","时登大楼山，舉手望仙真。","羽駕滅去影，飆车絕廻輪。","尚恐丹液遲，志願不及申。","徒霜镜中髮，羞彼鹤上人。","桃李何处开，此花非我春。","唯應清都境，长與韓衆親。"]', '诗', 'shi', '', NULL, '古風 四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae666bb8-1da4-4673-a01e-c8235e7426e4', '古風 五', '古风 五', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["太白何蒼蒼，星辰上森列。","去天三百里，邈爾與世絕。","中有綠髮翁，披雲臥松雪。","不笑亦不語，冥棲在巖穴。","我來逢真人，長跪問寶訣。","粲然啓玉齒，授以鍊藥說。","銘骨傳其語，竦身已電滅。","仰望不可及，蒼然五情熱。","吾將營丹砂，永與世人別。"]', '["太白何蒼蒼，星辰上森列。","去天三百里，邈爾與世絕。","中有綠髮翁，披云臥松雪。","不笑亦不語，冥棲在巖穴。","我来逢真人，长跪问寶訣。","粲然啓玉齒，授以鍊藥说。","銘骨傳其語，竦身已電滅。","仰望不可及，蒼然五情熱。","吾將營丹砂，永與世人別。"]', '诗', 'shi', '', NULL, '古風 五 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a1189e1-3d49-4791-be62-c9574912a279', '古風 六', '古风 六', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["代馬不思越，越禽不戀燕。","情性有所習，土風固其然。","昔別雁門關，今戍龍庭前。","驚沙亂海日，飛雪迷胡天。","蟣蝨生虎鶡，心魂逐旌旃。","苦戰功不賞，忠誠難可宣。","誰憐李飛將，白首沒三邊。"]', '["代马不思越，越禽不戀燕。","情性有所習，土风固其然。","昔別雁门关，今戍龙庭前。","驚沙亂海日，飞雪迷胡天。","蟣蝨生虎鶡，心魂逐旌旃。","苦戰功不賞，忠誠难可宣。","誰怜李飞將，白首沒三邊。"]', '诗', 'shi', '', NULL, '古風 六 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d1f40c7-9d1a-47f6-bb72-e5c31280c6be', '古風 七', '古风 七', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["五鶴西北來，飛飛凌太清。","仙人綠雲上，自道安期名。","兩兩白玉童，雙吹紫鸞笙。","去影忽不見，回風送天聲。","我欲一問之，飄然若流星。","願餐金光草，壽與天齊傾。"]', '["五鹤西北来，飞飞凌太清。","仙人綠云上，自道安期名。","兩兩白玉童，雙吹紫鸾笙。","去影忽不见，回风送天声。","我欲一问之，飄然若流星。","願餐金光草，壽與天齊傾。"]', '诗', 'shi', '', NULL, '古風 七 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('116a9706-0eca-4e95-aaf7-0abfa3c4554e', '古風 八', '古风 八', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["咸陽二三月，宮柳黃金枝。","綠幘誰家子，賣珠輕薄兒。","日暮醉酒歸，白馬驕且馳。","意氣人所仰，冶遊方及時。","子雲不曉事，晚獻長楊辭。","賦達身已老，草玄鬢若絲。","投閣良可歎，但爲此輩嗤。"]', '["咸陽二三月，宮柳黄金枝。","綠幘誰家子，賣珠轻薄兒。","日暮醉酒归，白马驕且驰。","意氣人所仰，冶游方及时。","子云不晓事，晚獻长楊辞。","賦達身已老，草玄鬢若絲。","投閣良可歎，但爲此輩嗤。"]', '诗', 'shi', '', NULL, '古風 八 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a1b3412-39ba-432d-bc88-064b88d8aa24', '古風 九', '古风 九', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["莊周夢胡蝶，胡蝶爲莊周。","一體更變易，萬事良悠悠。","乃知蓬萊水，復作清淺流。","青門種瓜人，舊日東陵侯。","富貴故如此，營營何所求。"]', '["莊周梦胡蝶，胡蝶爲莊周。","一體更变易，万事良悠悠。","乃知蓬萊水，复作清淺流。","青门種瓜人，旧日东陵侯。","富貴故如此，營營何所求。"]', '诗', 'shi', '', NULL, '古風 九 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('116561a6-8e41-4ccf-8be4-4507065f8c8d', '古風 十', '古风 十', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["齊有倜儻生，魯連特高妙。","明月出海底，一朝開光曜。","却秦振英聲，後世仰末照。","意輕千金贈，願向平原笑。","吾亦澹蕩人，拂衣可同調。"]', '["齊有倜儻生，魯連特高妙。","明月出海底，一朝开光曜。","却秦振英声，後世仰末照。","意轻千金贈，願向平原笑。","吾亦澹蕩人，拂衣可同調。"]', '诗', 'shi', '', NULL, '古風 十 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd3a2a44-d25c-4ce7-ac54-5c84a4bbbb81', '古風 十一', '古风 十一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["黃河走東溟，白日落西海。","逝川與流光，飄忽不相待。","春容捨我去，秋髮已衰改。","人生非寒松，年貌豈長在。","吾當乘雲螭，吸景駐光彩。"]', '["黄河走东溟，白日落西海。","逝川與流光，飄忽不相待。","春容捨我去，秋髮已衰改。","人生非寒松，年貌豈长在。","吾當乘云螭，吸景駐光彩。"]', '诗', 'shi', '', NULL, '古風 十一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06ed6495-bdfd-4667-98ea-6203d2251861', '古風 十二', '古风 十二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["松柏本孤直，難爲桃李顏。","昭昭嚴子陵，垂釣滄波間。","身將客星隱，心與浮雲閑。","長揖萬乘君，還歸富春山。","清風灑六合，邈然不可攀。","使我長歎息，冥棲巖石間。"]', '["松柏本孤直，难爲桃李顏。","昭昭嚴子陵，垂釣滄波间。","身將客星隐，心與浮云闲。","长揖万乘君，還归富春山。","清风灑六合，邈然不可攀。","使我长歎息，冥棲巖石间。"]', '诗', 'shi', '', NULL, '古風 十二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39486f9c-ca2e-4aba-a236-c59eb74046b1', '古風 十三', '古风 十三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["君平既棄世，世亦棄君平。","觀變窮太易，探元化羣生。","寂寞綴道論，空簾閉幽情。","騶虞不虛來，鸑鷟有時鳴。","安知天漢上，白日懸高名。","海客去已久，誰人測沈冥。"]', '["君平既棄世，世亦棄君平。","观变窮太易，探元化羣生。","寂寞綴道論，空簾閉幽情。","騶虞不虛来，鸑鷟有时鳴。","安知天漢上，白日懸高名。","海客去已久，誰人測沈冥。"]', '诗', 'shi', '', NULL, '古風 十三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f26bce2d-b068-460a-b58b-b045e2e25f7d', '古風 十四', '古风 十四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["胡關饒風沙，蕭索竟終古。","木落秋草黃，登高望戎虜。","荒城空大漠，邊邑無遺堵。","白骨橫千霜，嵯峨蔽榛莽。","借問誰凌虐，天驕毒威武。","赫怒我聖皇，勞師事鼙鼓。","陽和變殺氣，發卒騷中土。","三十六萬人，哀哀淚如雨。","且悲就行役，安得營農圃。","不見征戍兒，豈知關山苦。","李牧今不在，邊人飼豺虎。"]', '["胡关饒风沙，蕭索竟終古。","木落秋草黄，登高望戎虜。","荒城空大漠，邊邑無遺堵。","白骨橫千霜，嵯峨蔽榛莽。","借问誰凌虐，天驕毒威武。","赫怒我聖皇，勞師事鼙鼓。","陽和变殺氣，發卒騷中土。","三十六万人，哀哀泪如雨。","且悲就行役，安得營農圃。","不见征戍兒，豈知关山苦。","李牧今不在，邊人飼豺虎。"]', '诗', 'shi', '', NULL, '古風 十四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd45a2ec-aa2b-40ee-9c8a-b55af89629b8', '古風 十五', '古风 十五', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["燕昭延郭隗，遂築黃金臺。","劇辛方趙至，鄒衍復齊來。","奈何青雲士，棄我如塵埃。","珠玉買歌笑，糟糠養賢才。","方知黃鶴舉，千里獨裴回。"]', '["燕昭延郭隗，遂築黄金台。","劇辛方趙至，鄒衍复齊来。","奈何青云士，棄我如塵埃。","珠玉買歌笑，糟糠養賢才。","方知黄鹤舉，千里独裴回。"]', '诗', 'shi', '', NULL, '古風 十五 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0127020e-6c3e-4d06-a7a9-4926ed666a52', '古風 十六', '古风 十六', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["寶劒雙蛟龍，雪花照芙蓉。","精光射天地，雷騰不可衝。","一去別金匣，飛沈失相從。","風胡滅已久，所以潛其鋒。","吳水深萬丈，楚山邈千重。","雌雄終不隔，神物會當逢。"]', '["寶劒雙蛟龙，雪花照芙蓉。","精光射天地，雷腾不可衝。","一去別金匣，飞沈失相從。","风胡滅已久，所以潛其鋒。","吳水深万丈，楚山邈千重。","雌雄終不隔，神物會當逢。"]', '诗', 'shi', '', NULL, '古風 十六 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0052b26a-5f10-4ef0-a98b-09ae1b20a212', '古風 十七', '古风 十七', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["金華牧羊兒，乃是紫煙客。","我願從之遊，未去髮已白。","不知繁華子，擾擾何所迫。","崑山採瓊蘂，可以煉精魄。"]', '["金华牧羊兒，乃是紫煙客。","我願從之游，未去髮已白。","不知繁华子，擾擾何所迫。","崑山採瓊蘂，可以煉精魄。"]', '诗', 'shi', '', NULL, '古風 十七 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac9f6653-4759-41b8-ac15-4463fff27bac', '古風 十八', '古风 十八', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["天津三月時，千門桃與李。","朝爲斷腸花，暮逐東流水。","前水復後水，古今相續流。","新人非舊人，年年橋上遊。","雞鳴海色動，謁帝羅公侯。","月落西上陽，餘輝半城樓。","衣冠照雲日，朝下散皇州。","鞍馬如飛龍，黃金絡馬頭。","行人皆辟易，志氣橫嵩丘。","入門上高堂，列鼎錯珍羞。","香風引趙舞，清管隨齊謳。","七十紫鴛鴦，雙雙戲庭幽。","行樂爭晝夜，自言度千秋。","功成身不退，自古多愆尤。","黃犬空歎息，綠珠成釁讐。","何如鴟夷子，散髮櫂扁舟。"]', '["天津三月时，千门桃與李。","朝爲斷腸花，暮逐东流水。","前水复後水，古今相續流。","新人非旧人，年年橋上游。","雞鳴海色动，謁帝羅公侯。","月落西上陽，餘輝半城楼。","衣冠照云日，朝下散皇州。","鞍马如飞龙，黄金絡马头。","行人皆辟易，志氣橫嵩丘。","入门上高堂，列鼎錯珍羞。","香风引趙舞，清管隨齊謳。","七十紫鴛鴦，雙雙戲庭幽。","行乐爭晝夜，自言度千秋。","功成身不退，自古多愆尤。","黄犬空歎息，綠珠成釁讐。","何如鴟夷子，散髮櫂扁舟。"]', '诗', 'shi', '', NULL, '古風 十八 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c8a7e2e-8f4f-4a67-b988-7e18ff9a397c', '古風 十九', '古风 十九', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["西嶽蓮花山，迢迢見明星。","素手把芙蓉，虛步躡太清。","霓裳曳廣帶，飄拂昇天行。","邀我登雲臺，高揖衛叔卿。","恍恍與之去，駕鴻凌紫冥。","俯視洛陽川，茫茫走胡兵。","流血塗野草，豺狼盡冠纓。"]', '["西嶽蓮花山，迢迢见明星。","素手把芙蓉，虛步躡太清。","霓裳曳廣带，飄拂昇天行。","邀我登云台，高揖衛叔卿。","恍恍與之去，駕鴻凌紫冥。","俯視洛陽川，茫茫走胡兵。","流血塗野草，豺狼尽冠纓。"]', '诗', 'shi', '', NULL, '古風 十九 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c83c80d-c727-4248-bdee-f9e7d0620fa7', '古風 二十', '古风 二十', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["昔我遊齊都，登華不注峯。","茲山何峻秀，綠翠如芙蓉。","蕭颯古仙人，了知是赤松。","借予一白鹿，自挾兩青龍。","含笑凌倒景，欣然願相從。","泣與親友別，欲語再三咽。","勗君青松心，努力保霜雪。","世路多險艱，白日欺紅顏。","分手各千里，去去何時還。","在世復幾時，倏如飄風度。","空聞紫金經，白首愁相誤。","撫己忽自笑，沈吟爲誰故。","名利徒煎熬，安得閑余步。","終留赤玉舄，東上蓬萊路。","秦帝如我求，蒼蒼但煙霧。"]', '["昔我游齊都，登华不注峯。","茲山何峻秀，綠翠如芙蓉。","蕭颯古仙人，了知是赤松。","借予一白鹿，自挾兩青龙。","含笑凌倒景，欣然願相從。","泣與親友別，欲語再三咽。","勗君青松心，努力保霜雪。","世路多險艱，白日欺紅顏。","分手各千里，去去何时還。","在世复幾时，倏如飄风度。","空闻紫金經，白首愁相誤。","撫己忽自笑，沈吟爲誰故。","名利徒煎熬，安得闲余步。","終留赤玉舄，东上蓬萊路。","秦帝如我求，蒼蒼但煙霧。"]', '诗', 'shi', '', NULL, '古風 二十 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('750933f5-19d3-443e-8fed-412d4712e587', '古風 二十一', '古风 二十一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["郢客吟白雪，遺響飛青天。","徒勞歌此曲，舉世誰爲傳。","試爲巴人唱，和者乃數千。","吞聲何足道，歎息空淒然。"]', '["郢客吟白雪，遺响飞青天。","徒勞歌此曲，舉世誰爲傳。","試爲巴人唱，和者乃數千。","吞声何足道，歎息空淒然。"]', '诗', 'shi', '', NULL, '古風 二十一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1237bed-f6ad-4000-9ec3-6834b4faf264', '古風 二十二', '古风 二十二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秦水別隴首，幽咽多悲聲。","胡馬顧朔雪，躞蹀長嘶鳴。","感物動我心，緬然含歸情。","昔視秋蛾飛，今見春蠶生。","嫋嫋桑柘葉，萋萋柳垂榮。","急節謝流水，羈心搖懸旌。","揮涕且復去，惻愴何時平。"]', '["秦水別隴首，幽咽多悲声。","胡马顧朔雪，躞蹀长嘶鳴。","感物动我心，緬然含归情。","昔視秋蛾飞，今见春蠶生。","嫋嫋桑柘葉，萋萋柳垂榮。","急節謝流水，羈心搖懸旌。","揮涕且复去，惻愴何时平。"]', '诗', 'shi', '', NULL, '古風 二十二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aefa9025-6e63-4927-a787-8f732c211705', '古風 二十三', '古风 二十三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秋露白如玉，團團下庭綠。","我行忽見之，寒早悲歲促。","人生鳥過目，胡乃自結束。","景公一何愚，牛山淚相續。","物苦不知足，得隴又望蜀。","人心若波瀾，世路有屈曲。","三萬六千日，夜夜當秉燭。"]', '["秋露白如玉，團團下庭綠。","我行忽见之，寒早悲歲促。","人生鸟過目，胡乃自結束。","景公一何愚，牛山泪相續。","物苦不知足，得隴又望蜀。","人心若波瀾，世路有屈曲。","三万六千日，夜夜當秉燭。"]', '诗', 'shi', '', NULL, '古風 二十三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee9f9829-d1b0-4a47-a72a-3d13022cb520', '古風 二十四', '古风 二十四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["大車揚飛塵，亭午暗阡陌。","中貴多黃金，連雲開甲宅。","路逢鬬雞者，冠蓋何輝赫。","鼻息干虹蜺，行人皆怵惕。","世無洗耳翁，誰知堯與跖。"]', '["大车揚飞塵，亭午暗阡陌。","中貴多黄金，連云开甲宅。","路逢鬬雞者，冠蓋何輝赫。","鼻息干虹蜺，行人皆怵惕。","世無洗耳翁，誰知堯與跖。"]', '诗', 'shi', '', NULL, '古風 二十四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42a1616c-831e-4d7a-91c5-4c41e54c66c6', '古風 二十五', '古风 二十五', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["世道日交喪，澆風散淳源。","不採芳桂枝，反棲惡木根。","所以桃李樹，吐花竟不言。","大運有興沒，羣動爭飛奔。","歸來廣成子，去入無窮門。"]', '["世道日交喪，澆风散淳源。","不採芳桂枝，反棲惡木根。","所以桃李樹，吐花竟不言。","大運有兴沒，羣动爭飞奔。","归来廣成子，去入無窮门。"]', '诗', 'shi', '', NULL, '古風 二十五 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('518caa01-3b0b-4ed5-8ad3-bb1105723b40', '古風 二十六', '古风 二十六', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["碧荷生幽泉，朝日豔且鮮。","秋花冒綠水，密葉羅青煙。","秀色空絕世，馨香竟誰傳。","坐看飛霜滿，凋此紅芳年。","結根未得所，願託華池邊。"]', '["碧荷生幽泉，朝日豔且鲜。","秋花冒綠水，密葉羅青煙。","秀色空絕世，馨香竟誰傳。","坐看飞霜满，凋此紅芳年。","結根未得所，願託华池邊。"]', '诗', 'shi', '', NULL, '古風 二十六 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e682445-490c-4e15-bab2-e176cce24cf6', '古風 二十七', '古风 二十七', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["燕趙有秀色，綺樓青雲端。","眉目豔皎月，一笑傾城歡。","常恐碧草晚，坐泣秋風寒。","纖手怨玉琴，清晨起長歎。","焉得偶君子，共乘雙飛鸞。"]', '["燕趙有秀色，綺楼青云端。","眉目豔皎月，一笑傾城歡。","常恐碧草晚，坐泣秋风寒。","纖手怨玉琴，清晨起长歎。","焉得偶君子，共乘雙飞鸾。"]', '诗', 'shi', '', NULL, '古風 二十七 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f354845c-a4b2-4850-a2a0-6a638d58c443', '古風 二十八', '古风 二十八', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["容顏若飛電，時景如飄風。","草綠霜已白，日西月復東。","華鬢不耐秋，颯然成衰蓬。","古來賢聖人，一一誰成功。","君子變猿鶴，小人爲沙蟲。","不及廣成子，乘雲駕輕鴻。"]', '["容顏若飞電，时景如飄风。","草綠霜已白，日西月复东。","华鬢不耐秋，颯然成衰蓬。","古来賢聖人，一一誰成功。","君子变猿鹤，小人爲沙蟲。","不及廣成子，乘云駕轻鴻。"]', '诗', 'shi', '', NULL, '古風 二十八 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49945276-58d4-4d13-bd6d-27ccf65dad12', '古風 二十九', '古风 二十九', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["三季分戰國，七雄成亂麻。","王風何怨怒，世道終紛拏。","至人洞玄象，高舉凌紫霞。","仲尼欲浮海，吾祖之流沙。","聖賢共淪沒，臨岐胡咄嗟。"]', '["三季分戰国，七雄成亂麻。","王风何怨怒，世道終紛拏。","至人洞玄象，高舉凌紫霞。","仲尼欲浮海，吾祖之流沙。","聖賢共淪沒，臨岐胡咄嗟。"]', '诗', 'shi', '', NULL, '古風 二十九 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ff129f9-a157-4e48-910d-891d4d39de98', '古風 三十', '古风 三十', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["玄風變太古，道喪無時還。","擾擾季葉人，雞鳴趨四關。","但識金馬門，誰知蓬萊山。","白首死羅綺，笑歌無時閑。","綠酒哂丹液，青娥凋素顏。","大儒揮金椎，琢之詩禮間。","蒼蒼三株樹，冥目焉能攀。"]', '["玄风变太古，道喪無时還。","擾擾季葉人，雞鳴趨四关。","但識金马门，誰知蓬萊山。","白首死羅綺，笑歌無时闲。","綠酒哂丹液，青娥凋素顏。","大儒揮金椎，琢之诗禮间。","蒼蒼三株樹，冥目焉能攀。"]', '诗', 'shi', '', NULL, '古風 三十 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32952fd2-5ea9-4e4b-bc05-e3148fc93824', '古風 三十一', '古风 三十一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["鄭客西入關，行行未能已。","白馬華山君，相逢平原里。","璧遺鎬池君，明年祖龍死。","秦人相謂曰，吾屬可去矣。","一往桃花源，千春隔流水。"]', '["鄭客西入关，行行未能已。","白马华山君，相逢平原里。","璧遺鎬池君，明年祖龙死。","秦人相謂曰，吾屬可去矣。","一往桃花源，千春隔流水。"]', '诗', 'shi', '', NULL, '古風 三十一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('113394f1-0d71-4dae-a1cf-f5f209bf3dbe', '古風 三十二', '古风 三十二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["蓐收肅金氣，西陸弦海月。","秋蟬號階軒，感物憂不歇。","良辰竟何許，大運有淪忽。","天寒悲風生，夜久衆星沒。","惻惻不忍言，哀歌逮明發。"]', '["蓐收肅金氣，西陸弦海月。","秋蟬號階軒，感物憂不歇。","良辰竟何許，大運有淪忽。","天寒悲风生，夜久衆星沒。","惻惻不忍言，哀歌逮明發。"]', '诗', 'shi', '', NULL, '古風 三十二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8c464a6-9b3b-457e-b75c-5581eff5635e', '古風 三十三', '古风 三十三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["北溟有巨魚，身長數千里。","仰噴三山雪，橫吞百川水。","憑陵隨海運，燀赫因風起。","吾觀摩天飛，九萬方未已。"]', '["北溟有巨鱼，身长數千里。","仰噴三山雪，橫吞百川水。","憑陵隨海運，燀赫因风起。","吾观摩天飞，九万方未已。"]', '诗', 'shi', '', NULL, '古風 三十三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ea15e4c-3349-44f4-802f-e5be472546c9', '古風 三十四', '古风 三十四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["羽檄如流星，虎符合專城。","喧呼救邊急，羣鳥皆夜鳴。","白日曜紫微，三公運權衡。","天地皆得一，澹然四海清。","借問此何爲，荅言楚徵兵。","渡瀘及五月，將赴雲南征。","怯卒非戰士，炎方難遠行。","長號別嚴親，日月慘光晶。","泣盡繼以血，心摧兩無聲。","困獸當猛虎，窮魚餌奔鯨。","千去不一回，投軀豈全生。","如何舞干戚，一使有苗平。"]', '["羽檄如流星，虎符合專城。","喧呼救邊急，羣鸟皆夜鳴。","白日曜紫微，三公運權衡。","天地皆得一，澹然四海清。","借问此何爲，荅言楚徵兵。","渡瀘及五月，將赴云南征。","怯卒非戰士，炎方难远行。","长號別嚴親，日月慘光晶。","泣尽繼以血，心摧兩無声。","困獸當猛虎，窮鱼餌奔鯨。","千去不一回，投軀豈全生。","如何舞干戚，一使有苗平。"]', '诗', 'shi', '', NULL, '古風 三十四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a78a6471-f4b4-4d47-ade3-1d26d137dc7d', '古風 三十五', '古风 三十五', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["醜女來效顰，還家驚四隣。","壽陵失本步，笑殺邯鄲人。","一曲斐然子，雕蟲喪天真。","棘刺造沐猴，三年費精神。","功成無所用，楚楚且華身。","大雅思文王，頌聲久崩淪。","安得郢中質，一揮成斧斤。"]', '["醜女来效顰，還家驚四隣。","壽陵失本步，笑殺邯鄲人。","一曲斐然子，雕蟲喪天真。","棘刺造沐猴，三年費精神。","功成無所用，楚楚且华身。","大雅思文王，頌声久崩淪。","安得郢中質，一揮成斧斤。"]', '诗', 'shi', '', NULL, '古風 三十五 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('064c0907-a7e8-4fb4-a28b-54717a9b0b38', '古風 三十六', '古风 三十六', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["抱玉入楚國，見疑古所聞。","良寶終見棄，徒勞三獻君。","直木忌先伐，芳蘭哀自焚。","盈滿天所損，沈冥道爲羣。","東海沈碧水，西關乘紫雲。","魯連及柱史，可以躡清芬。"]', '["抱玉入楚国，见疑古所闻。","良寶終见棄，徒勞三獻君。","直木忌先伐，芳蘭哀自焚。","盈满天所損，沈冥道爲羣。","东海沈碧水，西关乘紫云。","魯連及柱史，可以躡清芬。"]', '诗', 'shi', '', NULL, '古風 三十六 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06517d86-a597-4ed6-9880-4807e603942a', '古風 三十七', '古风 三十七', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["燕臣昔慟哭，五月飛秋霜。","庶女號蒼天，震風擊齊堂。","精誠有所感，造化爲悲傷。","而我竟何辜，遠身金殿傍。","浮雲蔽紫闥，白日難回光。","羣沙穢明珠，衆草凌孤芳。","古來共歎息，流淚空霑裳。"]', '["燕臣昔慟哭，五月飞秋霜。","庶女號蒼天，震风擊齊堂。","精誠有所感，造化爲悲傷。","而我竟何辜，远身金殿傍。","浮云蔽紫闥，白日难回光。","羣沙穢明珠，衆草凌孤芳。","古来共歎息，流泪空霑裳。"]', '诗', 'shi', '', NULL, '古風 三十七 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73dd417e-e491-4ea5-8dd2-c554e29bdff9', '古風 三十八', '古风 三十八', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["孤蘭生幽園，衆草共蕪沒。","雖照陽春暉，復悲高秋月。","飛霜早淅瀝，綠豔恐休歇。","若無清風吹，香氣爲誰發。"]', '["孤蘭生幽园，衆草共蕪沒。","雖照陽春暉，复悲高秋月。","飞霜早淅瀝，綠豔恐休歇。","若無清风吹，香氣爲誰發。"]', '诗', 'shi', '', NULL, '古風 三十八 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abe109e7-f798-4942-8b34-166b80612ea2', '古風 三十九', '古风 三十九', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["登高望四海，天地何漫漫。","霜被羣物秋，風飄大荒寒。","榮華東流水，萬事皆波瀾。","白日掩徂輝，浮雲無定端。","梧桐巢燕雀，枳棘棲鴛鸞。","且復歸去來，劒歌行路難。"]', '["登高望四海，天地何漫漫。","霜被羣物秋，风飄大荒寒。","榮华东流水，万事皆波瀾。","白日掩徂輝，浮云無定端。","梧桐巢燕雀，枳棘棲鴛鸾。","且复归去来，劒歌行路难。"]', '诗', 'shi', '', NULL, '古風 三十九 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f173eefa-4207-4158-9a4b-d16e3f78286b', '古風 四十', '古风 四十', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["鳳飢不啄粟，所食唯琅玕。","焉能與羣雞，刺蹙爭一餐。","朝鳴崑丘樹，夕飲砥柱湍。","歸飛海路遠，獨宿天霜寒。","幸遇王子晉，結交青雲端。","懷恩未得報，感別空長歎。"]', '["鳳飢不啄粟，所食唯琅玕。","焉能與羣雞，刺蹙爭一餐。","朝鳴崑丘樹，夕饮砥柱湍。","归飞海路远，独宿天霜寒。","幸遇王子晉，結交青云端。","懷恩未得報，感別空长歎。"]', '诗', 'shi', '', NULL, '古風 四十 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b06269e7-0997-4c1b-81d0-c96982041406', '古風 四十一', '古风 四十一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["朝弄紫沂海，夕披丹霞裳。","揮手折若木，拂此西日光。","雲臥遊八極，玉顏已千霜。","飄飄入無倪，稽首祈上皇。","呼我遊太素，玉杯賜瓊漿。","一餐歷萬歲，何用還故鄉。","永隨長風去，天外恣飄揚。"]', '["朝弄紫沂海，夕披丹霞裳。","揮手折若木，拂此西日光。","云臥游八極，玉顏已千霜。","飄飄入無倪，稽首祈上皇。","呼我游太素，玉杯賜瓊漿。","一餐歷万歲，何用還故乡。","永隨长风去，天外恣飄揚。"]', '诗', 'shi', '', NULL, '古風 四十一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22e27e7a-85e1-4ba2-bb9e-9fbaabb923f6', '古風 四十二', '古风 四十二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["搖裔雙白鷗，鳴飛滄江流。","宜與海人狎，豈伊雲鶴儔。","寄形宿沙月，沿芳戲春洲。","吾亦洗心者，忘機從爾遊。"]', '["搖裔雙白鷗，鳴飞滄江流。","宜與海人狎，豈伊云鹤儔。","寄形宿沙月，沿芳戲春洲。","吾亦洗心者，忘機從爾游。"]', '诗', 'shi', '', NULL, '古風 四十二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de6fcb78-d56f-4d3e-b456-12f67e91e41b', '古風 四十三', '古风 四十三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["周穆八荒意，漢皇萬乘尊。","淫樂心不極，雄豪安足論。","西海宴王母，北宮邀上元。","瑤水聞遺歌，玉杯竟空言。","靈跡成蔓草，徒悲千載魂。"]', '["周穆八荒意，漢皇万乘尊。","淫乐心不極，雄豪安足論。","西海宴王母，北宮邀上元。","瑤水闻遺歌，玉杯竟空言。","靈跡成蔓草，徒悲千載魂。"]', '诗', 'shi', '', NULL, '古風 四十三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b560ff1f-b156-4646-8b84-7d5e3d9e929c', '古風 四十四', '古风 四十四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["綠蘿紛葳蕤，繚繞松栢枝。","草木有所託，歲寒尚不移。","奈何夭桃色，坐歎葑菲詩。","玉顏豔紅彩，雲髮非素絲。","君子恩已畢，賤妾將何爲。"]', '["綠蘿紛葳蕤，繚繞松栢枝。","草木有所託，歲寒尚不移。","奈何夭桃色，坐歎葑菲诗。","玉顏豔紅彩，云髮非素絲。","君子恩已畢，賤妾將何爲。"]', '诗', 'shi', '', NULL, '古風 四十四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d9cfd71-0c43-478e-baad-fb1740343f2f', '古風 四十五', '古风 四十五', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["八荒馳驚飆，萬物盡凋落。","浮雲蔽頹陽，洪波振大壑。","龍鳳脫罔罟，飄颻將安託。","去去乘白駒，空山詠場藿。"]', '["八荒驰驚飆，万物尽凋落。","浮云蔽頹陽，洪波振大壑。","龙鳳脫罔罟，飄颻將安託。","去去乘白駒，空山詠場藿。"]', '诗', 'shi', '', NULL, '古風 四十五 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd2124f8-ae92-43f7-bf26-5439d8d5fb3a', '古風 四十六', '古风 四十六', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["一百四十年，國容何赫然。","隱隱五鳳樓，峨峨橫三川。","王侯象星月，賓客如雲煙。","鬬雞金宮裏，蹴鞠瑤臺邊。","舉動搖白日，指揮回青天。","當塗何翕忽，失路長棄捐。","獨有揚執戟，閉關草太玄。"]', '["一百四十年，国容何赫然。","隐隐五鳳楼，峨峨橫三川。","王侯象星月，賓客如云煙。","鬬雞金宮裏，蹴鞠瑤台邊。","舉动搖白日，指揮回青天。","當塗何翕忽，失路长棄捐。","独有揚執戟，閉关草太玄。"]', '诗', 'shi', '', NULL, '古風 四十六 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3db87ddc-43a0-4209-a06c-71f336fd806a', '古風 四十七', '古风 四十七', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["桃花開東園，含笑誇白日。","偶蒙東風榮，生此豔陽質。","豈無佳人色，但恐花不實。","宛轉龍火飛，零落早相失。","詎知南山松，獨立自蕭飋。"]', '["桃花开东园，含笑誇白日。","偶蒙东风榮，生此豔陽質。","豈無佳人色，但恐花不實。","宛轉龙火飞，零落早相失。","詎知南山松，独立自蕭飋。"]', '诗', 'shi', '', NULL, '古風 四十七 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b3c8702-6705-4385-bdb1-ee3f35b8d8ba', '古風 四十八', '古风 四十八', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秦皇按寶劒，赫怒震威神。","逐日巡海右，驅石駕滄津。","徵卒空九宇，作橋傷萬人。","但求蓬島藥，豈思農鳸春。","力盡功不贍，千載爲悲辛。"]', '["秦皇按寶劒，赫怒震威神。","逐日巡海右，驱石駕滄津。","徵卒空九宇，作橋傷万人。","但求蓬島藥，豈思農鳸春。","力尽功不贍，千載爲悲辛。"]', '诗', 'shi', '', NULL, '古風 四十八 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7e10bcd-f437-4679-aae6-7ad8f77f1626', '古風 四十九', '古风 四十九', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["美人出南國，灼灼芙蓉姿。","皓齒終不發，芳心空自持。","由來紫宮女，共妬青蛾眉。","歸去瀟湘沚，沈吟何足悲。"]', '["美人出南国，灼灼芙蓉姿。","皓齒終不發，芳心空自持。","由来紫宮女，共妬青蛾眉。","归去瀟湘沚，沈吟何足悲。"]', '诗', 'shi', '', NULL, '古風 四十九 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbc22422-4c55-49cf-90ee-24bb4cd68142', '古風 五十', '古风 五十', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["宋國梧臺東，野人得燕石。","誇作天下珍，却哂趙王璧。","趙璧無緇磷，燕石非貞真。","流俗多錯誤，豈知玉與珉。"]', '["宋国梧台东，野人得燕石。","誇作天下珍，却哂趙王璧。","趙璧無緇磷，燕石非貞真。","流俗多錯誤，豈知玉與珉。"]', '诗', 'shi', '', NULL, '古風 五十 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('551d7161-7d87-4b6a-868d-89dc4071d39b', '古風 五十一', '古风 五十一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["殷后亂天紀，楚懷亦已昏。","夷羊滿中野，菉葹盈高門。","比干諫而死，屈平竄湘源。","虎口何婉孌，女嬃空嬋媛。","彭咸久淪沒，此意與誰論。"]', '["殷后亂天紀，楚懷亦已昏。","夷羊满中野，菉葹盈高门。","比干諫而死，屈平竄湘源。","虎口何婉孌，女嬃空嬋媛。","彭咸久淪沒，此意與誰論。"]', '诗', 'shi', '', NULL, '古風 五十一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e8e88b9-b428-4860-aef7-5e5b078ba62e', '古風 五十二', '古风 五十二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["青春流驚湍，朱明驟回薄。","不忍看秋蓬，飄揚竟何託。","光風滅蘭蕙，白露洒葵藿。","美人不我期，草木日零落。"]', '["青春流驚湍，朱明驟回薄。","不忍看秋蓬，飄揚竟何託。","光风滅蘭蕙，白露洒葵藿。","美人不我期，草木日零落。"]', '诗', 'shi', '', NULL, '古風 五十二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04929604-1ced-4db8-9437-c97f069927e0', '古風 五十三', '古风 五十三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["戰國何紛紛，兵戈亂浮雲。","趙倚兩虎鬬，晉爲六卿分。","姦臣欲竊位，樹黨自相羣。","果然田成子，一旦殺齊君。"]', '["戰国何紛紛，兵戈亂浮云。","趙倚兩虎鬬，晉爲六卿分。","姦臣欲竊位，樹黨自相羣。","果然田成子，一旦殺齊君。"]', '诗', 'shi', '', NULL, '古風 五十三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fb65711-3aa7-42a3-8dbf-580c83b28b11', '古風 五十四', '古风 五十四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["倚劒登高臺，悠悠送春目。","蒼榛蔽層丘，瓊草隱深谷。","鳳鳥鳴西海，欲集無珍木。","鸒斯得所居，蒿下盈萬族。","晉風日已頹，窮途方慟哭。"]', '["倚劒登高台，悠悠送春目。","蒼榛蔽層丘，瓊草隐深谷。","鳳鸟鳴西海，欲集無珍木。","鸒斯得所居，蒿下盈万族。","晉风日已頹，窮途方慟哭。"]', '诗', 'shi', '', NULL, '古風 五十四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6830895d-a140-4ce5-aa1e-97bb1aebe9e9', '古風 五十五', '古风 五十五', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["齊瑟彈東吟，秦弦弄西音。","慷慨動顏魄，使人成荒淫。","彼美佞邪子，婉孌來相尋。","一笑雙白璧，再歌千黃金。","珍色不貴道，詎惜飛光沈。","安識紫霞客，瑤臺鳴素琴。"]', '["齊瑟彈东吟，秦弦弄西音。","慷慨动顏魄，使人成荒淫。","彼美佞邪子，婉孌来相尋。","一笑雙白璧，再歌千黄金。","珍色不貴道，詎惜飞光沈。","安識紫霞客，瑤台鳴素琴。"]', '诗', 'shi', '', NULL, '古風 五十五 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('714f1a71-8889-4c49-8db4-7ff1bb985697', '古風 五十六', '古风 五十六', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["越客採明珠，提攜出南隅。","清輝照海月，美價傾皇都。","獻君君按劒，懷寶空長吁。","魚目復相哂，寸心增煩紆。"]', '["越客採明珠，提携出南隅。","清輝照海月，美價傾皇都。","獻君君按劒，懷寶空长吁。","鱼目复相哂，寸心增煩紆。"]', '诗', 'shi', '', NULL, '古風 五十六 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c14cb8d8-2275-4a11-8d25-3886e18179a1', '古風 五十七', '古风 五十七', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["羽族稟萬化，小大各有依。","周周亦何辜，六翮掩不揮。","願銜衆禽翼，一向黃河飛。","飛者莫我顧，歎息將安歸。"]', '["羽族稟万化，小大各有依。","周周亦何辜，六翮掩不揮。","願銜衆禽翼，一向黄河飞。","飞者莫我顧，歎息將安归。"]', '诗', 'shi', '', NULL, '古風 五十七 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ab58e8b-ee92-4cb2-a142-075bb08e5560', '古風 五十八', '古风 五十八', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我到巫山渚，尋古登陽臺。","天空綵雲滅，地遠清風來。","神女去已久，襄王安在哉。","荒淫竟淪替，樵牧徒悲哀。"]', '["我到巫山渚，尋古登陽台。","天空綵云滅，地远清风来。","神女去已久，襄王安在哉。","荒淫竟淪替，樵牧徒悲哀。"]', '诗', 'shi', '', NULL, '古風 五十八 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9134bf8-16f7-4fc6-a27b-ad2598788bd4', '古風 五十九', '古风 五十九', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["惻惻泣路岐，哀哀悲素絲。","路岐有南北，素絲易變移。","萬事固如此，人生無定期。","田竇相傾奪，賓客互盈虧。","世途多飜覆，交道方嶮巇。","斗酒强然諾，寸心終自疑。","張陳竟火滅，蕭朱亦星離。","衆鳥集榮柯，窮魚守枯池。","嗟嗟失權客，勤問何所規。"]', '["惻惻泣路岐，哀哀悲素絲。","路岐有南北，素絲易变移。","万事固如此，人生無定期。","田竇相傾奪，賓客互盈虧。","世途多飜覆，交道方嶮巇。","斗酒强然諾，寸心終自疑。","張陳竟火滅，蕭朱亦星離。","衆鸟集榮柯，窮鱼守枯池。","嗟嗟失權客，勤问何所規。"]', '诗', 'shi', '', NULL, '古風 五十九 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6e2618e-d556-44e6-af36-e645989334db', '遠別離', '远別離', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["遠別離，古有皇英之二女，乃在洞庭之南，瀟湘之浦。","海水直下萬里深，誰人不言此離苦。","日慘慘兮雲冥冥，猩猩啼煙兮鬼嘯雨。","我縱言之將何補，皇穹竊恐不照余之忠誠。","雲憑憑兮欲吼怒，堯舜當之亦禪禹。","君失臣兮龍爲魚，權歸臣兮鼠變虎。","或言堯幽囚，舜野死。","九疑聯綿皆相似，重瞳孤墳竟何是。","帝子泣兮綠雲間，隨風波兮去無還。","慟哭兮遠望，見蒼梧之深山。","蒼梧山崩湘水絕，竹上之淚乃可滅。"]', '["远別離，古有皇英之二女，乃在洞庭之南，瀟湘之浦。","海水直下万里深，誰人不言此離苦。","日慘慘兮云冥冥，猩猩啼煙兮鬼嘯雨。","我縱言之將何補，皇穹竊恐不照余之忠誠。","云憑憑兮欲吼怒，堯舜當之亦禪禹。","君失臣兮龙爲鱼，權归臣兮鼠变虎。","或言堯幽囚，舜野死。","九疑聯綿皆相似，重瞳孤墳竟何是。","帝子泣兮綠云间，隨风波兮去無還。","慟哭兮远望，见蒼梧之深山。","蒼梧山崩湘水絕，竹上之泪乃可滅。"]', '诗', 'shi', '', NULL, '遠別離 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02a6ea79-3d96-41a6-8b43-43a0190af743', '公無渡河', '公無渡河', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["黃河西來決崑崙，咆哮萬里觸龍門。","波滔天，堯咨嗟，大禹理百川，兒啼不窺家。","殺湍煙洪水，九州始蠶麻。","其害乃去，茫然風沙。","被髮之叟狂而癡，清晨臨流欲奚爲。","旁人不惜妻止之，公無渡河苦渡之。","虎可搏，河難憑，公果溺死流海湄。","有長鯨白齒若雪山，公乎公乎挂罥於其間，箜篌所悲竟不還。"]', '["黄河西来決崑崙，咆哮万里觸龙门。","波滔天，堯咨嗟，大禹理百川，兒啼不窺家。","殺湍煙洪水，九州始蠶麻。","其害乃去，茫然风沙。","被髮之叟狂而癡，清晨臨流欲奚爲。","旁人不惜妻止之，公無渡河苦渡之。","虎可搏，河难憑，公果溺死流海湄。","有长鯨白齒若雪山，公乎公乎挂罥於其间，箜篌所悲竟不還。"]', '诗', 'shi', '', NULL, '公無渡河 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f15c4b50-ee89-4927-8cf3-15e3a6a6ab95', '蜀道難', '蜀道难', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["噫吁戲！危乎高哉！蜀道之難難於上青天！蠶叢及魚鳧，開國何茫然。","爾來四萬八千歲，不與秦塞通人煙。","西當太白有鳥道，可以橫絕峨眉巔。","地崩山摧壯士死，然後天梯石棧相鉤連。","上有六龍回日之高標，下有衝波逆折之回川。","黃鶴之飛尚不得過，猨猱欲度愁攀援。","青泥何盤盤，百步九折縈巖巒。","捫參歷井仰脅息，以手撫膺坐長歎。","問君西遊何時還？畏途巉巖不可攀。","但見悲鳥號古木，雄飛雌從繞林間。","又聞子規啼夜月，愁空山，蜀道之難難於上青天，使人聽此凋朱顏。","連峯去天不盈尺，枯松倒挂倚絕壁。","飛湍瀑流爭喧豗，砅厓轉石萬壑雷。","其險也如此，嗟爾遠道之人胡爲乎來哉！劒閣崢嶸而崔嵬，一夫當關，萬夫莫開。","所守或匪親，化爲狼與豺。","朝避猛虎，夕避長蛇。","磨牙吮血，殺人如麻。","錦城雖云樂，不如早還家。","蜀道之難難於上青天，側身西望長咨嗟。"]', '["噫吁戲！危乎高哉！蜀道之难难於上青天！蠶叢及鱼鳧，开国何茫然。","爾来四万八千歲，不與秦塞通人煙。","西當太白有鸟道，可以橫絕峨眉巔。","地崩山摧壯士死，然後天梯石棧相鉤連。","上有六龙回日之高標，下有衝波逆折之回川。","黄鹤之飞尚不得過，猨猱欲度愁攀援。","青泥何盤盤，百步九折縈巖巒。","捫參歷井仰脅息，以手撫膺坐长歎。","问君西游何时還？畏途巉巖不可攀。","但见悲鸟號古木，雄飞雌從繞林间。","又闻子規啼夜月，愁空山，蜀道之难难於上青天，使人听此凋朱顏。","連峯去天不盈尺，枯松倒挂倚絕壁。","飞湍瀑流爭喧豗，砅厓轉石万壑雷。","其險也如此，嗟爾远道之人胡爲乎来哉！劒閣崢嶸而崔嵬，一夫當关，万夫莫开。","所守或匪親，化爲狼與豺。","朝避猛虎，夕避长蛇。","磨牙吮血，殺人如麻。","錦城雖云乐，不如早還家。","蜀道之难难於上青天，側身西望长咨嗟。"]', '诗', 'shi', '', NULL, '蜀道難 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7817c04-eed3-4666-a89f-9a76928fabb7', '梁甫吟', '梁甫吟', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["長嘯梁甫吟，何時見陽春。","君不見朝歌屠叟辭棘津，八十西來釣渭濱。","寧羞白髮照清水，逢時吐氣思經綸。","廣張三千六百釣，風期暗與文王親。","大賢虎變愚不測，當年頗似尋常人。","君不見高陽酒徒起草中，長揖山東隆準公。","入門不拜騁雄辯，兩女輟洗來趨風。","東下齊城七十二，指揮楚漢如旋蓬。","狂客落魄尚如此，何況壯士當羣雄。","我欲攀龍見明主，雷公砰訇震天鼓。","帝傍投壺多玉女，三時大笑開電光。","倏爍晦冥起風雨，閶闔九門不可通。","以額扣關閽者怒，白日不照吾精誠。","杞國無事憂天傾，䝟貐磨牙競人肉。","騶虞不折生草莖，手接飛猱搏彫虎。","側足焦原未言苦，智者可卷愚者豪。","世人見我輕鴻毛，力排南山三壯士，齊相殺之費二桃。","吳楚弄兵無劇孟，亞夫咍爾爲徒勞。","梁甫吟，梁甫吟，聲正悲。","張公兩龍劒，神物合有時。","風雲感會起屠釣，大人𡸣屼當安之。"]', '["长嘯梁甫吟，何时见陽春。","君不见朝歌屠叟辞棘津，八十西来釣渭濱。","寧羞白髮照清水，逢时吐氣思經綸。","廣張三千六百釣，风期暗與文王親。","大賢虎变愚不測，當年頗似尋常人。","君不见高陽酒徒起草中，长揖山东隆準公。","入门不拜騁雄辯，兩女輟洗来趨风。","东下齊城七十二，指揮楚漢如旋蓬。","狂客落魄尚如此，何況壯士當羣雄。","我欲攀龙见明主，雷公砰訇震天鼓。","帝傍投壺多玉女，三时大笑开電光。","倏爍晦冥起风雨，閶闔九门不可通。","以額扣关閽者怒，白日不照吾精誠。","杞国無事憂天傾，䝟貐磨牙競人肉。","騶虞不折生草莖，手接飞猱搏彫虎。","側足焦原未言苦，智者可卷愚者豪。","世人见我轻鴻毛，力排南山三壯士，齊相殺之費二桃。","吳楚弄兵無劇孟，亞夫咍爾爲徒勞。","梁甫吟，梁甫吟，声正悲。","張公兩龙劒，神物合有时。","风云感會起屠釣，大人𡸣屼當安之。"]', '诗', 'shi', '', NULL, '梁甫吟 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49750e0a-0ab2-47b9-9722-cfb63fe45552', '烏夜啼', '烏夜啼', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["黃雲城邊烏欲棲，歸飛啞啞枝上啼。","機中織錦秦川女，碧紗如煙隔窗語。","停梭悵然憶遠人，獨宿孤房淚如雨。"]', '["黄云城邊烏欲棲，归飞啞啞枝上啼。","機中织錦秦川女，碧紗如煙隔窗語。","停梭悵然憶远人，独宿孤房泪如雨。"]', '诗', 'shi', '', NULL, '烏夜啼 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b792a6a-9307-42bc-b6ba-e028ed6981f8', '烏棲曲', '烏棲曲', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["姑蘇臺上烏棲時，吳王宮裏醉西施。","吳歌楚舞歡未畢，青山欲銜半邊日。"]', '["姑蘇台上烏棲时，吳王宮裏醉西施。","吳歌楚舞歡未畢，青山欲銜半邊日。"]', '诗', 'shi', '', NULL, '烏棲曲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cf98d29-f652-4683-ba93-df5da16bd4be', '戰城南', '戰城南', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["去年戰桑乾源，今年戰蔥河道。","洗兵條支海上波，放馬天山雪中草。","萬里長征戰，三軍盡衰老。","匈奴以殺戮爲耕作，古來唯見白骨黃沙田。","秦家築城避胡處，漢家還有烽火然。","烽火然不息，征戰無已時。","野戰格鬬死，敗馬號鳴向天悲。","烏鳶啄人腸，銜飛上挂枯樹枝。","士卒塗草莽，將軍空爾爲。","乃知兵者是凶器，聖人不得已而用之。"]', '["去年戰桑乾源，今年戰蔥河道。","洗兵條支海上波，放马天山雪中草。","万里长征戰，三軍尽衰老。","匈奴以殺戮爲耕作，古来唯见白骨黄沙田。","秦家築城避胡处，漢家還有烽火然。","烽火然不息，征戰無已时。","野戰格鬬死，敗马號鳴向天悲。","烏鳶啄人腸，銜飞上挂枯樹枝。","士卒塗草莽，將軍空爾爲。","乃知兵者是凶器，聖人不得已而用之。"]', '诗', 'shi', '', NULL, '戰城南 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5e5f969-ddac-4491-9cfe-d77742e1416d', '將進酒', '將進酒', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["君不見黃河之水天上來，奔流到海不復迴。","君不見高堂明鏡悲白髮，朝如青絲暮成雪。","人生得意須盡歡，莫使金樽空對月。","天生我材必有用，千金散盡還復來。","烹羊宰牛且爲樂，會須一飲三百盃。","岑夫子，丹丘生，將進酒，君莫停。","與君歌一曲，請君爲我側耳聽。","鐘鼓饌玉不足貴，但願長醉不願醒。","古來聖賢皆寂寞，惟有飲者留其名。","陳王昔時宴平樂，斗酒十千恣讙謔。","主人何爲言少錢，徑須沽取對君酌。","五花馬，千金裘，呼兒將出換美酒，與爾同銷萬古愁。"]', '["君不见黄河之水天上来，奔流到海不复迴。","君不见高堂明镜悲白髮，朝如青絲暮成雪。","人生得意須尽歡，莫使金樽空对月。","天生我材必有用，千金散尽還复来。","烹羊宰牛且爲乐，會須一饮三百盃。","岑夫子，丹丘生，將進酒，君莫停。","與君歌一曲，請君爲我側耳听。","鐘鼓饌玉不足貴，但願长醉不願醒。","古来聖賢皆寂寞，惟有饮者留其名。","陳王昔时宴平乐，斗酒十千恣讙謔。","主人何爲言少錢，徑須沽取对君酌。","五花马，千金裘，呼兒將出換美酒，與爾同銷万古愁。"]', '诗', 'shi', '', NULL, '將進酒 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('138052b8-1396-4f6b-b0e8-aca814a878ee', '行行遊且獵篇', '行行游且獵篇', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["邊城兒，生年不讀一字書，但將遊獵誇輕趫。","胡馬秋肥宜白草，騎來躡影何矜驕。","金鞭拂雪揮鳴鞘，半酣呼鷹出遠郊。","弓彎滿月不虛發，雙鶬迸落連飛髇。","海邊觀者皆辟易，猛氣英風振沙磧。","儒生不及游俠人，白首下帷復何益。"]', '["邊城兒，生年不读一字书，但將游獵誇轻趫。","胡马秋肥宜白草，騎来躡影何矜驕。","金鞭拂雪揮鳴鞘，半酣呼鷹出远郊。","弓彎满月不虛發，雙鶬迸落連飞髇。","海邊观者皆辟易，猛氣英风振沙磧。","儒生不及游俠人，白首下帷复何益。"]', '诗', 'shi', '', NULL, '行行遊且獵篇 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af2f2138-fb22-49f8-b2f6-57abf04a7a4f', '飛龍引二首 一', '飞龙引二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["黃帝鑄鼎於荆山，鍊丹砂。","丹砂成黃金，騎龍飛上太清家。","雲愁海思令人嗟，宮中綵女顏如花。","飄然揮手凌紫霞，從風縱體登鸞車。","登鸞車，侍軒轅。","遨遊青天中，其樂不可言。"]', '["黄帝鑄鼎於荆山，鍊丹砂。","丹砂成黄金，騎龙飞上太清家。","云愁海思令人嗟，宮中綵女顏如花。","飄然揮手凌紫霞，從风縱體登鸾车。","登鸾车，侍軒轅。","遨游青天中，其乐不可言。"]', '诗', 'shi', '', NULL, '飛龍引二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cb72451-c59d-4d32-84b8-89a529feeceb', '飛龍引二首 二', '飞龙引二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["鼎湖流水清且閑，軒轅去時有弓劒。","古人傳道留其間，後宮嬋娟多花顏。","乘鸞飛煙亦不還，騎龍攀天造天關。","造天關，聞天語，長雲河車載玉女。","載玉女，過紫皇，紫皇乃賜白兔所擣之藥方，後天而老彫三光。","下視瑤池見王母，蛾眉蕭颯如秋霜。"]', '["鼎湖流水清且闲，軒轅去时有弓劒。","古人傳道留其间，後宮嬋娟多花顏。","乘鸾飞煙亦不還，騎龙攀天造天关。","造天关，闻天語，长云河车載玉女。","載玉女，過紫皇，紫皇乃賜白兔所擣之藥方，後天而老彫三光。","下視瑤池见王母，蛾眉蕭颯如秋霜。"]', '诗', 'shi', '', NULL, '飛龍引二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e41141f3-437d-4bb1-ba8b-a52044e3d17c', '天馬歌', '天马歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["天馬來出月支窟，背爲虎文龍翼骨。","嘶青雲，振綠髮，蘭筋權奇走滅沒。","騰崑崙，歷西極，四足無一蹶。","雞鳴刷燕晡秣越，神行電邁躡慌惚。","天馬呼，飛龍趨，目明長庚臆雙鳧。","尾如流星首渴烏，口噴紅光汗溝朱。","曾陪時龍躡天衢，羈金絡月照皇都。","逸氣稜稜淩九區，白璧如山誰敢沽。","回頭笑紫燕，但覺爾輩愚。","天馬奔，戀君軒，駷躍驚矯浮雲飜。","萬里足躑躅，遙瞻閶闔門。","不逢寒風子，誰採逸景孫。","白雲在青天，丘陵遠崔嵬。","鹽車上峻坂，倒行逆施畏日晚。","伯樂翦拂中道遺，少盡其力老棄之。","願逢田子方，惻然爲我悲。","雖有玉山禾，不能療苦飢。","嚴霜五月凋桂枝，伏櫪銜冤摧兩眉。","請君贖獻穆天子，猶堪弄影舞瑤池。"]', '["天马来出月支窟，背爲虎文龙翼骨。","嘶青云，振綠髮，蘭筋權奇走滅沒。","腾崑崙，歷西極，四足無一蹶。","雞鳴刷燕晡秣越，神行電邁躡慌惚。","天马呼，飞龙趨，目明长庚臆雙鳧。","尾如流星首渴烏，口噴紅光汗溝朱。","曾陪时龙躡天衢，羈金絡月照皇都。","逸氣稜稜淩九區，白璧如山誰敢沽。","回头笑紫燕，但覺爾輩愚。","天马奔，戀君軒，駷躍驚矯浮云飜。","万里足躑躅，遙瞻閶闔门。","不逢寒风子，誰採逸景孫。","白云在青天，丘陵远崔嵬。","鹽车上峻坂，倒行逆施畏日晚。","伯乐翦拂中道遺，少尽其力老棄之。","願逢田子方，惻然爲我悲。","雖有玉山禾，不能療苦飢。","嚴霜五月凋桂枝，伏櫪銜冤摧兩眉。","請君贖獻穆天子，猶堪弄影舞瑤池。"]', '诗', 'shi', '', NULL, '天馬歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c348bc2e-f50d-436b-88b7-c198d63dacfc', '行路難三首 一', '行路难三首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["金樽清酒斗十千，玉盤珍羞直萬錢。","停杯投筯不能食，拔劒四顧心茫然。","欲渡黃河冰塞川，將登太行雪滿山。","閑來垂釣碧溪上，忽復乘舟夢日邊。","行路難，行路難，多岐路，今安在。","長風破浪會有時，直挂雲帆濟滄海。"]', '["金樽清酒斗十千，玉盤珍羞直万錢。","停杯投筯不能食，拔劒四顧心茫然。","欲渡黄河冰塞川，將登太行雪满山。","闲来垂釣碧溪上，忽复乘舟梦日邊。","行路难，行路难，多岐路，今安在。","长风破浪會有时，直挂云帆濟滄海。"]', '诗', 'shi', '', NULL, '行路難三首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('801c3192-8001-4238-8ecf-0111f490e84c', '行路難三首 二', '行路难三首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["大道如青天，我獨不得出。","羞逐長安社中兒，赤雞白狗賭梨栗。","彈劒作歌奏苦聲，曳裾王門不稱情。","淮陰市井笑韓信，漢朝公卿忌賈生。","君不見昔時燕家重郭隗，擁篲折節無嫌猜。","劇辛樂毅感恩分，輸肝剖膽效英才。","昭王白骨縈爛草，誰人更掃黃金臺。","行路難，歸去來。"]', '["大道如青天，我独不得出。","羞逐长安社中兒，赤雞白狗賭梨栗。","彈劒作歌奏苦声，曳裾王门不稱情。","淮陰市井笑韓信，漢朝公卿忌賈生。","君不见昔时燕家重郭隗，擁篲折節無嫌猜。","劇辛乐毅感恩分，輸肝剖膽效英才。","昭王白骨縈爛草，誰人更掃黄金台。","行路难，归去来。"]', '诗', 'shi', '', NULL, '行路難三首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7b8e17f-ee93-4bdc-a144-b1ba5ab32bb5', '行路難三首 三', '行路难三首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["有耳莫洗潁川水，有口莫食首陽蕨。","含光混世貴無名，何用孤高比雲月。","吾觀自古賢達人，功成不退皆殞身。","子胥既棄吳江上，屈原終投湘水濱。","陸機雄才豈自保，李斯稅駕苦不早。","華亭鶴唳詎可聞，上蔡蒼鷹何足道。","君不見吳中張翰稱達生，秋風忽憶江東行。","且樂生前一杯酒，何須身後千載名。"]', '["有耳莫洗潁川水，有口莫食首陽蕨。","含光混世貴無名，何用孤高比云月。","吾观自古賢達人，功成不退皆殞身。","子胥既棄吳江上，屈原終投湘水濱。","陸機雄才豈自保，李斯稅駕苦不早。","华亭鹤唳詎可闻，上蔡蒼鷹何足道。","君不见吳中張翰稱達生，秋风忽憶江东行。","且乐生前一杯酒，何須身後千載名。"]', '诗', 'shi', '', NULL, '行路難三首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c1693fc-f4e6-43b7-a66f-6379c3a26eef', '長相思', '长相思', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["長相思，在長安，絡緯秋啼金井闌。","微霜淒淒簟色寒，孤燈不明思欲絕。","卷帷望月空長歎，美人如花隔雲端。","上有青冥之長天，下有淥水之波瀾。","天長路遠魂飛苦，夢魂不到關山難。","長相思，摧心肝。"]', '["长相思，在长安，絡緯秋啼金井闌。","微霜淒淒簟色寒，孤灯不明思欲絕。","卷帷望月空长歎，美人如花隔云端。","上有青冥之长天，下有淥水之波瀾。","天长路远魂飞苦，梦魂不到关山难。","长相思，摧心肝。"]', '诗', 'shi', '', NULL, '長相思 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08ba0dc7-d6da-498a-bcc6-ba3fd176fd40', '上留田行', '上留田行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["行至上留田，孤墳何崢嶸。","積此萬古恨，春草不復生。","悲風四邊來，腸斷白楊聲。","借問誰家地，埋沒蒿里塋。","古老向余言，言是上留田。","蓬科馬鬣今已平，昔之弟死兄不葬，他人於此舉銘旌。","一鳥死，百鳥鳴，一獸走，百獸驚。","桓山之禽別離苦，欲去迴翔不能征。","田氏倉卒骨肉分，青天白日摧紫荆。","交柯之木本同形，東枝顦顇西枝榮。","無心之物尚如此，參商胡乃尋天兵。","孤竹延陵，讓國揚名。","高風緬邈，頹波激清。","尺布之謠，塞耳不能聽。"]', '["行至上留田，孤墳何崢嶸。","積此万古恨，春草不复生。","悲风四邊来，腸斷白楊声。","借问誰家地，埋沒蒿里塋。","古老向余言，言是上留田。","蓬科马鬣今已平，昔之弟死兄不葬，他人於此舉銘旌。","一鸟死，百鸟鳴，一獸走，百獸驚。","桓山之禽別離苦，欲去迴翔不能征。","田氏倉卒骨肉分，青天白日摧紫荆。","交柯之木本同形，东枝顦顇西枝榮。","無心之物尚如此，參商胡乃尋天兵。","孤竹延陵，讓国揚名。","高风緬邈，頹波激清。","尺布之謠，塞耳不能听。"]', '诗', 'shi', '', NULL, '上留田行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9eda84f1-1d1c-4c2c-ad28-98a3963dcdf3', '春日行', '春日行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["深宮高樓入紫清，金作蛟龍盤繡楹。","佳人當窗弄白日，弦將手語彈鳴箏。","春風吹落君王耳，此曲乃是昇天行。","因出天池泛蓬瀛，樓船蹙沓波浪驚。","三千雙蛾獻歌笑，撾鐘考鼓宮殿傾。","萬姓聚舞歌太平，我無爲，人自寧。","三十六帝欲相迎，仙人飄翩下雲軿。","帝不去，留鎬京。","安能爲軒轅，獨往入窅冥。","小臣拜獻南山壽，陛下萬古垂鴻名。"]', '["深宮高楼入紫清，金作蛟龙盤繡楹。","佳人當窗弄白日，弦將手語彈鳴箏。","春风吹落君王耳，此曲乃是昇天行。","因出天池泛蓬瀛，楼船蹙沓波浪驚。","三千雙蛾獻歌笑，撾鐘考鼓宮殿傾。","万姓聚舞歌太平，我無爲，人自寧。","三十六帝欲相迎，仙人飄翩下云軿。","帝不去，留鎬京。","安能爲軒轅，独往入窅冥。","小臣拜獻南山壽，陛下万古垂鴻名。"]', '诗', 'shi', '', NULL, '春日行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0b8f475-e8d1-4690-bc4a-91d01dcb10fc', '前有一樽酒行二首 一', '前有一樽酒行二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["春風東來忽相過，金樽淥酒生微波。","落花紛紛稍覺多，美人欲醉朱顏酡。","青軒桃李能幾何，流光欺人忽蹉砣。","君起舞，日西夕，當年意氣不肯平，白髮如絲歎何益。"]', '["春风东来忽相過，金樽淥酒生微波。","落花紛紛稍覺多，美人欲醉朱顏酡。","青軒桃李能幾何，流光欺人忽蹉砣。","君起舞，日西夕，當年意氣不肯平，白髮如絲歎何益。"]', '诗', 'shi', '', NULL, '前有一樽酒行二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d35fdc56-1086-4d5d-a99d-89fb16438732', '前有一樽酒行二首 二', '前有一樽酒行二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["琴奏龍門之綠桐，玉壺美酒清若空。","催弦拂柱與君飲，看朱成碧顏始紅。","胡姬貌如花，當壚笑春風。","笑春風，舞羅衣，君今不醉將安歸。"]', '["琴奏龙门之綠桐，玉壺美酒清若空。","催弦拂柱與君饮，看朱成碧顏始紅。","胡姬貌如花，當壚笑春风。","笑春风，舞羅衣，君今不醉將安归。"]', '诗', 'shi', '', NULL, '前有一樽酒行二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a16e6544-8974-4234-a881-141beb0b6410', '夜坐吟', '夜坐吟', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["冬夜夜寒覺夜長，沈吟久坐坐北堂。","冰合井泉月入閨，金缸青凝照悲啼。","金缸滅，啼轉多。","掩妾淚，聽君歌。","歌有聲，妾有情。","情聲合，兩無違。","一語不入意，從君萬曲梁塵飛。"]', '["冬夜夜寒覺夜长，沈吟久坐坐北堂。","冰合井泉月入閨，金缸青凝照悲啼。","金缸滅，啼轉多。","掩妾泪，听君歌。","歌有声，妾有情。","情声合，兩無違。","一語不入意，從君万曲梁塵飞。"]', '诗', 'shi', '', NULL, '夜坐吟 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10465c42-a713-4a5d-9c02-2701a2bf7810', '野田黃雀行', '野田黄雀行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["遊莫逐炎洲翠，棲莫近吳宮燕。","吳宮火起焚巢窠，炎洲逐翠遭網羅。","蕭條兩翅蓬蒿下，縱有鷹鸇奈若何。"]', '["游莫逐炎洲翠，棲莫近吳宮燕。","吳宮火起焚巢窠，炎洲逐翠遭網羅。","蕭條兩翅蓬蒿下，縱有鷹鸇奈若何。"]', '诗', 'shi', '', NULL, '野田黃雀行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('274f2db5-389b-4c17-b691-014fe104bc37', '箜篌謠', '箜篌謠', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["攀天莫登龍，走山莫騎虎。","貴賤結交心不移，唯有嚴陵及光武。","周公稱大聖，管蔡寧相容。","漢謠一斗粟，不與淮南舂。","兄弟尚路人，吾心安所從。","他人方寸間，山海幾千重。","輕言託朋友，對面九疑峯。","開花必早落，桃李不如松。"]', '["攀天莫登龙，走山莫騎虎。","貴賤結交心不移，唯有嚴陵及光武。","周公稱大聖，管蔡寧相容。","漢謠一斗粟，不與淮南舂。","兄弟尚路人，吾心安所從。","他人方寸间，山海幾千重。","轻言託朋友，对面九疑峯。","开花必早落，桃李不如松。"]', '诗', 'shi', '', NULL, '箜篌謠 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d551c27-4ca3-47db-ab84-2aa31be40feb', '雉朝飛', '雉朝飞', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["麥隴青青三月時，白雉朝飛挾兩雌。","錦衣繡翼何離褷，犢牧採薪感之悲。","春天和，白日暖。","啄食飲泉勇氣滿，爭雄鬬死繡頸斷。","雉子班奏急管弦，傾心酒美盡玉椀。","枯楊枯楊爾生稊，我獨七十而孤棲。","彈弦寫恨意不盡，瞑目歸黃泥。"]', '["麦隴青青三月时，白雉朝飞挾兩雌。","錦衣繡翼何離褷，犢牧採薪感之悲。","春天和，白日暖。","啄食饮泉勇氣满，爭雄鬬死繡頸斷。","雉子班奏急管弦，傾心酒美尽玉椀。","枯楊枯楊爾生稊，我独七十而孤棲。","彈弦寫恨意不尽，瞑目归黄泥。"]', '诗', 'shi', '', NULL, '雉朝飛 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b9bfba7-1d21-4b85-9a0f-5aace405f734', '上雲樂', '上云乐', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["金天之西，白日所沒。","康老胡雛，生彼月窟。","巉巖容儀，戌削風骨。","碧玉炅炅雙目瞳，黃金拳拳兩鬢紅。","華蓋垂下睫，嵩嶽臨上唇。","不覩詭譎貌，豈知造化神。","大道是文康之嚴父，元氣乃文康之老親。","撫頂弄盤古，推車轉天輪。","云見日月初生時，鑄冶火精與水銀。","陽烏未出谷，顧兔半藏身。","女媧戲黃土，團作愚下人。","散在六合間，濛濛若沙塵。","生死了不盡，誰明此胡是仙真。","西海栽若木，東溟植扶桑。","別來幾多時，枝葉萬里長。","中國有七聖，半路頹洪荒。","陛下應運起，龍飛入咸陽。","赤眉立盆子，白水興漢光。","叱咤四海動，洪濤爲簸揚。","舉足蹋紫微，天關自開張。","老胡感至德，東來進仙倡。","五色師子，九苞鳳皇。","是老胡雞犬，鳴舞飛帝鄉。","淋漓颯沓，進退成行。","能胡歌，獻漢酒。","跪雙膝，立兩肘。","散花指天舉素手，拜龍顏，獻聖壽。","北斗戾，南山摧。","天子九九八十一萬歲，長傾萬歲杯。"]', '["金天之西，白日所沒。","康老胡雛，生彼月窟。","巉巖容儀，戌削风骨。","碧玉炅炅雙目瞳，黄金拳拳兩鬢紅。","华蓋垂下睫，嵩嶽臨上唇。","不覩詭譎貌，豈知造化神。","大道是文康之嚴父，元氣乃文康之老親。","撫頂弄盤古，推车轉天輪。","云见日月初生时，鑄冶火精與水銀。","陽烏未出谷，顧兔半藏身。","女媧戲黄土，團作愚下人。","散在六合间，濛濛若沙塵。","生死了不尽，誰明此胡是仙真。","西海栽若木，东溟植扶桑。","別来幾多时，枝葉万里长。","中国有七聖，半路頹洪荒。","陛下應運起，龙飞入咸陽。","赤眉立盆子，白水兴漢光。","叱咤四海动，洪濤爲簸揚。","舉足蹋紫微，天关自开張。","老胡感至德，东来進仙倡。","五色師子，九苞鳳皇。","是老胡雞犬，鳴舞飞帝乡。","淋漓颯沓，進退成行。","能胡歌，獻漢酒。","跪雙膝，立兩肘。","散花指天舉素手，拜龙顏，獻聖壽。","北斗戾，南山摧。","天子九九八十一万歲，长傾万歲杯。"]', '诗', 'shi', '', NULL, '上雲樂 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6724facd-c665-4f60-9266-2488d09006e3', '白鳩辭', '白鳩辞', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["鏗鳴鐘，考朗鼓。","歌白鳩，引拂舞。","白鳩之白誰與隣，霜衣雪襟誠可珍。","含哺七子能平均，食不噎，性安馴，首農政，鳴陽春。","天子刻玉杖，鏤形賜耆人。","白鷺之白非純真，外潔其色心匪仁。","闕五德，無司晨，胡爲啄我葭下之紫鱗。","鷹鸇鵰鶚，貪而好殺。","鳳凰雖大聖，不願以爲臣。"]', '["鏗鳴鐘，考朗鼓。","歌白鳩，引拂舞。","白鳩之白誰與隣，霜衣雪襟誠可珍。","含哺七子能平均，食不噎，性安馴，首農政，鳴陽春。","天子刻玉杖，鏤形賜耆人。","白鷺之白非純真，外潔其色心匪仁。","闕五德，無司晨，胡爲啄我葭下之紫鱗。","鷹鸇鵰鶚，貪而好殺。","鳳凰雖大聖，不願以爲臣。"]', '诗', 'shi', '', NULL, '白鳩辭 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5ea326e-7443-4a7b-87e9-7d898afa1c85', '日出行', '日出行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["日出東方隈，似從地底來。","歷天又入海，六龍所舍安在哉？","其始與終古不息，人非元氣安得與之久裴徊。","草不謝榮於春風，木不怨落於秋天。","誰揮鞭策驅四運，萬物興歇皆自然。","羲和羲和，汝奚汨沒於荒淫之波。","魯陽何德，駐景揮戈。","逆道違天，矯誣實多。","吾將囊括大塊，浩然與溟涬同科。"]', '["日出东方隈，似從地底来。","歷天又入海，六龙所舍安在哉？","其始與終古不息，人非元氣安得與之久裴徊。","草不謝榮於春风，木不怨落於秋天。","誰揮鞭策驱四運，万物兴歇皆自然。","羲和羲和，汝奚汨沒於荒淫之波。","魯陽何德，駐景揮戈。","逆道違天，矯誣實多。","吾將囊括大塊，浩然與溟涬同科。"]', '诗', 'shi', '', NULL, '日出行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2768bca-cffd-4616-b1ff-3ead592f6f28', '胡無人', '胡無人', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["嚴風吹霜海草凋，筋幹精堅胡馬驕。","漢家戰士三十萬，將軍兼領霍嫖姚。","流星白羽腰間插，劒花秋蓮光出匣。","天兵照雪下玉關，虜箭如沙射金甲。","雲龍風虎盡交回，太白入月敵可摧。","敵可摧，旄頭滅，履胡之腸涉胡血。","懸胡青天上，埋胡紫塞傍。","胡無人，漢道昌。"]', '["嚴风吹霜海草凋，筋幹精堅胡马驕。","漢家戰士三十万，將軍兼領霍嫖姚。","流星白羽腰间插，劒花秋蓮光出匣。","天兵照雪下玉关，虜箭如沙射金甲。","云龙风虎尽交回，太白入月敵可摧。","敵可摧，旄头滅，履胡之腸涉胡血。","懸胡青天上，埋胡紫塞傍。","胡無人，漢道昌。"]', '诗', 'shi', '', NULL, '胡無人 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c38a852c-9bf1-4ce5-9c91-80a9d1ec34b0', '北風行', '北风行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["燭龍棲寒門，光曜猶旦開。","日月照之何不及此，唯有北風號怒天上來。","燕山雪花大如席，片片吹落軒轅臺。","幽州思婦十二月，停歌罷笑雙蛾摧。","倚門望行人，念君長城苦寒良可哀。","別時提劒救邊去，遺此虎紋金鞞靫。","中有一雙白羽箭，蜘蛛結網生塵埃。","箭空在，人今戰死不復回。","不忍見此物，焚之已成灰。","黃河捧土尚可塞，北風雨雪恨難裁。"]', '["燭龙棲寒门，光曜猶旦开。","日月照之何不及此，唯有北风號怒天上来。","燕山雪花大如席，片片吹落軒轅台。","幽州思婦十二月，停歌罷笑雙蛾摧。","倚门望行人，念君长城苦寒良可哀。","別时提劒救邊去，遺此虎紋金鞞靫。","中有一雙白羽箭，蜘蛛結網生塵埃。","箭空在，人今戰死不复回。","不忍见此物，焚之已成灰。","黄河捧土尚可塞，北风雨雪恨难裁。"]', '诗', 'shi', '', NULL, '北風行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b5af006-ef8b-4e17-8109-a2824e4e720f', '俠客行', '俠客行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["趙客縵胡纓，吳鉤霜雪明。","銀鞍照白馬，颯沓如流星。","十步殺一人，千里不留行。","事了拂衣去，深藏身與名。","閑過信陵飲，脫劒膝前橫。","將炙啖朱亥，持觴勸侯嬴。","三盃吐然諾，五嶽倒爲輕。","眼花耳熱後，意氣素霓生。","救趙揮金槌，邯鄲先震驚。","千秋二壯士，烜赫大梁城。","縱死俠骨香，不慙世上英。","誰能書閤下，白首太玄經。"]', '["趙客縵胡纓，吳鉤霜雪明。","銀鞍照白马，颯沓如流星。","十步殺一人，千里不留行。","事了拂衣去，深藏身與名。","闲過信陵饮，脫劒膝前橫。","將炙啖朱亥，持觴勸侯嬴。","三盃吐然諾，五嶽倒爲轻。","眼花耳熱後，意氣素霓生。","救趙揮金槌，邯鄲先震驚。","千秋二壯士，烜赫大梁城。","縱死俠骨香，不慙世上英。","誰能书閤下，白首太玄經。"]', '诗', 'shi', '', NULL, '俠客行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4be77185-992e-4614-9746-de2e73c8a3c3', '關山月', '关山月', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["明月出天山，蒼茫雲海間。","長風幾萬里，吹度玉門關。","漢下白登道，胡窺青海灣。","由來征戰地，不見有人還。","[戍]客望邊色，思歸多苦顏。","高樓當此夜，歎息未應閑。"]', '["明月出天山，蒼茫云海间。","长风幾万里，吹度玉门关。","漢下白登道，胡窺青海灣。","由来征戰地，不见有人還。","[戍]客望邊色，思归多苦顏。","高楼當此夜，歎息未應闲。"]', '诗', 'shi', '', NULL, '關山月 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4afd4e21-8573-4595-b205-ec65a5462c73', '獨漉篇', '独漉篇', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["獨漉水中泥，水濁不見月。","不見月尚可，水深行人沒。","越鳥從南來，胡鷹亦北渡。","我欲彎弓向天射，惜其中道失歸路。","落葉別樹，飄零隨風。","客無所托，悲與此同。","羅幃舒卷，似有人開。","明月直入，無心可猜。","雄劒挂壁，時時龍鳴。","不斷犀象，繡澀苔生。","國耻未雪，何由成名。","神鷹夢澤，不顧鴟鳶。","爲君一擊，鵬[摶]鵬九天。"]', '["独漉水中泥，水濁不见月。","不见月尚可，水深行人沒。","越鸟從南来，胡鷹亦北渡。","我欲彎弓向天射，惜其中道失归路。","落葉別樹，飄零隨风。","客無所托，悲與此同。","羅幃舒卷，似有人开。","明月直入，無心可猜。","雄劒挂壁，时时龙鳴。","不斷犀象，繡澀苔生。","国耻未雪，何由成名。","神鷹梦澤，不顧鴟鳶。","爲君一擊，鵬[摶]鵬九天。"]', '诗', 'shi', '', NULL, '獨漉篇 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab3b9829-9a24-484e-9c99-1152c7cbfde5', '登高丘而望遠', '登高丘而望远', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["登高丘，望遠海。","六鼇骨已霜，三山流安在。","扶桑半摧折，白日沈光彩。","銀臺金闕如夢中，秦皇漢武空相待。","精衛費木石，黿鼉無所憑。","君不見驪山茂陵盡灰滅，牧羊之子來攀登。","盜賊劫寶玉，精靈竟何能。","窮兵黷武今如此，鼎湖飛龍安可乘。"]', '["登高丘，望远海。","六鼇骨已霜，三山流安在。","扶桑半摧折，白日沈光彩。","銀台金闕如梦中，秦皇漢武空相待。","精衛費木石，黿鼉無所憑。","君不见驪山茂陵尽灰滅，牧羊之子来攀登。","盜賊劫寶玉，精靈竟何能。","窮兵黷武今如此，鼎湖飞龙安可乘。"]', '诗', 'shi', '', NULL, '登高丘而望遠 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7527539f-7be4-42a0-a5aa-805fa72c5e38', '陽春歌', '陽春歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["長安白日照春空，綠楊結烟垂裊風。","披香殿前花始紅，流芳發色繡戶中。","繡戶中，相經過，飛燕皇后輕身舞，紫宮夫人絕世歌。"]', '["长安白日照春空，綠楊結烟垂裊风。","披香殿前花始紅，流芳發色繡戶中。","繡戶中，相經過，飞燕皇后轻身舞，紫宮夫人絕世歌。"]', '诗', 'shi', '', NULL, '陽春歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fc1c656-8a56-498c-8641-e1d2e438b912', '楊叛兒', '楊叛兒', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["君歌楊叛兒，妾勸新豐酒。","何許最關人，烏啼白門柳。","烏啼隱楊花，君醉留妾家。","博山爐中沈香火，雙煙一氣凌紫霞。"]', '["君歌楊叛兒，妾勸新豐酒。","何許最关人，烏啼白门柳。","烏啼隐楊花，君醉留妾家。","博山爐中沈香火，雙煙一氣凌紫霞。"]', '诗', 'shi', '', NULL, '楊叛兒 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb42467b-d4b5-4703-b6d8-871a737e0892', '雙燕離', '雙燕離', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["雙燕復雙燕，雙飛令人羨。","玉樓珠閣不獨棲，金窗繡戶長相見。","柏梁失火去，因入吳王宮。","吳宮又焚蕩，雛盡巢亦空。","憔悴一身在，孀雌憶故雄。","雙飛難再得，傷我寸心中。"]', '["雙燕复雙燕，雙飞令人羨。","玉楼珠閣不独棲，金窗繡戶长相见。","柏梁失火去，因入吳王宮。","吳宮又焚蕩，雛尽巢亦空。","憔悴一身在，孀雌憶故雄。","雙飞难再得，傷我寸心中。"]', '诗', 'shi', '', NULL, '雙燕離 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66121e3b-7ca9-4890-a45d-d34c006c0328', '山人勸酒', '山人勸酒', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["蒼蒼雲松，落落綺皓。","春風爾來爲阿誰，蝴蝶忽然滿芳草。","秀眉霜雪顏桃花，骨青髓綠長美好。","稱是秦時避世人，勸酒相歡不知老。","各守麋鹿志，耻隨龍虎爭。","歘起佐太子，漢王乃復驚。","顧謂戚夫人，彼翁羽翼成。","歸來商山下，泛若雲無情。","舉觴酹巢由，洗耳何獨清。","浩歌望嵩嶽，意氣還相傾。"]', '["蒼蒼云松，落落綺皓。","春风爾来爲阿誰，蝴蝶忽然满芳草。","秀眉霜雪顏桃花，骨青髓綠长美好。","稱是秦时避世人，勸酒相歡不知老。","各守麋鹿志，耻隨龙虎爭。","歘起佐太子，漢王乃复驚。","顧謂戚夫人，彼翁羽翼成。","归来商山下，泛若云無情。","舉觴酹巢由，洗耳何独清。","浩歌望嵩嶽，意氣還相傾。"]', '诗', 'shi', '', NULL, '山人勸酒 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b363f17-455e-4c34-a6b7-924b66a78bda', '于闐採花', '于闐採花', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["于闐採花人，自言花相似。","明妃一朝西入胡，胡中美女多羞死。","乃知漢地多名姝，胡中無花可方比。","丹青能令醜者妍，無鹽翻在深宮裏。","自古妬蛾眉，胡沙埋皓齒。"]', '["于闐採花人，自言花相似。","明妃一朝西入胡，胡中美女多羞死。","乃知漢地多名姝，胡中無花可方比。","丹青能令醜者妍，無鹽翻在深宮裏。","自古妬蛾眉，胡沙埋皓齒。"]', '诗', 'shi', '', NULL, '于闐採花 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b2e46d4-1af5-467f-a504-a16e25d51d1a', '鞠歌行', '鞠歌行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["玉不自言如桃李，魚目笑之卞和耻。","楚國青蠅何太多，連城白璧遭讒毀。","荆山長號泣血人，忠臣死爲刖足鬼。","聽曲知寧戚，夷吾因小妻。","秦穆五羊皮，買死百里奚。","洗拂青雲上，當時賤如泥。","朝歌鼓刀叟，虎變磻谿中。","一舉釣六合，遂荒營丘東。","平生渭水曲，誰識此老翁。","奈何今之人，雙目送飛鴻。"]', '["玉不自言如桃李，鱼目笑之卞和耻。","楚国青蠅何太多，連城白璧遭讒毀。","荆山长號泣血人，忠臣死爲刖足鬼。","听曲知寧戚，夷吾因小妻。","秦穆五羊皮，買死百里奚。","洗拂青云上，當时賤如泥。","朝歌鼓刀叟，虎变磻谿中。","一舉釣六合，遂荒營丘东。","平生渭水曲，誰識此老翁。","奈何今之人，雙目送飞鴻。"]', '诗', 'shi', '', NULL, '鞠歌行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47f80106-17f9-4d26-a4e4-6255b3ef872a', '幽澗泉', '幽澗泉', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["拂彼白石，彈吾素琴。","幽澗愀兮流泉深，善手明徽高張清。","心寂歷似千古，松颼飀兮萬尋。","中見愁猨弔影而危處兮，呌秋木而長吟。","客有哀時失職而聽者，淚淋浪以霑襟。","乃緝商輟羽，潺湲成音。","吾但寫聲發情於妙指，殊不知此曲之古今。","幽澗泉，鳴深林。"]', '["拂彼白石，彈吾素琴。","幽澗愀兮流泉深，善手明徽高張清。","心寂歷似千古，松颼飀兮万尋。","中见愁猨弔影而危处兮，呌秋木而长吟。","客有哀时失職而听者，泪淋浪以霑襟。","乃緝商輟羽，潺湲成音。","吾但寫声發情於妙指，殊不知此曲之古今。","幽澗泉，鳴深林。"]', '诗', 'shi', '', NULL, '幽澗泉 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44c40b37-9d4a-4abe-9b68-007e83e8fb4e', '王昭君二首 一', '王昭君二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["漢家秦地月，流影照明妃。","一上玉關道，天涯去不歸。","漢月還從東海出，明妃西嫁無來日。","燕支長寒雪作花，蛾眉憔悴沒胡沙。","生乏黃金枉圖畫，死留青冢使人嗟。"]', '["漢家秦地月，流影照明妃。","一上玉关道，天涯去不归。","漢月還從东海出，明妃西嫁無来日。","燕支长寒雪作花，蛾眉憔悴沒胡沙。","生乏黄金枉圖畫，死留青冢使人嗟。"]', '诗', 'shi', '', NULL, '王昭君二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67cde43b-5fa8-404d-a48e-09abb781f603', '王昭君二首 二', '王昭君二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["昭君拂玉鞍，上馬啼紅頰。","今日漢宮人，明朝胡地妾。"]', '["昭君拂玉鞍，上马啼紅頰。","今日漢宮人，明朝胡地妾。"]', '诗', 'shi', '', NULL, '王昭君二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e663ba8-49eb-41b9-a662-4f42f705d4b6', '中山孺子妾歌', '中山孺子妾歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["中山孺子妾，特以色見珍。","雖然不如延年妹，亦是當時絕世人。","桃李出深井，花豔驚上春。","一貴復一賤，關天豈由身。","芙蓉老秋霜，團扇羞網塵。","戚姬髡髮入舂市，萬古共悲辛。"]', '["中山孺子妾，特以色见珍。","雖然不如延年妹，亦是當时絕世人。","桃李出深井，花豔驚上春。","一貴复一賤，关天豈由身。","芙蓉老秋霜，團扇羞網塵。","戚姬髡髮入舂市，万古共悲辛。"]', '诗', 'shi', '', NULL, '中山孺子妾歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67b08a36-4eb4-47a1-b8fc-7fc3ee888f3d', '荆州歌', '荆州歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白帝城邊足風波，瞿塘五月誰敢過。","荆州麥熟繭成蛾，繅絲憶君頭緒多，撥穀飛鳴奈妾何。"]', '["白帝城邊足风波，瞿塘五月誰敢過。","荆州麦熟繭成蛾，繅絲憶君头緒多，撥穀飞鳴奈妾何。"]', '诗', 'shi', '', NULL, '荆州歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e402e3c-d2a6-46aa-aaba-1289ab9c5b1d', '雉子斑', '雉子斑', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["辟邪伎作鼓吹驚，雉子班之奏曲成，喔咿振迅欲飛鳴。","扇錦翼，雄風生。","雙雌同飲啄，趫悍誰能爭。","乍向草中耿介死，不求黃金籠下生。","天地至廣大，何惜遂物情。","善卷讓天子，務光亦逃名。","所貴曠士懷，朗然合太清。"]', '["辟邪伎作鼓吹驚，雉子班之奏曲成，喔咿振迅欲飞鳴。","扇錦翼，雄风生。","雙雌同饮啄，趫悍誰能爭。","乍向草中耿介死，不求黄金籠下生。","天地至廣大，何惜遂物情。","善卷讓天子，務光亦逃名。","所貴曠士懷，朗然合太清。"]', '诗', 'shi', '', NULL, '雉子斑 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f45b5770-f5ae-43a9-a039-c532cd66196a', '相逢行', '相逢行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["相逢紅塵內，高揖黃金鞭。","萬戶垂楊裏，君家阿那邊。"]', '["相逢紅塵內，高揖黄金鞭。","万戶垂楊裏，君家阿那邊。"]', '诗', 'shi', '', NULL, '相逢行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4da568ec-903b-485d-9994-0dd520c74410', '有所思', '有所思', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我思仙人乃在碧海之東隅，海寒多天風，白波連山倒蓬壺。","長鯨噴湧不可涉，撫心茫茫淚如珠。","西來青鳥東飛去，願寄一書謝麻姑。"]', '["我思仙人乃在碧海之东隅，海寒多天风，白波連山倒蓬壺。","长鯨噴湧不可涉，撫心茫茫泪如珠。","西来青鸟东飞去，願寄一书謝麻姑。"]', '诗', 'shi', '', NULL, '有所思 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58d13f67-ff43-4bbb-94d4-bb64f1f5b48f', '久別離', '久別離', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["別來幾春未還家，玉窗五見櫻桃花。","況有錦字書，開緘使人嗟。","至此腸斷彼心絕，雲鬟綠鬢罷梳結，愁如回飆亂白雪。","去年寄書報陽臺，今年寄書重相催。","東風兮東風，爲我吹行雲使西來。","待來竟不來，落花寂寂委清苔。"]', '["別来幾春未還家，玉窗五见櫻桃花。","況有錦字书，开緘使人嗟。","至此腸斷彼心絕，云鬟綠鬢罷梳結，愁如回飆亂白雪。","去年寄书報陽台，今年寄书重相催。","东风兮东风，爲我吹行云使西来。","待来竟不来，落花寂寂委清苔。"]', '诗', 'shi', '', NULL, '久別離 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f51e574b-61c2-45fb-b60d-2de4ecae9ce3', '白頭吟', '白头吟', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["錦水東北流，波蕩雙鴛鴦。","雄巢漢宮樹，雌弄秦草芳。","寧同萬死碎綺翼，不忍雲間兩分張。","此時阿嬌正嬌妬，獨坐長門愁日暮。","但願君恩顧妾深，豈惜黃金買詞賦。","相如作賦得黃金，丈夫好新多異心。","一朝將聘茂陵女，文君因贈白頭吟。","東流不作西歸水，落花辭條羞故林。","兔絲固無情，隨風任傾倒。","誰使女蘿枝，而來强縈抱。","兩草猶一心，人心不如草。","莫卷龍鬚席，從他生網絲。","且留琥珀枕，或有夢來時。","覆水再收豈滿杯，棄妾已去難重迴。","古來得意不相負，祇今惟見青陵臺。"]', '["錦水东北流，波蕩雙鴛鴦。","雄巢漢宮樹，雌弄秦草芳。","寧同万死碎綺翼，不忍云间兩分張。","此时阿嬌正嬌妬，独坐长门愁日暮。","但願君恩顧妾深，豈惜黄金買词賦。","相如作賦得黄金，丈夫好新多異心。","一朝將聘茂陵女，文君因贈白头吟。","东流不作西归水，落花辞條羞故林。","兔絲固無情，隨风任傾倒。","誰使女蘿枝，而来强縈抱。","兩草猶一心，人心不如草。","莫卷龙鬚席，從他生網絲。","且留琥珀枕，或有梦来时。","覆水再收豈满杯，棄妾已去难重迴。","古来得意不相負，祇今惟见青陵台。"]', '诗', 'shi', '', NULL, '白頭吟 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b15fb5e8-46e1-4266-8371-e2bc1383f840', '採蓮曲', '採蓮曲', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["若耶谿傍採蓮女，笑隔荷花共人語。","日照新妝水底明，風飄香袂空中舉。","岸上誰家遊冶郎，三三五五暎垂楊。","紫騮嘶入落花去，見此踟躕空斷腸。"]', '["若耶谿傍採蓮女，笑隔荷花共人語。","日照新妝水底明，风飄香袂空中舉。","岸上誰家游冶郎，三三五五暎垂楊。","紫騮嘶入落花去，见此踟躕空斷腸。"]', '诗', 'shi', '', NULL, '採蓮曲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44112ea6-a06c-485d-b2dd-21b94dda7b13', '臨江王節士歌', '臨江王節士歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["洞庭白波木葉稀，燕鴻始入吳雲飛。","吳雲寒，燕鴻苦，風號沙宿瀟湘浦。","節士悲秋淚如雨，白日當天心。","照之可以事明主，壯士憤，雄風生。","安得倚天劒，跨海斬長鯨。"]', '["洞庭白波木葉稀，燕鴻始入吳云飞。","吳云寒，燕鴻苦，风號沙宿瀟湘浦。","節士悲秋泪如雨，白日當天心。","照之可以事明主，壯士憤，雄风生。","安得倚天劒，跨海斬长鯨。"]', '诗', 'shi', '', NULL, '臨江王節士歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9831fd2a-a86f-4def-9bdd-97e5a8759d8a', '司馬將軍歌', '司马將軍歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["狂風吹古月，竊弄章華臺。","北落明星動光彩，南征猛將如雲雷。","手中電擊倚天劒，直斬長鯨海水開。","我見樓船壯心目，頗似龍驤下三蜀。","揚兵習戰張虎旗，江中白浪如銀屋。","身居玉帳臨河魁，紫髯若戟冠崔嵬。","細柳開營揖天子，始知灞上爲嬰孩。","羌笛橫吹阿嚲迴，向月樓中吹落梅。","將軍自起舞長劒，壯士呼聲動九垓。","功成獻凱見明主，丹青畫象麒麟臺。"]', '["狂风吹古月，竊弄章华台。","北落明星动光彩，南征猛將如云雷。","手中電擊倚天劒，直斬长鯨海水开。","我见楼船壯心目，頗似龙驤下三蜀。","揚兵習戰張虎旗，江中白浪如銀屋。","身居玉帳臨河魁，紫髯若戟冠崔嵬。","細柳开營揖天子，始知灞上爲嬰孩。","羌笛橫吹阿嚲迴，向月楼中吹落梅。","將軍自起舞长劒，壯士呼声动九垓。","功成獻凱见明主，丹青畫象麒麟台。"]', '诗', 'shi', '', NULL, '司馬將軍歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dfa2d12-9bbf-4cd9-80cf-73d7feedc19d', '君道曲', '君道曲', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["大君若天覆，廣運無不至。","軒后爪牙嘗先太山稽，如心之使臂。","小白鴻翼於夷吾，劉葛魚水本無二。","土校可成牆，積德爲厚地。"]', '["大君若天覆，廣運無不至。","軒后爪牙嘗先太山稽，如心之使臂。","小白鴻翼於夷吾，劉葛鱼水本無二。","土校可成牆，積德爲厚地。"]', '诗', 'shi', '', NULL, '君道曲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc53625c-820a-4ac4-987a-45c3b9b9c361', '結襪子', '結襪子', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["燕南壯士吳門豪，筑中置鉛魚隱刀。","感君恩重許君命，太山一擲輕鴻毛。"]', '["燕南壯士吳门豪，筑中置鉛鱼隐刀。","感君恩重許君命，太山一擲轻鴻毛。"]', '诗', 'shi', '', NULL, '結襪子 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7de71ee6-bbcf-47c1-a552-3bf83fe88f95', '結客少年場行', '結客少年場行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["紫燕黃金瞳，啾啾搖綠鬉。","平明相馳逐，結客洛門東。","少年學劒術，凌轢白猨公。","珠袍曳錦帶，匕首插吳鴻。","由來萬夫勇，挾此生雄風。","託交從劇孟，買醉入新豐。","笑盡一杯酒，殺人都市中。","羞道易水寒，從令日貫虹。","燕丹事不立，虛沒秦帝宮。","舞陽死灰人，安可與成功。"]', '["紫燕黄金瞳，啾啾搖綠鬉。","平明相驰逐，結客洛门东。","少年学劒術，凌轢白猨公。","珠袍曳錦带，匕首插吳鴻。","由来万夫勇，挾此生雄风。","託交從劇孟，買醉入新豐。","笑尽一杯酒，殺人都市中。","羞道易水寒，從令日貫虹。","燕丹事不立，虛沒秦帝宮。","舞陽死灰人，安可與成功。"]', '诗', 'shi', '', NULL, '結客少年場行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b867382-97cb-47c3-aa9a-c3fe87346200', '長干行二首 一', '长干行二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["妾髮初覆額，折花門前劇。","郎騎竹馬來，繞牀弄青梅。","同居長干里，兩小無嫌猜。","十四爲君婦，羞顏未嘗開。","低頭向暗壁，千喚不一迴。","十五始展眉，願同塵與灰。","常存抱柱信，豈上望夫臺。","十六君遠行，瞿塘灩澦堆。","五月不可觸，猨聲天上哀。","門前遲行跡，一一生綠苔。","苔深不能掃，落葉秋風早。","八月胡蝶來，雙飛西園草。","感此傷妾心，坐愁紅顏老。","早晚下三巴，預將書報家。","相迎不道遠，直至長風沙。"]', '["妾髮初覆額，折花门前劇。","郎騎竹马来，繞牀弄青梅。","同居长干里，兩小無嫌猜。","十四爲君婦，羞顏未嘗开。","低头向暗壁，千喚不一迴。","十五始展眉，願同塵與灰。","常存抱柱信，豈上望夫台。","十六君远行，瞿塘灩澦堆。","五月不可觸，猨声天上哀。","门前遲行跡，一一生綠苔。","苔深不能掃，落葉秋风早。","八月胡蝶来，雙飞西园草。","感此傷妾心，坐愁紅顏老。","早晚下三巴，預將书報家。","相迎不道远，直至长风沙。"]', '诗', 'shi', '', NULL, '長干行二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eea15433-e507-48d7-acf5-4e9c0baf5172', '長干行二首 二', '长干行二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["憶妾深閨裏，煙塵不曾識。","嫁與長干人，沙頭候風色。","五月南風興，思君下巴陵。","八月西風起，想君發揚子。","去來悲如何，見少離別多。","湘潭幾日到，妾夢越風波。","昨夜狂風度，吹折江頭樹。","淼淼暗無邊，行人在何處？","好乘浮雲驄，佳期蘭渚東。","鴛鴦綠蒲上，翡翠錦屏中。","自憐十五餘，顏色桃花紅。","那作商人婦，愁水復愁風。"]', '["憶妾深閨裏，煙塵不曾識。","嫁與长干人，沙头候风色。","五月南风兴，思君下巴陵。","八月西风起，想君發揚子。","去来悲如何，见少離別多。","湘潭幾日到，妾梦越风波。","昨夜狂风度，吹折江头樹。","淼淼暗無邊，行人在何处？","好乘浮云驄，佳期蘭渚东。","鴛鴦綠蒲上，翡翠錦屏中。","自怜十五餘，顏色桃花紅。","那作商人婦，愁水复愁风。"]', '诗', 'shi', '', NULL, '長干行二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('129c074d-f123-45d1-8062-ba949dcc8c6f', '古朗月行', '古朗月行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["小時不識月，呼作白玉盤。","又疑瑤臺鏡，飛在白雲端。","仙人垂兩足，桂樹作團團。","白兔擣藥成，問言與誰餐。","蟾蜍蝕圓影，大明夜已殘。","羿昔落九烏，天人清且安。","陰精此淪惑，去去不足觀。","憂來其如何，悽愴摧心肝。"]', '["小时不識月，呼作白玉盤。","又疑瑤台镜，飞在白云端。","仙人垂兩足，桂樹作團團。","白兔擣藥成，问言與誰餐。","蟾蜍蝕圓影，大明夜已殘。","羿昔落九烏，天人清且安。","陰精此淪惑，去去不足观。","憂来其如何，悽愴摧心肝。"]', '诗', 'shi', '', NULL, '古朗月行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f952bb0c-ab9e-4025-b771-c25f2e68c6e0', '上之回', '上之回', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["三十六離宮，樓臺與天通。","閣道步行月，美人愁烟空。","恩疎寵不及，桃李傷春風。","淫樂意何極，金輿向回中。","萬乘出黃道，千旗揚彩虹。","前軍細柳北，後騎甘泉東。","豈問渭川老，寧邀襄野童。","但慕瑤池宴，歸來樂未窮。"]', '["三十六離宮，楼台與天通。","閣道步行月，美人愁烟空。","恩疎寵不及，桃李傷春风。","淫乐意何極，金輿向回中。","万乘出黄道，千旗揚彩虹。","前軍細柳北，後騎甘泉东。","豈问渭川老，寧邀襄野童。","但慕瑤池宴，归来乐未窮。"]', '诗', 'shi', '', NULL, '上之回 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d930f6e0-9a15-4d8e-a527-4a4af0264faf', '獨不見', '独不见', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白馬誰家子，黃龍邊塞兒。","天山三丈雪，豈是遠行時。","春蕙忽秋草，莎雞鳴西池。","風摧寒椶響，月入霜閨悲。","憶與君別年，種桃齊蛾眉。","桃今百餘尺，花落成枯枝。","終然獨不見，流淚空自知。"]', '["白马誰家子，黄龙邊塞兒。","天山三丈雪，豈是远行时。","春蕙忽秋草，莎雞鳴西池。","风摧寒椶响，月入霜閨悲。","憶與君別年，種桃齊蛾眉。","桃今百餘尺，花落成枯枝。","終然独不见，流泪空自知。"]', '诗', 'shi', '', NULL, '獨不見 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37fbfbfd-1054-4eb2-bebf-b9bd36fdf3fc', '白紵辭三首 一', '白紵辞三首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["揚清歌，發皓齒，北方佳人東隣子。","且吟白紵停綠水，長袖拂面爲君起。","寒雲夜卷霜海空，胡風吹天飄塞鴻。","玉顏滿堂樂未終，館娃日落歌吹濛。"]', '["揚清歌，發皓齒，北方佳人东隣子。","且吟白紵停綠水，长袖拂面爲君起。","寒云夜卷霜海空，胡风吹天飄塞鴻。","玉顏满堂乐未終，館娃日落歌吹濛。"]', '诗', 'shi', '', NULL, '白紵辭三首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('192d012f-dbdd-4e79-a298-d741ce0d970c', '白紵辭三首 二', '白紵辞三首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["月寒江清夜沈沈，美人一笑千黃金。","垂羅舞縠揚哀音，郢中白雪且莫吟。","子夜吳歌動君心，動君心，冀君賞。","願作天池雙鴛鴦，一朝飛去青雲上。"]', '["月寒江清夜沈沈，美人一笑千黄金。","垂羅舞縠揚哀音，郢中白雪且莫吟。","子夜吳歌动君心，动君心，冀君賞。","願作天池雙鴛鴦，一朝飞去青云上。"]', '诗', 'shi', '', NULL, '白紵辭三首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea94670a-dd28-4d73-b574-bde1a0c70096', '白紵辭三首 三', '白紵辞三首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["吳刀剪綵縫舞衣，明妝麗服奪春暉。","揚眉轉袖若雪飛，傾城獨立世所稀。","激楚結風醉忘歸，高堂月落燭已微，玉釵挂纓君莫違。"]', '["吳刀剪綵縫舞衣，明妝丽服奪春暉。","揚眉轉袖若雪飞，傾城独立世所稀。","激楚結风醉忘归，高堂月落燭已微，玉釵挂纓君莫違。"]', '诗', 'shi', '', NULL, '白紵辭三首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49cc1160-8842-4a0a-9a6d-fa2691896914', '鳴雁行', '鳴雁行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["胡雁鳴，辭燕山，昨發委羽朝度關。","一一銜蘆枝，南飛散落天地間。","連行接翼往復還，客居煙波寄湘吳。","凌霜觸雪毛體枯，畏逢矰繳驚相呼。","聞弦虛墜良可吁，君更彈射何爲乎。"]', '["胡雁鳴，辞燕山，昨發委羽朝度关。","一一銜蘆枝，南飞散落天地间。","連行接翼往复還，客居煙波寄湘吳。","凌霜觸雪毛體枯，畏逢矰繳驚相呼。","闻弦虛墜良可吁，君更彈射何爲乎。"]', '诗', 'shi', '', NULL, '鳴雁行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f210fe0-a8a6-4a86-bc29-323c214c7212', '妾薄命', '妾薄命', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["漢帝寵阿嬌，貯之黃金屋。","咳唾落九天，隨風生珠玉。","寵極愛還歇，妬深情却疎。","長門一步地，不肯暫迴車。","雨落不上天，水覆難再收。","君情與妾意，各自東西流。","昔日芙蓉花，今成斷根草。","以色事他人，能得幾時好。"]', '["漢帝寵阿嬌，貯之黄金屋。","咳唾落九天，隨风生珠玉。","寵極愛還歇，妬深情却疎。","长门一步地，不肯暫迴车。","雨落不上天，水覆难再收。","君情與妾意，各自东西流。","昔日芙蓉花，今成斷根草。","以色事他人，能得幾时好。"]', '诗', 'shi', '', NULL, '妾薄命 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e14f3c7a-4453-48e0-9296-ff4749acf823', '幽州胡馬客歌', '幽州胡马客歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["幽州胡馬客，綠眼虎皮冠。","笑拂兩隻箭，萬人不可干。","彎弓若轉月，白雁落雲端。","雙雙掉鞭行，遊獵向樓蘭。","出門不顧後，報國死何難。","天驕五單于，狼戾好兇殘。","牛馬散北海，割鮮若虎餐。","雖居燕支山，不道朔雪寒。","婦女馬上笑，顏如赬玉盤。","飜飛射鳥獸，花月醉雕鞍。","旄頭四光芒，爭戰若蜂攢。","白刃灑赤血，流沙爲之丹。","名將古誰是，疲兵良可歎。","何時天狼滅，父子得閑安。"]', '["幽州胡马客，綠眼虎皮冠。","笑拂兩隻箭，万人不可干。","彎弓若轉月，白雁落云端。","雙雙掉鞭行，游獵向楼蘭。","出门不顧後，報国死何难。","天驕五單于，狼戾好兇殘。","牛马散北海，割鲜若虎餐。","雖居燕支山，不道朔雪寒。","婦女马上笑，顏如赬玉盤。","飜飞射鸟獸，花月醉雕鞍。","旄头四光芒，爭戰若蜂攢。","白刃灑赤血，流沙爲之丹。","名將古誰是，疲兵良可歎。","何时天狼滅，父子得闲安。"]', '诗', 'shi', '', NULL, '幽州胡馬客歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ea1c888-9993-4aae-9019-ae3e8540c426', '門有車馬客行', '门有车马客行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["門有車馬賓，金鞍曜朱輪。","謂從丹霄落，乃是故鄉親。","呼兒掃中堂，坐客論悲辛。","對酒兩不飲，停觴淚盈巾。","歎我萬里遊，飄飄三十春。","空談帝王略，紫綬不挂身。","雄劒藏玉匣，陰符生素塵。","廓落無所合，流離湘水濱。","借問宗黨間，多爲泉下人。","生苦百戰役，死託萬鬼隣。","北風揚胡沙，埋翳周與秦。","大運且如此，蒼穹寧匪仁。","惻愴竟何道，存亡任大鈞。"]', '["门有车马賓，金鞍曜朱輪。","謂從丹霄落，乃是故乡親。","呼兒掃中堂，坐客論悲辛。","对酒兩不饮，停觴泪盈巾。","歎我万里游，飄飄三十春。","空談帝王略，紫綬不挂身。","雄劒藏玉匣，陰符生素塵。","廓落無所合，流離湘水濱。","借问宗黨间，多爲泉下人。","生苦百戰役，死託万鬼隣。","北风揚胡沙，埋翳周與秦。","大運且如此，蒼穹寧匪仁。","惻愴竟何道，存亡任大鈞。"]', '诗', 'shi', '', NULL, '門有車馬客行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('097b32ad-0a73-44c6-a709-f351b531b1fd', '君子有所思行', '君子有所思行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["紫閣連終南，青冥天倪色。","凭崖望咸陽，宮闕羅北極。","萬井驚畫出，九衢如弦直。","渭水銀河清，橫天流不息。","朝野盛文物，衣冠何翕赩。","廄馬散連山，軍容威絕域。","伊臯運元化，衛霍輸筋力。","歌鐘樂未休，榮去老還逼。","圓光過滿缺，太陽移中昃。","不散東海金，何爭西飛匿。","無作牛山悲，惻愴淚沾臆。"]', '["紫閣連終南，青冥天倪色。","凭崖望咸陽，宮闕羅北極。","万井驚畫出，九衢如弦直。","渭水銀河清，橫天流不息。","朝野盛文物，衣冠何翕赩。","廄马散連山，軍容威絕域。","伊臯運元化，衛霍輸筋力。","歌鐘乐未休，榮去老還逼。","圓光過满缺，太陽移中昃。","不散东海金，何爭西飞匿。","無作牛山悲，惻愴泪沾臆。"]', '诗', 'shi', '', NULL, '君子有所思行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ab63c87-1bed-4f96-8fa4-8431f0f41635', '東海有勇婦', '东海有勇婦', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["梁山感杞妻，慟哭爲之傾。","金石忽蹔開，都由激深情。","東海有勇婦，何慚蘇子卿。","學劒越處子，超然若流星。","損軀報夫讎，萬死不顧生。","白刃耀素雪，蒼天感精誠。","十步兩躩躍，三呼一交兵。","斬首掉國門，蹴踏五藏行。","豁此伉儷憤，粲然大義明。","北海李使君，飛章奏天庭。","捨罪警風俗，流芳播滄瀛。","名在列女籍，竹帛已光榮。","淳于免詔獄，漢主爲緹縈。","津妾一櫂歌，脫父於嚴刑。","十子若不肖，不如一女英。","豫讓斬空衣，有心竟無成。","要離殺慶忌，壯夫所素輕。","妻子亦何辜，焚之買虛聲。","豈如東海婦，事立獨揚名。"]', '["梁山感杞妻，慟哭爲之傾。","金石忽蹔开，都由激深情。","东海有勇婦，何慚蘇子卿。","学劒越处子，超然若流星。","損軀報夫讎，万死不顧生。","白刃耀素雪，蒼天感精誠。","十步兩躩躍，三呼一交兵。","斬首掉国门，蹴踏五藏行。","豁此伉儷憤，粲然大義明。","北海李使君，飞章奏天庭。","捨罪警风俗，流芳播滄瀛。","名在列女籍，竹帛已光榮。","淳于免詔獄，漢主爲緹縈。","津妾一櫂歌，脫父於嚴刑。","十子若不肖，不如一女英。","豫讓斬空衣，有心竟無成。","要離殺慶忌，壯夫所素轻。","妻子亦何辜，焚之買虛声。","豈如东海婦，事立独揚名。"]', '诗', 'shi', '', NULL, '東海有勇婦 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('930d51d8-bb63-49f3-881a-e3a90f3ea030', '黃葛篇', '黄葛篇', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["黃葛生洛溪，黃花自綿冪。","青烟蔓長條，繚繞幾百尺。","閨人費素手，採緝作絺綌。","縫爲絕國衣，遠寄日南客。","蒼梧大火落，暑服莫輕擲。","此物雖過時，是妾手中跡。"]', '["黄葛生洛溪，黄花自綿冪。","青烟蔓长條，繚繞幾百尺。","閨人費素手，採緝作絺綌。","縫爲絕国衣，远寄日南客。","蒼梧大火落，暑服莫轻擲。","此物雖過时，是妾手中跡。"]', '诗', 'shi', '', NULL, '黃葛篇 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03af61b5-34a7-40bd-98a2-26ef86291097', '白馬篇', '白马篇', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["龍馬花雪毛，金鞍五陵豪。","秋霜切玉劒，落日明珠袍。","鬬雞事萬乘，軒蓋一何高。","弓摧南山虎，手接太行猱。","酒後競風采，三杯弄寶刀。","殺人如剪草，劇孟同遊遨。","發憤去函谷，從軍向臨洮。","叱咤萬戰場，匈奴盡奔逃。","歸來使酒氣，未肯拜蕭曹。","羞入原憲室，荒淫隱蓬蒿。"]', '["龙马花雪毛，金鞍五陵豪。","秋霜切玉劒，落日明珠袍。","鬬雞事万乘，軒蓋一何高。","弓摧南山虎，手接太行猱。","酒後競风采，三杯弄寶刀。","殺人如剪草，劇孟同游遨。","發憤去函谷，從軍向臨洮。","叱咤万戰場，匈奴尽奔逃。","归来使酒氣，未肯拜蕭曹。","羞入原憲室，荒淫隐蓬蒿。"]', '诗', 'shi', '', NULL, '白馬篇 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfb66f37-ac9a-4054-bc83-c8f71c2da690', '鳳吹笙曲', '鳳吹笙曲', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["仙人十五愛吹笙，學得崑丘彩鳳鳴。","始聞鍊氣餐金液，復道朝天赴玉京。","玉京迢迢幾千里，鳳笙去去無窮已。","欲歎離聲發絳脣，更嗟別調流纖指。","此時惜別詎堪聞，此地相看未忍分。","重吟真曲和清吹，却奏仙歌響綠雲。","綠雲紫氣向函關，訪道應尋緱氏山。","莫學吹笙王子晉，一遇浮丘斷不還。"]', '["仙人十五愛吹笙，学得崑丘彩鳳鳴。","始闻鍊氣餐金液，复道朝天赴玉京。","玉京迢迢幾千里，鳳笙去去無窮已。","欲歎離声發絳脣，更嗟別調流纖指。","此时惜別詎堪闻，此地相看未忍分。","重吟真曲和清吹，却奏仙歌响綠云。","綠云紫氣向函关，訪道應尋緱氏山。","莫学吹笙王子晉，一遇浮丘斷不還。"]', '诗', 'shi', '', NULL, '鳳吹笙曲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('716047ac-0c4b-4cf0-8eab-b2e93d55bf19', '怨歌行', '怨歌行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["十五入漢宮，花顏笑春紅。","君王選玉色，侍寢金屏中。","薦枕嬌夕月，卷衣戀春風。","寧知趙飛燕，奪寵恨無窮。","沈憂能傷人，綠鬢成霜蓬。","一朝不得意，世事徒爲空。","鷫鸘換美酒，舞衣罷雕龍。","寒苦不忍言，爲君奏絲桐。","腸斷弦亦絕，悲心夜忡忡。"]', '["十五入漢宮，花顏笑春紅。","君王選玉色，侍寢金屏中。","薦枕嬌夕月，卷衣戀春风。","寧知趙飞燕，奪寵恨無窮。","沈憂能傷人，綠鬢成霜蓬。","一朝不得意，世事徒爲空。","鷫鸘換美酒，舞衣罷雕龙。","寒苦不忍言，爲君奏絲桐。","腸斷弦亦絕，悲心夜忡忡。"]', '诗', 'shi', '', NULL, '怨歌行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d757fff5-bff2-4c3e-9df8-c306ea5e489d', '塞下曲六首 一', '塞下曲六首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["五月天山雪，無花祗有寒。","笛中聞折柳，春色未曾看。","曉戰隨金鼓，宵眠抱玉鞍。","願將腰下劒，直爲斬樓蘭。"]', '["五月天山雪，無花祗有寒。","笛中闻折柳，春色未曾看。","晓戰隨金鼓，宵眠抱玉鞍。","願將腰下劒，直爲斬楼蘭。"]', '诗', 'shi', '', NULL, '塞下曲六首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd80e304-1b28-45ae-8c3c-89cd35d0ff09', '塞下曲六首 二', '塞下曲六首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["天兵下北荒，胡馬欲南飲。","橫戈從百戰，直爲銜恩甚。","握雪海上餐，拂沙隴頭寢。","何當破月氏，然後方高枕。"]', '["天兵下北荒，胡马欲南饮。","橫戈從百戰，直爲銜恩甚。","握雪海上餐，拂沙隴头寢。","何當破月氏，然後方高枕。"]', '诗', 'shi', '', NULL, '塞下曲六首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f89ef74-fab4-4182-8c3b-34fcfa26660b', '塞下曲六首 三', '塞下曲六首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["駿馬似風飆，鳴鞭出渭橋。","彎弓辭漢月，插羽破天驕。","陣解星芒盡，營空海霧消。","功成畫麟閣，獨有霍嫖姚。"]', '["駿马似风飆，鳴鞭出渭橋。","彎弓辞漢月，插羽破天驕。","陣解星芒尽，營空海霧消。","功成畫麟閣，独有霍嫖姚。"]', '诗', 'shi', '', NULL, '塞下曲六首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c58780c4-0293-429a-8d5e-e2620c92db94', '塞下曲六首 四', '塞下曲六首 四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白馬黃金塞，雲砂遶夢思。","那堪愁苦節，遠憶邊城兒。","螢飛秋窗滿，月度霜閨遲。","摧殘梧桐葉，蕭颯沙棠枝。","無時獨不見，流淚空自知。"]', '["白马黄金塞，云砂遶梦思。","那堪愁苦節，远憶邊城兒。","螢飞秋窗满，月度霜閨遲。","摧殘梧桐葉，蕭颯沙棠枝。","無时独不见，流泪空自知。"]', '诗', 'shi', '', NULL, '塞下曲六首 四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1baa58f-51e8-4c06-8b76-5a5c4b4cef69', '塞下曲六首 五', '塞下曲六首 五', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["塞虜乘秋下，天兵出漢家。","將軍分虎竹，戰士臥龍沙。","邊月隨弓影，胡霜拂劒花。","玉關殊未入，少婦莫長嗟。"]', '["塞虜乘秋下，天兵出漢家。","將軍分虎竹，戰士臥龙沙。","邊月隨弓影，胡霜拂劒花。","玉关殊未入，少婦莫长嗟。"]', '诗', 'shi', '', NULL, '塞下曲六首 五 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c549213a-54bb-4424-9efb-843364635500', '塞下曲六首 六', '塞下曲六首 六', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["烽火動沙漠，連照甘泉雲。","漢皇按劒起，還召李將軍。","兵氣天上合，鼓聲隴底聞。","橫行負勇氣，一戰淨妖氛。"]', '["烽火动沙漠，連照甘泉云。","漢皇按劒起，還召李將軍。","兵氣天上合，鼓声隴底闻。","橫行負勇氣，一戰淨妖氛。"]', '诗', 'shi', '', NULL, '塞下曲六首 六 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af4989e0-ea67-4d2e-b694-cffc6aceec73', '來日大難', '来日大难', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["來日一身，攜糧負薪。","道長食盡，苦口焦脣。","今日醉飽，樂過千春。","仙人相存，誘我遠學。","海淩三山，陸憩五嶽。","乘龍天飛，目瞻兩角。","授以仙藥，金丹滿握。","蟪蛄蒙恩，深愧短促。","思填東海，强銜一木。","道重天地，軒師廣成。","蟬翼九五，以求長生。","下士大笑，如蒼蠅聲。"]', '["来日一身，携糧負薪。","道长食尽，苦口焦脣。","今日醉飽，乐過千春。","仙人相存，誘我远学。","海淩三山，陸憩五嶽。","乘龙天飞，目瞻兩角。","授以仙藥，金丹满握。","蟪蛄蒙恩，深愧短促。","思填东海，强銜一木。","道重天地，軒師廣成。","蟬翼九五，以求长生。","下士大笑，如蒼蠅声。"]', '诗', 'shi', '', NULL, '來日大難 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a525205a-0567-429e-a2c5-38240aca5741', '塞上曲', '塞上曲', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["大漢無中策，匈奴犯渭橋。","五原秋草綠，胡馬一何驕。","命將征西極，橫行陰山側。","燕支落漢家，婦女無華色。","轉戰渡黃河，休兵樂事多。","蕭條清萬里，瀚海寂無波。"]', '["大漢無中策，匈奴犯渭橋。","五原秋草綠，胡马一何驕。","命將征西極，橫行陰山側。","燕支落漢家，婦女無华色。","轉戰渡黄河，休兵乐事多。","蕭條清万里，瀚海寂無波。"]', '诗', 'shi', '', NULL, '塞上曲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a65e5646-14b1-4f75-924b-bbf262b242d7', '玉階怨', '玉階怨', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["玉階生白露，夜久侵羅襪。","却下水晶簾，玲瓏望秋月。"]', '["玉階生白露，夜久侵羅襪。","却下水晶簾，玲瓏望秋月。"]', '诗', 'shi', '', NULL, '玉階怨 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af9b5f9f-e863-4db9-9e47-7988aa2b22b4', '襄陽曲四首 一', '襄陽曲四首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["襄陽行樂處，歌舞白銅鞮。","江城回淥水，花月使人迷。"]', '["襄陽行乐处，歌舞白銅鞮。","江城回淥水，花月使人迷。"]', '诗', 'shi', '', NULL, '襄陽曲四首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b564007-c5e3-40d6-be95-5a00188b407c', '襄陽曲四首 二', '襄陽曲四首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["山公醉酒時，酩酊高陽下。","頭上白接䍦，倒著還騎馬。"]', '["山公醉酒时，酩酊高陽下。","头上白接䍦，倒著還騎马。"]', '诗', 'shi', '', NULL, '襄陽曲四首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f007e41-e85f-40bc-a93d-dd4a08cca239', '襄陽曲四首 三', '襄陽曲四首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["峴山臨漢江，水綠沙如雪。","上有墮淚碑，青苔久磨滅。"]', '["峴山臨漢江，水綠沙如雪。","上有墮泪碑，青苔久磨滅。"]', '诗', 'shi', '', NULL, '襄陽曲四首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57f6ddfe-f729-4973-83f6-66817a720ce3', '襄陽曲四首 四', '襄陽曲四首 四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["且醉習家池，莫看墮淚碑。","山公欲上馬，笑殺襄陽兒。"]', '["且醉習家池，莫看墮泪碑。","山公欲上马，笑殺襄陽兒。"]', '诗', 'shi', '', NULL, '襄陽曲四首 四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86fa9ad6-3cf7-4ef9-9804-32155d837120', '大堤曲', '大堤曲', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["漢水臨襄陽，花開大堤暖。","佳期大堤下，淚向南雲滿。","春風無復情，吹我夢魂散。","不見眼中人，天長音信斷。"]', '["漢水臨襄陽，花开大堤暖。","佳期大堤下，泪向南云满。","春风無复情，吹我梦魂散。","不见眼中人，天长音信斷。"]', '诗', 'shi', '', NULL, '大堤曲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b35291b7-f63e-45c3-8ef9-f7ad98807627', '宮中行樂詞八首 一', '宮中行乐词八首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["小小生金屋，盈盈在紫微。","山花插寶髻，石竹繡羅衣。","每出深宮裏，常隨步輦歸。","只愁歌舞散，化作綵雲飛。"]', '["小小生金屋，盈盈在紫微。","山花插寶髻，石竹繡羅衣。","每出深宮裏，常隨步輦归。","只愁歌舞散，化作綵云飞。"]', '诗', 'shi', '', NULL, '宮中行樂詞八首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('970e8456-5bf7-43fa-b8b3-227dac0e9051', '宮中行樂詞八首 二', '宮中行乐词八首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["柳色黃金嫩，梨花白雪香。","玉樓巢翡翠，金殿鎖鴛鴦。","選妓隨雕輦，徵歌出洞房。","宮中誰第一，飛燕在昭陽。"]', '["柳色黄金嫩，梨花白雪香。","玉楼巢翡翠，金殿鎖鴛鴦。","選妓隨雕輦，徵歌出洞房。","宮中誰第一，飞燕在昭陽。"]', '诗', 'shi', '', NULL, '宮中行樂詞八首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('379bc0cf-6d26-46c4-a51c-244e516e6a41', '宮中行樂詞八首 三', '宮中行乐词八首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["盧橘爲秦樹，蒲萄出漢宮。","煙花宜落日，絲管醉春風。","笛奏龍吟水，簫鳴鳳下空。","君王多樂事，還與萬方同。"]', '["盧橘爲秦樹，蒲萄出漢宮。","煙花宜落日，絲管醉春风。","笛奏龙吟水，簫鳴鳳下空。","君王多乐事，還與万方同。"]', '诗', 'shi', '', NULL, '宮中行樂詞八首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b26f0b8-4006-4755-95c7-5a0e99a9acdd', '宮中行樂詞八首 四', '宮中行乐词八首 四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["玉樹春歸日，金宮樂事多。","後庭朝未入，輕輦夜相過。","笑出花間語，嬌來竹下歌。","莫教明月去，留著醉嫦蛾。"]', '["玉樹春归日，金宮乐事多。","後庭朝未入，轻輦夜相過。","笑出花间語，嬌来竹下歌。","莫教明月去，留著醉嫦蛾。"]', '诗', 'shi', '', NULL, '宮中行樂詞八首 四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99b8c08d-15ad-48d7-a567-21e90ad205b6', '宮中行樂詞八首 五', '宮中行乐词八首 五', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["繡戶香風暖，紗窗曙色新。","宮花爭笑日，池草暗生春。","綠樹聞歌鳥，青樓見舞人。","昭陽桃李月，羅綺自相親。"]', '["繡戶香风暖，紗窗曙色新。","宮花爭笑日，池草暗生春。","綠樹闻歌鸟，青楼见舞人。","昭陽桃李月，羅綺自相親。"]', '诗', 'shi', '', NULL, '宮中行樂詞八首 五 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca7c63a3-907e-43ed-9e2f-0ec18619dcb0', '宮中行樂詞八首 六', '宮中行乐词八首 六', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["今日明光裏，還須結伴遊。","春風開紫殿，天樂下朱樓。","豔舞全知巧，嬌歌半欲羞。","更憐花月夜，宮女笑藏鉤。"]', '["今日明光裏，還須結伴游。","春风开紫殿，天乐下朱楼。","豔舞全知巧，嬌歌半欲羞。","更怜花月夜，宮女笑藏鉤。"]', '诗', 'shi', '', NULL, '宮中行樂詞八首 六 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8da550b7-9278-4649-9124-960110bf7b1a', '宮中行樂詞八首 七', '宮中行乐词八首 七', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["寒雪梅中盡，春風柳上歸。","宮鶯嬌欲醉，簷燕語還飛。","遲日明歌席，新花豔舞衣。","晚來移綵仗，行樂泥光輝。"]', '["寒雪梅中尽，春风柳上归。","宮鶯嬌欲醉，簷燕語還飞。","遲日明歌席，新花豔舞衣。","晚来移綵仗，行乐泥光輝。"]', '诗', 'shi', '', NULL, '宮中行樂詞八首 七 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21b11745-2b29-46e3-bde8-29ef351a4f47', '宮中行樂詞八首 八', '宮中行乐词八首 八', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["水綠南薰殿，花紅北闕樓。","鶯歌聞太液，鳳吹繞瀛洲。","素女鳴珠珮，天人弄綵毬。","今朝風日好，宜入未央遊。"]', '["水綠南薰殿，花紅北闕楼。","鶯歌闻太液，鳳吹繞瀛洲。","素女鳴珠珮，天人弄綵毬。","今朝风日好，宜入未央游。"]', '诗', 'shi', '', NULL, '宮中行樂詞八首 八 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('948fa40a-492e-4fa1-99f4-b002ae87cd24', '清平調詞三首 一', '清平調词三首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["雲想衣裳花想容，春風拂檻露華濃。","若非羣玉山頭見，會向瑤臺月下逢。"]', '["云想衣裳花想容，春风拂檻露华濃。","若非羣玉山头见，會向瑤台月下逢。"]', '诗', 'shi', '', NULL, '清平調詞三首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99167d13-8e2c-4b75-bf93-62b0682dfdd0', '清平調詞三首 二', '清平調词三首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["一枝穠豔露凝香，雲雨巫山枉斷腸。","借問漢宮誰得似，可憐飛燕倚新妝。"]', '["一枝穠豔露凝香，云雨巫山枉斷腸。","借问漢宮誰得似，可怜飞燕倚新妝。"]', '诗', 'shi', '', NULL, '清平調詞三首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b706bb8-c836-4637-bec3-3fa2adc88ca7', '清平調詞三首 三', '清平調词三首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["名花傾國兩相歡，長得君王帶笑看。","觧釋春風無限恨，沈香亭北倚闌干。"]', '["名花傾国兩相歡，长得君王带笑看。","觧釋春风無限恨，沈香亭北倚闌干。"]', '诗', 'shi', '', NULL, '清平調詞三首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3de1566-b132-4c39-800a-7f72fc5d31bc', '入朝曲', '入朝曲', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["金陵控海浦，淥水帶吳京。","鐃歌列騎吹，颯沓引公卿。","槌鐘速嚴妝，伐鼓啓重城。","天子憑玉几，劒履若雲行。","日出照萬戶，簪裾爛明星。","朝罷沐浴閑，遨遊閬風亭。","濟濟雙闕下，歡娛樂恩榮。"]', '["金陵控海浦，淥水带吳京。","鐃歌列騎吹，颯沓引公卿。","槌鐘速嚴妝，伐鼓啓重城。","天子憑玉几，劒履若云行。","日出照万戶，簪裾爛明星。","朝罷沐浴闲，遨游閬风亭。","濟濟雙闕下，歡娛乐恩榮。"]', '诗', 'shi', '', NULL, '入朝曲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd2c5587-72ba-4657-a633-b96c9838abb7', '秦女休行', '秦女休行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["西門秦氏女，秀色如瓊花。","手揮白楊刀，清晝殺讐家。","羅袖灑赤血，英氣凌紫霞。","直上西山去，關吏相邀遮。","壻爲燕國王，身被詔獄加。","犯刑若履虎，不畏落爪牙。","素頸未及斷，摧眉伏泥沙。","金雞忽放赦，大辟得寬賒。","何慙聶政姊，萬古共驚嗟。"]', '["西门秦氏女，秀色如瓊花。","手揮白楊刀，清晝殺讐家。","羅袖灑赤血，英氣凌紫霞。","直上西山去，关吏相邀遮。","壻爲燕国王，身被詔獄加。","犯刑若履虎，不畏落爪牙。","素頸未及斷，摧眉伏泥沙。","金雞忽放赦，大辟得寬賒。","何慙聶政姊，万古共驚嗟。"]', '诗', 'shi', '', NULL, '秦女休行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87899f62-0eef-41ed-9037-409f4af8cd77', '秦女卷衣', '秦女卷衣', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["天子居未央，妾侍卷衣裳。","顧無紫宮寵，敢拂黃金牀。","水至亦不去，熊來尚可當。","微身奉日月，飄若螢之光。","願君采葑菲，無以下體妨。"]', '["天子居未央，妾侍卷衣裳。","顧無紫宮寵，敢拂黄金牀。","水至亦不去，熊来尚可當。","微身奉日月，飄若螢之光。","願君采葑菲，無以下體妨。"]', '诗', 'shi', '', NULL, '秦女卷衣 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f222122-d8aa-4484-9fd5-422dcc204c04', '東武吟', '东武吟', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["好古笑流俗，素聞賢達風。","方希佐明主，長揖辭成功。","白日在高天，迴光燭微躬。","恭承鳳凰詔，歘起雲蘿中。","清切紫霄迥，優游丹禁通。","君王賜顏色，聲價凌煙虹。","乘輿擁翠蓋，扈從金城東。","寶馬麗絕景，錦衣入新豐。","依巖望松雪，對酒鳴絲桐。","因學揚子雲，獻賦甘泉宮。","天書美片善，清芬播無窮。","歸來入咸陽，談笑皆王公。","一朝去金馬，飄落成飛蓬。","賓客日疎散，玉樽亦已空。","才力猶可倚，不慙世上雄。","閑作東武吟，曲盡情未終。","書此謝知己，吾尋黃綺翁。"]', '["好古笑流俗，素闻賢達风。","方希佐明主，长揖辞成功。","白日在高天，迴光燭微躬。","恭承鳳凰詔，歘起云蘿中。","清切紫霄迥，優游丹禁通。","君王賜顏色，声價凌煙虹。","乘輿擁翠蓋，扈從金城东。","寶马丽絕景，錦衣入新豐。","依巖望松雪，对酒鳴絲桐。","因学揚子云，獻賦甘泉宮。","天书美片善，清芬播無窮。","归来入咸陽，談笑皆王公。","一朝去金马，飄落成飞蓬。","賓客日疎散，玉樽亦已空。","才力猶可倚，不慙世上雄。","闲作东武吟，曲尽情未終。","书此謝知己，吾尋黄綺翁。"]', '诗', 'shi', '', NULL, '東武吟 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a23853df-1c19-414e-9941-6dd7892ac707', '邯鄲才人嫁爲廝養卒婦', '邯鄲才人嫁爲廝養卒婦', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["妾本崇臺女，揚蛾入丹闕。","自倚顏如花，寧知有凋歇。","一辭玉階下，去若朝雲沒。","每憶邯鄲城，深宮夢秋月。","君王不可見，惆悵至明發。"]', '["妾本崇台女，揚蛾入丹闕。","自倚顏如花，寧知有凋歇。","一辞玉階下，去若朝云沒。","每憶邯鄲城，深宮梦秋月。","君王不可见，惆悵至明發。"]', '诗', 'shi', '', NULL, '邯鄲才人嫁爲廝養卒婦 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d0a5f9b-80a6-447e-8acb-08b3fd30b8b5', '出自薊北門行', '出自薊北门行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["虜陣橫北荒，胡星耀精芒。","羽書速驚電，烽火晝連光。","虎竹救邊急，戎車森已行。","明主不安席，按劒心飛揚。","推轂出猛將，連旗登戰場。","兵威衝絕幕，殺氣凌穹蒼。","列卒赤山下，開營紫塞傍。","孟冬風沙緊，旌旗颯凋傷。","畫角悲海月，征衣卷天霜。","揮刃斬樓蘭，彎弓射賢王。","單于一平蕩，種落自奔亡。","收功報天子，行歌歸咸陽。"]', '["虜陣橫北荒，胡星耀精芒。","羽书速驚電，烽火晝連光。","虎竹救邊急，戎车森已行。","明主不安席，按劒心飞揚。","推轂出猛將，連旗登戰場。","兵威衝絕幕，殺氣凌穹蒼。","列卒赤山下，开營紫塞傍。","孟冬风沙緊，旌旗颯凋傷。","畫角悲海月，征衣卷天霜。","揮刃斬楼蘭，彎弓射賢王。","單于一平蕩，種落自奔亡。","收功報天子，行歌归咸陽。"]', '诗', 'shi', '', NULL, '出自薊北門行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07b54f1c-f69e-4f95-906e-7fe4742c2ffb', '洛陽陌', '洛陽陌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白玉誰家郎，回車渡天津。","看花東陌上，驚動洛陽人。"]', '["白玉誰家郎，回车渡天津。","看花东陌上，驚动洛陽人。"]', '诗', 'shi', '', NULL, '洛陽陌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd4449d3-dd2d-4648-baea-eca59123dc21', '北上行', '北上行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["北上何所苦，北上緣太行。","磴道盤且峻，巉巖凌穹蒼。","馬足蹶側石，車輪摧高岡。","沙塵接幽州，烽火連朔方。","殺氣毒劒戟，嚴風裂衣裳。","奔鯨夾黃河，鑿齒屯洛陽。","前行無歸日，返顧思舊鄉。","慘戚冰雪裏，悲號絕中腸。","尺布不掩體，皮膚劇枯桑。","汲水澗谷阻，採薪隴坂長。","猛虎又掉尾，磨牙皓秋霜。","草木不可餐，飢飲零露漿。","歎此北上苦，停驂爲之傷。","何日王道平，開顏覩天光。"]', '["北上何所苦，北上緣太行。","磴道盤且峻，巉巖凌穹蒼。","马足蹶側石，车輪摧高岡。","沙塵接幽州，烽火連朔方。","殺氣毒劒戟，嚴风裂衣裳。","奔鯨夾黄河，鑿齒屯洛陽。","前行無归日，返顧思旧乡。","慘戚冰雪裏，悲號絕中腸。","尺布不掩體，皮膚劇枯桑。","汲水澗谷阻，採薪隴坂长。","猛虎又掉尾，磨牙皓秋霜。","草木不可餐，飢饮零露漿。","歎此北上苦，停驂爲之傷。","何日王道平，开顏覩天光。"]', '诗', 'shi', '', NULL, '北上行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4eec103c-1a08-4b20-bfc1-bc30763b935e', '短歌行', '短歌行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白日何短短，百年苦易滿。","蒼穹浩茫茫，萬劫太極長。","麻姑垂兩鬢，一半已成霜。","天公見玉女，大笑億千場。","吾欲攬六龍，迴車挂扶桑。","北斗酌美酒，勸龍各一觴。","富貴非所願，與人駐顏光。"]', '["白日何短短，百年苦易满。","蒼穹浩茫茫，万劫太極长。","麻姑垂兩鬢，一半已成霜。","天公见玉女，大笑億千場。","吾欲攬六龙，迴车挂扶桑。","北斗酌美酒，勸龙各一觴。","富貴非所願，與人駐顏光。"]', '诗', 'shi', '', NULL, '短歌行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19e77d27-3601-4830-94ca-b812ac4ac1c3', '空城雀', '空城雀', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["嗷嗷空城雀，身計何戚促。","本與鷦鷯羣，不隨鳳凰族。","提攜四黃口，飲乳未嘗足。","食君糠粃餘，嘗恐烏鳶逐。","耻涉太行險，羞營覆車粟。","天命有定端，守分絕所欲。"]', '["嗷嗷空城雀，身計何戚促。","本與鷦鷯羣，不隨鳳凰族。","提携四黄口，饮乳未嘗足。","食君糠粃餘，嘗恐烏鳶逐。","耻涉太行險，羞營覆车粟。","天命有定端，守分絕所欲。"]', '诗', 'shi', '', NULL, '空城雀 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('676a45c2-64d9-4159-9695-6c3b24fc5193', '發白馬', '發白马', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["將軍發白馬，旌節度黃河。","簫鼓聒川嶽，滄溟湧濤波。","武安有振瓦，易水無寒歌。","鐵騎若雪山，飲流涸滹沱。","揚兵獵月窟，轉戰略朝那。","倚劒登燕然，邊烽列嵯峨。","蕭條萬里外，耕作五原多。","一掃清大漠，包虎戢金戈。"]', '["將軍發白马，旌節度黄河。","簫鼓聒川嶽，滄溟湧濤波。","武安有振瓦，易水無寒歌。","鐵騎若雪山，饮流涸滹沱。","揚兵獵月窟，轉戰略朝那。","倚劒登燕然，邊烽列嵯峨。","蕭條万里外，耕作五原多。","一掃清大漠，包虎戢金戈。"]', '诗', 'shi', '', NULL, '發白馬 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f81bc9aa-b41d-48af-a861-8a8c782ac0d3', '陌上桑', '陌上桑', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["美女渭橋東，春還事蠶作。","五馬如飛龍，青絲結金絡。","不知誰家子，調笑來相謔。","妾本秦羅敷，玉顏豔名都。","綠條映素手，採桑向城隅。","使君且不顧，況復論秋胡。","寒螿愛碧草，鳴鳳棲青梧。","託心自有處，但怪旁人愚。","徒令白日暮，高駕空踟躕。"]', '["美女渭橋东，春還事蠶作。","五马如飞龙，青絲結金絡。","不知誰家子，調笑来相謔。","妾本秦羅敷，玉顏豔名都。","綠條映素手，採桑向城隅。","使君且不顧，況复論秋胡。","寒螿愛碧草，鳴鳳棲青梧。","託心自有处，但怪旁人愚。","徒令白日暮，高駕空踟躕。"]', '诗', 'shi', '', NULL, '陌上桑 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbc355b2-ee47-42cc-8694-f9b783ec5e79', '枯魚過河泣', '枯鱼過河泣', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白龍改常服，偶被豫且制。","誰使爾爲魚，徒勞訴天帝。","作書報鯨鯢，勿恃風濤勢。","濤落歸泥沙，翻遭螻蟻噬。","萬乘慎出入，柏人以爲識。"]', '["白龙改常服，偶被豫且制。","誰使爾爲鱼，徒勞訴天帝。","作书報鯨鯢，勿恃风濤勢。","濤落归泥沙，翻遭螻蟻噬。","万乘慎出入，柏人以爲識。"]', '诗', 'shi', '', NULL, '枯魚過河泣 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c417fd4-9798-43ae-b2ea-4fba4400af3f', '丁督護歌', '丁督護歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["雲陽上征去，兩岸饒商賈。","吳牛喘月時，拖船一何苦。","水濁不可飲，壺漿半成土。","一唱督護歌，心摧淚如雨。","萬人鑿磐石，無由達江滸。","君看石芒碭，掩淚悲千古。"]', '["云陽上征去，兩岸饒商賈。","吳牛喘月时，拖船一何苦。","水濁不可饮，壺漿半成土。","一唱督護歌，心摧泪如雨。","万人鑿磐石，無由達江滸。","君看石芒碭，掩泪悲千古。"]', '诗', 'shi', '', NULL, '丁督護歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bd7db76-e850-4560-af60-0b930a7e648a', '相逢行', '相逢行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["朝騎五花馬，謁帝出銀臺。","秀色誰家子，雲車珠箔開。","金鞭遙指點，玉勒近遲回。","夾轂相借問，疑從天上來。","蹙入青綺門，當歌共銜杯。","銜杯暎歌扇，似月雲中見。","相見不得親，不如不相見。","相見情已深，未語可知心。","胡爲守空閨，孤眠愁錦衾。","錦衾與羅幃，纏綿會有時。","春風正澹蕩，暮雨來何遲。","願因三青鳥，更報長相思。","光景不待人，須臾髮成絲。","當年失行樂，老去徒傷悲。","持此道密意，毋令曠佳期。"]', '["朝騎五花马，謁帝出銀台。","秀色誰家子，云车珠箔开。","金鞭遙指点，玉勒近遲回。","夾轂相借问，疑從天上来。","蹙入青綺门，當歌共銜杯。","銜杯暎歌扇，似月云中见。","相见不得親，不如不相见。","相见情已深，未語可知心。","胡爲守空閨，孤眠愁錦衾。","錦衾與羅幃，纏綿會有时。","春风正澹蕩，暮雨来何遲。","願因三青鸟，更報长相思。","光景不待人，須臾髮成絲。","當年失行乐，老去徒傷悲。","持此道密意，毋令曠佳期。"]', '诗', 'shi', '', NULL, '相逢行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a56d7021-f30a-4391-93ae-d6467d57b921', '千里思', '千里思', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["李陵沒胡沙，蘇武還漢家。","迢迢五原關，朔雪亂邊花。","一去隔絕國，思歸但長嗟。","鴻雁向西北，因書報天涯。"]', '["李陵沒胡沙，蘇武還漢家。","迢迢五原关，朔雪亂邊花。","一去隔絕国，思归但长嗟。","鴻雁向西北，因书報天涯。"]', '诗', 'shi', '', NULL, '千里思 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5f3b0ad-d3f4-438d-aa54-a6b8445c6b03', '樹中草', '樹中草', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["鳥銜野田草，誤入枯桑裏。","客土植危根，逢春猶不死。","草木雖無情，因依尚可生。","如何同枝葉，各自有枯榮。"]', '["鸟銜野田草，誤入枯桑裏。","客土植危根，逢春猶不死。","草木雖無情，因依尚可生。","如何同枝葉，各自有枯榮。"]', '诗', 'shi', '', NULL, '樹中草 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae248db2-43b1-4195-8b26-aea30fb8790a', '君馬黃', '君马黄', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["君馬黃，我馬白。","馬色雖不同，人心本無隔。","共作遊冶盤，雙行洛陽陌。","長劒既照曜，高冠何赩赫。","各有千金裘，俱爲五侯客。","猛虎落陷穽，壯夫時屈厄。","相知在急難，獨好亦何益。"]', '["君马黄，我马白。","马色雖不同，人心本無隔。","共作游冶盤，雙行洛陽陌。","长劒既照曜，高冠何赩赫。","各有千金裘，俱爲五侯客。","猛虎落陷穽，壯夫时屈厄。","相知在急难，独好亦何益。"]', '诗', 'shi', '', NULL, '君馬黃 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fecb8c7-f8f0-4dd1-a3f4-3175599f83e2', '擬古', '擬古', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["融融白玉輝，暎我青蛾眉。","寶鏡似空水，落花如風吹。","出門望帝子，蕩漾不可期。","安得黃鶴羽，一報佳人知。"]', '["融融白玉輝，暎我青蛾眉。","寶镜似空水，落花如风吹。","出门望帝子，蕩漾不可期。","安得黄鹤羽，一報佳人知。"]', '诗', 'shi', '', NULL, '擬古 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7702c0f-2cce-49fe-97b7-5d0abd5953d3', '折楊柳', '折楊柳', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["垂楊拂綠水，搖豔東風年。","花明玉關雪，葉暖金牕煙。","美人結長想，對此心淒然。","攀條折春色，遠寄龍庭前。"]', '["垂楊拂綠水，搖豔东风年。","花明玉关雪，葉暖金牕煙。","美人結长想，对此心淒然。","攀條折春色，远寄龙庭前。"]', '诗', 'shi', '', NULL, '折楊柳 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1b51727-f72a-4eb6-82db-99a458271ac2', '少年子', '少年子', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["青雲年少子，挾彈章臺左。","鞍馬四邊開，突如流星過。","金丸落飛鳥，夜入瓊樓臥。","夷齊是何人，獨守西山餓。"]', '["青云年少子，挾彈章台左。","鞍马四邊开，突如流星過。","金丸落飞鸟，夜入瓊楼臥。","夷齊是何人，独守西山餓。"]', '诗', 'shi', '', NULL, '少年子 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65e8aaff-bbd3-445f-ad03-782789c9a5d0', '紫騮馬', '紫騮马', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["紫騮行且嘶，雙翻碧玉蹄。","臥流不肯渡，似惜錦障泥。","白雪關山遠，黃雲海戍迷。","揮鞭萬里去，安得念春閨。"]', '["紫騮行且嘶，雙翻碧玉蹄。","臥流不肯渡，似惜錦障泥。","白雪关山远，黄云海戍迷。","揮鞭万里去，安得念春閨。"]', '诗', 'shi', '', NULL, '紫騮馬 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e68a4fa2-c681-4716-9e24-04b76dd1e723', '少年行二首 一', '少年行二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["擊筑飲美酒，劒歌易水湄。","經過燕太子，結託幷州兒。","少年負壯氣，奮烈自有時。","因擊魯句踐，爭博勿相欺。"]', '["擊筑饮美酒，劒歌易水湄。","經過燕太子，結託幷州兒。","少年負壯氣，奮烈自有时。","因擊魯句踐，爭博勿相欺。"]', '诗', 'shi', '', NULL, '少年行二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75f41e72-ce1e-46d8-873d-6a2f5463e234', '少年行二首 二', '少年行二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["五陵年少金市東，銀鞍白馬度春風。","落花踏盡遊何處，笑入胡姬酒肆中。"]', '["五陵年少金市东，銀鞍白马度春风。","落花踏尽游何处，笑入胡姬酒肆中。"]', '诗', 'shi', '', NULL, '少年行二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cd762f4-f2ea-44d4-92f2-e9a6d0bf2b56', '白鼻騧', '白鼻騧', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["銀鞍白鼻騧，綠地障泥錦。","細雨春風花落時，揮鞭直就胡姬飲。"]', '["銀鞍白鼻騧，綠地障泥錦。","細雨春风花落时，揮鞭直就胡姬饮。"]', '诗', 'shi', '', NULL, '白鼻騧 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5afcefcb-9c1a-4ca0-8fac-e5889937dea4', '豫章行', '豫章行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["胡風吹代馬，北擁魯陽關。","吳兵照海雪，西討何時還。","半渡上遼津，黃雲慘無顏。","老母與子別，呼天野草間。","白馬繞旌旗，悲鳴相追攀。","白楊秋月苦，早落豫章山。","本爲休明人，斬虜素不閑。","豈惜戰鬬死，爲君掃兇頑。","精感石沒羽，豈云憚險艱。","樓船若鯨飛，波蕩落星灣。","此曲不可奏，三軍鬢成斑。"]', '["胡风吹代马，北擁魯陽关。","吳兵照海雪，西討何时還。","半渡上遼津，黄云慘無顏。","老母與子別，呼天野草间。","白马繞旌旗，悲鳴相追攀。","白楊秋月苦，早落豫章山。","本爲休明人，斬虜素不闲。","豈惜戰鬬死，爲君掃兇頑。","精感石沒羽，豈云憚險艱。","楼船若鯨飞，波蕩落星灣。","此曲不可奏，三軍鬢成斑。"]', '诗', 'shi', '', NULL, '豫章行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61f23379-7a06-48dd-b68c-a93ddf4315af', '沐浴子', '沐浴子', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["沐芳莫彈冠，浴蘭莫振衣。","處世忌太潔，至人貴藏暉。","滄浪有釣叟，吾與爾同歸。"]', '["沐芳莫彈冠，浴蘭莫振衣。","处世忌太潔，至人貴藏暉。","滄浪有釣叟，吾與爾同归。"]', '诗', 'shi', '', NULL, '沐浴子 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c00c6453-c7d2-4ca6-84a9-c37cf5a196d1', '高句驪', '高句驪', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["金花折風帽，白馬小遲回。","翩翩舞廣袖，似鳥海東來。"]', '["金花折风帽，白马小遲回。","翩翩舞廣袖，似鸟海东来。"]', '诗', 'shi', '', NULL, '高句驪 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36a924f7-a805-4c5b-aee5-89cec3d4b6cd', '舍利弗', '舍利弗', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["金繩界寶地，珍木蔭瑤池。","雲間妙音奏，天際法蠡吹。"]', '["金繩界寶地，珍木蔭瑤池。","云间妙音奏，天際法蠡吹。"]', '诗', 'shi', '', NULL, '舍利弗 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca2c489a-e433-4c0f-8248-77d354f0665e', '靜夜思', '静夜思', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["牀前看月光，疑是地上霜。","舉頭望山月，低頭思故鄉。"]', '["牀前看月光，疑是地上霜。","舉头望山月，低头思故乡。"]', '诗', 'shi', '', NULL, '靜夜思 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e26acba5-04cc-4459-aadd-2e23ea5026af', '淥水曲', '淥水曲', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["淥水明秋月，南湖採白蘋。","荷花嬌欲語，愁殺蕩舟人。"]', '["淥水明秋月，南湖採白蘋。","荷花嬌欲語，愁殺蕩舟人。"]', '诗', 'shi', '', NULL, '淥水曲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbd5eeec-ef92-46be-a389-e254dd0549f5', '鳳凰曲', '鳳凰曲', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["嬴女吹玉簫，吟弄天上春。","青鸞不獨去，更有攜手人。","影滅彩雲斷，遺聲落西秦。"]', '["嬴女吹玉簫，吟弄天上春。","青鸾不独去，更有携手人。","影滅彩云斷，遺声落西秦。"]', '诗', 'shi', '', NULL, '鳳凰曲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e82acb34-729a-41ea-bc99-75c28c90c9a2', '鳳臺曲', '鳳台曲', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["嘗聞秦帝女，傳得鳳凰聲。","是日逢仙子，當時別有情。","人吹綵簫去，天借綠雲迎。","曲在身不返，空餘弄玉名。"]', '["嘗闻秦帝女，傳得鳳凰声。","是日逢仙子，當时別有情。","人吹綵簫去，天借綠云迎。","曲在身不返，空餘弄玉名。"]', '诗', 'shi', '', NULL, '鳳臺曲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8da2fb55-b15b-4e42-a060-a7dddacbc6d3', '從軍行', '從軍行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["從軍玉門道，逐虜金微山。","笛奏梅花曲，刀開明月環。","鼓聲鳴海上，兵氣擁雲間。","願斬單于首，長驅靜鐵關。"]', '["從軍玉门道，逐虜金微山。","笛奏梅花曲，刀开明月环。","鼓声鳴海上，兵氣擁云间。","願斬單于首，长驱静鐵关。"]', '诗', 'shi', '', NULL, '從軍行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9486b34-2104-4ab3-bfdd-8c4140b04c2a', '秋思', '秋思', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["春陽如昨日，碧樹鳴黃鸝。","蕪然蕙草暮，颯爾涼風吹。","天秋木葉下，月冷莎雞悲。","坐愁羣芳歇，白露凋華滋。"]', '["春陽如昨日，碧樹鳴黄鸝。","蕪然蕙草暮，颯爾涼风吹。","天秋木葉下，月冷莎雞悲。","坐愁羣芳歇，白露凋华滋。"]', '诗', 'shi', '', NULL, '秋思 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7277c420-9f3f-4093-a5b2-6331494721e8', '春思', '春思', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["燕草如碧絲，秦桑低綠枝。","當君懷歸日，是妾斷腸時。","春風不相識，何事入羅幃。"]', '["燕草如碧絲，秦桑低綠枝。","當君懷归日，是妾斷腸时。","春风不相識，何事入羅幃。"]', '诗', 'shi', '', NULL, '春思 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('817cdd6d-d0e2-4b48-9117-fd9a88fee1a7', '秋思', '秋思', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["燕支黃葉落，妾望自登臺。","海上碧雲斷，單于秋色來。","胡兵沙塞合，漢使玉關回。","征客無歸日，空悲蕙草摧。"]', '["燕支黄葉落，妾望自登台。","海上碧云斷，單于秋色来。","胡兵沙塞合，漢使玉关回。","征客無归日，空悲蕙草摧。"]', '诗', 'shi', '', NULL, '秋思 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57203d7f-380c-4052-b21b-d1ea79fbe231', '子夜吳歌 春歌', '子夜吳歌 春歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秦地羅敷女，採桑綠水邊。","素手青條上，紅妝白日鮮。","蠶飢妾欲去，五馬莫留連。"]', '["秦地羅敷女，採桑綠水邊。","素手青條上，紅妝白日鲜。","蠶飢妾欲去，五马莫留連。"]', '诗', 'shi', '', NULL, '子夜吳歌 春歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abb3e465-f10e-43dd-b564-a5de08010478', '子夜吳歌 夏歌', '子夜吳歌 夏歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["鏡湖三百里，菡萏發荷花。","五月西施採，人看隘若耶。","回舟不待月，歸去越王家。"]', '["镜湖三百里，菡萏發荷花。","五月西施採，人看隘若耶。","回舟不待月，归去越王家。"]', '诗', 'shi', '', NULL, '子夜吳歌 夏歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baccf46a-41c4-4a0f-b90f-37cc35b04a64', '子夜吳歌 秋歌', '子夜吳歌 秋歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["長安一片月，萬戶擣衣聲。","秋風吹不盡，總是玉關情。","何日平胡虜，良人罷遠征。"]', '["长安一片月，万戶擣衣声。","秋风吹不尽，總是玉关情。","何日平胡虜，良人罷远征。"]', '诗', 'shi', '', NULL, '子夜吳歌 秋歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f990af2e-d929-48da-a9b3-fdbc706ca4a3', '子夜吳歌 冬歌', '子夜吳歌 冬歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["明朝驛使發，一夜絮征袍。","素手抽針冷，那堪把剪刀。","裁縫寄遠道，幾日到臨洮。"]', '["明朝驛使發，一夜絮征袍。","素手抽針冷，那堪把剪刀。","裁縫寄远道，幾日到臨洮。"]', '诗', 'shi', '', NULL, '子夜吳歌 冬歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6b2fb13-c1bf-4c00-80fc-fd24f908c86e', '對酒行', '对酒行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["松子栖金華，安期入蓬海。","此人古之仙，羽化竟何在。","浮生速流電，倏忽變光彩。","天地無凋換，容顏有遷改。","對酒不肯飲，含情欲誰待。"]', '["松子栖金华，安期入蓬海。","此人古之仙，羽化竟何在。","浮生速流電，倏忽变光彩。","天地無凋換，容顏有遷改。","对酒不肯饮，含情欲誰待。"]', '诗', 'shi', '', NULL, '對酒行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54bb87e8-3846-432a-95b7-6d951997bed9', '估客行', '估客行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["海客乘天風，將船遠行役。","譬如雲中鳥，一去無蹤跡。"]', '["海客乘天风，將船远行役。","譬如云中鸟，一去無蹤跡。"]', '诗', 'shi', '', NULL, '估客行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6f4c79e-4f13-447c-9c90-c8f957c6701b', '擣衣篇', '擣衣篇', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["閨裏佳人年十餘，嚬蛾對影恨離居。","忽逢江上春歸燕，銜得雲中尺素書。","玉手開緘長歎息，狂夫猶戍交河北。","萬里交河水北流，願爲雙燕泛中洲。","君邊雲擁青絲騎，妾處苔生紅粉樓。","樓上春風日將歇，誰能攬鏡看愁髮。","曉吹員管隨落花，夜擣戎衣向明月。","明月高高刻漏長，真珠簾箔掩蘭堂。","橫垂寶幄同心結，半拂瓊筵蘇合香。","瓊筵寶幄連枝錦，燈燭熒熒照孤寢。","有便憑將金剪刀，爲君留下相思枕。","摘盡庭蘭不見君，紅巾拭淚生氤氳。","明年若更征邊塞，願作陽臺一叚雲。"]', '["閨裏佳人年十餘，嚬蛾对影恨離居。","忽逢江上春归燕，銜得云中尺素书。","玉手开緘长歎息，狂夫猶戍交河北。","万里交河水北流，願爲雙燕泛中洲。","君邊云擁青絲騎，妾处苔生紅粉楼。","楼上春风日將歇，誰能攬镜看愁髮。","晓吹員管隨落花，夜擣戎衣向明月。","明月高高刻漏长，真珠簾箔掩蘭堂。","橫垂寶幄同心結，半拂瓊筵蘇合香。","瓊筵寶幄連枝錦，灯燭熒熒照孤寢。","有便憑將金剪刀，爲君留下相思枕。","摘尽庭蘭不见君，紅巾拭泪生氤氳。","明年若更征邊塞，願作陽台一叚云。"]', '诗', 'shi', '', NULL, '擣衣篇 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9c6795e-e76e-4805-a268-6263a733bd66', '少年行', '少年行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["君不見淮南少年游俠客，白日毬獵夜擁擲。","呼盧百萬終不惜，報讎千里如咫尺。","少年游俠好經過，渾身裝束皆綺羅。","蕙蘭相隨喧妓女，風光去處滿笙歌。","驕矜自言不可有，俠士堂中養來久。","好鞍好馬乞與人，十千五千旋沽酒。","赤心用盡爲知己，黃金不惜栽桃李。","桃李栽來幾度春，一回花落一回新。","府縣盡爲門下客，王侯皆是平交人。","男兒百年且樂命，何須徇書受貧病。","男兒百年且榮身，何須徇節甘風塵。","衣冠半是征戰士，窮儒浪作林泉民。","遮莫枝根長百丈，不如當代多還往。","遮莫姻親連帝城，不如當身自簪纓。","看取富貴眼前者，何用悠悠身後名。"]', '["君不见淮南少年游俠客，白日毬獵夜擁擲。","呼盧百万終不惜，報讎千里如咫尺。","少年游俠好經過，渾身裝束皆綺羅。","蕙蘭相隨喧妓女，风光去处满笙歌。","驕矜自言不可有，俠士堂中養来久。","好鞍好马乞與人，十千五千旋沽酒。","赤心用尽爲知己，黄金不惜栽桃李。","桃李栽来幾度春，一回花落一回新。","府縣尽爲门下客，王侯皆是平交人。","男兒百年且乐命，何須徇书受貧病。","男兒百年且榮身，何須徇節甘风塵。","衣冠半是征戰士，窮儒浪作林泉民。","遮莫枝根长百丈，不如當代多還往。","遮莫姻親連帝城，不如當身自簪纓。","看取富貴眼前者，何用悠悠身後名。"]', '诗', 'shi', '', NULL, '少年行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cbca79c-cbbf-47f3-afd3-f96e151c2678', '長歌行', '长歌行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["桃李待日開，榮華照當年。","東風動百物，草木盡欲言。","枯枝無醜葉，涸水吐清泉。","大力運天地，羲和無停鞭。","功名不早著，竹帛將何宣。","桃李務青春，誰能貫白日。","富貴與神仙，蹉跎成兩失。","金石猶銷鑠，風霜無久質。","畏落日月後，强歡歌與酒。","秋霜不惜人，倏忽侵蒲柳。"]', '["桃李待日开，榮华照當年。","东风动百物，草木尽欲言。","枯枝無醜葉，涸水吐清泉。","大力運天地，羲和無停鞭。","功名不早著，竹帛將何宣。","桃李務青春，誰能貫白日。","富貴與神仙，蹉跎成兩失。","金石猶銷鑠，风霜無久質。","畏落日月後，强歡歌與酒。","秋霜不惜人，倏忽侵蒲柳。"]', '诗', 'shi', '', NULL, '長歌行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('427d3ea5-681b-4689-90f4-6da4f116ef11', '長相思 一', '长相思 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["日色已盡花含煙，月明欲素愁不眠。","趙瑟初停鳳凰柱，蜀琴欲奏鴛鴦弦。","此曲有意無人傳，願隨春風寄燕然，憶君迢迢隔青天。","昔日橫波目，今成流淚泉。","不信妾腸斷，歸來看取明鏡前。"]', '["日色已尽花含煙，月明欲素愁不眠。","趙瑟初停鳳凰柱，蜀琴欲奏鴛鴦弦。","此曲有意無人傳，願隨春风寄燕然，憶君迢迢隔青天。","昔日橫波目，今成流泪泉。","不信妾腸斷，归来看取明镜前。"]', '诗', 'shi', '', NULL, '長相思 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12792cda-8a0c-4af3-b338-c6fbe036b865', '長相思 二', '长相思 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["美人在時花滿堂，美人去後空餘牀。","牀中繡被卷不寢，至今三載猶聞香。","香亦竟不滅，人亦竟不來。","相思黃葉落，白露點青苔。"]', '["美人在时花满堂，美人去後空餘牀。","牀中繡被卷不寢，至今三載猶闻香。","香亦竟不滅，人亦竟不来。","相思黄葉落，白露点青苔。"]', '诗', 'shi', '', NULL, '長相思 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('174d0a8f-1350-4736-92d3-5c9f16fcff1f', '猛虎行', '猛虎行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["朝作猛虎行，暮作猛虎吟。","腸斷非關隴頭水，淚下不爲雍門琴。","旌旗繽紛兩河道，戰鼓驚山欲顛倒。","秦人半作燕地囚，胡馬翻銜洛陽草。","一輸一失關下兵，朝降夕叛幽薊城。","巨鼇未斬海水動，魚龍奔走安得寧。","頗似楚漢時，翻覆無定止。","朝過博浪沙，暮入淮陰市。","張良未遇韓信貧，劉項存亡在兩臣。","蹔到下邳受兵略，來投漂母作主人。","賢哲棲棲古如此，今時亦棄青雲士。","有策不敢犯龍鱗，竄身南國避胡塵。","寶書玉劒挂高閣，金鞍駿馬散故人。","昨日方爲宣城客，掣鈴交通二千石。","有時六博快壯心，遶牀三匝呼一擲。","楚人每道張旭奇，心藏風雲世莫知。","三吳邦伯皆顧盼，四海雄俠兩追隨。","蕭曹曾作沛中吏，攀龍附鳳當有時。","溧陽酒樓三月春，楊花茫茫愁殺人。","胡雛綠眼吹玉笛，吳歌白紵飛梁塵。","丈夫相見且爲樂，槌牛撾鼓會衆賓。","我從此去釣東海，得魚笑寄情相親。"]', '["朝作猛虎行，暮作猛虎吟。","腸斷非关隴头水，泪下不爲雍门琴。","旌旗繽紛兩河道，戰鼓驚山欲顛倒。","秦人半作燕地囚，胡马翻銜洛陽草。","一輸一失关下兵，朝降夕叛幽薊城。","巨鼇未斬海水动，鱼龙奔走安得寧。","頗似楚漢时，翻覆無定止。","朝過博浪沙，暮入淮陰市。","張良未遇韓信貧，劉項存亡在兩臣。","蹔到下邳受兵略，来投漂母作主人。","賢哲棲棲古如此，今时亦棄青云士。","有策不敢犯龙鱗，竄身南国避胡塵。","寶书玉劒挂高閣，金鞍駿马散故人。","昨日方爲宣城客，掣鈴交通二千石。","有时六博快壯心，遶牀三匝呼一擲。","楚人每道張旭奇，心藏风云世莫知。","三吳邦伯皆顧盼，四海雄俠兩追隨。","蕭曹曾作沛中吏，攀龙附鳳當有时。","溧陽酒楼三月春，楊花茫茫愁殺人。","胡雛綠眼吹玉笛，吳歌白紵飞梁塵。","丈夫相见且爲乐，槌牛撾鼓會衆賓。","我從此去釣东海，得鱼笑寄情相親。"]', '诗', 'shi', '', NULL, '猛虎行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37b09928-1193-4162-903a-d788c99863d8', '去婦詞', '去婦词', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["古來有棄婦，棄婦有歸處。","今日妾辭君，辭君遣何去。","本家零落盡，慟哭來時路。","憶昔未嫁君，聞君却周旋。","綺羅錦繡段，有贈黃金千。","十五許嫁君，二十移所天。","自從結髮日未幾，離君緬山川。","家家盡歡喜，孤妾長自憐。","幽閨多怨思，盛色無十年。","相思若循還，枕席生流泉。","流泉咽不掃，獨夢關山道。","及此見君歸，君歸妾已老。","物情惡衰賤，新寵方妍好。","掩淚出故房，傷心劇秋草。","自妾爲君妻，君東妾在西。","羅幃到曉恨，玉貌一生啼。","自從離別久，不覺塵埃厚。","嘗嫌玳瑁孤，猶羨鴛鴦偶。","歲華逐霜霰，賤妾何能久。","寒沼落芙蓉，秋風散楊柳。","以比顦顇顏，空持舊物還。","餘生欲何寄，誰肯相牽攀。","君恩既斷絕，相見何年月。","悔傾連理杯，虛作同心結。","女蘿附青松，貴欲相依投。","浮萍失綠水，教作若爲流。","不歎君棄妾，自歎妾緣業。","憶昔初嫁君，小姑纔倚牀。","今日妾辭君，小姑如妾長。","回頭語小姑，莫嫁如兄夫。"]', '["古来有棄婦，棄婦有归处。","今日妾辞君，辞君遣何去。","本家零落尽，慟哭来时路。","憶昔未嫁君，闻君却周旋。","綺羅錦繡段，有贈黄金千。","十五許嫁君，二十移所天。","自從結髮日未幾，離君緬山川。","家家尽歡喜，孤妾长自怜。","幽閨多怨思，盛色無十年。","相思若循還，枕席生流泉。","流泉咽不掃，独梦关山道。","及此见君归，君归妾已老。","物情惡衰賤，新寵方妍好。","掩泪出故房，傷心劇秋草。","自妾爲君妻，君东妾在西。","羅幃到晓恨，玉貌一生啼。","自從離別久，不覺塵埃厚。","嘗嫌玳瑁孤，猶羨鴛鴦偶。","歲华逐霜霰，賤妾何能久。","寒沼落芙蓉，秋风散楊柳。","以比顦顇顏，空持旧物還。","餘生欲何寄，誰肯相牽攀。","君恩既斷絕，相见何年月。","悔傾連理杯，虛作同心結。","女蘿附青松，貴欲相依投。","浮萍失綠水，教作若爲流。","不歎君棄妾，自歎妾緣業。","憶昔初嫁君，小姑纔倚牀。","今日妾辞君，小姑如妾长。","回头語小姑，莫嫁如兄夫。"]', '诗', 'shi', '', NULL, '去婦詞 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('569ee61d-350a-4d24-b320-b2e99ca54dd7', '襄陽歌', '襄陽歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["落日欲沒峴山西，倒著接䍦花下迷。","襄陽小兒齊拍手，攔街爭唱白銅鞮。","傍人借問笑何事，笑殺山翁醉似泥。","鸕鷀杓，鸚鵡杯，百年三萬六千日，一日須傾三百杯。","遙看漢水鴨頭綠，恰似葡萄初醱醅。","此江若變作春酒，壘麴便築糟丘臺。","千金駿馬換小妾，笑坐雕鞍歌落梅。","車傍側挂一壺酒，鳳笙龍管行相摧。","咸陽市中歎黃犬，何如月下傾金罍。","君不見晉朝羊公一片石，龜頭剝落生莓苔。","淚亦不能爲之墮，心亦不能爲之哀。","清風朗月不用一錢買，玉山自倒非人推。","舒州杓，力士鐺，李白與爾同死生。","襄王雲雨今安在，江水東流猨夜聲。"]', '["落日欲沒峴山西，倒著接䍦花下迷。","襄陽小兒齊拍手，攔街爭唱白銅鞮。","傍人借问笑何事，笑殺山翁醉似泥。","鸕鷀杓，鸚鵡杯，百年三万六千日，一日須傾三百杯。","遙看漢水鴨头綠，恰似葡萄初醱醅。","此江若变作春酒，壘麴便築糟丘台。","千金駿马換小妾，笑坐雕鞍歌落梅。","车傍側挂一壺酒，鳳笙龙管行相摧。","咸陽市中歎黄犬，何如月下傾金罍。","君不见晉朝羊公一片石，龟头剝落生莓苔。","泪亦不能爲之墮，心亦不能爲之哀。","清风朗月不用一錢買，玉山自倒非人推。","舒州杓，力士鐺，李白與爾同死生。","襄王云雨今安在，江水东流猨夜声。"]', '诗', 'shi', '', NULL, '襄陽歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6cf8d2d-6d88-4914-84c9-61f5cf52cfc1', '南都行', '南都行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["南都信佳麗，武闕橫西關。","白水真人居，萬商羅鄽闤。","高樓對紫陌，甲第連青山。","此地多英豪，邈然不可攀。","陶朱與五羖，名播天壤間。","麗華秀玉色，漢女嬌朱顏。","清歌遏流雲，豔舞有餘閑。","遨遊盛宛洛，冠蓋隨風還。","走馬紅陽城，呼鷹白河灣。","誰識臥龍客，長吟愁鬢斑。"]', '["南都信佳丽，武闕橫西关。","白水真人居，万商羅鄽闤。","高楼对紫陌，甲第連青山。","此地多英豪，邈然不可攀。","陶朱與五羖，名播天壤间。","丽华秀玉色，漢女嬌朱顏。","清歌遏流云，豔舞有餘闲。","遨游盛宛洛，冠蓋隨风還。","走马紅陽城，呼鷹白河灣。","誰識臥龙客，长吟愁鬢斑。"]', '诗', 'shi', '', NULL, '南都行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5945ca23-1072-44ab-9e3a-04b8bbc3c74d', '江上吟', '江上吟', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["木蘭之枻沙棠舟，玉簫金管坐兩頭。","美酒尊中置千斛，載妓隨波任去留。","仙人有待乘黃鶴，海客無心隨白鷗。","屈平詞賦懸日月，楚王臺榭空山丘。","興酣落筆搖五嶽，詩成笑傲凌滄洲。","功名富貴若長在，漢水亦應西北流。"]', '["木蘭之枻沙棠舟，玉簫金管坐兩头。","美酒尊中置千斛，載妓隨波任去留。","仙人有待乘黄鹤，海客無心隨白鷗。","屈平词賦懸日月，楚王台榭空山丘。","兴酣落笔搖五嶽，诗成笑傲凌滄洲。","功名富貴若长在，漢水亦應西北流。"]', '诗', 'shi', '', NULL, '江上吟 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11c0a3c7-dbae-46d3-bb72-7b75b76ba02e', '侍從宜春苑奉詔賦龍池柳色初青聽新鶯百囀歌', '侍從宜春苑奉詔賦龙池柳色初青听新鶯百囀歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["東風已綠瀛洲草，紫殿紅樓覺春好，池南柳色半青青。","縈烟嫋娜拂綺城，垂絲百尺挂雕楹。","上有好鳥相和鳴，間關早得春風情。","春風卷入碧雲去，千門萬戶皆春聲。","是時君王在鎬京，五雲垂暉耀紫清。","仗出金宮隨日轉，天回玉輦繞花行。","始向蓬萊看舞鶴，還過茝石聽新鶯。","新鶯飛繞上林苑，願入簫韶雜鳳笙。"]', '["东风已綠瀛洲草，紫殿紅楼覺春好，池南柳色半青青。","縈烟嫋娜拂綺城，垂絲百尺挂雕楹。","上有好鸟相和鳴，间关早得春风情。","春风卷入碧云去，千门万戶皆春声。","是时君王在鎬京，五云垂暉耀紫清。","仗出金宮隨日轉，天回玉輦繞花行。","始向蓬萊看舞鹤，還過茝石听新鶯。","新鶯飞繞上林苑，願入簫韶杂鳳笙。"]', '诗', 'shi', '', NULL, '侍從宜春苑奉詔賦龍池柳色初青聽新鶯百囀歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6173ae4-186d-4ac0-8804-2ab36ecf4606', '玉壺吟', '玉壺吟', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["烈士擊玉壺，壯心惜暮年。","三杯拂劒舞秋月，忽然高詠涕泗漣。","鳳凰初下紫泥詔，謁帝稱觴登御筵。","揄揚九重萬乘主，謔浪赤墀青瑣賢。","朝天數換飛龍馬，勅賜珊瑚白玉鞭。","世人不識東方朔，大隱金門是謫仙。","西施宜笑復宜嚬，醜女效之徒累身。","君王雖愛蛾眉好，無奈宮中妬殺人。"]', '["烈士擊玉壺，壯心惜暮年。","三杯拂劒舞秋月，忽然高詠涕泗漣。","鳳凰初下紫泥詔，謁帝稱觴登御筵。","揄揚九重万乘主，謔浪赤墀青瑣賢。","朝天數換飞龙马，勅賜珊瑚白玉鞭。","世人不識东方朔，大隐金门是謫仙。","西施宜笑复宜嚬，醜女效之徒累身。","君王雖愛蛾眉好，無奈宮中妬殺人。"]', '诗', 'shi', '', NULL, '玉壺吟 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c23e8a0a-bc62-4f63-99b5-5d6032ccafe9', '豳歌行上新平長史兄粲', '豳歌行上新平长史兄粲', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["豳谷稍稍振庭柯，涇水浩浩揚湍波。","哀鴻酸嘶暮聲急，愁雲蒼慘寒氣多。","憶昨去家此爲客，荷花初紅柳條碧。","中宵出飲三百杯，明朝歸揖二千石。","寧知流寓變光輝，胡霜蕭颯繞客衣。","寒灰寂寞憑誰暖，落葉飄揚何處歸。","吾兄行樂窮曛旭，滿堂有美顏如玉。","趙女長歌入綵雲，燕姬醉舞嬌紅燭。","狐裘獸炭酌流霞，壯士悲吟寧見嗟。","前榮後枯相翻覆，何惜餘光及棣華。"]', '["豳谷稍稍振庭柯，涇水浩浩揚湍波。","哀鴻酸嘶暮声急，愁云蒼慘寒氣多。","憶昨去家此爲客，荷花初紅柳條碧。","中宵出饮三百杯，明朝归揖二千石。","寧知流寓变光輝，胡霜蕭颯繞客衣。","寒灰寂寞憑誰暖，落葉飄揚何处归。","吾兄行乐窮曛旭，满堂有美顏如玉。","趙女长歌入綵云，燕姬醉舞嬌紅燭。","狐裘獸炭酌流霞，壯士悲吟寧见嗟。","前榮後枯相翻覆，何惜餘光及棣华。"]', '诗', 'shi', '', NULL, '豳歌行上新平長史兄粲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15394b6f-365e-4ac8-9eaf-1d394d41c58c', '西嶽雲臺歌送丹丘子', '西嶽云台歌送丹丘子', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["西嶽崢嶸何壯哉，黃河如絲天際來。","黃河萬里觸山動，盤渦轂轉秦地雷。","榮光休氣紛五彩，千年一清聖人在。","巨靈咆哮擘兩山，洪波噴箭射東海。","三峯却立如欲摧，翠崖丹谷高掌開。","白帝金精運元氣，石作蓮花雲作臺。","雲臺閣道連窈冥，中有不死丹丘生。","明星玉女備灑掃，麻姑搔背指爪輕。","我皇手把天地戶，丹丘談天與天語。","九重出入生光輝，東來蓬萊復西歸。","玉漿儻惠故人飲，騎二茅龍上天飛。"]', '["西嶽崢嶸何壯哉，黄河如絲天際来。","黄河万里觸山动，盤渦轂轉秦地雷。","榮光休氣紛五彩，千年一清聖人在。","巨靈咆哮擘兩山，洪波噴箭射东海。","三峯却立如欲摧，翠崖丹谷高掌开。","白帝金精運元氣，石作蓮花云作台。","云台閣道連窈冥，中有不死丹丘生。","明星玉女備灑掃，麻姑搔背指爪轻。","我皇手把天地戶，丹丘談天與天語。","九重出入生光輝，东来蓬萊复西归。","玉漿儻惠故人饮，騎二茅龙上天飞。"]', '诗', 'shi', '', NULL, '西嶽雲臺歌送丹丘子 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1596c459-4184-412c-9538-e0a663e00d42', '元丹丘歌', '元丹丘歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["元丹丘，愛神仙，朝飲潁川之清流，暮還嵩岑之紫烟，三十六峰長周旋。","長周旋，躡星虹，身騎飛龍耳生風。","橫河跨海與天通，我知爾遊心無窮。"]', '["元丹丘，愛神仙，朝饮潁川之清流，暮還嵩岑之紫烟，三十六峰长周旋。","长周旋，躡星虹，身騎飞龙耳生风。","橫河跨海與天通，我知爾游心無窮。"]', '诗', 'shi', '', NULL, '元丹丘歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e21baa8a-c2cb-48eb-822b-2041486980da', '扶風豪士歌', '扶风豪士歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["洛陽三月飛胡沙，洛陽城中人怨嗟。","天津流水波赤血，白骨相撐如亂麻。","我亦東奔向吳國，浮雲四塞道路賒。","東方日出啼早鴉，城門人開掃落花。","梧桐楊柳拂金井，來醉扶風豪士家。","扶風豪士天下奇，意氣相傾山可移。","作人不倚將軍勢，飲酒豈顧尚書期。","雕盤綺食會衆客，吳歌趙舞香風吹。","原嘗春陵六國時，開心寫意君所知。","堂中各有三千士，明日報恩知是誰。","撫長劒，一揚眉，清水白石何離離。","脫吾帽，向君笑，飲君酒，爲君吟。","張良未逐赤松去，橋邊黃石知我心。"]', '["洛陽三月飞胡沙，洛陽城中人怨嗟。","天津流水波赤血，白骨相撐如亂麻。","我亦东奔向吳国，浮云四塞道路賒。","东方日出啼早鴉，城门人开掃落花。","梧桐楊柳拂金井，来醉扶风豪士家。","扶风豪士天下奇，意氣相傾山可移。","作人不倚將軍勢，饮酒豈顧尚书期。","雕盤綺食會衆客，吳歌趙舞香风吹。","原嘗春陵六国时，开心寫意君所知。","堂中各有三千士，明日報恩知是誰。","撫长劒，一揚眉，清水白石何離離。","脫吾帽，向君笑，饮君酒，爲君吟。","張良未逐赤松去，橋邊黄石知我心。"]', '诗', 'shi', '', NULL, '扶風豪士歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3b648df-c3d8-4f61-904f-e50cc5864f0a', '同族弟金城尉叔卿燭照山水壁畫歌', '同族弟金城尉叔卿燭照山水壁畫歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["高堂粉壁圖蓬瀛，燭前一見滄洲清。","洪波洶湧山崢嶸，皎若丹丘隔海望赤城。","光中乍喜嵐氣滅，謂逢山陰晴後雪。","迴溪碧流寂無喧，又如秦人月下窺花源。","了然不覺清心魂，祗將疊嶂鳴秋猨。","與君對此歡未歇，放歌行吟達明發。","却顧海客揚雲帆，便欲因之向溟渤。"]', '["高堂粉壁圖蓬瀛，燭前一见滄洲清。","洪波洶湧山崢嶸，皎若丹丘隔海望赤城。","光中乍喜嵐氣滅，謂逢山陰晴後雪。","迴溪碧流寂無喧，又如秦人月下窺花源。","了然不覺清心魂，祗將叠嶂鳴秋猨。","與君对此歡未歇，放歌行吟達明發。","却顧海客揚云帆，便欲因之向溟渤。"]', '诗', 'shi', '', NULL, '同族弟金城尉叔卿燭照山水壁畫歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3883a24-6c95-430b-863e-caa570aa90a1', '白毫子歌', '白毫子歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["淮南小山白毫子，乃在淮南小山裏。","夜臥松下雲，朝餐石中髓。","小山連緜向江開，碧峰巉巖綠水迴。","余配白毫子，獨酌流霞杯。","拂花弄琴坐青苔，綠蘿樹下春風來。","南窗蕭颯松聲起，憑崖一聽清心耳。","可得見，未得親。","八公攜手五雲去，空餘桂樹愁殺人。"]', '["淮南小山白毫子，乃在淮南小山裏。","夜臥松下云，朝餐石中髓。","小山連緜向江开，碧峰巉巖綠水迴。","余配白毫子，独酌流霞杯。","拂花弄琴坐青苔，綠蘿樹下春风来。","南窗蕭颯松声起，憑崖一听清心耳。","可得见，未得親。","八公携手五云去，空餘桂樹愁殺人。"]', '诗', 'shi', '', NULL, '白毫子歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14febea6-9b81-4ef4-9b50-b1b6138a161c', '梁園吟', '梁园吟', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我浮黃雲去京闕，挂席欲進波連山。","天長水闊厭遠涉，訪古始及平臺間。","平臺爲客憂思多，對酒遂作梁園歌。","却憶蓬池阮公詠，因吟淥水揚洪波。","洪波浩蕩迷舊國，路遠西歸安可得。","人生達命豈暇愁，且飲美酒登高樓。","平頭奴子搖大扇，五月不熱疑清秋。","玉盤楊梅爲君設，吳鹽如花皎白雪。","持鹽把酒但飲之，莫學夷齊事高潔。","昔人豪貴信陵君，今人耕種信陵墳。","荒城虛照碧山月，古木盡入蒼梧雲。","粱王宮闕今安在？枚馬先歸不相待。","舞影歌聲散綠池，空餘汴水東流海。","沈吟此事淚滿衣，黃金買醉未能歸。","連呼五白行六博，分曹賭酒酣馳輝。","歌且謠，意方遠，東山高臥時起來，欲濟蒼生未應晚。"]', '["我浮黄云去京闕，挂席欲進波連山。","天长水闊厭远涉，訪古始及平台间。","平台爲客憂思多，对酒遂作梁园歌。","却憶蓬池阮公詠，因吟淥水揚洪波。","洪波浩蕩迷旧国，路远西归安可得。","人生達命豈暇愁，且饮美酒登高楼。","平头奴子搖大扇，五月不熱疑清秋。","玉盤楊梅爲君設，吳鹽如花皎白雪。","持鹽把酒但饮之，莫学夷齊事高潔。","昔人豪貴信陵君，今人耕種信陵墳。","荒城虛照碧山月，古木尽入蒼梧云。","粱王宮闕今安在？枚马先归不相待。","舞影歌声散綠池，空餘汴水东流海。","沈吟此事泪满衣，黄金買醉未能归。","連呼五白行六博，分曹賭酒酣驰輝。","歌且謠，意方远，东山高臥时起来，欲濟蒼生未應晚。"]', '诗', 'shi', '', NULL, '梁園吟 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa4aebdb-e612-4a09-9c23-2f02617ccf69', '鳴臯歌送岑徵君', '鳴臯歌送岑徵君', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["若有人兮思鳴臯，阻積雪兮心煩勞。","洪河凌競不可以徑度，冰龍鱗兮難容舠。","邈仙山之峻極兮，聞天籟之嘈嘈。","霜厓縞皓以合沓兮，若長風扇海湧滄溟之波濤。","玄猨綠羆，舔舕崟岌。","危柯振石，駭膽慄魄，羣呼而相號。","峯崢嶸以路絕，挂星辰於巖㟼。","送君之歸兮，動鳴臯之新作。","交鼓吹兮彈絲，觴清泠之池閣。","君不行兮何待，若反顧之黃鶴。","掃梁園之羣英，振大雅於東洛。","巾征軒兮歷阻折，尋幽居兮越巘崿。","盤白石兮坐素月，琴松風兮寂萬壑。","望不見兮心氛氳，蘿冥冥兮霰紛紛。","水橫洞以下淥，波小聲而上聞。","虎嘯谷而生風，龍藏溪而吐雲。","寡鶴清唳，飢鼯嚬呻。","魂獨處此幽默兮，愀空山而愁人。","雞聚族以爭食，鳳孤飛而無隣。","蝘蜓嘲龍，魚目混珍。","嫫母衣錦，西施負薪。","若使巢由桎梏於軒冕兮，亦奚異乎夔龍蹩躠於風塵。","哭何苦而救楚，笑何誇而却秦。","吾誠不能學二子沽名矯節以耀世兮，固將棄天地而遺身。","白鷗兮飛來，長與君兮相親。"]', '["若有人兮思鳴臯，阻積雪兮心煩勞。","洪河凌競不可以徑度，冰龙鱗兮难容舠。","邈仙山之峻極兮，闻天籟之嘈嘈。","霜厓縞皓以合沓兮，若长风扇海湧滄溟之波濤。","玄猨綠羆，舔舕崟岌。","危柯振石，駭膽慄魄，羣呼而相號。","峯崢嶸以路絕，挂星辰於巖㟼。","送君之归兮，动鳴臯之新作。","交鼓吹兮彈絲，觴清泠之池閣。","君不行兮何待，若反顧之黄鹤。","掃梁园之羣英，振大雅於东洛。","巾征軒兮歷阻折，尋幽居兮越巘崿。","盤白石兮坐素月，琴松风兮寂万壑。","望不见兮心氛氳，蘿冥冥兮霰紛紛。","水橫洞以下淥，波小声而上闻。","虎嘯谷而生风，龙藏溪而吐云。","寡鹤清唳，飢鼯嚬呻。","魂独处此幽默兮，愀空山而愁人。","雞聚族以爭食，鳳孤飞而無隣。","蝘蜓嘲龙，鱼目混珍。","嫫母衣錦，西施負薪。","若使巢由桎梏於軒冕兮，亦奚異乎夔龙蹩躠於风塵。","哭何苦而救楚，笑何誇而却秦。","吾誠不能学二子沽名矯節以耀世兮，固將棄天地而遺身。","白鷗兮飞来，长與君兮相親。"]', '诗', 'shi', '', NULL, '鳴臯歌送岑徵君 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec25cdb5-9da2-4142-9fdb-0560787f854d', '鳴臯歌奉餞從翁清歸五厓山居', '鳴臯歌奉餞從翁清归五厓山居', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["憶昨鳴臯夢裏還，手弄素月清潭間。","覺時枕席非碧山，側身西望阻秦關。","麒膦閣上春還早，著書却憶伊陽好。","青松來風吹古道，綠蘿飛花覆烟草。","我家仙翁愛清真，才雄草聖凌古人，欲臥鳴臯絕世塵。","鳴臯微茫在何處？五厓峽水橫樵路。","身披翠雲裘，袖拂紫烟去。","去時應過嵩少間，相思爲折三花樹。"]', '["憶昨鳴臯梦裏還，手弄素月清潭间。","覺时枕席非碧山，側身西望阻秦关。","麒膦閣上春還早，著书却憶伊陽好。","青松来风吹古道，綠蘿飞花覆烟草。","我家仙翁愛清真，才雄草聖凌古人，欲臥鳴臯絕世塵。","鳴臯微茫在何处？五厓峽水橫樵路。","身披翠云裘，袖拂紫烟去。","去时應過嵩少间，相思爲折三花樹。"]', '诗', 'shi', '', NULL, '鳴臯歌奉餞從翁清歸五厓山居 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7159e6e2-2682-4984-9d32-43f5acefb97c', '勞勞亭歌', '勞勞亭歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["金陵勞勞送客堂，蔓草離離生道傍。","古情不盡東流水，此地悲風愁白楊。","我乘素舸同康樂，朗詠清川飛夜霜。","昔聞牛渚吟五章，今來何謝袁家郎。","苦竹寒聲動秋月，獨宿空簾歸夢長。"]', '["金陵勞勞送客堂，蔓草離離生道傍。","古情不尽东流水，此地悲风愁白楊。","我乘素舸同康乐，朗詠清川飞夜霜。","昔闻牛渚吟五章，今来何謝袁家郎。","苦竹寒声动秋月，独宿空簾归梦长。"]', '诗', 'shi', '', NULL, '勞勞亭歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58462be4-aa40-4a7f-a879-1c38832a838c', '橫江詞六首 一', '橫江词六首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["人道橫江好，儂道橫江惡。","一風三日吹倒山，白浪高於瓦官閣。"]', '["人道橫江好，儂道橫江惡。","一风三日吹倒山，白浪高於瓦官閣。"]', '诗', 'shi', '', NULL, '橫江詞六首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c16cfbee-41fc-4170-a5f5-c8bf3793fd36', '橫江詞六首 二', '橫江词六首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["海潮南去過潯陽，牛渚由來險馬當。","橫江欲渡風波惡，一水牽愁萬里長。"]', '["海潮南去過潯陽，牛渚由来險马當。","橫江欲渡风波惡，一水牽愁万里长。"]', '诗', 'shi', '', NULL, '橫江詞六首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbe66c93-b169-4720-87de-e4bcc325b874', '橫江詞六首 三', '橫江词六首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["橫江西望阻西秦，漢水東連揚子津。","白浪如山那可渡，狂風愁殺峭帆人。"]', '["橫江西望阻西秦，漢水东連揚子津。","白浪如山那可渡，狂风愁殺峭帆人。"]', '诗', 'shi', '', NULL, '橫江詞六首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('902ee0e4-1534-4353-bc48-5acefc0fdfd6', '橫江詞六首 四', '橫江词六首 四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["海神來過惡風迴，浪打天門石壁開。","浙江八月何如此，濤似連山噴雪來。"]', '["海神来過惡风迴，浪打天门石壁开。","浙江八月何如此，濤似連山噴雪来。"]', '诗', 'shi', '', NULL, '橫江詞六首 四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b77bc04-02d5-49ea-ac32-438ab33eadb2', '橫江詞六首 五', '橫江词六首 五', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["橫江館前津吏迎，向余東指海雲生。","郎今欲渡緣何事，如此風波不可行。"]', '["橫江館前津吏迎，向余东指海云生。","郎今欲渡緣何事，如此风波不可行。"]', '诗', 'shi', '', NULL, '橫江詞六首 五 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dd83676-e8ed-4d6e-ae39-7337590ed2f4', '橫江詞六首 六', '橫江词六首 六', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["月暈天風霧不開，海鯨東蹙百川迴。","驚波一起三山動，公無渡河歸去來。"]', '["月暈天风霧不开，海鯨东蹙百川迴。","驚波一起三山动，公無渡河归去来。"]', '诗', 'shi', '', NULL, '橫江詞六首 六 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53b6b263-edaa-41a6-b7c2-b896c22de8c4', '金陵城西樓月下吟', '金陵城西楼月下吟', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["金陵夜寂涼風發，獨上高樓望吳越。","白雲暎水搖空城，白露垂珠滴秋月。","月下沈吟久不歸，古來相接眼中稀。","解道澄江淨如練，令人長憶謝玄暉。"]', '["金陵夜寂涼风發，独上高楼望吳越。","白云暎水搖空城，白露垂珠滴秋月。","月下沈吟久不归，古来相接眼中稀。","解道澄江淨如練，令人长憶謝玄暉。"]', '诗', 'shi', '', NULL, '金陵城西樓月下吟 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('738b8857-2149-414e-87ae-0213953d78ee', '東山吟', '东山吟', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["攜妓東土山，悵然悲謝安。","我妓今朝如花月，他妓古墳荒草寒。","白雞夢後三百歲，洒酒澆君同所歡。","酣來自作青海舞，秋風吹落紫綺冠。","彼亦一時，此亦一時，浩浩洪流之詠何必奇。"]', '["携妓东土山，悵然悲謝安。","我妓今朝如花月，他妓古墳荒草寒。","白雞梦後三百歲，洒酒澆君同所歡。","酣来自作青海舞，秋风吹落紫綺冠。","彼亦一时，此亦一时，浩浩洪流之詠何必奇。"]', '诗', 'shi', '', NULL, '東山吟 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6961a819-c817-459d-aa25-fde06e991df7', '僧伽歌', '僧伽歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["真僧法號號僧伽，有時與我論三車。","問言誦咒幾千徧，口道恆河沙復沙。","此僧本住南天竺，爲法頭陀來此國。","戒得長天秋月明，心如世上青蓮色。","意清淨，貌稜稜，亦不減，亦不增。","瓶裏千年鐵柱骨，手中萬歲胡孫藤。","嗟予落魄江淮久，罕遇真僧說空有。","一言散盡波羅夷，再禮渾除犯輕垢。"]', '["真僧法號號僧伽，有时與我論三车。","问言誦咒幾千徧，口道恆河沙复沙。","此僧本住南天竺，爲法头陀来此国。","戒得长天秋月明，心如世上青蓮色。","意清淨，貌稜稜，亦不減，亦不增。","瓶裏千年鐵柱骨，手中万歲胡孫藤。","嗟予落魄江淮久，罕遇真僧说空有。","一言散尽波羅夷，再禮渾除犯轻垢。"]', '诗', 'shi', '', NULL, '僧伽歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bc47782-7c80-4541-87f1-d1a657e2c24a', '白雲歌送劉十六歸山', '白云歌送劉十六归山', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["楚山秦山皆白雲，白雲處處長隨君。","長隨君，君入楚山裏，雲亦隨君渡湘水。","湘水上，女蘿衣，白雲堪臥君早歸。"]', '["楚山秦山皆白云，白云处处长隨君。","长隨君，君入楚山裏，云亦隨君渡湘水。","湘水上，女蘿衣，白云堪臥君早归。"]', '诗', 'shi', '', NULL, '白雲歌送劉十六歸山 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e6c43ff-126c-4e1d-a4df-cd6e8adc31a6', '白雲歌送友人', '白云歌送友人', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["楚山秦山多白雲，白雲䖏䖏長隨君。","君今還入楚山裏，雲亦隨君渡湘水。","水上女蘿衣白雲，早卧早行君早起。"]', '["楚山秦山多白云，白云䖏䖏长隨君。","君今還入楚山裏，云亦隨君渡湘水。","水上女蘿衣白云，早卧早行君早起。"]', '诗', 'shi', '', NULL, '白雲歌送友人 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d90b9ba-9e08-4f8d-ae30-f159dfb7fc94', '金陵歌送別范宣', '金陵歌送別范宣', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["石頭巉巖如虎踞，凌波欲過滄江去。","鍾山龍盤走勢來，秀色橫分歷陽樹。","四十餘帝三百秋，功名事跡隨東流。","白馬小兒誰家子，泰清之歲來關囚。","金陵昔時何壯哉，席卷英豪天下來。","冠蓋散爲烟霧盡，金輿玉座成寒灰。","扣劒悲吟空咄嗟，梁陳白骨亂如麻。","天子龍沈景陽井，誰歌玉樹後庭花。","此地傷心不能道，目下離離長春草。","送爾長江萬里心，他年來訪南山老。"]', '["石头巉巖如虎踞，凌波欲過滄江去。","鍾山龙盤走勢来，秀色橫分歷陽樹。","四十餘帝三百秋，功名事跡隨东流。","白马小兒誰家子，泰清之歲来关囚。","金陵昔时何壯哉，席卷英豪天下来。","冠蓋散爲烟霧尽，金輿玉座成寒灰。","扣劒悲吟空咄嗟，梁陳白骨亂如麻。","天子龙沈景陽井，誰歌玉樹後庭花。","此地傷心不能道，目下離離长春草。","送爾长江万里心，他年来訪南山老。"]', '诗', 'shi', '', NULL, '金陵歌送別范宣 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae50afae-05a7-43c5-b362-0eecf9f49622', '笑歌行', '笑歌行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["笑矣乎，笑矣乎！君不見曲如鉤，古人知爾封公侯。","君不見直如弦，古人知爾死道邊。","張儀所以只掉三寸舌，蘇秦所以不墾二傾田。","笑矣乎，笑矣乎！君不見滄浪老人歌一曲，還道滄浪濯吾足。","平生不解謀此身，虛作離騷遣人讀。","笑矣乎，笑矣乎！趙有豫讓楚屈平，賣身買得千年名。","巢由洗耳有何益，夷齊餓死終無成。","君愛身後名，我愛眼前酒。","飲酒眼前樂，虛名何處有。","男兒窮通當有時，曲腰向君君不知。","猛虎不看几上肉，洪鑪不鑄囊中錐。","笑矣乎，笑矣乎！甯武子，朱買臣，扣角行歌背負薪。","今日逢君君不識，豈得不如佯狂人。"]', '["笑矣乎，笑矣乎！君不见曲如鉤，古人知爾封公侯。","君不见直如弦，古人知爾死道邊。","張儀所以只掉三寸舌，蘇秦所以不墾二傾田。","笑矣乎，笑矣乎！君不见滄浪老人歌一曲，還道滄浪濯吾足。","平生不解謀此身，虛作離騷遣人读。","笑矣乎，笑矣乎！趙有豫讓楚屈平，賣身買得千年名。","巢由洗耳有何益，夷齊餓死終無成。","君愛身後名，我愛眼前酒。","饮酒眼前乐，虛名何处有。","男兒窮通當有时，曲腰向君君不知。","猛虎不看几上肉，洪鑪不鑄囊中錐。","笑矣乎，笑矣乎！甯武子，朱買臣，扣角行歌背負薪。","今日逢君君不識，豈得不如佯狂人。"]', '诗', 'shi', '', NULL, '笑歌行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a9f5cbb-1d9e-4d3b-a205-50d81461f6ab', '悲歌行', '悲歌行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["悲來乎，悲來乎！主人有酒且莫斟，聽我一曲悲來吟。","悲來不吟還不笑，天下無人知我心。","君有數斗酒，我有三尺琴。","琴鳴酒樂兩相得，一杯不啻千鈞金。","悲來乎，悲來乎！天雖長，地雖久，金玉滿堂應不守。","富貴百年能幾何，死生一度人皆有。","孤猨坐啼墳上月，且須一盡杯中酒。","悲來乎，悲來乎！鳳皇不至河無圖，微子去之箕子奴。","漢帝不憶李將軍，楚王放却屈大夫。","悲來乎，悲來乎！秦家李斯早追悔，虛名撥向身之外。","范子何曾愛五湖，功成名遂身自退。","劒是一夫用，書能知姓名。","惠施不肯干萬乘，卜式未必窮一經。","還須黑頭取方伯，莫謾白首爲儒生。"]', '["悲来乎，悲来乎！主人有酒且莫斟，听我一曲悲来吟。","悲来不吟還不笑，天下無人知我心。","君有數斗酒，我有三尺琴。","琴鳴酒乐兩相得，一杯不啻千鈞金。","悲来乎，悲来乎！天雖长，地雖久，金玉满堂應不守。","富貴百年能幾何，死生一度人皆有。","孤猨坐啼墳上月，且須一尽杯中酒。","悲来乎，悲来乎！鳳皇不至河無圖，微子去之箕子奴。","漢帝不憶李將軍，楚王放却屈大夫。","悲来乎，悲来乎！秦家李斯早追悔，虛名撥向身之外。","范子何曾愛五湖，功成名遂身自退。","劒是一夫用，书能知姓名。","惠施不肯干万乘，卜式未必窮一經。","還須黑头取方伯，莫謾白首爲儒生。"]', '诗', 'shi', '', NULL, '悲歌行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86dd7753-11d3-48b5-a2ec-75967ea97855', '秋浦歌十七首 一', '秋浦歌十七首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秋浦長似秋，蕭條使人愁。","客愁不可度，行上東大樓。","正西望長安，下見江水流。","寄言向江水，汝意憶儂不。","遙傳一掬淚，爲我達揚州。"]', '["秋浦长似秋，蕭條使人愁。","客愁不可度，行上东大楼。","正西望长安，下见江水流。","寄言向江水，汝意憶儂不。","遙傳一掬泪，爲我達揚州。"]', '诗', 'shi', '', NULL, '秋浦歌十七首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63e6182c-66e4-4c79-9f65-08b63903cfae', '秋浦歌十七首 二', '秋浦歌十七首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秋浦猨夜愁，黃山堪白頭。","清溪非隴水，翻作斷腸流。","欲去不得去，薄遊成久遊。","何年是歸日，雨淚下孤舟。"]', '["秋浦猨夜愁，黄山堪白头。","清溪非隴水，翻作斷腸流。","欲去不得去，薄游成久游。","何年是归日，雨泪下孤舟。"]', '诗', 'shi', '', NULL, '秋浦歌十七首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fba10bdf-612f-40f3-abba-ed86cced0940', '秋浦歌十七首 三', '秋浦歌十七首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秋浦錦駝鳥，人間天上稀。","山雞羞淥水，不敢照毛衣。"]', '["秋浦錦駝鸟，人间天上稀。","山雞羞淥水，不敢照毛衣。"]', '诗', 'shi', '', NULL, '秋浦歌十七首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2d84136-3150-4fd8-9d94-c18b7fb44b71', '秋浦歌十七首 四', '秋浦歌十七首 四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["兩鬢入秋浦，一朝颯已衰。","猨聲催白髮，長短盡成絲。"]', '["兩鬢入秋浦，一朝颯已衰。","猨声催白髮，长短尽成絲。"]', '诗', 'shi', '', NULL, '秋浦歌十七首 四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2e41acb-dbb9-4e5c-86ff-39def83514c0', '秋浦歌十七首 五', '秋浦歌十七首 五', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秋浦多白猨，超騰若飛雪。","牽引條上兒，飲弄水中月。"]', '["秋浦多白猨，超腾若飞雪。","牽引條上兒，饮弄水中月。"]', '诗', 'shi', '', NULL, '秋浦歌十七首 五 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b815ccc6-739b-4ef4-867f-9dfc9c66734e', '秋浦歌十七首 六', '秋浦歌十七首 六', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["愁作秋浦客，強看秋浦花。","山川如剡縣，風日似長沙。"]', '["愁作秋浦客，強看秋浦花。","山川如剡縣，风日似长沙。"]', '诗', 'shi', '', NULL, '秋浦歌十七首 六 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d337413-1a74-44a9-aa6d-c1798fe81b59', '秋浦歌十七首 七', '秋浦歌十七首 七', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["醉上山公馬，寒歌甯戚牛。","空吟白石爛，淚滿黑貂裘。"]', '["醉上山公马，寒歌甯戚牛。","空吟白石爛，泪满黑貂裘。"]', '诗', 'shi', '', NULL, '秋浦歌十七首 七 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('258cad70-5cd1-4373-b1ee-118b2d0cd0a4', '秋浦歌十七首 八', '秋浦歌十七首 八', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秋浦千重嶺，水車嶺最奇。","天傾欲墮石，水拂寄生枝。"]', '["秋浦千重嶺，水车嶺最奇。","天傾欲墮石，水拂寄生枝。"]', '诗', 'shi', '', NULL, '秋浦歌十七首 八 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e5c232e-a4c8-4868-9d39-35434a26691a', '秋浦歌十七首 九', '秋浦歌十七首 九', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["江祖一片石，青天掃畫屏。","題詩留萬古，綠字錦苔生。"]', '["江祖一片石，青天掃畫屏。","題诗留万古，綠字錦苔生。"]', '诗', 'shi', '', NULL, '秋浦歌十七首 九 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88ad039a-16f3-4ea6-8c56-e4394531e039', '秋浦歌十七首 十', '秋浦歌十七首 十', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["千千石楠樹，萬萬女貞林。","山山白鷺滿，澗澗白猨吟。","君莫向秋浦，猨聲碎客心。"]', '["千千石楠樹，万万女貞林。","山山白鷺满，澗澗白猨吟。","君莫向秋浦，猨声碎客心。"]', '诗', 'shi', '', NULL, '秋浦歌十七首 十 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58a66aff-d6a6-4e67-b96b-a9887ee4b7ea', '秋浦歌十七首 十一', '秋浦歌十七首 十一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["邏人（一作「叉」）橫鳥道，江祖出魚梁。","水急客舟（一作「行」）疾，山花拂面香。"]', '["邏人（一作「叉」）橫鸟道，江祖出鱼梁。","水急客舟（一作「行」）疾，山花拂面香。"]', '诗', 'shi', '', NULL, '秋浦歌十七首 十一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('452a8a79-20e5-4322-96a8-657ab4222472', '秋浦歌十七首 十二', '秋浦歌十七首 十二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["水如一匹練，此地即平天。","耐可乘明月，看花上酒船。"]', '["水如一匹練，此地即平天。","耐可乘明月，看花上酒船。"]', '诗', 'shi', '', NULL, '秋浦歌十七首 十二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07710d64-db0a-419e-8a9c-f1afa44c58e0', '秋浦歌十七首 十三', '秋浦歌十七首 十三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["淥水淨素月，月明白鷺飛。","郎聽採菱女，一道夜歌歸。"]', '["淥水淨素月，月明白鷺飞。","郎听採菱女，一道夜歌归。"]', '诗', 'shi', '', NULL, '秋浦歌十七首 十三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11fbf0a3-2f39-400e-832f-4c8ed3931fa8', '秋浦歌十七首 十四', '秋浦歌十七首 十四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["爐火照天地，紅星亂紫煙。","赧郎明月夜，歌曲動寒川。"]', '["爐火照天地，紅星亂紫煙。","赧郎明月夜，歌曲动寒川。"]', '诗', 'shi', '', NULL, '秋浦歌十七首 十四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('968dcfca-7d80-478e-a18b-ba69afe93346', '秋浦歌十七首 十五', '秋浦歌十七首 十五', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白髮三千丈，緣愁似個長。","不知明鏡裡，何處得秋霜。"]', '["白髮三千丈，緣愁似個长。","不知明镜裡，何处得秋霜。"]', '诗', 'shi', '', NULL, '秋浦歌十七首 十五 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e7b87c1-be9b-4e4b-a4cb-02f1ab2950fc', '秋浦歌十七首 十六', '秋浦歌十七首 十六', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秋浦田舍翁，採魚水中宿。","妻子張白鷴，結罝暎深竹。"]', '["秋浦田舍翁，採鱼水中宿。","妻子張白鷴，結罝暎深竹。"]', '诗', 'shi', '', NULL, '秋浦歌十七首 十六 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26e801ac-cc4c-43dc-b55d-65ee6fc94f05', '秋浦歌十七首 十七', '秋浦歌十七首 十七', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["桃波（一作「陂」）一步地，了了語聲聞。","闇與山僧別，低頭禮白雲。"]', '["桃波（一作「陂」）一步地，了了語声闻。","闇與山僧別，低头禮白云。"]', '诗', 'shi', '', NULL, '秋浦歌十七首 十七 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('703a3f52-3784-4006-862a-c0ad356ba855', '當塗趙炎少府粉圖山水歌', '當塗趙炎少府粉圖山水歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["峨眉高出西極天，羅浮直與南溟連。","名公繹思揮彩筆，驅山走海置眼前。","滿堂空翠如可掃，赤城霞氣蒼梧烟。","洞庭瀟湘意渺綿，三江七澤情洄沿。","驚濤洶湧向何處，孤舟一去迷歸年。","征帆不動亦不旋，飄如隨風落天邊。","心搖目斷興難盡，幾時可到三山巔。","西峯崢嶸噴流泉，橫石蹙水波潺湲。","東厓合沓蔽輕霧，深林雜樹空芊綿。","此中冥昧失晝夜，隱几寂聽無鳴蟬。","長松之下列羽客，對坐不語南昌仙。","南昌仙人趙夫子，妙年歷落青雲士。","訟庭無事羅衆賓，杳然如在丹青裏。","五色粉圖安足珍，真仙可以全吾身。","若待功成拂衣去，武陵桃花笑殺人。"]', '["峨眉高出西極天，羅浮直與南溟連。","名公繹思揮彩笔，驱山走海置眼前。","满堂空翠如可掃，赤城霞氣蒼梧烟。","洞庭瀟湘意渺綿，三江七澤情洄沿。","驚濤洶湧向何处，孤舟一去迷归年。","征帆不动亦不旋，飄如隨风落天邊。","心搖目斷兴难尽，幾时可到三山巔。","西峯崢嶸噴流泉，橫石蹙水波潺湲。","东厓合沓蔽轻霧，深林杂樹空芊綿。","此中冥昧失晝夜，隐几寂听無鳴蟬。","长松之下列羽客，对坐不語南昌仙。","南昌仙人趙夫子，妙年歷落青云士。","訟庭無事羅衆賓，杳然如在丹青裏。","五色粉圖安足珍，真仙可以全吾身。","若待功成拂衣去，武陵桃花笑殺人。"]', '诗', 'shi', '', NULL, '當塗趙炎少府粉圖山水歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1faa66c1-a135-4c95-a0f8-ecbd47e2a0a5', '永王東巡歌十一首 一', '永王东巡歌十一首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["永王正月東出師，天子遙分龍虎旗。","樓船一舉風波靜，江漢翻爲雁鶩池。"]', '["永王正月东出師，天子遙分龙虎旗。","楼船一舉风波静，江漢翻爲雁鶩池。"]', '诗', 'shi', '', NULL, '永王東巡歌十一首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cabfb03-bef9-4898-ad85-6d92db0a5aaf', '永王東巡歌十一首 二', '永王东巡歌十一首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["三川北虜亂如麻，四海南奔似永嘉。","但用東山謝安石，爲君談笑靜胡沙。"]', '["三川北虜亂如麻，四海南奔似永嘉。","但用东山謝安石，爲君談笑静胡沙。"]', '诗', 'shi', '', NULL, '永王東巡歌十一首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdcabbfe-c183-4260-a7ae-85a854bad316', '永王東巡歌十一首 三', '永王东巡歌十一首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["雷鼓嘈嘈喧武昌，雲旗獵獵過尋陽。","秋毫不犯三吳悅，春日遙看五色光。"]', '["雷鼓嘈嘈喧武昌，云旗獵獵過尋陽。","秋毫不犯三吳悅，春日遙看五色光。"]', '诗', 'shi', '', NULL, '永王東巡歌十一首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a853c307-f382-4dcd-9c16-d12a385f6961', '永王東巡歌十一首 四', '永王东巡歌十一首 四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["龍蟠虎踞帝王州，帝子金陵訪古丘。","春風試暖昭陽殿，明月還過鳷鵲樓。"]', '["龙蟠虎踞帝王州，帝子金陵訪古丘。","春风試暖昭陽殿，明月還過鳷鵲楼。"]', '诗', 'shi', '', NULL, '永王東巡歌十一首 四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29e61048-40c2-4b98-997b-774bb0248964', '永王東巡歌十一首 五', '永王东巡歌十一首 五', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["二帝巡遊俱未迴，五陵松栢使人哀。","諸侯不救河南地，更喜賢王遠道來。"]', '["二帝巡游俱未迴，五陵松栢使人哀。","諸侯不救河南地，更喜賢王远道来。"]', '诗', 'shi', '', NULL, '永王東巡歌十一首 五 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e0654dd-58d9-40d2-a2fa-b3266cac2d46', '永王東巡歌十一首 六', '永王东巡歌十一首 六', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["丹陽北固是吳關，畫出樓臺雲水間。","千巖烽火連滄海，兩岸旌旗繞碧山。"]', '["丹陽北固是吳关，畫出楼台云水间。","千巖烽火連滄海，兩岸旌旗繞碧山。"]', '诗', 'shi', '', NULL, '永王東巡歌十一首 六 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07f7fe66-f3c9-4c6b-afd1-d955bcdeeb87', '永王東巡歌十一首 七', '永王东巡歌十一首 七', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["王出三山按五湖，樓船跨海次陪都。","戰艦森森羅虎士，征帆一一引龍駒。"]', '["王出三山按五湖，楼船跨海次陪都。","戰艦森森羅虎士，征帆一一引龙駒。"]', '诗', 'shi', '', NULL, '永王東巡歌十一首 七 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('432c5149-2416-4bc3-b484-4896e19eefda', '永王東巡歌十一首 八', '永王东巡歌十一首 八', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["長風挂席勢難迴，海動山傾古月摧。","君看帝子浮江日，何似龍驤出峽來。"]', '["长风挂席勢难迴，海动山傾古月摧。","君看帝子浮江日，何似龙驤出峽来。"]', '诗', 'shi', '', NULL, '永王東巡歌十一首 八 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35111e31-f468-4698-9369-f4e34208388c', '永王東巡歌十一首 九', '永王东巡歌十一首 九', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["祖龍浮海不成橋，漢武尋陽空射蛟。","我王樓艦輕秦漢，却似文皇欲渡遼。"]', '["祖龙浮海不成橋，漢武尋陽空射蛟。","我王楼艦轻秦漢，却似文皇欲渡遼。"]', '诗', 'shi', '', NULL, '永王東巡歌十一首 九 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ba4db31-89c7-4f13-bcbf-c68d421096be', '永王東巡歌十一首 十', '永王东巡歌十一首 十', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["帝寵賢王入楚關，掃清江漢始應還。","初從雲夢開朱邸，更取金陵作小山。"]', '["帝寵賢王入楚关，掃清江漢始應還。","初從云梦开朱邸，更取金陵作小山。"]', '诗', 'shi', '', NULL, '永王東巡歌十一首 十 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94873c8c-d4b9-47cd-aa64-b088fae16c7e', '永王東巡歌十一首 十一', '永王东巡歌十一首 十一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["試借君王玉馬鞭，指揮戎虜坐瓊筵。","南風一掃胡塵靜，西入長安到日邊。"]', '["試借君王玉马鞭，指揮戎虜坐瓊筵。","南风一掃胡塵静，西入长安到日邊。"]', '诗', 'shi', '', NULL, '永王東巡歌十一首 十一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86008f97-e77d-4330-b507-64c35210be12', '上皇西巡南京歌十首 一', '上皇西巡南京歌十首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["胡塵輕拂建章臺，聖主西巡蜀道來。","劒壁門高五千尺，石爲樓閣九天開。"]', '["胡塵轻拂建章台，聖主西巡蜀道来。","劒壁门高五千尺，石爲楼閣九天开。"]', '诗', 'shi', '', NULL, '上皇西巡南京歌十首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bde3214-e68d-4780-a7ff-a62953c0ed13', '上皇西巡南京歌十首 二', '上皇西巡南京歌十首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["九天開出一成都，萬戶千門入畫圖。","草樹雲山如錦繡，秦川得及此間無。"]', '["九天开出一成都，万戶千门入畫圖。","草樹云山如錦繡，秦川得及此间無。"]', '诗', 'shi', '', NULL, '上皇西巡南京歌十首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1040f25c-51cc-4fb6-902f-d62d086a43b6', '上皇西巡南京歌十首 三', '上皇西巡南京歌十首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["華陽春樹號新豐，行入新都若舊宮。","柳色未饒秦地綠，花光不滅上陽紅。"]', '["华陽春樹號新豐，行入新都若旧宮。","柳色未饒秦地綠，花光不滅上陽紅。"]', '诗', 'shi', '', NULL, '上皇西巡南京歌十首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dd0f071-7518-40dc-aeca-5e07188e6bff', '上皇西巡南京歌十首 四', '上皇西巡南京歌十首 四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["誰道君王行路難，六龍西幸萬人歡。","地轉錦江成渭水，天迴玉壘作長安。"]', '["誰道君王行路难，六龙西幸万人歡。","地轉錦江成渭水，天迴玉壘作长安。"]', '诗', 'shi', '', NULL, '上皇西巡南京歌十首 四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69f2d8e0-00b0-4451-bf8b-531913ee370d', '上皇西巡南京歌十首 五', '上皇西巡南京歌十首 五', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["萬國同風共一時，錦江何謝曲江池。","石鏡更明天上月，後宮親得照蛾眉。"]', '["万国同风共一时，錦江何謝曲江池。","石镜更明天上月，後宮親得照蛾眉。"]', '诗', 'shi', '', NULL, '上皇西巡南京歌十首 五 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('045ef334-ce56-4dc5-bf77-231901ea062c', '上皇西巡南京歌十首 六', '上皇西巡南京歌十首 六', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["濯錦清江萬里流，雲帆龍舸下揚州。","北地雖誇上林苑，南京還有散花樓。"]', '["濯錦清江万里流，云帆龙舸下揚州。","北地雖誇上林苑，南京還有散花楼。"]', '诗', 'shi', '', NULL, '上皇西巡南京歌十首 六 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('722942a4-98d7-46a1-9fc9-ed44851445a5', '上皇西巡南京歌十首 七', '上皇西巡南京歌十首 七', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["錦水東流繞錦城，星橋北挂象天星。","四海此中朝聖主，峨眉山下列仙庭。"]', '["錦水东流繞錦城，星橋北挂象天星。","四海此中朝聖主，峨眉山下列仙庭。"]', '诗', 'shi', '', NULL, '上皇西巡南京歌十首 七 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4300913-b648-459b-9ee9-bc762945e2b7', '上皇西巡南京歌十首 八', '上皇西巡南京歌十首 八', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秦開蜀道置金牛，漢水元通星漢流。","天子一行遺聖跡，錦城長作帝王州。"]', '["秦开蜀道置金牛，漢水元通星漢流。","天子一行遺聖跡，錦城长作帝王州。"]', '诗', 'shi', '', NULL, '上皇西巡南京歌十首 八 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8802a2bb-09ca-4bcc-8bb5-016c3456f599', '上皇西巡南京歌十首 九', '上皇西巡南京歌十首 九', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["水綠天青不起塵，風光和暖勝三秦。","萬國烟花隨玉輦，西來添作錦江春。"]', '["水綠天青不起塵，风光和暖勝三秦。","万国烟花隨玉輦，西来添作錦江春。"]', '诗', 'shi', '', NULL, '上皇西巡南京歌十首 九 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e62ccfb6-dcdc-4980-b9bb-b5f87c0450f1', '上皇西巡南京歌十首 十', '上皇西巡南京歌十首 十', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["劒閣重關蜀北門，上皇歸馬若雲屯。","少帝長安開紫極，雙懸日月照乾坤。"]', '["劒閣重关蜀北门，上皇归马若云屯。","少帝长安开紫極，雙懸日月照乾坤。"]', '诗', 'shi', '', NULL, '上皇西巡南京歌十首 十 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('343cf232-56ef-4cfe-88dd-3781c0b57cb5', '峨眉山月歌', '峨眉山月歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["峨眉山月半輪秋，影入平羌江水流。","夜發清溪向三峽，思君不見下渝州。"]', '["峨眉山月半輪秋，影入平羌江水流。","夜發清溪向三峽，思君不见下渝州。"]', '诗', 'shi', '', NULL, '峨眉山月歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0108be7b-0780-4442-a496-16776f20be59', '峨眉山月歌送蜀僧晏入中京', '峨眉山月歌送蜀僧晏入中京', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我在巴東三峽時，西看明月憶峨眉。","月出峨眉照滄海，與人萬里長相隨。","黃鶴樓前月華白，此中忽見峨眉客。","峨眉山月還送君，風吹西到長安陌。","長安大道橫九天，峨眉山月照秦川。","黃金獅子乘高座，白玉麈尾談重玄。","我似浮雲殢吳越，君逢聖主遊丹闕。","一振高名滿帝都，歸時還弄峨眉月。"]', '["我在巴东三峽时，西看明月憶峨眉。","月出峨眉照滄海，與人万里长相隨。","黄鹤楼前月华白，此中忽见峨眉客。","峨眉山月還送君，风吹西到长安陌。","长安大道橫九天，峨眉山月照秦川。","黄金獅子乘高座，白玉麈尾談重玄。","我似浮云殢吳越，君逢聖主游丹闕。","一振高名满帝都，归时還弄峨眉月。"]', '诗', 'shi', '', NULL, '峨眉山月歌送蜀僧晏入中京 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b6687bc-57ab-4615-b185-938386eebd37', '赤壁歌送別', '赤壁歌送別', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["二龍爭戰決雌雄，赤壁樓船掃地空。","烈火張天照雲海，周瑜於此破曹公。","君去滄江望澄碧，鯨鯢唐突留餘跡。","一一書來報故人，我欲因之壯心魄。"]', '["二龙爭戰決雌雄，赤壁楼船掃地空。","烈火張天照云海，周瑜於此破曹公。","君去滄江望澄碧，鯨鯢唐突留餘跡。","一一书来報故人，我欲因之壯心魄。"]', '诗', 'shi', '', NULL, '赤壁歌送別 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f6b918f-4920-4c2d-b53c-dc9a2c1c3e2c', '江夏行', '江夏行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["憶昔嬌小姿，春心亦自持。","爲言嫁夫壻，得免長相思。","誰知嫁商賈，令人却愁苦。","自從爲夫妻，何曾在鄉土。","去年下揚州，相送黃鶴樓。","眼看帆去遠，心逐江水流。","只言期一載，誰謂歷三秋。","使妾腸欲斷，恨君情悠悠。","東家西舍同時發，北去南來不逾月。","未知行李遊何方，作箇音書能斷絕。","適來往南浦，欲問西江船。","正見當壚女，紅粧二八年。","一種爲人妻，獨自多悲悽。","對鏡便垂淚，逢人只欲啼。","不如輕薄兒，旦暮長相隨。","悔作商人婦，青春長別離。","如今正好同懽樂，君去容華誰得知。"]', '["憶昔嬌小姿，春心亦自持。","爲言嫁夫壻，得免长相思。","誰知嫁商賈，令人却愁苦。","自從爲夫妻，何曾在乡土。","去年下揚州，相送黄鹤楼。","眼看帆去远，心逐江水流。","只言期一載，誰謂歷三秋。","使妾腸欲斷，恨君情悠悠。","东家西舍同时發，北去南来不逾月。","未知行李游何方，作箇音书能斷絕。","適来往南浦，欲问西江船。","正见當壚女，紅粧二八年。","一種爲人妻，独自多悲悽。","对镜便垂泪，逢人只欲啼。","不如轻薄兒，旦暮长相隨。","悔作商人婦，青春长別離。","如今正好同懽乐，君去容华誰得知。"]', '诗', 'shi', '', NULL, '江夏行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76a8f569-4175-4352-bbfe-973112a384d1', '懷仙歌', '懷仙歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["一鶴東飛過滄海，放心散漫知何在。","仙人浩歌望我來，應攀玉樹長相待。","堯舜之事不足驚，自餘囂囂直可輕。","巨鼇莫戴三山去，我欲蓬萊頂上行。"]', '["一鹤东飞過滄海，放心散漫知何在。","仙人浩歌望我来，應攀玉樹长相待。","堯舜之事不足驚，自餘囂囂直可轻。","巨鼇莫戴三山去，我欲蓬萊頂上行。"]', '诗', 'shi', '', NULL, '懷仙歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20f54408-5677-4714-b6de-b6caa8a217e1', '玉真仙人詞', '玉真仙人词', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["玉真之仙人，時往太華峰。","清晨鳴天鼓，飆歘騰雙龍。","弄電不輟手，行雲本無蹤。","幾時入少室，王母應相逢。"]', '["玉真之仙人，时往太华峰。","清晨鳴天鼓，飆歘腾雙龙。","弄電不輟手，行云本無蹤。","幾时入少室，王母應相逢。"]', '诗', 'shi', '', NULL, '玉真仙人詞 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('157866b0-85c6-4602-a388-0db895a50c55', '清溪行', '清溪行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["清溪清我心，水色異諸水。","借問新安江，見底何如此。","人行明鏡中，鳥度屏風裏。","向晚猩猩啼，空悲遠遊子。"]', '["清溪清我心，水色異諸水。","借问新安江，见底何如此。","人行明镜中，鸟度屏风裏。","向晚猩猩啼，空悲远游子。"]', '诗', 'shi', '', NULL, '清溪行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94eb3754-819e-4e04-b880-76f1ae3e3849', '詶殷明佐見贈五雲裘歌', '詶殷明佐见贈五云裘歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我吟謝朓詩上語，朔風颯颯吹飛雨。","謝朓已沒青山空，後來繼之有殷公。","粉圖珍裘五雲色，曄如晴天散彩虹。","文章彪炳光陸離，應是素娥玉女之所爲。","輕如松花落金粉，濃似苔錦含碧滋。","遠山積翠橫海島，殘霞飛丹暎江草。","凝毫採掇花露容，幾年功成奪天造。","故人贈我我不違，著令山水含清暉。","頓驚謝康樂，詩興生我衣。","襟前林壑斂暝色，袖上雲霞收夕霏。","羣仙長歎驚此物，千厓萬嶺相縈鬱。","身騎白鹿行飄颻，手翳紫芝笑披拂。","相如不足跨鷫鸘，王恭鶴氅安可方。","瑤臺雪花數千點，片片吹落春風香。","爲君持此凌蒼蒼，上朝三十六玉皇。","下窺夫子不可及，矯首相思空斷腸。"]', '["我吟謝朓诗上語，朔风颯颯吹飞雨。","謝朓已沒青山空，後来繼之有殷公。","粉圖珍裘五云色，曄如晴天散彩虹。","文章彪炳光陸離，應是素娥玉女之所爲。","轻如松花落金粉，濃似苔錦含碧滋。","远山積翠橫海島，殘霞飞丹暎江草。","凝毫採掇花露容，幾年功成奪天造。","故人贈我我不違，著令山水含清暉。","頓驚謝康乐，诗兴生我衣。","襟前林壑斂暝色，袖上云霞收夕霏。","羣仙长歎驚此物，千厓万嶺相縈鬱。","身騎白鹿行飄颻，手翳紫芝笑披拂。","相如不足跨鷫鸘，王恭鹤氅安可方。","瑤台雪花數千点，片片吹落春风香。","爲君持此凌蒼蒼，上朝三十六玉皇。","下窺夫子不可及，矯首相思空斷腸。"]', '诗', 'shi', '', NULL, '詶殷明佐見贈五雲裘歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba666719-7bea-4a74-a186-cf8f7bcec5c7', '臨路歌', '臨路歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["大鵬飛兮振八裔，中天摧兮力不濟。","餘風激兮萬世，遊扶桑兮挂石袂。","後人得之傳此，仲尼亡兮誰爲出涕。"]', '["大鵬飞兮振八裔，中天摧兮力不濟。","餘风激兮万世，游扶桑兮挂石袂。","後人得之傳此，仲尼亡兮誰爲出涕。"]', '诗', 'shi', '', NULL, '臨路歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d5ab58d-0ac1-474d-97fa-84c35096e952', '古意', '古意', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["君爲女蘿草，妾作兔絲花。","輕條不自引，爲逐春風斜。","百丈託遠松，纏綿成一家。","誰言會面易，各在青山厓。","女蘿發馨香，兔絲斷人腸。","枝枝相糾結，葉葉競飄揚。","生子不知根，因誰共芬芳。","中巢雙翡翠，上宿紫鴛鴦。","若識二草心，海潮亦可量。"]', '["君爲女蘿草，妾作兔絲花。","轻條不自引，爲逐春风斜。","百丈託远松，纏綿成一家。","誰言會面易，各在青山厓。","女蘿發馨香，兔絲斷人腸。","枝枝相糾結，葉葉競飄揚。","生子不知根，因誰共芬芳。","中巢雙翡翠，上宿紫鴛鴦。","若識二草心，海潮亦可量。"]', '诗', 'shi', '', NULL, '古意 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d912de08-eb32-49f7-823c-ee17e6e71d12', '山鷓鴣詞', '山鷓鴣词', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["苦竹嶺頭秋月輝，苦竹南枝鷓鴣飛。","嫁得燕山胡雁壻，欲銜我向雁門歸。","山雞翟雉來相勸，南禽多被北禽欺。","紫塞嚴霜如劒戟，蒼梧欲巢難背違。","我今誓死不能去，哀鳴驚呌淚沾衣。"]', '["苦竹嶺头秋月輝，苦竹南枝鷓鴣飞。","嫁得燕山胡雁壻，欲銜我向雁门归。","山雞翟雉来相勸，南禽多被北禽欺。","紫塞嚴霜如劒戟，蒼梧欲巢难背違。","我今誓死不能去，哀鳴驚呌泪沾衣。"]', '诗', 'shi', '', NULL, '山鷓鴣詞 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9b93d29-cfb2-4de3-8c3f-90a7ba821fb6', '歷陽壯士勤將軍名思齊歌', '歷陽壯士勤將軍名思齊歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["太古歷陽郡，化爲洪川在。","江山猶鬱盤，龍虎祕光彩。","蓄洩數千載，風雲何霮䨴。","特生勤將軍，神力百夫倍。"]', '["太古歷陽郡，化爲洪川在。","江山猶鬱盤，龙虎祕光彩。","蓄洩數千載，风云何霮䨴。","特生勤將軍，神力百夫倍。"]', '诗', 'shi', '', NULL, '歷陽壯士勤將軍名思齊歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2996e939-ef11-4845-971b-c4915ae754fb', '草書歌行', '草书歌行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["少年上人號懷素，草書天下稱獨步。","墨池飛出北溟魚，筆鋒殺盡中山兔。","八月九月天氣涼，酒徒詞客滿高堂。","牋麻素絹排數廂，宣州石硯墨色光。","吾師醉後倚繩牀，須臾掃盡數千張。","飄風驟雨驚颯颯，落花飛雪何茫茫。","起來向壁不停手，一行數字大如斗。","怳怳如聞神鬼驚，時時只見龍蛇走。","左盤右蹙如驚電，狀同楚漢相攻戰。","湖南七郡凡幾家，家家屏障書題徧。","王逸少，張伯英，古來幾許浪得名。","張顛老死不足數，我師此義不師古。","古來萬事貴天生，何必要公孫大娘渾脫舞。"]', '["少年上人號懷素，草书天下稱独步。","墨池飞出北溟鱼，笔鋒殺尽中山兔。","八月九月天氣涼，酒徒词客满高堂。","牋麻素絹排數廂，宣州石硯墨色光。","吾師醉後倚繩牀，須臾掃尽數千張。","飄风驟雨驚颯颯，落花飞雪何茫茫。","起来向壁不停手，一行數字大如斗。","怳怳如闻神鬼驚，时时只见龙蛇走。","左盤右蹙如驚電，狀同楚漢相攻戰。","湖南七郡凡幾家，家家屏障书題徧。","王逸少，張伯英，古来幾許浪得名。","張顛老死不足數，我師此義不師古。","古来万事貴天生，何必要公孫大娘渾脫舞。"]', '诗', 'shi', '', NULL, '草書歌行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b7a5d82-7f6a-4f90-a042-2e97c5867206', '和盧侍御通塘曲', '和盧侍御通塘曲', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["君誇通塘好，通塘勝耶溪。","通塘在何處，遠在尋陽西。","青蘿嫋嫋挂烟樹，白鷴處處聚沙堤。","石門中斷平湖出，百丈金潭照雲日。","何處滄浪垂釣翁，鼓櫂漁歌趣非一。","相逢不相識，出沒繞通塘。","浦邊清水明素足，別有浣沙吳女郎。","行盡綠潭潭轉幽，疑是武陵春碧流。","秦人雞犬桃花裏，將比通塘渠見羞。","通塘不忍別，十去九遲回。","偶逢佳境心已醉，忽有一鳥從天來。","月出青山送行子，四邊苦竹秋聲起。","長吟白雪望星河，雙垂兩足揚素波。","梁鴻德耀會稽日，寧知此中樂事多。"]', '["君誇通塘好，通塘勝耶溪。","通塘在何处，远在尋陽西。","青蘿嫋嫋挂烟樹，白鷴处处聚沙堤。","石门中斷平湖出，百丈金潭照云日。","何处滄浪垂釣翁，鼓櫂漁歌趣非一。","相逢不相識，出沒繞通塘。","浦邊清水明素足，別有浣沙吳女郎。","行尽綠潭潭轉幽，疑是武陵春碧流。","秦人雞犬桃花裏，將比通塘渠见羞。","通塘不忍別，十去九遲回。","偶逢佳境心已醉，忽有一鸟從天来。","月出青山送行子，四邊苦竹秋声起。","长吟白雪望星河，雙垂兩足揚素波。","梁鴻德耀會稽日，寧知此中乐事多。"]', '诗', 'shi', '', NULL, '和盧侍御通塘曲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d1b6a18-571c-4f25-bfdb-3fe260115c3f', '贈孟浩然', '贈孟浩然', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["吾愛孟夫子，風流天下聞。","紅顏棄軒冕，白首臥松雲。","醉月頻中聖，迷花不事君。","高山安可仰，徒此揖清芬。"]', '["吾愛孟夫子，风流天下闻。","紅顏棄軒冕，白首臥松云。","醉月頻中聖，迷花不事君。","高山安可仰，徒此揖清芬。"]', '诗', 'shi', '', NULL, '贈孟浩然 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef2c9c01-038b-441d-b947-95c0046c0061', '贈從兄襄陽少府皓', '贈從兄襄陽少府皓', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["結髮未識事，所交盡豪雄。","却秦不受賞，擊晉寧爲功。","小節豈足言，退耕舂陵東。","歸來無產業，生事如轉蓬。","一朝烏裘敝，百鎰黃金空。","彈劒徒激昂，出門悲路窮。","吾兄青雲士，然諾聞諸公。","所以陳片言，片言貴情通。","棣華儻不接，甘與秋草同。"]', '["結髮未識事，所交尽豪雄。","却秦不受賞，擊晉寧爲功。","小節豈足言，退耕舂陵东。","归来無產業，生事如轉蓬。","一朝烏裘敝，百鎰黄金空。","彈劒徒激昂，出门悲路窮。","吾兄青云士，然諾闻諸公。","所以陳片言，片言貴情通。","棣华儻不接，甘與秋草同。"]', '诗', 'shi', '', NULL, '贈從兄襄陽少府皓 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66fbdf3a-5429-40a4-8ba8-396fb7ad8506', '淮海對雪贈傅靄', '淮海对雪贈傅靄', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["朔雪落吳天，從風渡溟渤。","海樹成陽春，江沙浩明月。","興從剡溪起，思繞梁園發。","寄君郢中歌，曲罷心斷絕。"]', '["朔雪落吳天，從风渡溟渤。","海樹成陽春，江沙浩明月。","兴從剡溪起，思繞梁园發。","寄君郢中歌，曲罷心斷絕。"]', '诗', 'shi', '', NULL, '淮海對雪贈傅靄 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8b115f0-1f90-4f95-8b31-96dd1223e674', '贈徐安宜', '贈徐安宜', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白田見楚老，歌詠徐安宜。","製錦不擇地，操刀良在茲。","清風動百里，惠化聞京師。","浮人若雲歸，耕種滿郊岐。","川光淨麥隴，日色明桑枝。","訟息但長嘯，賓來或解頤。","青橙拂戶牖，白水流園池。","遊子滯安邑，懷恩未忍辭。","翳君樹桃李，歲晚託深期。"]', '["白田见楚老，歌詠徐安宜。","製錦不擇地，操刀良在茲。","清风动百里，惠化闻京師。","浮人若云归，耕種满郊岐。","川光淨麦隴，日色明桑枝。","訟息但长嘯，賓来或解頤。","青橙拂戶牖，白水流园池。","游子滯安邑，懷恩未忍辞。","翳君樹桃李，歲晚託深期。"]', '诗', 'shi', '', NULL, '贈徐安宜 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9678f941-ae8f-489b-ac31-7864158b26e3', '贈任城盧主簿', '贈任城盧主簿', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["海鳥知天風，竄身魯門東。","臨觴不能飲，矯翼思凌空。","鐘鼓不爲樂，烟霜誰與同。","歸飛未忍去，流淚謝鴛鴻。"]', '["海鸟知天风，竄身魯门东。","臨觴不能饮，矯翼思凌空。","鐘鼓不爲乐，烟霜誰與同。","归飞未忍去，流泪謝鴛鴻。"]', '诗', 'shi', '', NULL, '贈任城盧主簿 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f970d4db-74a1-45c3-b409-58359aecb709', '早秋贈裴十七仲堪', '早秋贈裴十七仲堪', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["遠海動風色，吹愁落天涯。","南星變大火，熱氣餘丹霞。","光景不可迴，六龍轉天車。","荆人泣美玉，魯叟悲匏瓜。","功業若夢裏，撫琴發長嗟。","裴生信英邁，屈起多才華。","歷抵海岱豪，結交魯朱家。","復攜兩少女，豔色驚荷葩。","雙歌入青雲，但惜白日斜。","窮溟出寶貝，大澤饒龍蛇。","明主儻見收，烟霞路非賒。","時命若不會，歸應鍊丹砂。"]', '["远海动风色，吹愁落天涯。","南星变大火，熱氣餘丹霞。","光景不可迴，六龙轉天车。","荆人泣美玉，魯叟悲匏瓜。","功業若梦裏，撫琴發长嗟。","裴生信英邁，屈起多才华。","歷抵海岱豪，結交魯朱家。","复携兩少女，豔色驚荷葩。","雙歌入青云，但惜白日斜。","窮溟出寶貝，大澤饒龙蛇。","明主儻见收，烟霞路非賒。","时命若不會，归應鍊丹砂。"]', '诗', 'shi', '', NULL, '早秋贈裴十七仲堪 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0be52b7d-9f9a-46fc-b1ca-f41e98eee07d', '贈范金卿二首 一', '贈范金卿二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["君子枉清盼，不知東走迷。","離家來幾月，絡緯鳴中閨。","桃李君不言，攀花願成蹊。","那能吐芳信，惠好相招攜。","我有結綠珍，久藏濁水泥。","時人棄此物，乃與燕珉齊。","摭拭欲贈之，申眉路無梯。","遼東慙白豕，楚客羞山雞。","徒有獻芹心，終流泣玉啼。","祗應自索漠，留舌示山妻。"]', '["君子枉清盼，不知东走迷。","離家来幾月，絡緯鳴中閨。","桃李君不言，攀花願成蹊。","那能吐芳信，惠好相招携。","我有結綠珍，久藏濁水泥。","时人棄此物，乃與燕珉齊。","摭拭欲贈之，申眉路無梯。","遼东慙白豕，楚客羞山雞。","徒有獻芹心，終流泣玉啼。","祗應自索漠，留舌示山妻。"]', '诗', 'shi', '', NULL, '贈范金卿二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9b03c5e-292d-45d3-83ff-c9a1330f9016', '贈范金卿二首 二', '贈范金卿二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["范宰不買名，弦歌對前楹。","爲邦默自化，日覺冰壺清。","百里雞犬靜，千廬機杼鳴。","浮人少蕩析，愛客多逢迎。","遊子覩嘉政，因之聽頌聲。"]', '["范宰不買名，弦歌对前楹。","爲邦默自化，日覺冰壺清。","百里雞犬静，千廬機杼鳴。","浮人少蕩析，愛客多逢迎。","游子覩嘉政，因之听頌声。"]', '诗', 'shi', '', NULL, '贈范金卿二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0789a72-1155-4a6f-b42d-1f7111023821', '贈瑕丘王少府', '贈瑕丘王少府', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["皎皎鸞鳳姿，飄飄神仙氣。","梅生亦何事，來作南昌尉。","清風佐鳴琴，寂寞道爲貴。","一見過所聞，操持難與羣。","毫揮魯邑訟，目送瀛洲雲。","我隱屠釣下，爾當玉石分。","無由接高論，空此仰清芬。"]', '["皎皎鸾鳳姿，飄飄神仙氣。","梅生亦何事，来作南昌尉。","清风佐鳴琴，寂寞道爲貴。","一见過所闻，操持难與羣。","毫揮魯邑訟，目送瀛洲云。","我隐屠釣下，爾當玉石分。","無由接高論，空此仰清芬。"]', '诗', 'shi', '', NULL, '贈瑕丘王少府 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('802b7363-b528-4107-952d-1c1b7a1c0420', '東魯見狄博通', '东魯见狄博通', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["去年別我向何處，有人傳道遊江東。","謂言挂席度滄海，却來應是無長風。"]', '["去年別我向何处，有人傳道游江东。","謂言挂席度滄海，却来應是無长风。"]', '诗', 'shi', '', NULL, '東魯見狄博通 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c7dd791-00bd-4bbc-baee-4c09520c1111', '見京兆韋參軍量移東陽二首 一', '见京兆韋參軍量移东陽二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["潮水還歸海，流人却到吳。","相逢問愁苦，淚盡日南珠。"]', '["潮水還归海，流人却到吳。","相逢问愁苦，泪尽日南珠。"]', '诗', 'shi', '', NULL, '見京兆韋參軍量移東陽二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13be75df-3568-4f7d-bfc3-f65a4ebcafe5', '見京兆韋參軍量移東陽二首 二', '见京兆韋參軍量移东陽二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["聞說金華渡，東連五百灘。","全勝若耶好，莫道此行難。","猨嘯千谿合，松風五月寒。","他年一攜手，搖艇入新安。"]', '["闻说金华渡，东連五百灘。","全勝若耶好，莫道此行难。","猨嘯千谿合，松风五月寒。","他年一携手，搖艇入新安。"]', '诗', 'shi', '', NULL, '見京兆韋參軍量移東陽二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e763265-a5c2-4fda-9a2d-f8826098442e', '贈丹陽橫山周處士惟長', '贈丹陽橫山周处士惟长', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["周子橫山隱，開門臨城隅。","連峯入戶牖，勝概凌方壺。","時作白紵詞，放歌丹陽湖。","水色傲溟渤，川光秀菰蒲。","當其得意時，心與天壤俱。","閑雲隨舒卷，安識身有無。","抱石耻獻玉，沈泉笑探珠。","羽化如可作，相攜上清都。"]', '["周子橫山隐，开门臨城隅。","連峯入戶牖，勝概凌方壺。","时作白紵词，放歌丹陽湖。","水色傲溟渤，川光秀菰蒲。","當其得意时，心與天壤俱。","闲云隨舒卷，安識身有無。","抱石耻獻玉，沈泉笑探珠。","羽化如可作，相携上清都。"]', '诗', 'shi', '', NULL, '贈丹陽橫山周處士惟長 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e1d96f5-bf22-49e2-9124-4de3af7cab5a', '玉真公主別館苦雨贈衛尉張卿二首 一', '玉真公主別館苦雨贈衛尉張卿二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秋坐金張館，繁陰晝不開。","空烟迷雨色，蕭颯望中來。","翳翳昏墊苦，沈沈憂恨催。","清秋何以慰，白酒盈吾杯。","吟詠思管樂，此人已成灰。","獨酌聊自勉，誰貴經綸才。","彈劒謝公子，無魚良可哀。"]', '["秋坐金張館，繁陰晝不开。","空烟迷雨色，蕭颯望中来。","翳翳昏墊苦，沈沈憂恨催。","清秋何以慰，白酒盈吾杯。","吟詠思管乐，此人已成灰。","独酌聊自勉，誰貴經綸才。","彈劒謝公子，無鱼良可哀。"]', '诗', 'shi', '', NULL, '玉真公主別館苦雨贈衛尉張卿二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8df1ac8-97df-41c3-bac1-ff323e94a4cf', '玉真公主別館苦雨贈衛尉張卿二首 二', '玉真公主別館苦雨贈衛尉張卿二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["苦雨思白日，浮雲何由卷。","稷卨和天人，陰陽乃驕蹇。","秋霖劇倒井，昏霧橫絕巘。","欲往咫尺塗，遂成山川限。","潨潨奔溜聞，浩浩驚波轉。","泥沙塞中途，牛馬不可辨。","飢從漂母食，閑綴羽陵簡。","園家逢秋蔬，藜藿不滿眼。","蟏蛸結思幽，蟋蟀傷褊淺。","廚竈無青煙，刀机生綠蘚。","投筯解鷫鸘，換酒醉北堂。","丹徒布衣者，慷慨未可量。","何時黃金盤，一斛薦檳榔。","功成拂衣去，搖曳滄洲傍。"]', '["苦雨思白日，浮云何由卷。","稷卨和天人，陰陽乃驕蹇。","秋霖劇倒井，昏霧橫絕巘。","欲往咫尺塗，遂成山川限。","潨潨奔溜闻，浩浩驚波轉。","泥沙塞中途，牛马不可辨。","飢從漂母食，闲綴羽陵簡。","园家逢秋蔬，藜藿不满眼。","蟏蛸結思幽，蟋蟀傷褊淺。","廚竈無青煙，刀机生綠蘚。","投筯解鷫鸘，換酒醉北堂。","丹徒布衣者，慷慨未可量。","何时黄金盤，一斛薦檳榔。","功成拂衣去，搖曳滄洲傍。"]', '诗', 'shi', '', NULL, '玉真公主別館苦雨贈衛尉張卿二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce0fcb64-2151-41bb-94cb-09c45861a5a9', '贈韋祕書子春二首 一', '贈韋祕书子春二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["谷口鄭子真，躬耕在巖石。","高名動京師，天下皆籍籍。","斯人竟不起，雲臥從所適。","苟無濟代心，獨善亦何益。","惟君家世者，偃息逢休明。","談天信浩蕩，說劒紛縱橫。","謝公不徒然，起來爲蒼生。","祕書何寂寂，無乃羈豪英。","且復歸碧山，安能戀金闕。","舊宅樵漁地，蓬蒿已應沒。","却顧女几峯，胡顏見雲月。"]', '["谷口鄭子真，躬耕在巖石。","高名动京師，天下皆籍籍。","斯人竟不起，云臥從所適。","苟無濟代心，独善亦何益。","惟君家世者，偃息逢休明。","談天信浩蕩，说劒紛縱橫。","謝公不徒然，起来爲蒼生。","祕书何寂寂，無乃羈豪英。","且复归碧山，安能戀金闕。","旧宅樵漁地，蓬蒿已應沒。","却顧女几峯，胡顏见云月。"]', '诗', 'shi', '', NULL, '贈韋祕書子春二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdcd9921-6616-4f9f-8904-b47b7b0a1e6d', '贈韋祕書子春二首 二', '贈韋祕书子春二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["徒爲風塵苦，一官已白鬚。","氣同萬里合，訪我來瓊都。","披雲覩青天，捫蝨話良圖。","留侯將綺里，出處未云殊。","終與安社稷，功成去五湖。"]', '["徒爲风塵苦，一官已白鬚。","氣同万里合，訪我来瓊都。","披云覩青天，捫蝨話良圖。","留侯將綺里，出处未云殊。","終與安社稷，功成去五湖。"]', '诗', 'shi', '', NULL, '贈韋祕書子春二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfa440f7-c8ee-49a4-a2f3-58741a500d81', '贈韋侍御黃裳二首 一', '贈韋侍御黄裳二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["太華生長松，亭亭凌霜雪。","天與百尺高，豈爲微飆折。","桃李賣陽豔，路人行且迷。","春光掃地盡，碧葉成黃泥。","願君學長松，慎勿作桃李。","受屈不改心，然後知君子。"]', '["太华生长松，亭亭凌霜雪。","天與百尺高，豈爲微飆折。","桃李賣陽豔，路人行且迷。","春光掃地尽，碧葉成黄泥。","願君学长松，慎勿作桃李。","受屈不改心，然後知君子。"]', '诗', 'shi', '', NULL, '贈韋侍御黃裳二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('006df741-146a-46a4-a1c4-70361fdf1bb0', '贈韋侍御黃裳二首 二', '贈韋侍御黄裳二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["見君乘驄馬，知上太山道。","此地果摧輪，全身以爲寶。","我如豐年玉，棄置秋田草。","但勖冰壺心，無爲嘆衰老。"]', '["见君乘驄马，知上太山道。","此地果摧輪，全身以爲寶。","我如豐年玉，棄置秋田草。","但勖冰壺心，無爲嘆衰老。"]', '诗', 'shi', '', NULL, '贈韋侍御黃裳二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6a59299-39f1-4f85-bebb-a1e4008bf181', '贈薛校書', '贈薛校书', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我有吳越曲，無人知此音。","姑蘇成蔓草，麋鹿空悲吟。","未誇觀濤作，空鬱釣鼇心。","舉手謝東海，虛行歸故林。"]', '["我有吳越曲，無人知此音。","姑蘇成蔓草，麋鹿空悲吟。","未誇观濤作，空鬱釣鼇心。","舉手謝东海，虛行归故林。"]', '诗', 'shi', '', NULL, '贈薛校書 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee9e27ac-445b-4018-8153-0cb44a29e2ad', '贈何七判官昌浩', '贈何七判官昌浩', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["有時忽惆悵，匡坐至夜分。","平明空嘯咤，思欲解世紛。","心隨長風去，吹散萬里雲。","羞作濟南生，九十誦古文。","不然拂劒起，沙漠收奇勳。","老死阡陌間，何因揚清芬。","夫子今管樂，英才冠三軍。","終與同出處，豈將沮溺羣。"]', '["有时忽惆悵，匡坐至夜分。","平明空嘯咤，思欲解世紛。","心隨长风去，吹散万里云。","羞作濟南生，九十誦古文。","不然拂劒起，沙漠收奇勳。","老死阡陌间，何因揚清芬。","夫子今管乐，英才冠三軍。","終與同出处，豈將沮溺羣。"]', '诗', 'shi', '', NULL, '贈何七判官昌浩 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92886e52-6348-4f27-a8fa-e7cd136e0ac4', '讀諸葛武侯傳書懷贈長安崔少府叔封昆季', '读諸葛武侯傳书懷贈长安崔少府叔封昆季', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["漢道昔云季，羣雄方戰爭。","霸圖各未立，割據資豪英。","赤伏起頹運，臥龍得孔明。","當其南陽時，隴畝躬自耕。","魚水三顧合，風雲四海生。","武侯立岷蜀，壯志吞咸京。","何人先見許，但有崔州平。","余亦草間人，頗懷拯物情。","晚途值子玉，華髮同衰榮。","託意在經濟，結交爲弟兄。","毋令管與鮑，千載獨知名。"]', '["漢道昔云季，羣雄方戰爭。","霸圖各未立，割據資豪英。","赤伏起頹運，臥龙得孔明。","當其南陽时，隴畝躬自耕。","鱼水三顧合，风云四海生。","武侯立岷蜀，壯志吞咸京。","何人先见許，但有崔州平。","余亦草间人，頗懷拯物情。","晚途值子玉，华髮同衰榮。","託意在經濟，結交爲弟兄。","毋令管與鲍，千載独知名。"]', '诗', 'shi', '', NULL, '讀諸葛武侯傳書懷贈長安崔少府叔封昆季 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64cdd579-10d2-44ae-a331-73970e878f63', '贈郭將軍', '贈郭將軍', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["將軍少年出武威，入掌銀臺護紫微。","平明拂劒朝天去，薄暮垂鞭醉酒歸。","愛子臨風吹玉笛，美人向月舞羅衣。","疇昔雄豪如夢裏，相逢且欲醉春暉。"]', '["將軍少年出武威，入掌銀台護紫微。","平明拂劒朝天去，薄暮垂鞭醉酒归。","愛子臨风吹玉笛，美人向月舞羅衣。","疇昔雄豪如梦裏，相逢且欲醉春暉。"]', '诗', 'shi', '', NULL, '贈郭將軍 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae129bba-5c25-4b46-a6a5-2e467e7b2920', '駕去溫泉後贈楊山人', '駕去溫泉後贈楊山人', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["少年落魄楚漢間，風塵蕭瑟多苦顏。","自言管葛竟誰許，長吁莫錯還閉關。","一朝君王垂拂拭，剖心輸丹雪胸臆。","忽蒙白日回景光，直上青雲生羽翼。","幸陪鸞輦出鴻都，身騎飛龍天馬駒。","王公大人借顏色，金璋紫綬來相趨。","當時結交何紛紛，片言道合惟有君。","待吾盡節報明主，然後相攜臥白雲。"]', '["少年落魄楚漢间，风塵蕭瑟多苦顏。","自言管葛竟誰許，长吁莫錯還閉关。","一朝君王垂拂拭，剖心輸丹雪胸臆。","忽蒙白日回景光，直上青云生羽翼。","幸陪鸾輦出鴻都，身騎飞龙天马駒。","王公大人借顏色，金璋紫綬来相趨。","當时結交何紛紛，片言道合惟有君。","待吾尽節報明主，然後相携臥白云。"]', '诗', 'shi', '', NULL, '駕去溫泉後贈楊山人 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d8e64cc-1adb-4d1f-85e7-875e1b063c00', '溫泉侍從歸逢故人', '溫泉侍從归逢故人', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["漢帝長楊苑，誇胡羽獵歸。","子雲叨侍從，獻賦有光輝。","激賞搖天筆，承恩賜御衣。","逢君奏明主，他日共飜飛。"]', '["漢帝长楊苑，誇胡羽獵归。","子云叨侍從，獻賦有光輝。","激賞搖天笔，承恩賜御衣。","逢君奏明主，他日共飜飞。"]', '诗', 'shi', '', NULL, '溫泉侍從歸逢故人 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c60324e6-18da-4762-97d1-ecfed20ba078', '贈裴十四', '贈裴十四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["朝見裴叔則，朗如行玉山。","黃河落天走東海，萬里寫入胸懷間。","身騎白黿不敢度，金高南山買君顧。","裴回六合無相知，飄若浮雲且西去。"]', '["朝见裴叔則，朗如行玉山。","黄河落天走东海，万里寫入胸懷间。","身騎白黿不敢度，金高南山買君顧。","裴回六合無相知，飄若浮云且西去。"]', '诗', 'shi', '', NULL, '贈裴十四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e79cb34a-007d-402f-b98a-0ac390b86282', '贈崔侍郎', '贈崔侍郎', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["黃河二尺鯉，本在孟津居。","點額不成龍，歸來伴凡魚。","故人東海客，一見借吹噓。","風濤儻相見，更欲凌崑墟。"]', '["黄河二尺鯉，本在孟津居。","点額不成龙，归来伴凡鱼。","故人东海客，一见借吹噓。","风濤儻相见，更欲凌崑墟。"]', '诗', 'shi', '', NULL, '贈崔侍郎 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d7b203e-e8f9-4d8d-829d-da221f460101', '述德兼陳情上哥舒大夫', '述德兼陳情上哥舒大夫', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["天爲國家孕英才，森森矛戟擁靈臺。","浩蕩深謀噴江海，縱橫逸氣走風雷。","丈夫立身有如此，一呼三軍皆披靡。","衛青謾作大將軍，白起真成一豎子。"]', '["天爲国家孕英才，森森矛戟擁靈台。","浩蕩深謀噴江海，縱橫逸氣走风雷。","丈夫立身有如此，一呼三軍皆披靡。","衛青謾作大將軍，白起真成一豎子。"]', '诗', 'shi', '', NULL, '述德兼陳情上哥舒大夫 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f889b4d7-00c5-49cd-ab29-655f9e9cac0c', '雪讒詩贈友人', '雪讒诗贈友人', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["嗟予沈迷，猖獗已久。","五十知非，古人嘗有。","立言補過，庶存不朽。","包荒匿瑕，蓄此頑醜。","月出致譏，貽愧皓首。","感悟遂晚，事往日遷。","白璧何辜，青蠅屢前。","羣輕折軸，下沈黃泉。","衆毛飛骨，上凌青天。","萋斐暗成，貝錦粲然。","泥沙聚埃，珠玉不鮮。","洪燄爍山，發自纖煙。","蒼波蕩日，起于微涓。","交亂四國，播于八埏。","拾塵掇蜂，疑聖猜賢。","哀哉悲夫！誰察予之貞堅。","彼婦人之猖狂，不如鵲之彊彊。","彼婦人之淫昏，不如鶉之奔奔。","坦蕩君子，無悅簧言。","擢髮續罪，罪乃孔多。","傾海流惡，惡無以過。","人生實難，逢此織羅。","積毀銷金，沈憂作歌。","天未喪文，其如余何。","妲己滅紂，褒女惑周。","天維蕩覆，職此之由。","漢祖呂氏，食其在傍。","秦皇太后，毐亦淫荒。","螮蝀作昏，遂掩太陽。","萬乘尚爾，匹夫何傷。","辭殫意窮，心切理直。","如或妄談，昊天是殛。","子野善聽，離婁至明。","神靡遁響，鬼無逃形。","不我遐棄，庶昭忠誠。"]', '["嗟予沈迷，猖獗已久。","五十知非，古人嘗有。","立言補過，庶存不朽。","包荒匿瑕，蓄此頑醜。","月出致譏，貽愧皓首。","感悟遂晚，事往日遷。","白璧何辜，青蠅屢前。","羣轻折軸，下沈黄泉。","衆毛飞骨，上凌青天。","萋斐暗成，貝錦粲然。","泥沙聚埃，珠玉不鲜。","洪燄爍山，發自纖煙。","蒼波蕩日，起于微涓。","交亂四国，播于八埏。","拾塵掇蜂，疑聖猜賢。","哀哉悲夫！誰察予之貞堅。","彼婦人之猖狂，不如鵲之彊彊。","彼婦人之淫昏，不如鶉之奔奔。","坦蕩君子，無悅簧言。","擢髮續罪，罪乃孔多。","傾海流惡，惡無以過。","人生實难，逢此织羅。","積毀銷金，沈憂作歌。","天未喪文，其如余何。","妲己滅紂，褒女惑周。","天維蕩覆，職此之由。","漢祖呂氏，食其在傍。","秦皇太后，毐亦淫荒。","螮蝀作昏，遂掩太陽。","万乘尚爾，匹夫何傷。","辞殫意窮，心切理直。","如或妄談，昊天是殛。","子野善听，離婁至明。","神靡遁响，鬼無逃形。","不我遐棄，庶昭忠誠。"]', '诗', 'shi', '', NULL, '雪讒詩贈友人 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61de265c-c660-4e5c-938d-eaa4ee246ba1', '贈參寥子', '贈參寥子', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白鶴飛天書，南荆訪高士。","五雲在峴山，果得參寥子。","骯髒辭故園，昂藏入君門。","天子分玉帛，百官接話言。","毫墨時灑落，探玄有奇作。","著論窮天人，千春祕麟閣。","長揖不受官，拂衣歸林巒。","余亦去金馬，藤蘿同所歡。","相思在何處，桂樹青雲端。"]', '["白鹤飞天书，南荆訪高士。","五云在峴山，果得參寥子。","骯髒辞故园，昂藏入君门。","天子分玉帛，百官接話言。","毫墨时灑落，探玄有奇作。","著論窮天人，千春祕麟閣。","长揖不受官，拂衣归林巒。","余亦去金马，藤蘿同所歡。","相思在何处，桂樹青云端。"]', '诗', 'shi', '', NULL, '贈參寥子 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ebf752f-dc8e-4e89-96bc-7d5891f54d6d', '贈饒陽張司戶燧', '贈饒陽張司戶燧', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["朝飲蒼梧泉，夕棲碧海煙。","寧知鸞鳳意，遠託椅桐前。","慕藺豈曩古，攀嵇是當年。","愧非黃石老，安識子房賢。","功業嗟落日，容華棄徂川。","一語已道意，三山期著鞭。","蹉跎人間世，寥落壺中天。","獨見遊物祖，探元窮化先。","何當共攜手，相與排冥筌。"]', '["朝饮蒼梧泉，夕棲碧海煙。","寧知鸾鳳意，远託椅桐前。","慕藺豈曩古，攀嵇是當年。","愧非黄石老，安識子房賢。","功業嗟落日，容华棄徂川。","一語已道意，三山期著鞭。","蹉跎人间世，寥落壺中天。","独见游物祖，探元窮化先。","何當共携手，相與排冥筌。"]', '诗', 'shi', '', NULL, '贈饒陽張司戶燧 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f842c81f-4987-4cac-a897-52ac75a8e773', '贈清漳明府姪聿', '贈清漳明府姪聿', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我李百萬葉，柯條布中州。","天開青雲器，日爲蒼生憂。","小邑且割雞，大刀佇烹牛。","雷聲動四境，惠與清漳流。","弦歌詠唐堯，脫落隱簪組。","心和得天真，風俗猶太古。","牛羊散阡陌，夜寢不扃戶。","問此何以然，賢人宰吾土。","舉邑樹桃李，垂陰亦流芬。","河堤繞綠水，桑柘連青雲。","趙女不冶容，提籠晝成羣。","繰絲鳴機杼，百里聲相聞。","訟息鳥下堦，高臥披道帙。","蒲鞭挂簷枝，示耻無撲抶。","琴清月當戶，人寂風入室。","長嘯無一言，陶然上皇逸。","白玉壺冰水，壺中見底清。","清光洞毫髮，皎潔照羣情。","趙北美佳政，燕南播高名。","過客覽行謠，因之誦德聲。"]', '["我李百万葉，柯條布中州。","天开青云器，日爲蒼生憂。","小邑且割雞，大刀佇烹牛。","雷声动四境，惠與清漳流。","弦歌詠唐堯，脫落隐簪組。","心和得天真，风俗猶太古。","牛羊散阡陌，夜寢不扃戶。","问此何以然，賢人宰吾土。","舉邑樹桃李，垂陰亦流芬。","河堤繞綠水，桑柘連青云。","趙女不冶容，提籠晝成羣。","繰絲鳴機杼，百里声相闻。","訟息鸟下堦，高臥披道帙。","蒲鞭挂簷枝，示耻無撲抶。","琴清月當戶，人寂风入室。","长嘯無一言，陶然上皇逸。","白玉壺冰水，壺中见底清。","清光洞毫髮，皎潔照羣情。","趙北美佳政，燕南播高名。","過客覽行謠，因之誦德声。"]', '诗', 'shi', '', NULL, '贈清漳明府姪聿 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d76d2936-a725-4564-8019-2f9672c127bf', '贈臨洺縣令皓弟', '贈臨洺縣令皓弟', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["陶令去彭澤，茫然太古心。","大音自成曲，但奏無弦琴。","釣水路非遠，連鼇意何深。","終期龍伯國，與爾相招尋。"]', '["陶令去彭澤，茫然太古心。","大音自成曲，但奏無弦琴。","釣水路非远，連鼇意何深。","終期龙伯国，與爾相招尋。"]', '诗', 'shi', '', NULL, '贈臨洺縣令皓弟 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de5c5ebb-0ae3-4e86-a8c6-489f44ca71ec', '贈郭季鷹', '贈郭季鷹', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["河東郭有道，於世若浮雲。","盛德無我位，清光獨暎君。","耻將雞並食，長與鳳爲羣。","一擊九千仞，相期凌紫氛。"]', '["河东郭有道，於世若浮云。","盛德無我位，清光独暎君。","耻將雞並食，长與鳳爲羣。","一擊九千仞，相期凌紫氛。"]', '诗', 'shi', '', NULL, '贈郭季鷹 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51834578-720b-4ede-9ef2-2c5aebe15b47', '鄴中贈王大', '鄴中贈王大', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["一身竟無託，遠與孤蓬征。","千里失所依，復將落葉幷。","中途偶良朋，問我將何行。","欲獻濟時策，此心誰見明。","君王制六合，海塞無交兵。","壯士伏草間，沈憂亂縱橫。","飄飄不得意，昨發南都城。","紫燕櫪下嘶，青萍匣中鳴。","投軀寄天下，長嘯尋豪英。","耻學瑯琊人，龍蟠事躬耕。","富貴吾自取，建功及春榮。","我願執爾手，爾方達我情。","相知同一己，豈惟弟與兄。","抱子弄白雲，琴歌發清聲。","臨別意難盡，各希存令名。"]', '["一身竟無託，远與孤蓬征。","千里失所依，复將落葉幷。","中途偶良朋，问我將何行。","欲獻濟时策，此心誰见明。","君王制六合，海塞無交兵。","壯士伏草间，沈憂亂縱橫。","飄飄不得意，昨發南都城。","紫燕櫪下嘶，青萍匣中鳴。","投軀寄天下，长嘯尋豪英。","耻学瑯琊人，龙蟠事躬耕。","富貴吾自取，建功及春榮。","我願執爾手，爾方達我情。","相知同一己，豈惟弟與兄。","抱子弄白云，琴歌發清声。","臨別意难尽，各希存令名。"]', '诗', 'shi', '', NULL, '鄴中贈王大 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56dfaaf5-7987-4db7-a126-0fd319535c15', '贈華州王司士', '贈华州王司士', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["淮水不絕濤瀾高，盛德未泯生英髦。","知君先負廟堂器，今日還須贈寶刀。"]', '["淮水不絕濤瀾高，盛德未泯生英髦。","知君先負廟堂器，今日還須贈寶刀。"]', '诗', 'shi', '', NULL, '贈華州王司士 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98126631-cee9-4e83-b214-afbba3233f2e', '贈盧徵君昆弟', '贈盧徵君昆弟', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["明主訪賢逸，雲泉今已空。","二盧竟不起，萬乘高其風。","河上喜相得，壺中趣每同。","滄州即此地，觀化遊無窮。","水落海上清，鼇背覩方蓬。","與君弄倒景，攜手凌星虹。"]', '["明主訪賢逸，云泉今已空。","二盧竟不起，万乘高其风。","河上喜相得，壺中趣每同。","滄州即此地，观化游無窮。","水落海上清，鼇背覩方蓬。","與君弄倒景，携手凌星虹。"]', '诗', 'shi', '', NULL, '贈盧徵君昆弟 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c0c14e2-d8e9-4691-902c-ce616809f62f', '贈新平少年', '贈新平少年', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["韓信在淮陰，少年相欺凌。","屈體若無骨，壯心有所憑。","一遭龍顏君，嘯咤從此興。","千金答漂母，萬古共嗟稱。","而我竟何爲，寒苦坐相仍。","長風入短袂，兩手如懷冰。","故友不相恤，新交寧見矜。","摧殘檻中虎，羈紲韝上鷹。","何時騰風雲，搏擊申所能。"]', '["韓信在淮陰，少年相欺凌。","屈體若無骨，壯心有所憑。","一遭龙顏君，嘯咤從此兴。","千金答漂母，万古共嗟稱。","而我竟何爲，寒苦坐相仍。","长风入短袂，兩手如懷冰。","故友不相恤，新交寧见矜。","摧殘檻中虎，羈紲韝上鷹。","何时腾风云，搏擊申所能。"]', '诗', 'shi', '', NULL, '贈新平少年 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd0e56ab-818a-4cae-8e88-ebc59f31366e', '贈崔侍郎', '贈崔侍郎', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["長劒一杯酒，男兒方寸心。","洛陽因劇孟，託宿話胸襟。","但仰山嶽秀，不知江海深。","長安復攜手，再顧重千金。","君乃輶軒佐，予叨翰墨林。","高風摧秀木，虛彈落驚禽。","不取回舟興，而來命駕尋。","扶搖應借力，桃李願成陰。","笑吐張儀舌，愁爲莊舃吟。","誰憐明月夜，腸斷聽秋砧。"]', '["长劒一杯酒，男兒方寸心。","洛陽因劇孟，託宿話胸襟。","但仰山嶽秀，不知江海深。","长安复携手，再顧重千金。","君乃輶軒佐，予叨翰墨林。","高风摧秀木，虛彈落驚禽。","不取回舟兴，而来命駕尋。","扶搖應借力，桃李願成陰。","笑吐張儀舌，愁爲莊舃吟。","誰怜明月夜，腸斷听秋砧。"]', '诗', 'shi', '', NULL, '贈崔侍郎 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04423e53-a15c-47e2-b57b-5cb8a78f453b', '走筆贈獨孤駙馬', '走笔贈独孤駙马', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["都尉朝天躍馬歸，香風吹人花亂飛。","銀鞍紫鞚照雲日，左顧右盼生光輝。","是時僕在金門裏，待詔公車謁天子。","長揖蒙垂國士恩，壯心剖出酬知己。","一別蹉跎朝市間，青雲之交不可攀。","儻其公子重回顧，何必侯嬴長抱關。"]', '["都尉朝天躍马归，香风吹人花亂飞。","銀鞍紫鞚照云日，左顧右盼生光輝。","是时僕在金门裏，待詔公车謁天子。","长揖蒙垂国士恩，壯心剖出酬知己。","一別蹉跎朝市间，青云之交不可攀。","儻其公子重回顧，何必侯嬴长抱关。"]', '诗', 'shi', '', NULL, '走筆贈獨孤駙馬 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('310a01a7-2e75-4fba-be00-3d69b1af41f7', '贈嵩山焦鍊師', '贈嵩山焦鍊師', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["二室凌青天，三花含紫煙。","中有蓬海客，宛疑麻姑仙。","道在喧莫染，跡高想已綿。","時餐金鵝蘂，屢讀青苔篇。","八極恣遊憩，九垓長周旋。","下瓢酌潁水，舞鶴來伊川。","還歸空山上，獨拂秋霞眠。","蘿月挂朝鏡，松風鳴夜弦。","潛光隱嵩嶽，鍊魄棲雲幄。","霓裳何飄颻，鳳吹轉緜邈。","願同西王母，下顧東方朔。","紫書儻可傳，銘骨誓相學。"]', '["二室凌青天，三花含紫煙。","中有蓬海客，宛疑麻姑仙。","道在喧莫染，跡高想已綿。","时餐金鵝蘂，屢读青苔篇。","八極恣游憩，九垓长周旋。","下瓢酌潁水，舞鹤来伊川。","還归空山上，独拂秋霞眠。","蘿月挂朝镜，松风鳴夜弦。","潛光隐嵩嶽，鍊魄棲云幄。","霓裳何飄颻，鳳吹轉緜邈。","願同西王母，下顧东方朔。","紫书儻可傳，銘骨誓相学。"]', '诗', 'shi', '', NULL, '贈嵩山焦鍊師 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a043a23-9681-46c5-ae30-b8aaff569326', '口號贈徵君鴻', '口號贈徵君鴻', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["陶令辭彭澤，梁鴻入會稽。","我尋高士傳，君與古人齊。","雲臥留丹壑，天書降紫泥。","不知楊伯起，早晚向關西。"]', '["陶令辞彭澤，梁鴻入會稽。","我尋高士傳，君與古人齊。","云臥留丹壑，天书降紫泥。","不知楊伯起，早晚向关西。"]', '诗', 'shi', '', NULL, '口號贈徵君鴻 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac06cfdc-adad-4ca5-9304-ee48522b8172', '上李邕', '上李邕', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["大鵬一日同風起，摶搖直上九萬里。","假令風歇時下來，猶能簸却滄溟水。","世人見我恆殊調，聞余大言皆冷笑。","宣父猶能畏後生，丈夫未可輕年少。"]', '["大鵬一日同风起，摶搖直上九万里。","假令风歇时下来，猶能簸却滄溟水。","世人见我恆殊調，闻余大言皆冷笑。","宣父猶能畏後生，丈夫未可轻年少。"]', '诗', 'shi', '', NULL, '上李邕 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83d1b9ba-9fea-4abd-a179-34251325ca3b', '贈張公洲革處士', '贈張公洲革处士', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["列子居鄭圃，不將衆庶分。","革侯遁南浦，常恐楚人聞。","抱甕灌秋蔬，心閑遊天雲。","每將瓜田叟，耕種漢水濆。","時登張公洲，入獸不亂羣。","井無桔槔事，門絕刺繡文。","長揖二千石，遠辭百里君。","斯爲真隱者，吾黨慕清芬。"]', '["列子居鄭圃，不將衆庶分。","革侯遁南浦，常恐楚人闻。","抱甕灌秋蔬，心闲游天云。","每將瓜田叟，耕種漢水濆。","时登張公洲，入獸不亂羣。","井無桔槔事，门絕刺繡文。","长揖二千石，远辞百里君。","斯爲真隐者，吾黨慕清芬。"]', '诗', 'shi', '', NULL, '贈張公洲革處士 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f36a17f-7ee3-49b8-8a0a-52533946c162', '秋日鍊藥院鑷白髮贈元六兄林宗', '秋日鍊藥院鑷白髮贈元六兄林宗', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["木落識歲秋，瓶冰知天寒。","桂枝日已綠，拂雪凌雲端。","弱齡接光景，矯翼攀鴻鸞。","投分三十載，榮枯同所歡。","長吁望青雲，鑷白坐相看。","秋顏入曉鏡，壯髮凋危冠。","窮與鮑生賈，饑從漂母餐。","時來極天人，道在豈吟嘆。","樂毅方適趙，蘇秦初說韓。","卷舒固在我，何事空摧殘。"]', '["木落識歲秋，瓶冰知天寒。","桂枝日已綠，拂雪凌云端。","弱齡接光景，矯翼攀鴻鸾。","投分三十載，榮枯同所歡。","长吁望青云，鑷白坐相看。","秋顏入晓镜，壯髮凋危冠。","窮與鲍生賈，饑從漂母餐。","时来極天人，道在豈吟嘆。","乐毅方適趙，蘇秦初说韓。","卷舒固在我，何事空摧殘。"]', '诗', 'shi', '', NULL, '秋日鍊藥院鑷白髮贈元六兄林宗 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a75693da-8ff2-4807-8a46-9233406ee780', '書情題蔡舍人雄', '书情題蔡舍人雄', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["嘗高謝太傅，攜妓東山門。","楚舞醉碧雲，吳歌斷清猨。","蹔因蒼生起，談笑安黎元。","余亦愛此人，丹霄冀飛飜。","遭逢聖明主，敢進興亡言。","白璧竟何辜，青蠅遂成冤。","一朝去京國，十載客梁園。","猛犬吠九關，殺人憤精魂。","皇穹雪冤枉，白日開氛昏。","泰階得夔龍，桃李滿中原。","倒海索明月，凌山採芳蓀。","媿無橫草功，虛負雨露恩。","跡謝雲臺閣，心隨天馬轅。","夫子王佐才，而今復誰論。","層飆振六翮，不日思騰騫。","我縱五湖櫂，煙濤恣崩奔。","夢釣子陵湍，英風緬猶存。","彼希客星隱，弱植不足援。","千里一迴首，萬里一長歌。","黃鶴不復來，清風愁奈何。","舟浮瀟湘月，山倒洞庭波。","投汨笑古人，臨濠得天和。","閑時田畝中，搔背牧雞鵝。","別離解相訪，應在武陵多。"]', '["嘗高謝太傅，携妓东山门。","楚舞醉碧云，吳歌斷清猨。","蹔因蒼生起，談笑安黎元。","余亦愛此人，丹霄冀飞飜。","遭逢聖明主，敢進兴亡言。","白璧竟何辜，青蠅遂成冤。","一朝去京国，十載客梁园。","猛犬吠九关，殺人憤精魂。","皇穹雪冤枉，白日开氛昏。","泰階得夔龙，桃李满中原。","倒海索明月，凌山採芳蓀。","媿無橫草功，虛負雨露恩。","跡謝云台閣，心隨天马轅。","夫子王佐才，而今复誰論。","層飆振六翮，不日思腾騫。","我縱五湖櫂，煙濤恣崩奔。","梦釣子陵湍，英风緬猶存。","彼希客星隐，弱植不足援。","千里一迴首，万里一长歌。","黄鹤不复来，清风愁奈何。","舟浮瀟湘月，山倒洞庭波。","投汨笑古人，臨濠得天和。","闲时田畝中，搔背牧雞鵝。","別離解相訪，應在武陵多。"]', '诗', 'shi', '', NULL, '書情題蔡舍人雄 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfa27348-43dd-4ad5-a05a-dcad4e95b48c', '憶襄陽舊遊贈馬少府巨', '憶襄陽旧游贈马少府巨', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["昔爲大堤客，曾上山公樓。","開牕碧嶂滿，拂鏡滄江流。","高冠佩雄劒，長揖韓荆州。","此地別夫子，今來思舊遊。","朱顏君未老，白髮我先秋。","壯志恐蹉跎，功名若雲浮。","歸心結遠夢，落日懸春愁。","空思羊叔子，墮淚峴山頭。"]', '["昔爲大堤客，曾上山公楼。","开牕碧嶂满，拂镜滄江流。","高冠佩雄劒，长揖韓荆州。","此地別夫子，今来思旧游。","朱顏君未老，白髮我先秋。","壯志恐蹉跎，功名若云浮。","归心結远梦，落日懸春愁。","空思羊叔子，墮泪峴山头。"]', '诗', 'shi', '', NULL, '憶襄陽舊遊贈馬少府巨 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e9530c1-fd7d-494d-97ed-4e180cafa536', '對雪獻從兄虞城宰', '对雪獻從兄虞城宰', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["昨夜梁園裏，弟寒兄不知。","庭前看玉樹，腸斷憶連枝。"]', '["昨夜梁园裏，弟寒兄不知。","庭前看玉樹，腸斷憶連枝。"]', '诗', 'shi', '', NULL, '對雪獻從兄虞城宰 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b84c71b5-0f31-4a49-9401-c0512d51ff6c', '訪道安陵遇蓋還爲余造真籙臨別留贈', '訪道安陵遇蓋還爲余造真籙臨別留贈', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["清水見白石，仙人識青童。","安陵蓋夫子，十歲與天通。","懸河與微言，談論安可窮。","能令二千石，撫背驚神聰。","揮毫贈新詩，高價掩山東。","至今平原客，感激慕清風。","學道北海仙，傳書蘂珠宮。","丹田了玉闕，白日思雲空。","爲我草真籙，天人慙妙工。","七元洞豁落，八角輝星虹。","三災蕩璿璣，蛟龍翼微躬。","舉手謝天地，虛無齊始終。","黃金滿高堂，荅荷難克充。","下笑世上士，沈魂北羅酆。","昔日萬乘墳，今成一科蓬。","贈言若可重，實此輕華嵩。"]', '["清水见白石，仙人識青童。","安陵蓋夫子，十歲與天通。","懸河與微言，談論安可窮。","能令二千石，撫背驚神聰。","揮毫贈新诗，高價掩山东。","至今平原客，感激慕清风。","学道北海仙，傳书蘂珠宮。","丹田了玉闕，白日思云空。","爲我草真籙，天人慙妙工。","七元洞豁落，八角輝星虹。","三災蕩璿璣，蛟龙翼微躬。","舉手謝天地，虛無齊始終。","黄金满高堂，荅荷难克充。","下笑世上士，沈魂北羅酆。","昔日万乘墳，今成一科蓬。","贈言若可重，實此轻华嵩。"]', '诗', 'shi', '', NULL, '訪道安陵遇蓋還爲余造真籙臨別留贈 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2efb1caa-24f6-4479-b4bc-6db4599d52cb', '贈崔郎中宗之', '贈崔郎中宗之', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["胡雁拂海翼，翱翔鳴素秋。","驚雲辭沙朔，飄蕩迷河洲。","有如飛蓬人，去逐萬里遊。","登高望浮雲，彷彿如舊丘。","日從海傍沒，水向天邊流。","長嘯倚孤劒，目極心悠悠。","歲晏歸去來，富貴安可求。","仲尼七十說，歷聘莫見收。","魯連逃千金，珪組豈可酬。","時哉苟不會，草木爲我儔。","希君同攜手，長往南山幽。"]', '["胡雁拂海翼，翱翔鳴素秋。","驚云辞沙朔，飄蕩迷河洲。","有如飞蓬人，去逐万里游。","登高望浮云，彷彿如旧丘。","日從海傍沒，水向天邊流。","长嘯倚孤劒，目極心悠悠。","歲晏归去来，富貴安可求。","仲尼七十说，歷聘莫见收。","魯連逃千金，珪組豈可酬。","时哉苟不會，草木爲我儔。","希君同携手，长往南山幽。"]', '诗', 'shi', '', NULL, '贈崔郎中宗之 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e28ff60-3d3f-41fa-9266-9049803a4691', '贈崔諮議', '贈崔諮議', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["綠驥本天馬，素非伏櫪駒。","長嘶向清風，倏忽凌九區。","何言西北至，却走東南隅。","世道有飜覆，前期難豫圖。","希君一翦拂，猶可騁中衢。"]', '["綠驥本天马，素非伏櫪駒。","长嘶向清风，倏忽凌九區。","何言西北至，却走东南隅。","世道有飜覆，前期难豫圖。","希君一翦拂，猶可騁中衢。"]', '诗', 'shi', '', NULL, '贈崔諮議 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2404e804-be38-46ba-b07b-194672bf204c', '贈昇州王使君忠臣', '贈昇州王使君忠臣', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["六代帝王國，三吳佳麗城。","賢人當重寄，天子借高名。","巨海一邊靜，長江萬里清。","應須救趙策，未肯棄侯嬴。"]', '["六代帝王国，三吳佳丽城。","賢人當重寄，天子借高名。","巨海一邊静，长江万里清。","應須救趙策，未肯棄侯嬴。"]', '诗', 'shi', '', NULL, '贈昇州王使君忠臣 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abc568f8-8579-484a-a090-e138bcdb2035', '贈別從甥高五', '贈別從甥高五', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["魚目高泰山，不如一璵璠。","賢甥即明月，聲價動天門。","能成吾宅相，不減魏陽元。","自顧寡籌略，功名安所存。","五木思一擲，如繩繫窮猨。","櫪中駿馬空，堂上醉人喧。","黃金久已罄，爲報故交恩。","聞君隴西行，使我驚心魂。","與爾共飄颻，雲天各飛飜。","江水流或卷，此心難具論。","貧家羞好客，語拙覺辭繁。","三朝空錯莫，對飯却慚冤。","自笑我非夫，生事多契闊。","蓄積萬古憤，向誰得開豁。","天地一浮雲，此身乃毫末。","忽見無端倪，太虛可包括。","去去何足道，臨岐空復愁。","肝膽不楚越，山河亦衾裯。","雲龍若相從，明主會見收。","成功解相訪，溪水桃花流。"]', '["鱼目高泰山，不如一璵璠。","賢甥即明月，声價动天门。","能成吾宅相，不減魏陽元。","自顧寡籌略，功名安所存。","五木思一擲，如繩繫窮猨。","櫪中駿马空，堂上醉人喧。","黄金久已罄，爲報故交恩。","闻君隴西行，使我驚心魂。","與爾共飄颻，云天各飞飜。","江水流或卷，此心难具論。","貧家羞好客，語拙覺辞繁。","三朝空錯莫，对飯却慚冤。","自笑我非夫，生事多契闊。","蓄積万古憤，向誰得开豁。","天地一浮云，此身乃毫末。","忽见無端倪，太虛可包括。","去去何足道，臨岐空复愁。","肝膽不楚越，山河亦衾裯。","云龙若相從，明主會见收。","成功解相訪，溪水桃花流。"]', '诗', 'shi', '', NULL, '贈別從甥高五 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7d4ce94-7937-494e-a303-f51135733d56', '贈裴司馬', '贈裴司马', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["翡翠黃金縷，繡成歌舞衣。","若無雲間月，誰可比光輝。","秀色一如此，多爲衆女譏。","君恩移昔愛，失寵秋風歸。","愁苦不窺隣，泣上流黃機。","天寒素手冷，夜長燭復微。","十日不滿匹，鬢蓬亂若絲。","猶是可憐人，容華世中稀。","向君發皓齒，顧我莫相違。"]', '["翡翠黄金縷，繡成歌舞衣。","若無云间月，誰可比光輝。","秀色一如此，多爲衆女譏。","君恩移昔愛，失寵秋风归。","愁苦不窺隣，泣上流黄機。","天寒素手冷，夜长燭复微。","十日不满匹，鬢蓬亂若絲。","猶是可怜人，容华世中稀。","向君發皓齒，顧我莫相違。"]', '诗', 'shi', '', NULL, '贈裴司馬 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32daa6b2-3621-49c2-8afc-069e16464eda', '敘舊贈江陽宰陸調', '敘旧贈江陽宰陸調', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["泰伯讓天下，仲雍揚波濤。","清風蕩萬古，跡與星辰高。","開吳食東溟，陸氏世英髦。","多君秉古節，嶽立冠人曹。","風流少年時，京洛事遊遨。","腰間延陵劒，玉帶明珠袍。","我昔鬬雞徒，連延五陵豪。","邀遮相組織，呵嚇來煎熬。","君開萬叢人，鞍馬皆辟易。","告急清憲臺，脫余北門厄。","間宰江陽邑，翦棘樹蘭芳。","城門何肅穆，五月飛秋霜。","好鳥集珍木，高才列華堂。","時從府中歸，絲管儼成行。","但苦隔遠道，無由共銜觴。","江北荷花開，江南楊梅熟。","正好飲酒時，懷賢在心目。","掛席拾海月，乘風下長川。","多沽新豐醁，滿載剡溪船。","中途不遇人，直到爾門前。","大笑同一醉，取樂平生年。"]', '["泰伯讓天下，仲雍揚波濤。","清风蕩万古，跡與星辰高。","开吳食东溟，陸氏世英髦。","多君秉古節，嶽立冠人曹。","风流少年时，京洛事游遨。","腰间延陵劒，玉带明珠袍。","我昔鬬雞徒，連延五陵豪。","邀遮相組织，呵嚇来煎熬。","君开万叢人，鞍马皆辟易。","告急清憲台，脫余北门厄。","间宰江陽邑，翦棘樹蘭芳。","城门何肅穆，五月飞秋霜。","好鸟集珍木，高才列华堂。","时從府中归，絲管儼成行。","但苦隔远道，無由共銜觴。","江北荷花开，江南楊梅熟。","正好饮酒时，懷賢在心目。","掛席拾海月，乘风下长川。","多沽新豐醁，满載剡溪船。","中途不遇人，直到爾门前。","大笑同一醉，取乐平生年。"]', '诗', 'shi', '', NULL, '敘舊贈江陽宰陸調 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c01d511c-b1ba-4f54-b6d7-3d1976853061', '贈從孫義興宰銘', '贈從孫義兴宰銘', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["天子思茂宰，天枝得英才。","朗然清秋月，獨出映吳臺。","落筆生綺繡，操刀振風雷。","蠖屈雖百里，鵬騫望三台。","退食無外事，琴堂向山開。","綠水寂以閑，白雲有時來。","河陽富奇藻，彭澤縱名杯。","所恨不見之，猶如仰昭回。","元惡昔滔天，疲人散幽草。","驚川無活鱗，舉邑罕遺老。","誓雪會稽恥，將奔宛陵道。","亞相素所重，投刃應桑林。","獨坐傷激揚，神融一開襟。","絃歌欣再理，和樂醉人心。","蠹政除害馬，傾巢有歸禽。","壺漿候君來，聚舞共謳吟。","農人棄簔笠，蠶女墮纓簪。","歡笑相拜賀，則知惠愛深。","歷職吾所聞，稱賢爾爲最。","化洽一邦上，名馳三江外。","峻節貫雲霄，通方堪遠大。","能文變風俗，好客留軒蓋。","他日一來遊，因之嚴光瀨。"]', '["天子思茂宰，天枝得英才。","朗然清秋月，独出映吳台。","落笔生綺繡，操刀振风雷。","蠖屈雖百里，鵬騫望三台。","退食無外事，琴堂向山开。","綠水寂以闲，白云有时来。","河陽富奇藻，彭澤縱名杯。","所恨不见之，猶如仰昭回。","元惡昔滔天，疲人散幽草。","驚川無活鱗，舉邑罕遺老。","誓雪會稽恥，將奔宛陵道。","亞相素所重，投刃應桑林。","独坐傷激揚，神融一开襟。","絃歌欣再理，和乐醉人心。","蠹政除害马，傾巢有归禽。","壺漿候君来，聚舞共謳吟。","農人棄簔笠，蠶女墮纓簪。","歡笑相拜賀，則知惠愛深。","歷職吾所闻，稱賢爾爲最。","化洽一邦上，名驰三江外。","峻節貫云霄，通方堪远大。","能文变风俗，好客留軒蓋。","他日一来游，因之嚴光瀨。"]', '诗', 'shi', '', NULL, '贈從孫義興宰銘 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09aa2f43-14d5-48bd-a363-c8cc52b79925', '草創大還贈柳官迪', '草創大還贈柳官迪', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["天地爲橐籥，周流行太易。","造化合元符，交媾騰精魄。","自然成妙用，孰知其指的。","羅絡四季間，綿微無一隙。","日月更出沒，雙光豈云隻。","姹女乘河車，黃金充轅軛。","執樞相管轄，摧伏傷羽翮。","朱鳥張炎威，白虎守本宅。","相煎成苦老，消鑠凝津液。","髣髴明窗塵，死灰同至寂。","擣冶入赤色，十二周律曆。","赫然稱大還，與道本無隔。","白日可撫弄，清都在咫尺。","北酆落死名，南斗上生籍。","抑予是何者，身在方士格。","才術信縱橫，世途自輕擲。","吾求仙棄俗，君曉損勝益。","不向金闕遊，思爲玉皇客。","鸞車速風電，龍騎無鞭策。","一舉上九天，相攜同所適。"]', '["天地爲橐籥，周流行太易。","造化合元符，交媾腾精魄。","自然成妙用，孰知其指的。","羅絡四季间，綿微無一隙。","日月更出沒，雙光豈云隻。","姹女乘河车，黄金充轅軛。","執樞相管轄，摧伏傷羽翮。","朱鸟張炎威，白虎守本宅。","相煎成苦老，消鑠凝津液。","髣髴明窗塵，死灰同至寂。","擣冶入赤色，十二周律曆。","赫然稱大還，與道本無隔。","白日可撫弄，清都在咫尺。","北酆落死名，南斗上生籍。","抑予是何者，身在方士格。","才術信縱橫，世途自轻擲。","吾求仙棄俗，君晓損勝益。","不向金闕游，思爲玉皇客。","鸾车速风電，龙騎無鞭策。","一舉上九天，相携同所適。"]', '诗', 'shi', '', NULL, '草創大還贈柳官迪 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ea485a2-3b64-4620-b3ee-9db7957d1406', '贈崔司戶文昆季', '贈崔司戶文昆季', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["雙珠出海底，俱是連城珍。","明月兩特達，餘輝傍照人。","英聲振名都，高價動殊鄰。","豈伊箕山故，特以風期親。","惟昔不自媒，擔簦西入秦。","攀龍九天上，忝列歲星臣。","布衣侍丹墀，密勿草絲綸。","才微惠渥重，讒巧生緇磷。","一去已十載，今來復盈旬。","清霜入曉鬢，白露生衣巾。","側見綠水亭，開門列華茵。","千金散義士，四坐無凡賓。","欲折月中桂，持爲寒者薪。","路傍已竊笑，天路將何因。","垂恩儻丘山，報德有微身。"]', '["雙珠出海底，俱是連城珍。","明月兩特達，餘輝傍照人。","英声振名都，高價动殊鄰。","豈伊箕山故，特以风期親。","惟昔不自媒，擔簦西入秦。","攀龙九天上，忝列歲星臣。","布衣侍丹墀，密勿草絲綸。","才微惠渥重，讒巧生緇磷。","一去已十載，今来复盈旬。","清霜入晓鬢，白露生衣巾。","側见綠水亭，开门列华茵。","千金散義士，四坐無凡賓。","欲折月中桂，持爲寒者薪。","路傍已竊笑，天路將何因。","垂恩儻丘山，報德有微身。"]', '诗', 'shi', '', NULL, '贈崔司戶文昆季 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edb138a4-d3fe-4756-b99a-fb0de2c818b6', '贈溧陽宋少府陟', '贈溧陽宋少府陟', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["李斯未相秦，且逐東門兔。","宋玉事襄王，能爲高唐賦。","常聞綠水曲，忽此相逢遇。","掃灑青天開，豁然披雲霧。","葳甤紫鸞鳥，巢在崑山樹。","驚風西北吹，飛落南溟去。","早懷經濟策，特受龍顏顧。","白玉棲青蠅，君臣忽行路。","人生感分義，貴欲呈丹素。","何日清中原，相期廓天步。"]', '["李斯未相秦，且逐东门兔。","宋玉事襄王，能爲高唐賦。","常闻綠水曲，忽此相逢遇。","掃灑青天开，豁然披云霧。","葳甤紫鸾鸟，巢在崑山樹。","驚风西北吹，飞落南溟去。","早懷經濟策，特受龙顏顧。","白玉棲青蠅，君臣忽行路。","人生感分義，貴欲呈丹素。","何日清中原，相期廓天步。"]', '诗', 'shi', '', NULL, '贈溧陽宋少府陟 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de7fcf8a-b3f8-4431-a50e-f5f5f3cf78a1', '戲贈鄭溧陽', '戲贈鄭溧陽', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["陶令日日醉，不知五柳春。","素琴本無弦，漉酒用葛巾。","清風北牕下，自謂羲皇人。","何時到栗里，一見平生親。"]', '["陶令日日醉，不知五柳春。","素琴本無弦，漉酒用葛巾。","清风北牕下，自謂羲皇人。","何时到栗里，一见平生親。"]', '诗', 'shi', '', NULL, '戲贈鄭溧陽 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b64c987-9747-4113-b68b-956c5a74a9a2', '贈僧崖公', '贈僧崖公', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["昔在朗陵東，學禪白眉空。","大地了鏡徹，迴旋寄輪風。","攬彼造化力，持爲我神通。","晚謁泰山君，親見日沒雲。","中夜臥山月，拂衣逃人羣。","授余金仙道，曠劫未始聞。","冥機發天光，獨朗謝垢氛。","虛舟不繫物，觀化遊江濆。","江濆遇同聲，道崖乃僧英。","說法動海嶽，遊方化公卿。","手秉玉麈尾，如登白樓亭。","微言注百川，亹亹信可聽。","一風鼓羣有，萬籟各自鳴。","啓閉八牕牖，託宿掣電霆。","自言歷天台，搏壁躡翠屏。","凌兢石橋去，恍惚入青冥。","昔往今來歸，絕景無不經。","何日更攜手，乘杯向蓬瀛。"]', '["昔在朗陵东，学禪白眉空。","大地了镜徹，迴旋寄輪风。","攬彼造化力，持爲我神通。","晚謁泰山君，親见日沒云。","中夜臥山月，拂衣逃人羣。","授余金仙道，曠劫未始闻。","冥機發天光，独朗謝垢氛。","虛舟不繫物，观化游江濆。","江濆遇同声，道崖乃僧英。","说法动海嶽，游方化公卿。","手秉玉麈尾，如登白楼亭。","微言注百川，亹亹信可听。","一风鼓羣有，万籟各自鳴。","啓閉八牕牖，託宿掣電霆。","自言歷天台，搏壁躡翠屏。","凌兢石橋去，恍惚入青冥。","昔往今来归，絕景無不經。","何日更携手，乘杯向蓬瀛。"]', '诗', 'shi', '', NULL, '贈僧崖公 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75d710be-1a60-444e-8e34-371cf0f9d56e', '遊溧陽北湖亭望瓦屋山懷古贈同旅', '游溧陽北湖亭望瓦屋山懷古贈同旅', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["朝登北湖亭，遙望瓦屋山。","天清白露下，始覺秋風還。","遊子託主人，仰觀眉睫間。","目色送飛鴻，邈然不可攀。","長吁相勸勉，何事來吳關。","聞有貞義女，振窮溧水灣。","清光了在眼，白日如披顏。","高墳五六墩，崒兀棲猛虎。","遺跡翳九泉，芳名動千古。","子胥昔乞食，此女傾壺漿。","運開展宿憤，入楚鞭平王。","凜冽天地間，聞名若懷霜。","壯夫或未達，十步九太行。","與君拂衣去，萬里同翱翔。"]', '["朝登北湖亭，遙望瓦屋山。","天清白露下，始覺秋风還。","游子託主人，仰观眉睫间。","目色送飞鴻，邈然不可攀。","长吁相勸勉，何事来吳关。","闻有貞義女，振窮溧水灣。","清光了在眼，白日如披顏。","高墳五六墩，崒兀棲猛虎。","遺跡翳九泉，芳名动千古。","子胥昔乞食，此女傾壺漿。","運开展宿憤，入楚鞭平王。","凜冽天地间，闻名若懷霜。","壯夫或未達，十步九太行。","與君拂衣去，万里同翱翔。"]', '诗', 'shi', '', NULL, '遊溧陽北湖亭望瓦屋山懷古贈同旅 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94819d98-45d2-4502-a306-2d1c9cff38d4', '醉後贈從甥高鎮', '醉後贈從甥高鎮', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["馬上相逢揖馬鞭，客中相見客中憐。","欲邀擊筑悲歌飲，正值傾家無酒錢。","江東風光不借人，枉殺落花空自春。","黃金逐手快意盡，昨日破產今朝貧。","丈夫何事空嘯傲，不如燒却頭上巾。","君爲進士不得進，我被秋霜生旅鬢。","時清不及英豪人，三尺童兒重廉藺。","匣中盤劒裝䱜魚，閑在腰間未用渠。","且將換酒與君醉，醉歸託宿吳專諸。"]', '["马上相逢揖马鞭，客中相见客中怜。","欲邀擊筑悲歌饮，正值傾家無酒錢。","江东风光不借人，枉殺落花空自春。","黄金逐手快意尽，昨日破產今朝貧。","丈夫何事空嘯傲，不如燒却头上巾。","君爲進士不得進，我被秋霜生旅鬢。","时清不及英豪人，三尺童兒重廉藺。","匣中盤劒裝䱜鱼，闲在腰间未用渠。","且將換酒與君醉，醉归託宿吳專諸。"]', '诗', 'shi', '', NULL, '醉後贈從甥高鎮 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('996b4503-801b-489f-ae0e-1559e0475817', '崔秋浦柳少府', '崔秋浦柳少府', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秋浦舊蕭索，公庭人吏稀。","因君樹桃李，此地忽芳菲。","搖筆望白雲，開簾當翠微。","時來引山月，縱酒酣清暉。","而我愛夫子，淹留未忍歸。"]', '["秋浦旧蕭索，公庭人吏稀。","因君樹桃李，此地忽芳菲。","搖笔望白云，开簾當翠微。","时来引山月，縱酒酣清暉。","而我愛夫子，淹留未忍归。"]', '诗', 'shi', '', NULL, '崔秋浦柳少府 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f4d5865-eba5-4c02-ac53-1250d3d4c7aa', '贈崔秋浦三首 一', '贈崔秋浦三首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["吾愛崔秋浦，宛然陶令風。","門前五楊柳，井上二梧桐。","山鳥下廳事，簷花落酒中。","懷君未忍去，惆悵意無窮。"]', '["吾愛崔秋浦，宛然陶令风。","门前五楊柳，井上二梧桐。","山鸟下廳事，簷花落酒中。","懷君未忍去，惆悵意無窮。"]', '诗', 'shi', '', NULL, '贈崔秋浦三首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed77a4c0-6438-4ab5-9953-27dc57e4779f', '贈崔秋浦三首 二', '贈崔秋浦三首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["崔令學陶令，北牕常晝眠。","抱琴時弄月，取意任無弦。","見客但傾酒，爲官不愛錢。","東臯春事起，種黍早歸田。"]', '["崔令学陶令，北牕常晝眠。","抱琴时弄月，取意任無弦。","见客但傾酒，爲官不愛錢。","东臯春事起，種黍早归田。"]', '诗', 'shi', '', NULL, '贈崔秋浦三首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab19feb0-04d7-441e-89e0-7580b407c8cd', '贈崔秋浦三首 三', '贈崔秋浦三首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["河陽花作縣，秋浦玉爲人。","地逐名賢好，風隨惠化春。","水從天漢落，山逼畫屏新。","應念金門客，投沙弔楚臣。"]', '["河陽花作縣，秋浦玉爲人。","地逐名賢好，风隨惠化春。","水從天漢落，山逼畫屏新。","應念金门客，投沙弔楚臣。"]', '诗', 'shi', '', NULL, '贈崔秋浦三首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c0f9c61-580a-42ff-a0ab-fcc322af93b3', '望九華贈青陽韋仲堪', '望九华贈青陽韋仲堪', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["昔在九江上，遙望九華峰。","天河掛綠水，秀出九芙蓉。","我欲一揮手，誰人可相從。","君爲東道主，於此臥雲松。"]', '["昔在九江上，遙望九华峰。","天河掛綠水，秀出九芙蓉。","我欲一揮手，誰人可相從。","君爲东道主，於此臥云松。"]', '诗', 'shi', '', NULL, '望九華贈青陽韋仲堪 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec900f91-f6b5-48e6-ac23-9558b41f9c8a', '贈王判官時余歸隱居廬山屏風疊', '贈王判官时余归隐居廬山屏风叠', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["昔別黃鶴樓，蹉跎淮海秋。","俱飄零落葉，各散洞庭流。","中年不相見，蹭蹬遊吳越。","何處我思君，天台綠蘿月。","會稽風月好，却遶剡溪迴。","雲山海上出，人物鏡中來。","一度浙江北，十年醉楚臺。","荆門倒屈宋，梁苑傾鄒枚。","苦笑我誇誕，知音安在哉。","大盜割鴻溝，如風掃秋葉。","吾非濟代人，且隱屏風疊。","中夜天中望，憶君思見君。","明朝拂衣去，永與海鷗羣。"]', '["昔別黄鹤楼，蹉跎淮海秋。","俱飄零落葉，各散洞庭流。","中年不相见，蹭蹬游吳越。","何处我思君，天台綠蘿月。","會稽风月好，却遶剡溪迴。","云山海上出，人物镜中来。","一度浙江北，十年醉楚台。","荆门倒屈宋，梁苑傾鄒枚。","苦笑我誇誕，知音安在哉。","大盜割鴻溝，如风掃秋葉。","吾非濟代人，且隐屏风叠。","中夜天中望，憶君思见君。","明朝拂衣去，永與海鷗羣。"]', '诗', 'shi', '', NULL, '贈王判官時余歸隱居廬山屏風疊 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('602f1647-233b-4a4e-9aa0-cb11c90fac9c', '在水軍宴贈幕府諸侍御', '在水軍宴贈幕府諸侍御', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["月化五白龍，翻飛凌九天。","胡沙驚北海，電掃洛陽川。","虜箭雨宮闕，皇輿成播遷。","英王受廟略，秉鉞清南邊。","雲旗卷海雪，金戟羅江煙。","聚散百萬人，弛張在一賢。","霜臺降羣彥，水國奉戎旃。","繡服開宴語，天人借樓船。","如登黃金臺，遙謁紫霞仙。","卷身編蓬下，冥機四十年。","寧知草間人，腰下有龍泉。","浮雲在一決，誓欲清幽燕。","願與四座公，靜談金匱篇。","齊心戴朝恩，不惜微軀捐。","所冀旄頭滅，功成追魯連。"]', '["月化五白龙，翻飞凌九天。","胡沙驚北海，電掃洛陽川。","虜箭雨宮闕，皇輿成播遷。","英王受廟略，秉鉞清南邊。","云旗卷海雪，金戟羅江煙。","聚散百万人，弛張在一賢。","霜台降羣彥，水国奉戎旃。","繡服开宴語，天人借楼船。","如登黄金台，遙謁紫霞仙。","卷身編蓬下，冥機四十年。","寧知草间人，腰下有龙泉。","浮云在一決，誓欲清幽燕。","願與四座公，静談金匱篇。","齊心戴朝恩，不惜微軀捐。","所冀旄头滅，功成追魯連。"]', '诗', 'shi', '', NULL, '在水軍宴贈幕府諸侍御 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb6cf52e-4b9f-49bd-bcf2-51314dc7a16c', '贈武十七諤幷序', '贈武十七諤幷序', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["馬如一匹練，明日過吳門。","乃是要離客，西來欲報恩。","笑開燕匕首，拂拭竟無言。","狄犬吠清洛，天津成塞垣。","愛子隔東魯，空悲斷腸猨。","林回棄白璧，千里阻同奔。","君爲我致之，輕齎涉淮原。","精誠合天道，不媿遠遊魂。"]', '["马如一匹練，明日過吳门。","乃是要離客，西来欲報恩。","笑开燕匕首，拂拭竟無言。","狄犬吠清洛，天津成塞垣。","愛子隔东魯，空悲斷腸猨。","林回棄白璧，千里阻同奔。","君爲我致之，轻齎涉淮原。","精誠合天道，不媿远游魂。"]', '诗', 'shi', '', NULL, '贈武十七諤幷序 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7522f3a7-04f9-4114-8973-eb57c93a2017', '贈閭丘宿松', '贈閭丘宿松', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["阮籍爲太守，乘驢上東平。","剖竹十日間，一朝風化清。","偶來拂衣去，誰測主人情。","夫子理宿松，浮雲知古城。","掃地物莽然，秋來百草生。","飛鳥還舊巢，遷人返躬耕。","何慙宓子賤，不減陶淵明。","吾知千載後，却掩二賢名。"]', '["阮籍爲太守，乘驢上东平。","剖竹十日间，一朝风化清。","偶来拂衣去，誰測主人情。","夫子理宿松，浮云知古城。","掃地物莽然，秋来百草生。","飞鸟還旧巢，遷人返躬耕。","何慙宓子賤，不減陶淵明。","吾知千載後，却掩二賢名。"]', '诗', 'shi', '', NULL, '贈閭丘宿松 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eed9b030-eed4-4c4a-86a9-a509e780fd26', '獄中上崔相渙', '獄中上崔相渙', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["胡馬渡洛水，血流征戰場。","千門閉秋景，萬姓危朝霜。","賢相燮元氣，再欣海縣康。","台庭有夔龍，列宿粲成行。","羽翼三元聖，發輝兩太陽。","應念覆盆下，雪泣拜天光。"]', '["胡马渡洛水，血流征戰場。","千门閉秋景，万姓危朝霜。","賢相燮元氣，再欣海縣康。","台庭有夔龙，列宿粲成行。","羽翼三元聖，發輝兩太陽。","應念覆盆下，雪泣拜天光。"]', '诗', 'shi', '', NULL, '獄中上崔相渙 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e52d1c6a-60e1-41e2-b664-dcaa855eec1c', '中丞宋公以吳兵三千赴河南軍次尋陽脫余之囚參謀幕府因贈之', '中丞宋公以吳兵三千赴河南軍次尋陽脫余之囚參謀幕府因贈之', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["獨坐清天下，專征出海隅。","九江皆渡虎，三郡盡還珠。","組練明秋浦，樓船入郢都。","風高初選將，月滿欲平胡。","殺氣橫千里，軍聲動九區。","白猨慙劒術，黃石借兵符。","戎虜行當翦，鯨鯢立可誅。","自憐非劇孟，何以佐良圖。"]', '["独坐清天下，專征出海隅。","九江皆渡虎，三郡尽還珠。","組練明秋浦，楼船入郢都。","风高初選將，月满欲平胡。","殺氣橫千里，軍声动九區。","白猨慙劒術，黄石借兵符。","戎虜行當翦，鯨鯢立可誅。","自怜非劇孟，何以佐良圖。"]', '诗', 'shi', '', NULL, '中丞宋公以吳兵三千赴河南軍次尋陽脫余之囚參謀幕府因贈之 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f190880a-4ece-4fab-9853-b67eb441042c', '流夜郎贈辛判官', '流夜郎贈辛判官', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["昔在長安醉花柳，五侯七貴同杯酒。","氣岸遙凌豪士前，風流肯落他人後。","夫子紅顏我少年，章臺走馬著金鞭。","文章獻納麒麟殿，歌舞淹留玳瑁筵。","與君自謂長如此，寧知草動風塵起。","函谷忽驚胡馬來，秦宮桃李向明開。","我愁遠謫夜郎去，何日金雞放赦回。"]', '["昔在长安醉花柳，五侯七貴同杯酒。","氣岸遙凌豪士前，风流肯落他人後。","夫子紅顏我少年，章台走马著金鞭。","文章獻納麒麟殿，歌舞淹留玳瑁筵。","與君自謂长如此，寧知草动风塵起。","函谷忽驚胡马来，秦宮桃李向明开。","我愁远謫夜郎去，何日金雞放赦回。"]', '诗', 'shi', '', NULL, '流夜郎贈辛判官 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2873fe6-8634-4ec0-b80b-16f3fc913f53', '贈劉都使', '贈劉都使', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["東平劉公幹，南國秀餘芳。","一鳴即朱紱，五十佩銀章。","飲冰事戎幕，衣錦華水鄉。","銅官幾萬人，諍訟清玉堂。","吐言貴珠玉，落筆迴風霜。","而我謝明主，銜哀投夜郎。","歸家酒債多，門客粲成行。","高談滿四座，一日傾千觴。","所求竟無緒，裘馬欲摧藏。","主人若不顧，明發釣滄浪。"]', '["东平劉公幹，南国秀餘芳。","一鳴即朱紱，五十佩銀章。","饮冰事戎幕，衣錦华水乡。","銅官幾万人，諍訟清玉堂。","吐言貴珠玉，落笔迴风霜。","而我謝明主，銜哀投夜郎。","归家酒債多，门客粲成行。","高談满四座，一日傾千觴。","所求竟無緒，裘马欲摧藏。","主人若不顧，明發釣滄浪。"]', '诗', 'shi', '', NULL, '贈劉都使 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44fb14b9-0270-49d8-89b7-3f396c535f6b', '贈常侍御', '贈常侍御', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["安石在東山，無心濟天下。","一起振橫流，功成復瀟灑。","大賢有卷舒，季葉輕風雅。","匡復屬何人，君爲知音者。","傳聞武安將，氣振長平瓦。","燕趙期洗清，周秦保宗社。","登朝若有言，爲訪南遷賈。"]', '["安石在东山，無心濟天下。","一起振橫流，功成复瀟灑。","大賢有卷舒，季葉轻风雅。","匡复屬何人，君爲知音者。","傳闻武安將，氣振长平瓦。","燕趙期洗清，周秦保宗社。","登朝若有言，爲訪南遷賈。"]', '诗', 'shi', '', NULL, '贈常侍御 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0eb6d91-a53f-4ba6-ba0e-f42f1b508f19', '贈易秀才', '贈易秀才', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["少年解長劒，投贈即分離。","何不斷犀象，精光暗往時。","蹉跎君自惜，竄逐我因誰。","地遠虞翻老，秋深宋玉悲。","空摧芳桂色，不屈古松姿。","感激平生意，勞歌寄此辭。"]', '["少年解长劒，投贈即分離。","何不斷犀象，精光暗往时。","蹉跎君自惜，竄逐我因誰。","地远虞翻老，秋深宋玉悲。","空摧芳桂色，不屈古松姿。","感激平生意，勞歌寄此辞。"]', '诗', 'shi', '', NULL, '贈易秀才 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4429abf8-a575-4067-b572-1ec4e31bc925', '經亂離後天恩流夜郎憶舊遊書懷贈江夏韋太守良宰', '經亂離後天恩流夜郎憶旧游书懷贈江夏韋太守良宰', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["天上白玉京，十二樓五城。","仙人撫我頂，結髮受長生。","誤逐世間樂，頗窮理亂情。","九十六聖君，浮雲挂空名。","天地賭一擲，未能望戰爭。","試涉霸王略，將期軒冕榮。","時命乃大謬，棄之海上行。","學劒翻自哂，爲文竟何成。","劒非萬人敵，文竊四海聲。","兒戲不足道，五噫出西京。","臨當欲去時，慷慨淚沾纓。","嘆君倜儻才，標舉冠羣英。","開筵引祖帳，慰此遠徂征。","鞍馬若浮雲，送余驃騎亭。","歌鍾不盡意，白日落昆明。","十月到幽州，戈鋋若羅星。","君王棄北海，掃地借長鯨。","呼吸走百川，燕然可摧傾。","心知不得語，却欲棲蓬瀛。","彎弧懼天狼，挾矢不敢張。","攬涕黃金臺，呼天哭昭王。","無人貴駿骨，騄耳空騰驤。","樂毅儻再生，于今亦奔亡。","蹉跎不得意，驅馬還貴鄉。","逢君聽弦歌，肅穆坐華堂。","百里獨太古，陶然臥羲皇。","徵樂昌樂館，開筵列壺觴。","賢豪間青娥，對燭儼成行。","醉舞紛綺席，清歌繞飛梁。","歡娛未終朝，秩滿歸咸陽。","祖道擁萬人，供帳遙相望。","一別隔千里，榮枯異炎涼。","炎涼幾度改，九土中橫潰。","漢甲連胡兵，沙塵暗雲海。","草木搖殺氣，星辰無光彩。","白骨成丘山，蒼生竟何罪。","函關壯帝居，國命懸哥舒。","長戟三十萬，開門納兇渠。","公卿如犬羊，忠讜醢與葅。","二聖出遊豫，兩京遂丘墟。","帝子許專征，秉旄控强楚。","節制非桓文，軍師擁熊虎。","人心失去就，賊勢騰風雨。","惟君固房陵，誠節冠終古。","僕臥香爐頂，餐霞漱瑤泉。","門開九江轉，枕下五湖連。","半夜水軍來，潯陽滿旌旃。","空名適自誤，迫脅上樓船。","徒賜五百金，棄之若浮煙。","辭官不受賞，飜謫夜郎天。","夜郎萬里道，西上令人老。","掃蕩六合清，仍爲負霜草。","日月無偏照，何由訴蒼昊。","良牧稱神明，深仁恤交道。","一忝青雲客，三登黃鶴樓。","顧慙禰處士，虛對鸚鵡洲。","樊山霸氣盡，寥落天地秋。","江帶峨眉雪，川橫三峽流。","萬舸此中來，連帆過揚州。","送此萬里目，曠然散我愁。","紗窗倚天開，水樹綠如髮。","窺日畏銜山，促酒喜得月。","吳娃與越豔，窈窕誇鉛紅。","呼來上雲梯，含笑出簾櫳。","對客小垂手，羅衣舞春風。","賓跪請休息，主人情未極。","覽君荆山作，江鮑堪動色。","清水出芙蓉，天然去雕飾。","逸興橫素襟，無時不招尋。","朱門擁虎士，列戟何森森。","剪鑿竹石開，縈流漲清深。","登臺坐水閣，吐論多英音。","片辭貴白壁，一諾輕黃金。","謂我不愧君，青鳥明丹心。","五色雲間鵲，飛鳴天上來。","傳聞赦書至，却放夜郎迴。","暖氣變寒谷，炎煙生死灰。","君登鳳池去，忽棄賈生才。","桀犬尚吠堯，匈奴笑千秋。","中夜四五歎，常爲大國憂。","旌斾夾兩山，黃河當中流。","連雞不得進，飲馬空夷猶。","安得羿善射，一箭落旄頭。"]', '["天上白玉京，十二楼五城。","仙人撫我頂，結髮受长生。","誤逐世间乐，頗窮理亂情。","九十六聖君，浮云挂空名。","天地賭一擲，未能望戰爭。","試涉霸王略，將期軒冕榮。","时命乃大謬，棄之海上行。","学劒翻自哂，爲文竟何成。","劒非万人敵，文竊四海声。","兒戲不足道，五噫出西京。","臨當欲去时，慷慨泪沾纓。","嘆君倜儻才，標舉冠羣英。","开筵引祖帳，慰此远徂征。","鞍马若浮云，送余驃騎亭。","歌鍾不尽意，白日落昆明。","十月到幽州，戈鋋若羅星。","君王棄北海，掃地借长鯨。","呼吸走百川，燕然可摧傾。","心知不得語，却欲棲蓬瀛。","彎弧懼天狼，挾矢不敢張。","攬涕黄金台，呼天哭昭王。","無人貴駿骨，騄耳空腾驤。","乐毅儻再生，于今亦奔亡。","蹉跎不得意，驱马還貴乡。","逢君听弦歌，肅穆坐华堂。","百里独太古，陶然臥羲皇。","徵乐昌乐館，开筵列壺觴。","賢豪间青娥，对燭儼成行。","醉舞紛綺席，清歌繞飞梁。","歡娛未終朝，秩满归咸陽。","祖道擁万人，供帳遙相望。","一別隔千里，榮枯異炎涼。","炎涼幾度改，九土中橫潰。","漢甲連胡兵，沙塵暗云海。","草木搖殺氣，星辰無光彩。","白骨成丘山，蒼生竟何罪。","函关壯帝居，国命懸哥舒。","长戟三十万，开门納兇渠。","公卿如犬羊，忠讜醢與葅。","二聖出游豫，兩京遂丘墟。","帝子許專征，秉旄控强楚。","節制非桓文，軍師擁熊虎。","人心失去就，賊勢腾风雨。","惟君固房陵，誠節冠終古。","僕臥香爐頂，餐霞漱瑤泉。","门开九江轉，枕下五湖連。","半夜水軍来，潯陽满旌旃。","空名適自誤，迫脅上楼船。","徒賜五百金，棄之若浮煙。","辞官不受賞，飜謫夜郎天。","夜郎万里道，西上令人老。","掃蕩六合清，仍爲負霜草。","日月無偏照，何由訴蒼昊。","良牧稱神明，深仁恤交道。","一忝青云客，三登黄鹤楼。","顧慙禰处士，虛对鸚鵡洲。","樊山霸氣尽，寥落天地秋。","江带峨眉雪，川橫三峽流。","万舸此中来，連帆過揚州。","送此万里目，曠然散我愁。","紗窗倚天开，水樹綠如髮。","窺日畏銜山，促酒喜得月。","吳娃與越豔，窈窕誇鉛紅。","呼来上云梯，含笑出簾櫳。","对客小垂手，羅衣舞春风。","賓跪請休息，主人情未極。","覽君荆山作，江鲍堪动色。","清水出芙蓉，天然去雕飾。","逸兴橫素襟，無时不招尋。","朱门擁虎士，列戟何森森。","剪鑿竹石开，縈流漲清深。","登台坐水閣，吐論多英音。","片辞貴白壁，一諾轻黄金。","謂我不愧君，青鸟明丹心。","五色云间鵲，飞鳴天上来。","傳闻赦书至，却放夜郎迴。","暖氣变寒谷，炎煙生死灰。","君登鳳池去，忽棄賈生才。","桀犬尚吠堯，匈奴笑千秋。","中夜四五歎，常爲大国憂。","旌斾夾兩山，黄河當中流。","連雞不得進，饮马空夷猶。","安得羿善射，一箭落旄头。"]', '诗', 'shi', '', NULL, '經亂離後天恩流夜郎憶舊遊書懷贈江夏韋太守良宰 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90edd84c-05d9-4f52-8364-252e435a0074', '江夏使君叔席上贈史郎中', '江夏使君叔席上贈史郎中', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["鳳凰丹禁裏，銜出紫泥書。","昔放三湘去，今還萬死餘。","仙郎久爲別，客舍問何如。","涸轍思流水，浮雲失舊居。","多慙華省貴，不以逐臣疎。","復如竹林下，叨陪芳宴初。","希君生羽翼，一化北溟魚。"]', '["鳳凰丹禁裏，銜出紫泥书。","昔放三湘去，今還万死餘。","仙郎久爲別，客舍问何如。","涸轍思流水，浮云失旧居。","多慙华省貴，不以逐臣疎。","复如竹林下，叨陪芳宴初。","希君生羽翼，一化北溟鱼。"]', '诗', 'shi', '', NULL, '江夏使君叔席上贈史郎中 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfd56752-c1d6-4a16-9cbc-89e46b6f3be8', '博平鄭太守自廬山千里相尋入江夏北市門見訪却之武陵立馬贈別', '博平鄭太守自廬山千里相尋入江夏北市门见訪却之武陵立马贈別', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["大梁貴公子，氣蓋蒼梧雲。","若無三千客，誰道信陵君。","救趙復存魏，英威天下聞。","邯鄲能屈節，訪博從毛薛。","夷門得隱淪，而與侯生親。","仍要鼓刀者，乃是袖槌人。","好士不盡心，何能保其身。","多君重然諾，意氣遙相託。","五馬入市門，金鞍照城郭。","都忘虎竹貴，且與荷衣樂。","去去桃花源，何時見歸軒。","相思無終極，腸斷朗江猨。"]', '["大梁貴公子，氣蓋蒼梧云。","若無三千客，誰道信陵君。","救趙复存魏，英威天下闻。","邯鄲能屈節，訪博從毛薛。","夷门得隐淪，而與侯生親。","仍要鼓刀者，乃是袖槌人。","好士不尽心，何能保其身。","多君重然諾，意氣遙相託。","五马入市门，金鞍照城郭。","都忘虎竹貴，且與荷衣乐。","去去桃花源，何时见归軒。","相思無終極，腸斷朗江猨。"]', '诗', 'shi', '', NULL, '博平鄭太守自廬山千里相尋入江夏北市門見訪却之武陵立馬贈別 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ae6306b-b91f-4004-a662-08b25538f28e', '江上贈竇長史', '江上贈竇长史', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["漢求季布魯朱家，楚逐伍胥去章華。","萬里南遷夜郎國，三年歸及長風沙。","聞道青雲貴公子，錦帆游戲西江水。","人疑天上坐樓船，水淨霞明兩重綺。","相約相期何太深，棹歌搖艇月中尋。","不同珠履三千客，別欲論交一片心。"]', '["漢求季布魯朱家，楚逐伍胥去章华。","万里南遷夜郎国，三年归及长风沙。","闻道青云貴公子，錦帆游戲西江水。","人疑天上坐楼船，水淨霞明兩重綺。","相約相期何太深，棹歌搖艇月中尋。","不同珠履三千客，別欲論交一片心。"]', '诗', 'shi', '', NULL, '江上贈竇長史 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b00ef2a-8516-4b42-b1cf-6aaebca65ca0', '贈王漢陽', '贈王漢陽', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["天落白玉棺，王喬辭葉縣。","一去未千年，漢陽復相見。","猶乘飛鳧舃，尚識仙人面。","鬢髮何青青，童顏皎如練。","吾曾弄海水，清淺嗟三變。","果愜麻姑言，時光速流電。","與君數杯酒，可以窮歡宴。","白雲歸去來，何事坐交戰。"]', '["天落白玉棺，王喬辞葉縣。","一去未千年，漢陽复相见。","猶乘飞鳧舃，尚識仙人面。","鬢髮何青青，童顏皎如練。","吾曾弄海水，清淺嗟三变。","果愜麻姑言，时光速流電。","與君數杯酒，可以窮歡宴。","白云归去来，何事坐交戰。"]', '诗', 'shi', '', NULL, '贈王漢陽 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('142b27f0-534b-419c-a9b7-b88e7e5f5a7c', '贈漢陽輔錄事二首 一', '贈漢陽輔錄事二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["聞君罷官意，我抱漢川湄。","借問久疎索，何如聽訟時。","天清江月白，心靜海鷗知。","應念投沙客，空餘弔屈悲。"]', '["闻君罷官意，我抱漢川湄。","借问久疎索，何如听訟时。","天清江月白，心静海鷗知。","應念投沙客，空餘弔屈悲。"]', '诗', 'shi', '', NULL, '贈漢陽輔錄事二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e109d594-3635-43ad-aa8f-36d820bcbd1b', '贈漢陽輔錄事二首 二', '贈漢陽輔錄事二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["鸚鵡洲橫漢陽渡，水引寒煙沒江樹。","南浦登樓不見君，君今罷官在何處？","漢口雙魚白錦鱗，令傳尺素報情人。","其中字數無多少，祗是相思秋復春。"]', '["鸚鵡洲橫漢陽渡，水引寒煙沒江樹。","南浦登楼不见君，君今罷官在何处？","漢口雙鱼白錦鱗，令傳尺素報情人。","其中字數無多少，祗是相思秋复春。"]', '诗', 'shi', '', NULL, '贈漢陽輔錄事二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a16c704-8bd3-4806-81c3-675cc27230f8', '江夏贈韋南陵冰', '江夏贈韋南陵冰', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["胡驕馬驚沙塵起，胡雛飲馬天津水。","君爲張掖近酒泉，我竄三巴九千里。","天地再新法令寬，夜郎遷客帶霜寒。","西憶故人不可見，東風吹夢到長安。","寧期此地忽相遇，驚喜茫如墮煙霧。","玉簫金管喧四筵，苦心不得申長句。","昨日繡衣傾綠尊，病如桃李竟何言。","昔騎天子大宛馬，今乘款段諸侯門。","賴遇南平豁方寸，復兼夫子持清論。","有似山開萬里雲，四望青天解人悶。","人悶還心悶，苦辛長苦辛。","愁來飲酒二千石，寒灰重暖生陽春。","山公醉後能騎馬，別是風流賢主人。","頭陀雲月多僧氣，山水何曾稱人意。","不然鳴笳按鼓戲滄流，呼取江南女兒歌櫂謳。","我且爲君槌碎黃鶴樓，君亦爲吾倒却鵡鸚洲。","赤壁爭雄如夢裏，且須歌舞寬離憂。"]', '["胡驕马驚沙塵起，胡雛饮马天津水。","君爲張掖近酒泉，我竄三巴九千里。","天地再新法令寬，夜郎遷客带霜寒。","西憶故人不可见，东风吹梦到长安。","寧期此地忽相遇，驚喜茫如墮煙霧。","玉簫金管喧四筵，苦心不得申长句。","昨日繡衣傾綠尊，病如桃李竟何言。","昔騎天子大宛马，今乘款段諸侯门。","賴遇南平豁方寸，复兼夫子持清論。","有似山开万里云，四望青天解人悶。","人悶還心悶，苦辛长苦辛。","愁来饮酒二千石，寒灰重暖生陽春。","山公醉後能騎马，別是风流賢主人。","头陀云月多僧氣，山水何曾稱人意。","不然鳴笳按鼓戲滄流，呼取江南女兒歌櫂謳。","我且爲君槌碎黄鹤楼，君亦爲吾倒却鵡鸚洲。","赤壁爭雄如梦裏，且須歌舞寬離憂。"]', '诗', 'shi', '', NULL, '江夏贈韋南陵冰 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f58597e-964d-40be-a11c-7c417d6de32e', '贈盧司戶', '贈盧司戶', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秋色無遠近，出門盡寒山。","白雲遙相識，待我蒼梧間。","借問盧耽鶴，西飛幾歲還。"]', '["秋色無远近，出门尽寒山。","白云遙相識，待我蒼梧间。","借问盧耽鹤，西飞幾歲還。"]', '诗', 'shi', '', NULL, '贈盧司戶 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd64f135-e0f7-4e64-b62b-305d16cfc6e2', '贈從弟南平太守之遙二首 一', '贈從弟南平太守之遙二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["少年不得意，落魄無安居。","願隨任公子，欲釣吞舟魚。","常時飲酒逐風景，壯心遂與功名疎。","蘭生谷底人不鋤，雲在高山空卷舒。","漢家天子馳駟馬，赤軍蜀道迎相如。","天門九重謁聖人，龍顏一解四海春。","彤庭左右呼萬歲，拜賀明主收沈淪。","翰林秉筆回英眄，麟閣崢嶸誰可見。","承恩初入銀臺門，著書獨在金鑾殿。","龍鉤雕鐙白玉鞍，象牀綺席黃金盤。","當時笑我微賤者，却來請謁爲交歡。","一朝謝病遊江海，疇昔相知幾人在。","前門長揖後門關，今日結交明日改。","愛君山岳心不移，隨君雲霧迷所爲。","夢得池塘生春草，使我長價登樓詩。","別後遙傳臨海作，可見羊何共和之。"]', '["少年不得意，落魄無安居。","願隨任公子，欲釣吞舟鱼。","常时饮酒逐风景，壯心遂與功名疎。","蘭生谷底人不鋤，云在高山空卷舒。","漢家天子驰駟马，赤軍蜀道迎相如。","天门九重謁聖人，龙顏一解四海春。","彤庭左右呼万歲，拜賀明主收沈淪。","翰林秉笔回英眄，麟閣崢嶸誰可见。","承恩初入銀台门，著书独在金鑾殿。","龙鉤雕鐙白玉鞍，象牀綺席黄金盤。","當时笑我微賤者，却来請謁爲交歡。","一朝謝病游江海，疇昔相知幾人在。","前门长揖後门关，今日結交明日改。","愛君山岳心不移，隨君云霧迷所爲。","梦得池塘生春草，使我长價登楼诗。","別後遙傳臨海作，可见羊何共和之。"]', '诗', 'shi', '', NULL, '贈從弟南平太守之遙二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9f00848-7c46-467d-888c-e9bebe78167a', '贈從弟南平太守之遙二首 二', '贈從弟南平太守之遙二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["東平與南平，今古兩步兵。","素心愛美酒，不是顧專城。","謫官桃源去，尋花幾處行。","秦人如舊識，出戶笑相迎。"]', '["东平與南平，今古兩步兵。","素心愛美酒，不是顧專城。","謫官桃源去，尋花幾处行。","秦人如旧識，出戶笑相迎。"]', '诗', 'shi', '', NULL, '贈從弟南平太守之遙二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('574102be-b63f-4370-b187-4078e6ce44ba', '贈潘侍御論錢少陽', '贈潘侍御論錢少陽', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["繡衣柱史何昂藏，鐵冠白筆橫秋霜。","三軍論事多引納，堦前虎士羅干將。","雖無二十五老者，且有一翁錢少陽。","眉如松雪齊四皓，調笑可以安儲皇。","君能禮此最下士，九州拭目瞻清光。"]', '["繡衣柱史何昂藏，鐵冠白笔橫秋霜。","三軍論事多引納，堦前虎士羅干將。","雖無二十五老者，且有一翁錢少陽。","眉如松雪齊四皓，調笑可以安儲皇。","君能禮此最下士，九州拭目瞻清光。"]', '诗', 'shi', '', NULL, '贈潘侍御論錢少陽 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b1e6556-5ba1-4be4-84aa-551518f746f5', '贈柳圓', '贈柳圓', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["竹實滿秋浦，鳳來何苦飢。","還同月下鵲，三繞未安枝。","夫子即瓊樹，傾柯拂羽儀。","懷君戀明德，歸去日相思。"]', '["竹實满秋浦，鳳来何苦飢。","還同月下鵲，三繞未安枝。","夫子即瓊樹，傾柯拂羽儀。","懷君戀明德，归去日相思。"]', '诗', 'shi', '', NULL, '贈柳圓 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d35654bd-c4c4-45cd-be19-2d47b0bc092a', '流夜郎半道承恩放還兼欣剋復之美書懷示息秀才', '流夜郎半道承恩放還兼欣剋复之美书懷示息秀才', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["黃口爲人羅，白龍乃魚服。","得罪豈怨天，以愚陷網目。","鯨鯢未翦滅，豺狼屢翻覆。","悲作楚地囚，何日秦庭哭。","遭逢二明主，前後兩遷逐。","去國愁夜郎，投身竄荒谷。","半道雪屯蒙，曠如鳥出籠。","遙欣剋復美，光武安可同。","天子巡劒閣，儲皇守扶風。","揚袂正北辰，開襟攬羣雄。","胡兵出月窟，雷破關之東。","左掃因右拂，旋收洛陽宮。","迴輿入咸京，席卷六合通。","叱咤開帝業，手成天地功。","大駕還長安，兩日忽再中。","一朝讓寶位，劒璽傳無窮。","媿無秋豪力，誰念矍鑠翁。","弋者何所慕，高飛仰冥鴻。","棄劒學丹砂，臨鑪雙玉童。","寄言息夫子，歲晚陟方蓬。"]', '["黄口爲人羅，白龙乃鱼服。","得罪豈怨天，以愚陷網目。","鯨鯢未翦滅，豺狼屢翻覆。","悲作楚地囚，何日秦庭哭。","遭逢二明主，前後兩遷逐。","去国愁夜郎，投身竄荒谷。","半道雪屯蒙，曠如鸟出籠。","遙欣剋复美，光武安可同。","天子巡劒閣，儲皇守扶风。","揚袂正北辰，开襟攬羣雄。","胡兵出月窟，雷破关之东。","左掃因右拂，旋收洛陽宮。","迴輿入咸京，席卷六合通。","叱咤开帝業，手成天地功。","大駕還长安，兩日忽再中。","一朝讓寶位，劒璽傳無窮。","媿無秋豪力，誰念矍鑠翁。","弋者何所慕，高飞仰冥鴻。","棄劒学丹砂，臨鑪雙玉童。","寄言息夫子，歲晚陟方蓬。"]', '诗', 'shi', '', NULL, '流夜郎半道承恩放還兼欣剋復之美書懷示息秀才 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdd6a23e-199e-41ab-8924-869aa168ad8f', '贈張相鎬二首 一', '贈張相鎬二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["神器難竊弄，天狼窺紫宸。","六龍遷白日，四海暗胡塵。","昊穹降元宰，君子方經綸。","澹然養浩氣，歘起持大鈞。","秀骨象山嶽，英謀合鬼神。","佐漢解鴻門，生唐爲後身。","擁旄秉金鉞，伐鼓乘朱輪。","虎將如雷霆，總戎向東巡。","諸侯拜馬首，猛士騎鯨鱗。","澤被魚鳥悅，令行草木春。","聖智不失時，建功及良辰。","醜虜安足紀，可貽幗與巾。","倒瀉溟海珠，盡爲入幕珍。","馮異獻赤伏，鄧生倏來臻。","庶同昆陽舉，再覩漢儀新。","昔爲管將鮑，中奔吳隔秦。","一生欲報主，百代思榮親。","其事竟不就，哀哉難重陳。","臥病宿松山，蒼茫空四鄰。","風雲激壯志，枯槁驚常倫。","聞君自天來，目張氣益振。","亞夫得劇孟，敵國空無人。","捫蝨對桓公，願得論悲辛。","大塊方噫氣，何辭鼓青蘋。","斯言儻不合，歸老漢江濱。"]', '["神器难竊弄，天狼窺紫宸。","六龙遷白日，四海暗胡塵。","昊穹降元宰，君子方經綸。","澹然養浩氣，歘起持大鈞。","秀骨象山嶽，英謀合鬼神。","佐漢解鴻门，生唐爲後身。","擁旄秉金鉞，伐鼓乘朱輪。","虎將如雷霆，總戎向东巡。","諸侯拜马首，猛士騎鯨鱗。","澤被鱼鸟悅，令行草木春。","聖智不失时，建功及良辰。","醜虜安足紀，可貽幗與巾。","倒瀉溟海珠，尽爲入幕珍。","馮異獻赤伏，鄧生倏来臻。","庶同昆陽舉，再覩漢儀新。","昔爲管將鲍，中奔吳隔秦。","一生欲報主，百代思榮親。","其事竟不就，哀哉难重陳。","臥病宿松山，蒼茫空四鄰。","风云激壯志，枯槁驚常倫。","闻君自天来，目張氣益振。","亞夫得劇孟，敵国空無人。","捫蝨对桓公，願得論悲辛。","大塊方噫氣，何辞鼓青蘋。","斯言儻不合，归老漢江濱。"]', '诗', 'shi', '', NULL, '贈張相鎬二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb308ac7-facf-4d88-9f84-de866c9f62f6', '贈張相鎬二首 二', '贈張相鎬二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["本家隴西人，先爲漢邊將。","功略葢天地，名飛青雲上。","苦戰竟不侯，富年頗惆悵。","世傳崆峒勇，氣激金風壯。","英烈遺厥孫，百代神猶王。","十五觀奇書，作賦凌相如。","龍顏惠殊寵，麟閣憑天居。","晚途未云已，蹭蹬遭讒毀。","想像晉末時，崩騰胡塵起。","衣冠陷鋒鏑，戎虜盈朝市。","石勒窺神州，劉聰劫天子。","撫劒夜吟嘯，雄心日千里。","誓欲斬鯨鯢，澄清洛陽水。","六合灑霖雨，萬物無彫枯。","我揮一杯水，自笑何區區。","因人恥成事，貴欲決良圖。","滅虜不言功，飄然陟蓬壺。","惟有安期舃，留之滄海隅。"]', '["本家隴西人，先爲漢邊將。","功略葢天地，名飞青云上。","苦戰竟不侯，富年頗惆悵。","世傳崆峒勇，氣激金风壯。","英烈遺厥孫，百代神猶王。","十五观奇书，作賦凌相如。","龙顏惠殊寵，麟閣憑天居。","晚途未云已，蹭蹬遭讒毀。","想像晉末时，崩腾胡塵起。","衣冠陷鋒鏑，戎虜盈朝市。","石勒窺神州，劉聰劫天子。","撫劒夜吟嘯，雄心日千里。","誓欲斬鯨鯢，澄清洛陽水。","六合灑霖雨，万物無彫枯。","我揮一杯水，自笑何區區。","因人恥成事，貴欲決良圖。","滅虜不言功，飄然陟蓬壺。","惟有安期舃，留之滄海隅。"]', '诗', 'shi', '', NULL, '贈張相鎬二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2661ebda-b1c5-452d-9d09-b59ed3b45d16', '聞謝楊兒吟猛虎詞因此有贈', '闻謝楊兒吟猛虎词因此有贈', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["同州隔秋浦，聞吟猛虎詞。","晨朝來借問，知是謝楊兒。"]', '["同州隔秋浦，闻吟猛虎词。","晨朝来借问，知是謝楊兒。"]', '诗', 'shi', '', NULL, '聞謝楊兒吟猛虎詞因此有贈 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ded0e0f-8e24-4119-8536-896fb91f4fd4', '宿清溪主人', '宿清溪主人', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["夜到清溪宿，主人碧巖裏。","簷楹挂星斗，枕席響風水。","月落西山時，啾啾夜猨起。"]', '["夜到清溪宿，主人碧巖裏。","簷楹挂星斗，枕席响风水。","月落西山时，啾啾夜猨起。"]', '诗', 'shi', '', NULL, '宿清溪主人 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3c2d519-801e-4419-892f-b7affa1e7762', '繫尋陽上崔相渙三首 一', '繫尋陽上崔相渙三首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["邯鄲四十萬，同日陷長平。","能迴造化筆，或冀一人生。"]', '["邯鄲四十万，同日陷长平。","能迴造化笔，或冀一人生。"]', '诗', 'shi', '', NULL, '繫尋陽上崔相渙三首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db9952a3-612e-4fb3-ae54-79cc011cb1db', '繫尋陽上崔相渙三首 二', '繫尋陽上崔相渙三首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["毛遂不墮井，曾參寧殺人。","虛言誤公子，投杼惑慈親。","白璧雙明月，方知一玉真。"]', '["毛遂不墮井，曾參寧殺人。","虛言誤公子，投杼惑慈親。","白璧雙明月，方知一玉真。"]', '诗', 'shi', '', NULL, '繫尋陽上崔相渙三首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2f40d4f-0c75-4fb4-b325-3e508749facf', '繫尋陽上崔相渙三首 三', '繫尋陽上崔相渙三首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["虛傳一片雨，枉作陽臺神。","縱爲夢裏相隨去，不是襄王傾國人。"]', '["虛傳一片雨，枉作陽台神。","縱爲梦裏相隨去，不是襄王傾国人。"]', '诗', 'shi', '', NULL, '繫尋陽上崔相渙三首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f4a8832-1953-41cf-b202-a15e5faa5f48', '巴陵贈賈舍人', '巴陵贈賈舍人', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["賈生西望憶京華，湘浦南遷莫怨嗟。","聖主恩深漢文帝，憐君不遣到長沙。"]', '["賈生西望憶京华，湘浦南遷莫怨嗟。","聖主恩深漢文帝，怜君不遣到长沙。"]', '诗', 'shi', '', NULL, '巴陵贈賈舍人 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79d04ecd-ef45-4094-a8a4-c3d9fffdebd0', '贈別舍人弟臺卿之江南', '贈別舍人弟台卿之江南', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["去國客行遠，還山秋夢長。","梧桐落金井，一葉飛銀牀。","覺罷攬明鏡，鬢毛颯已霜。","良圖委蔓草，古貌成枯桑。","欲道心下事，時人疑夜光。","因爲洞庭葉，飄落之瀟湘。","令弟經濟士，謫居我何傷。","潛虬隱尺水，著論談興亡。","客遇王子喬，口傳不死方。","入洞過天地，登真朝玉皇。","吾將撫爾背，揮手遂翱翔。"]', '["去国客行远，還山秋梦长。","梧桐落金井，一葉飞銀牀。","覺罷攬明镜，鬢毛颯已霜。","良圖委蔓草，古貌成枯桑。","欲道心下事，时人疑夜光。","因爲洞庭葉，飄落之瀟湘。","令弟經濟士，謫居我何傷。","潛虬隐尺水，著論談兴亡。","客遇王子喬，口傳不死方。","入洞過天地，登真朝玉皇。","吾將撫爾背，揮手遂翱翔。"]', '诗', 'shi', '', NULL, '贈別舍人弟臺卿之江南 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e458c7a9-9749-4e9e-8ec0-c07ab91f5d9d', '醉後贈王歷陽', '醉後贈王歷陽', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["書禿千兔毫，詩裁兩牛腰。","筆蹤起龍虎，舞袖拂雲霄。","雙歌二胡姬，更奏遠清朝。","舉酒挑朔雪，從君不相饒。"]', '["书禿千兔毫，诗裁兩牛腰。","笔蹤起龙虎，舞袖拂云霄。","雙歌二胡姬，更奏远清朝。","舉酒挑朔雪，從君不相饒。"]', '诗', 'shi', '', NULL, '醉後贈王歷陽 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('626d358d-52d3-4619-88cc-3b9772b90faf', '贈歷陽褚司馬', '贈歷陽褚司马', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["北堂千萬壽，侍奉有光輝。","先同稚子舞，更著老萊衣。","因爲小兒啼，醉倒月下歸。","人聞無此樂，此樂世中稀。"]', '["北堂千万壽，侍奉有光輝。","先同稚子舞，更著老萊衣。","因爲小兒啼，醉倒月下归。","人闻無此乐，此乐世中稀。"]', '诗', 'shi', '', NULL, '贈歷陽褚司馬 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e14e0303-5597-492f-8b24-7a968803e809', '對雪醉後贈王歷陽', '对雪醉後贈王歷陽', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["有身莫犯飛龍鱗，有手莫辮猛虎鬚。","君看昔日汝南市，白頭仙人隱玉壺。","子猷聞風動窻竹，相邀共醉杯中綠。","歷陽何異山陰時，白雪飛花亂人目。","君家有酒我何愁，客多樂酣秉燭遊。","謝尚自能鸜鵒舞，相如免脫鷫鸘裘。","清晨鼓櫂過江去，千里相思明月樓。"]', '["有身莫犯飞龙鱗，有手莫辮猛虎鬚。","君看昔日汝南市，白头仙人隐玉壺。","子猷闻风动窻竹，相邀共醉杯中綠。","歷陽何異山陰时，白雪飞花亂人目。","君家有酒我何愁，客多乐酣秉燭游。","謝尚自能鸜鵒舞，相如免脫鷫鸘裘。","清晨鼓櫂過江去，千里相思明月楼。"]', '诗', 'shi', '', NULL, '對雪醉後贈王歷陽 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebd3c20e-ff69-47f8-8847-c3d7b2b0a091', '贈宣城宇文太守兼呈崔侍御', '贈宣城宇文太守兼呈崔侍御', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白若白鷺鮮，清如清唳蟬。","受氣有本性，不爲外物遷。","飲水箕山上，食雪首陽顛。","迴車避朝歌，掩口去盜泉。","岧嶢廣成子，倜儻魯仲連。","卓絕二公外，丹心無間然。","昔攀六龍飛，今作百鍊鉛。","懷恩欲報主，投佩向北燕。","彎弓綠弦開，滿月不憚堅。","閑騎駿馬獵，一射兩虎穿。","回旋若流光，轉背落雙鳶。","胡虜三嘆息，兼知五兵權。","鎗鎗突雲將，却掩我之妍。","多逢剿絕兒，先著祖生鞭。","據鞍空矍鑠，壯志竟誰宣。","蹉跎復來歸，憂恨坐相煎。","無風難破浪，失計長江邊。","危苦惜頹光，金波忽三圓。","時遊敬亭上，閑聽松風眠。","或弄宛溪月，虛舟信洄沿。","顏公二十萬，盡付酒家錢。","興發每取之，聊向醉中仙。","過此無一事，靜談秋水篇。","君從九卿來，水國有豐年。","魚鹽滿市井，布帛如雲煙。","下馬不作威，冰壺照清川。","霜眉邑中叟，皆美太守賢。","時時慰風俗，往往出東田。","竹馬數小兒，拜迎白鹿前。","含笑問使君，日晚可迴旋。","遂歸池上酌，掩抑清風絃。","曾標橫浮雲，下撫謝朓肩。","樓高碧海出，樹古青蘿懸。","光祿紫霞杯，伊昔忝相傳。","良圖掃沙漠，別夢繞旌旃。","富貴日成疎，願言杳無緣。","登龍有直道，倚玉阻芳筵。","敢獻繞朝策，思同郭泰船。","何言一水淺，似隔九重天。","崔生何傲岸，縱酒復談玄。","身爲名公子，英才苦迍邅。","鳴鳳託高梧，凌風何翩翩。","安知慕羣客，彈劒拂秋蓮。"]', '["白若白鷺鲜，清如清唳蟬。","受氣有本性，不爲外物遷。","饮水箕山上，食雪首陽顛。","迴车避朝歌，掩口去盜泉。","岧嶢廣成子，倜儻魯仲連。","卓絕二公外，丹心無间然。","昔攀六龙飞，今作百鍊鉛。","懷恩欲報主，投佩向北燕。","彎弓綠弦开，满月不憚堅。","闲騎駿马獵，一射兩虎穿。","回旋若流光，轉背落雙鳶。","胡虜三嘆息，兼知五兵權。","鎗鎗突云將，却掩我之妍。","多逢剿絕兒，先著祖生鞭。","據鞍空矍鑠，壯志竟誰宣。","蹉跎复来归，憂恨坐相煎。","無风难破浪，失計长江邊。","危苦惜頹光，金波忽三圓。","时游敬亭上，闲听松风眠。","或弄宛溪月，虛舟信洄沿。","顏公二十万，尽付酒家錢。","兴發每取之，聊向醉中仙。","過此無一事，静談秋水篇。","君從九卿来，水国有豐年。","鱼鹽满市井，布帛如云煙。","下马不作威，冰壺照清川。","霜眉邑中叟，皆美太守賢。","时时慰风俗，往往出东田。","竹马數小兒，拜迎白鹿前。","含笑问使君，日晚可迴旋。","遂归池上酌，掩抑清风絃。","曾標橫浮云，下撫謝朓肩。","楼高碧海出，樹古青蘿懸。","光祿紫霞杯，伊昔忝相傳。","良圖掃沙漠，別梦繞旌旃。","富貴日成疎，願言杳無緣。","登龙有直道，倚玉阻芳筵。","敢獻繞朝策，思同郭泰船。","何言一水淺，似隔九重天。","崔生何傲岸，縱酒复談玄。","身爲名公子，英才苦迍邅。","鳴鳳託高梧，凌风何翩翩。","安知慕羣客，彈劒拂秋蓮。"]', '诗', 'shi', '', NULL, '贈宣城宇文太守兼呈崔侍御 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4a74d37-6238-4149-a99f-6dfd4871c97f', '贈宣城趙太守悅', '贈宣城趙太守悅', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["趙得寶符盛，山河功業存。","三千堂上客，出入擁平原。","六國揚清風，英聲何喧喧。","大賢茂遠業，虎竹光南藩。","錯落千丈松，虬龍盤古根。","枝下無俗草，所植唯蘭蓀。","憶在南陽時，始承國士恩。","公爲柱下史，脫繡歸田園。","伊昔簪白筆，幽都逐遊魂。","持斧冠三軍，霜清天北門。","差池宰兩邑，鶚立重飛翻。","焚香入蘭臺，起草多芳言。","夔龍一顧重，矯翼凌翔鵷。","赤縣揚雷聲，彊項聞至尊。","驚飆頹秀木，跡屈道彌敦。","出牧歷三郡，所居猛獸奔。","遷人同衛鶴，謬上懿公軒。","自笑東郭履，側慙狐白溫。","閑吟步竹石，精義忘朝昏。","顦顇成醜士，風雲何足論。","獮猴騎土牛，羸馬夾雙轅。","願借羲皇景，爲人照覆盆。","溟海不振蕩，何由縱鵬鯤。","所期玄津白，倜儻假騰騫。"]', '["趙得寶符盛，山河功業存。","三千堂上客，出入擁平原。","六国揚清风，英声何喧喧。","大賢茂远業，虎竹光南藩。","錯落千丈松，虬龙盤古根。","枝下無俗草，所植唯蘭蓀。","憶在南陽时，始承国士恩。","公爲柱下史，脫繡归田园。","伊昔簪白笔，幽都逐游魂。","持斧冠三軍，霜清天北门。","差池宰兩邑，鶚立重飞翻。","焚香入蘭台，起草多芳言。","夔龙一顧重，矯翼凌翔鵷。","赤縣揚雷声，彊項闻至尊。","驚飆頹秀木，跡屈道彌敦。","出牧歷三郡，所居猛獸奔。","遷人同衛鹤，謬上懿公軒。","自笑东郭履，側慙狐白溫。","闲吟步竹石，精義忘朝昏。","顦顇成醜士，风云何足論。","獮猴騎土牛，羸马夾雙轅。","願借羲皇景，爲人照覆盆。","溟海不振蕩，何由縱鵬鯤。","所期玄津白，倜儻假腾騫。"]', '诗', 'shi', '', NULL, '贈宣城趙太守悅 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cac4f75-c3a3-4760-a886-52bacdc596f8', '贈從弟宣州長史昭', '贈從弟宣州长史昭', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["淮南望江南，千里碧山對。","我行倦過之，半落青天外。","宗英佐雄郡，水陸相控帶。","長川豁中流，千里瀉吳會。","君心亦如此，包納無小大。","搖筆起風霜，推誠結仁愛。","訟庭垂桃李，賓館羅軒蓋。","何意蒼梧雲，飄然忽相會。","才將聖不偶，命與時俱背。","獨立山海間，空老聖明代。","知音不易得，撫劒增感慨。","當結九萬期，中途莫先退。"]', '["淮南望江南，千里碧山对。","我行倦過之，半落青天外。","宗英佐雄郡，水陸相控带。","长川豁中流，千里瀉吳會。","君心亦如此，包納無小大。","搖笔起风霜，推誠結仁愛。","訟庭垂桃李，賓館羅軒蓋。","何意蒼梧云，飄然忽相會。","才將聖不偶，命與时俱背。","独立山海间，空老聖明代。","知音不易得，撫劒增感慨。","當結九万期，中途莫先退。"]', '诗', 'shi', '', NULL, '贈從弟宣州長史昭 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78e45e06-868d-49e0-a5e6-62fc878a50c4', '於五松山贈南陵常贊府', '於五松山贈南陵常贊府', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["爲草當作蘭，爲木當作松。","蘭秋香風遠，松寒不改容。","松蘭相因依，蕭艾徒丰茸。","雞與雞幷食，鸞與鸞同枝。","揀珠去沙礫，但有珠相隨。","遠客投名賢，真堪寫懷抱。","若惜方寸心，待誰可傾倒。","虞卿棄趙相，便與魏齊行。","海上五百人，同日死田橫。","當時不好賢，豈傳千古名。","願君同心人，於我少留情。","寂寂還寂寂，出門迷所適。","長鋏歸來乎，秋風思歸客。"]', '["爲草當作蘭，爲木當作松。","蘭秋香风远，松寒不改容。","松蘭相因依，蕭艾徒丰茸。","雞與雞幷食，鸾與鸾同枝。","揀珠去沙礫，但有珠相隨。","远客投名賢，真堪寫懷抱。","若惜方寸心，待誰可傾倒。","虞卿棄趙相，便與魏齊行。","海上五百人，同日死田橫。","當时不好賢，豈傳千古名。","願君同心人，於我少留情。","寂寂還寂寂，出门迷所適。","长鋏归来乎，秋风思归客。"]', '诗', 'shi', '', NULL, '於五松山贈南陵常贊府 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b6b24f6-4341-40c5-9ee3-b51d9b4341ab', '自梁園至敬亭山見會公談陵陽山水兼期同遊因有此贈', '自梁园至敬亭山见會公談陵陽山水兼期同游因有此贈', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我隨秋風來，瑤草恐衰歇。","中途寡名山，安得弄雲月。","渡江如昨日，黃葉向人飛。","敬亭愜素尚，弭櫂流清輝。","冰谷明且秀，陵巒抱江城。","粲粲吳與史，衣冠耀天京。","水國饒英奇，潛光臥幽草。","會公真名僧，所在即爲寶。","開堂振白拂，高論橫青雲。","雪山掃粉壁，墨客多新文。","爲余話幽棲，且述陵陽美。","天開白龍潭，月映清秋水。","黃山望石柱，突兀誰開張。","黃鶴久不來，子安在蒼茫。","東南焉可窮，山鳥飛絕處。","稠疊千萬峰，相連入雲去。","聞此期振策，歸來空閉關。","相思如明月，可望不可攀。","何當移白足，早晚凌蒼山。","且寄一書札，令予解愁顏。"]', '["我隨秋风来，瑤草恐衰歇。","中途寡名山，安得弄云月。","渡江如昨日，黄葉向人飞。","敬亭愜素尚，弭櫂流清輝。","冰谷明且秀，陵巒抱江城。","粲粲吳與史，衣冠耀天京。","水国饒英奇，潛光臥幽草。","會公真名僧，所在即爲寶。","开堂振白拂，高論橫青云。","雪山掃粉壁，墨客多新文。","爲余話幽棲，且述陵陽美。","天开白龙潭，月映清秋水。","黄山望石柱，突兀誰开張。","黄鹤久不来，子安在蒼茫。","东南焉可窮，山鸟飞絕处。","稠叠千万峰，相連入云去。","闻此期振策，归来空閉关。","相思如明月，可望不可攀。","何當移白足，早晚凌蒼山。","且寄一书札，令予解愁顏。"]', '诗', 'shi', '', NULL, '自梁園至敬亭山見會公談陵陽山水兼期同遊因有此贈 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c3c2f6b-ad7b-4fc1-a9d7-ced3af99f6e9', '贈友人三首 一', '贈友人三首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["蘭生不當戶，別是閑庭草。","夙被霜露欺，紅榮已先老。","謬接瑤華枝，結根君王池。","顧無馨香美，叨沐清風吹。","餘芳若可佩，卒歲長相隨。"]', '["蘭生不當戶，別是闲庭草。","夙被霜露欺，紅榮已先老。","謬接瑤华枝，結根君王池。","顧無馨香美，叨沐清风吹。","餘芳若可佩，卒歲长相隨。"]', '诗', 'shi', '', NULL, '贈友人三首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('786d292a-3b4f-4780-ab21-34e00f6ed18c', '贈友人三首 二', '贈友人三首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["袖中趙匕首，買自徐夫人。","玉匣閉霜雪，經燕復歷秦。","其事竟不捷，淪落歸沙塵。","持此願投贈，與君同急難。","荆卿一去後，壯士多摧殘。","長號易水上，爲我揚波瀾。","鑿井當及泉，張帆當濟川。","廉夫唯重義，駿馬不勞鞭。","人生貴相知，何必金與錢。"]', '["袖中趙匕首，買自徐夫人。","玉匣閉霜雪，經燕复歷秦。","其事竟不捷，淪落归沙塵。","持此願投贈，與君同急难。","荆卿一去後，壯士多摧殘。","长號易水上，爲我揚波瀾。","鑿井當及泉，張帆當濟川。","廉夫唯重義，駿马不勞鞭。","人生貴相知，何必金與錢。"]', '诗', 'shi', '', NULL, '贈友人三首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eedb33b4-fdcb-41a5-8d7d-96c3d44b5929', '贈友人三首 三', '贈友人三首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["慢世薄功業，非無胷中畫。","謔浪萬古賢，以爲兒童劇。","立產如廣費，匡君懷長策。","但苦山北寒，誰知道南宅。","歲酒上逐風，霜鬢兩邊白。","蜀主思孔明，晉家望安石。","時人列五鼎，談笑期一擲。","虎伏被胡塵，漁歌遊海濱。","弊裘恥妻嫂，長劒託交親。","夫子秉家義，羣公難與隣。","莫持西江水，空許東溟臣。","他日青雲去，黃金報主人。"]', '["慢世薄功業，非無胷中畫。","謔浪万古賢，以爲兒童劇。","立產如廣費，匡君懷长策。","但苦山北寒，誰知道南宅。","歲酒上逐风，霜鬢兩邊白。","蜀主思孔明，晉家望安石。","时人列五鼎，談笑期一擲。","虎伏被胡塵，漁歌游海濱。","弊裘恥妻嫂，长劒託交親。","夫子秉家義，羣公难與隣。","莫持西江水，空許东溟臣。","他日青云去，黄金報主人。"]', '诗', 'shi', '', NULL, '贈友人三首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f7ff344-d530-4d17-8545-64e7e11ae25e', '陳情贈友人', '陳情贈友人', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["延陵有寶劒，價重千黃金。","觀風歷上國，暗許故人深。","歸來挂墳松，萬古知其心。","懦夫感達節，壯士激青衿。","鮑生薦夷吾，一舉置齊相。","斯人無良朋，豈有青雲望。","臨財不苟取，推分固詞讓。","後世稱其賢，英風邈難尚。","論交但若此，友道孰云喪。","多君騁逸藻，掩映當時人。","舒文振頹波，秉德冠彝倫。","卜居乃此地，共井爲比隣。","清琴弄雲月，美酒娛冬春。","薄德中見捐，忽之如遺塵。","英豪未豹變，自古多艱辛。","他人縱以疎，君意宜獨親。","奈何成離居，相去復幾許。","飄風吹雲霓，蔽目不得語。","投珠冀相報，按劒恐相距。","所思採芳蘭，欲贈隔荆渚。","沈憂心若醉，積恨淚如雨。","願假東壁輝，餘光照貧女。"]', '["延陵有寶劒，價重千黄金。","观风歷上国，暗許故人深。","归来挂墳松，万古知其心。","懦夫感達節，壯士激青衿。","鲍生薦夷吾，一舉置齊相。","斯人無良朋，豈有青云望。","臨財不苟取，推分固词讓。","後世稱其賢，英风邈难尚。","論交但若此，友道孰云喪。","多君騁逸藻，掩映當时人。","舒文振頹波，秉德冠彝倫。","卜居乃此地，共井爲比隣。","清琴弄云月，美酒娛冬春。","薄德中见捐，忽之如遺塵。","英豪未豹变，自古多艱辛。","他人縱以疎，君意宜独親。","奈何成離居，相去复幾許。","飄风吹云霓，蔽目不得語。","投珠冀相報，按劒恐相距。","所思採芳蘭，欲贈隔荆渚。","沈憂心若醉，積恨泪如雨。","願假东壁輝，餘光照貧女。"]', '诗', 'shi', '', NULL, '陳情贈友人 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a1cef11-7bd7-4e86-90db-d5622b12557c', '贈從弟冽', '贈從弟冽', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["楚人不識鳳，重價求山雞。","獻主昔云是，今來方覺迷。","自居漆園北，久別咸陽西。","風飄落日去，節變流鶯啼。","桃李寒未開，幽關豈來蹊。","逢君發花萼，若與青雲齊。","及此桑葉綠，春蠶起中閨。","日出布穀鳴，田家擁鋤犂。","顧余乏尺土，東作誰相攜。","傅說降霖雨，公輸造雲梯。","羌戎事未息，君子悲塗泥。","報國有長策，成功羞執珪。","無由謁明主，杖策還蓬藜。","他年爾相訪，知我在磻溪。"]', '["楚人不識鳳，重價求山雞。","獻主昔云是，今来方覺迷。","自居漆园北，久別咸陽西。","风飄落日去，節变流鶯啼。","桃李寒未开，幽关豈来蹊。","逢君發花萼，若與青云齊。","及此桑葉綠，春蠶起中閨。","日出布穀鳴，田家擁鋤犂。","顧余乏尺土，东作誰相携。","傅说降霖雨，公輸造云梯。","羌戎事未息，君子悲塗泥。","報国有长策，成功羞執珪。","無由謁明主，杖策還蓬藜。","他年爾相訪，知我在磻溪。"]', '诗', 'shi', '', NULL, '贈從弟冽 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34ea27c9-4378-4a90-a528-3bfd1f31940c', '贈閭丘處士', '贈閭丘处士', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["賢人有素業，乃在沙塘陂。","竹影掃秋月，荷衣落古池。","閑讀山海經，散帙臥遙帷。","且耽田家樂，遂曠林中期。","野酌勸芳酒，園蔬烹露葵。","如能樹桃李，爲我結茅茨。"]', '["賢人有素業，乃在沙塘陂。","竹影掃秋月，荷衣落古池。","闲读山海經，散帙臥遙帷。","且耽田家乐，遂曠林中期。","野酌勸芳酒，园蔬烹露葵。","如能樹桃李，爲我結茅茨。"]', '诗', 'shi', '', NULL, '贈閭丘處士 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25f3ac1b-d579-4704-80d2-1d48a1865ce7', '贈錢徵君少陽', '贈錢徵君少陽', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白玉一杯酒，綠楊三月時。","春風餘幾日，兩鬢各成絲。","秉燭唯須飲，投竿也未遲。","如逢渭川獵，猶可帝王師。"]', '["白玉一杯酒，綠楊三月时。","春风餘幾日，兩鬢各成絲。","秉燭唯須饮，投竿也未遲。","如逢渭川獵，猶可帝王師。"]', '诗', 'shi', '', NULL, '贈錢徵君少陽 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('725af0dd-9a6e-4534-9afd-b7c35eaa54e0', '贈宣州靈源寺仲濬公', '贈宣州靈源寺仲濬公', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["敬亭白雲氣，秀色連蒼梧。","下映雙溪水，如天落鏡湖。","此中積龍象，獨許濬公殊。","風韻逸江左，文章動海隅。","觀心同水月，解領得明珠。","今日逢支遁，高談出有無。"]', '["敬亭白云氣，秀色連蒼梧。","下映雙溪水，如天落镜湖。","此中積龙象，独許濬公殊。","风韻逸江左，文章动海隅。","观心同水月，解領得明珠。","今日逢支遁，高談出有無。"]', '诗', 'shi', '', NULL, '贈宣州靈源寺仲濬公 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0c0fff7-0adb-4b54-b0af-ac71f5c0036e', '贈僧朝美', '贈僧朝美', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["水客凌洪波，長鯨湧溟海。","百川隨龍舟，噓吸竟安在。","中有不死者，探得明月珠。","高價傾宇宙，餘輝照江湖。","苞卷金縷褐，蕭然若空無。","誰人識此寶，竊笑有狂夫。","了心何言說，各勉黃金軀。"]', '["水客凌洪波，长鯨湧溟海。","百川隨龙舟，噓吸竟安在。","中有不死者，探得明月珠。","高價傾宇宙，餘輝照江湖。","苞卷金縷褐，蕭然若空無。","誰人識此寶，竊笑有狂夫。","了心何言说，各勉黄金軀。"]', '诗', 'shi', '', NULL, '贈僧朝美 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c26c1c1-738a-4b40-92ca-47f918bbbccd', '贈僧行融', '贈僧行融', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["梁有湯惠休，常從鮑照遊。","峨眉史懷一，獨映陳公出。","卓絕二道人，結交鳳與麟。","行融亦俊發，吾知有英骨。","海若不隱珠，驪龍吐明月。","大海乘虛舟，隨波任安流。","賦詩旃檀閣，縱酒鸚鵡洲。","待我適東越，相攜上白樓。"]', '["梁有湯惠休，常從鲍照游。","峨眉史懷一，独映陳公出。","卓絕二道人，結交鳳與麟。","行融亦俊發，吾知有英骨。","海若不隐珠，驪龙吐明月。","大海乘虛舟，隨波任安流。","賦诗旃檀閣，縱酒鸚鵡洲。","待我適东越，相携上白楼。"]', '诗', 'shi', '', NULL, '贈僧行融 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3284a2cb-0844-4ff8-b3ca-976dd1ba5d23', '贈黃山胡公求白鷴', '贈黄山胡公求白鷴', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["請以雙白璧，買君雙白鷴。","白鷴白如錦，白雪恥容顏。","照影玉潭裏，刷毛琪樹間。","夜棲寒月靜，朝步落花閑。","我願得此鳥，翫之坐碧山。","胡公能輟贈，籠寄野人還。"]', '["請以雙白璧，買君雙白鷴。","白鷴白如錦，白雪恥容顏。","照影玉潭裏，刷毛琪樹间。","夜棲寒月静，朝步落花闲。","我願得此鸟，翫之坐碧山。","胡公能輟贈，籠寄野人還。"]', '诗', 'shi', '', NULL, '贈黃山胡公求白鷴 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39e352e5-3e19-4fab-8dff-adf9dea2b380', '登敬亭山南望懷古贈竇主簿', '登敬亭山南望懷古贈竇主簿', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["敬亭一迴首，目盡天南端。","仙者五六人，常聞此遊盤。","谿流琴高水，石聳麻姑壇。","白龍降陵陽，黃鶴呼子安。","羽化騎日月，雲行翼鴛鸞。","下視宇宙間，四溟皆波瀾。","汰絕目下事，從之復何難。","百歲落半途，前期浩漫漫。","彊食不成味，清晨起長嘆。","願隨子明去，鍊火燒金丹。"]', '["敬亭一迴首，目尽天南端。","仙者五六人，常闻此游盤。","谿流琴高水，石聳麻姑壇。","白龙降陵陽，黄鹤呼子安。","羽化騎日月，云行翼鴛鸾。","下視宇宙间，四溟皆波瀾。","汰絕目下事，從之复何难。","百歲落半途，前期浩漫漫。","彊食不成味，清晨起长嘆。","願隨子明去，鍊火燒金丹。"]', '诗', 'shi', '', NULL, '登敬亭山南望懷古贈竇主簿 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9358ac19-de26-49ad-a115-d23d60474627', '經亂後將避地剡中留贈崔宣城', '經亂後將避地剡中留贈崔宣城', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["雙鵝飛洛陽，五馬渡江徼。","何意上東門，胡雛更長嘯。","中原走豺虎，烈火焚宗廟。","太白晝經天，頹陽掩餘照。","王城皆蕩覆，世路成奔峭。","四海望長安，嚬眉寡西笑。","蒼生疑落葉，白骨空相弔。","連兵似雪山，破敵誰能料。","我垂北溟翼，且學南山豹。","崔子賢主人，歡娛每相召。","胡牀紫玉笛，却坐青雲呌。","楊花滿州城，置酒同臨眺。","忽思剡溪去，水石遠清妙。","雪盡天地明，風開湖山貌。","悶爲洛生詠，醉發吳越調。","赤霞動金光，日足森海嶠。","獨散萬古意，閑垂一溪釣。","猨近天上啼，人移月邊櫂。","無以墨綬苦，來求丹砂要。","華髮長折腰，將貽陶公誚。"]', '["雙鵝飞洛陽，五马渡江徼。","何意上东门，胡雛更长嘯。","中原走豺虎，烈火焚宗廟。","太白晝經天，頹陽掩餘照。","王城皆蕩覆，世路成奔峭。","四海望长安，嚬眉寡西笑。","蒼生疑落葉，白骨空相弔。","連兵似雪山，破敵誰能料。","我垂北溟翼，且学南山豹。","崔子賢主人，歡娛每相召。","胡牀紫玉笛，却坐青云呌。","楊花满州城，置酒同臨眺。","忽思剡溪去，水石远清妙。","雪尽天地明，风开湖山貌。","悶爲洛生詠，醉發吳越調。","赤霞动金光，日足森海嶠。","独散万古意，闲垂一溪釣。","猨近天上啼，人移月邊櫂。","無以墨綬苦，来求丹砂要。","华髮长折腰，將貽陶公誚。"]', '诗', 'shi', '', NULL, '經亂後將避地剡中留贈崔宣城 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff0a0705-6342-41a1-880d-13a5e69e8c29', '獻從叔當塗宰陽冰', '獻從叔當塗宰陽冰', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["金鏡霾六國，亡新亂天經。","焉知高光起，自有羽翼生。","蕭曹安𡸣屼，耿賈摧欃槍。","吾家有季父，傑出聖代英。","雖無三台位，不借四豪名。","激昂風雲氣，終協龍虎精。","弱冠燕趙來，賢彥多逢迎。","魯連善談笑，季布折公卿。","遙知禮數絕，常恐不合幷。","惕想結宵夢，素心久已冥。","顧慙青雲器，謬奉玉樽傾。","山陽五百年，綠竹忽再榮。","高歌振林木，大笑喧雷霆。","落筆灑篆文，崩雲使人驚。","吐辭又炳煥，五色羅華星。","秀句滿江國，高才掞天庭。","宰邑艱難時，浮雲空古城。","居人若薙草，掃地無纖莖。","惠澤及飛走，農夫盡歸耕。","廣漢水萬里，長流玉琴聲。","雅頌播吳越，還如泰階平。","小子別金陵，來時白下亭。","羣鳳憐客鳥，差池相哀鳴。","各拔五色毛，意重泰山輕。","贈微所費廣，斗水澆長鯨。","彈劒歌苦寒，嚴風起前楹。","月銜天門曉，霜落牛渚清。","長歎即歸路，臨川空屏營。"]', '["金镜霾六国，亡新亂天經。","焉知高光起，自有羽翼生。","蕭曹安𡸣屼，耿賈摧欃槍。","吾家有季父，傑出聖代英。","雖無三台位，不借四豪名。","激昂风云氣，終協龙虎精。","弱冠燕趙来，賢彥多逢迎。","魯連善談笑，季布折公卿。","遙知禮數絕，常恐不合幷。","惕想結宵梦，素心久已冥。","顧慙青云器，謬奉玉樽傾。","山陽五百年，綠竹忽再榮。","高歌振林木，大笑喧雷霆。","落笔灑篆文，崩云使人驚。","吐辞又炳煥，五色羅华星。","秀句满江国，高才掞天庭。","宰邑艱难时，浮云空古城。","居人若薙草，掃地無纖莖。","惠澤及飞走，農夫尽归耕。","廣漢水万里，长流玉琴声。","雅頌播吳越，還如泰階平。","小子別金陵，来时白下亭。","羣鳳怜客鸟，差池相哀鳴。","各拔五色毛，意重泰山轻。","贈微所費廣，斗水澆长鯨。","彈劒歌苦寒，嚴风起前楹。","月銜天门晓，霜落牛渚清。","长歎即归路，臨川空屏營。"]', '诗', 'shi', '', NULL, '獻從叔當塗宰陽冰 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56db3199-dc52-430b-974d-3a2b0bdbb8c6', '書懷贈南陵常贊府', '书懷贈南陵常贊府', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["歲星入漢年，方朔見明主。","調笑當時人，中天謝雲雨。","一去麒麟閣，遂將朝市乖。","故交不過門，秋草日上階。","當時何特達，獨與我心諧。","置酒凌歊臺，歡娛未曾歇。","歌動白紵山，舞迴天門月。","問我心中事，爲君前致辭。","君看我才能，何似魯仲尼。","大聖猶不遇，小儒安足悲。","雲南五月中，頻喪渡瀘師。","毒草殺漢馬，張兵奪雲旗。","至今西二河，流血擁僵屍。","將無七擒略，魯女惜園葵。","咸陽天下樞，累歲人不足。","雖有數斗玉，不如一盤粟。","賴得契宰衡，持釣慰風俗。","自顧無所用，辭家方來歸。","霜驚壯士髮，淚滿逐臣衣。","以此不安席，蹉跎身世違。","終當滅衛謗，不受魯人譏。"]', '["歲星入漢年，方朔见明主。","調笑當时人，中天謝云雨。","一去麒麟閣，遂將朝市乖。","故交不過门，秋草日上階。","當时何特達，独與我心諧。","置酒凌歊台，歡娛未曾歇。","歌动白紵山，舞迴天门月。","问我心中事，爲君前致辞。","君看我才能，何似魯仲尼。","大聖猶不遇，小儒安足悲。","云南五月中，頻喪渡瀘師。","毒草殺漢马，張兵奪云旗。","至今西二河，流血擁僵屍。","將無七擒略，魯女惜园葵。","咸陽天下樞，累歲人不足。","雖有數斗玉，不如一盤粟。","賴得契宰衡，持釣慰风俗。","自顧無所用，辞家方来归。","霜驚壯士髮，泪满逐臣衣。","以此不安席，蹉跎身世違。","終當滅衛謗，不受魯人譏。"]', '诗', 'shi', '', NULL, '書懷贈南陵常贊府 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1737db3-ddf4-4eae-9c91-c16c9a03e41e', '贈汪倫', '贈汪倫', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["李白乘舟將欲行，忽聞岸上踏歌聲。","桃花潭水深千尺，不及汪倫送我情。"]', '["李白乘舟將欲行，忽闻岸上踏歌声。","桃花潭水深千尺，不及汪倫送我情。"]', '诗', 'shi', '', NULL, '贈汪倫 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('064fe17e-fe88-4e01-a859-84adca604ebc', '安陸白兆山桃花嵒寄劉侍御綰', '安陸白兆山桃花嵒寄劉侍御綰', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["雲臥三十年，好閑復愛仙。","蓬壺雖冥絕，鸞鶴心悠然。","歸來桃花嵒，得憩雲窗眠。","對嶺人共語，飲潭猨相連。","時昇翠微上，邈若羅浮巔。","兩岑抱東壑，一嶂橫西天。","樹雜日易隱，崖傾月難圓。","芳草換野色，飛蘿搖春煙。","入遠構石室，選幽開上田。","獨此林下意，杳無區中緣。","永辭霜臺客，千載方來旋。"]', '["云臥三十年，好闲复愛仙。","蓬壺雖冥絕，鸾鹤心悠然。","归来桃花嵒，得憩云窗眠。","对嶺人共語，饮潭猨相連。","时昇翠微上，邈若羅浮巔。","兩岑抱东壑，一嶂橫西天。","樹杂日易隐，崖傾月难圓。","芳草換野色，飞蘿搖春煙。","入远構石室，選幽开上田。","独此林下意，杳無區中緣。","永辞霜台客，千載方来旋。"]', '诗', 'shi', '', NULL, '安陸白兆山桃花嵒寄劉侍御綰 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('419d1ec1-102a-4928-8fb9-2be4dc160d0c', '淮南臥病書懷寄蜀中趙徵君蕤', '淮南臥病书懷寄蜀中趙徵君蕤', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["吳會一浮雲，飄如遠行客。","功業莫從就，歲光屢奔迫。","良圖俄棄損，衰疾乃綿劇。","古琴藏虛匣，長劒挂空壁。","楚冠懷鍾儀，越吟比莊舃。","國門遙天外，鄉路遠山隔。","朝憶相如臺，夜夢子雲宅。","旅情初結緝，秋氣方寂歷。","風入松下清，露出草間白。","故人不可見，幽夢誰與適。","寄書西飛鴻，贈爾慰離析。"]', '["吳會一浮云，飄如远行客。","功業莫從就，歲光屢奔迫。","良圖俄棄損，衰疾乃綿劇。","古琴藏虛匣，长劒挂空壁。","楚冠懷鍾儀，越吟比莊舃。","国门遙天外，乡路远山隔。","朝憶相如台，夜梦子云宅。","旅情初結緝，秋氣方寂歷。","风入松下清，露出草间白。","故人不可见，幽梦誰與適。","寄书西飞鴻，贈爾慰離析。"]', '诗', 'shi', '', NULL, '淮南臥病書懷寄蜀中趙徵君蕤 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff5cf55e-bce2-4e08-b9a0-77987bedc39a', '寄弄月溪吳山人', '寄弄月溪吳山人', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["嘗聞龐德公，家住洞湖水。","終身棲鹿門，不入襄陽市。","夫君弄明月，滅景清淮裏。","高蹤邈難追，可與古人比。","清揚杳莫覩，白雲空望美。","待我辭人間，攜手訪松子。"]', '["嘗闻龐德公，家住洞湖水。","終身棲鹿门，不入襄陽市。","夫君弄明月，滅景清淮裏。","高蹤邈难追，可與古人比。","清揚杳莫覩，白云空望美。","待我辞人间，携手訪松子。"]', '诗', 'shi', '', NULL, '寄弄月溪吳山人 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfc85b07-5bc5-42cb-8544-0e76f6a15680', '秋山寄衛尉張卿及王徵君', '秋山寄衛尉張卿及王徵君', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["何以折相贈，白花青桂枝。","月華若夜雪，見此令人思。","雖然剡溪興，不異山陰時。","明發懷二子，空吟招隱詩。"]', '["何以折相贈，白花青桂枝。","月华若夜雪，见此令人思。","雖然剡溪兴，不異山陰时。","明發懷二子，空吟招隐诗。"]', '诗', 'shi', '', NULL, '秋山寄衛尉張卿及王徵君 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb48e420-6508-44b6-9861-ec7ae959b266', '望終南山寄紫閣隱者', '望終南山寄紫閣隐者', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["出門見南山，引領意無限。","秀色難爲名，蒼翠日在眼。","有時白雲起，天際自舒卷。","心中與之然，託興每不淺。","何當造幽人，滅跡棲絕巘。"]', '["出门见南山，引領意無限。","秀色难爲名，蒼翠日在眼。","有时白云起，天際自舒卷。","心中與之然，託兴每不淺。","何當造幽人，滅跡棲絕巘。"]', '诗', 'shi', '', NULL, '望終南山寄紫閣隱者 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c01d1d5f-d7ed-4eef-85a2-f22229f01293', '夕霽杜陵登樓寄韋繇', '夕霽杜陵登楼寄韋繇', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["浮陽滅霽景，萬物生秋容。","登樓送遠目，伏檻觀羣峰。","原野曠超緬，關河紛雜重。","清暉映竹日，翠色明雲松。","蹈海寄遐想，還山迷舊蹤。","徒然迫晚暮，未果諧心胷。","結桂空佇立，折麻恨莫從。","思君達永夜，長樂聞疎鐘。"]', '["浮陽滅霽景，万物生秋容。","登楼送远目，伏檻观羣峰。","原野曠超緬，关河紛杂重。","清暉映竹日，翠色明云松。","蹈海寄遐想，還山迷旧蹤。","徒然迫晚暮，未果諧心胷。","結桂空佇立，折麻恨莫從。","思君達永夜，长乐闻疎鐘。"]', '诗', 'shi', '', NULL, '夕霽杜陵登樓寄韋繇 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4925add5-c83c-4dce-b56c-5b7f47f25539', '秋夜宿龍門香山寺奉寄王方城十七丈奉國瑩上人從弟幼成令問', '秋夜宿龙门香山寺奉寄王方城十七丈奉国瑩上人從弟幼成令问', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["朝發汝海東，暮棲龍門中。","水寒夕波急，木落秋山空。","望極九霄迥，賞幽萬壑通。","目皓沙上月，心清松下風。","玉斗橫網戶，銀河耿花宮。","興在趣方逸，歡餘情未終。","鳳駕憶王子，虎溪懷遠公。","桂枝坐蕭瑟，棣華不復同。","流恨寄伊水，盈盈焉可窮。"]', '["朝發汝海东，暮棲龙门中。","水寒夕波急，木落秋山空。","望極九霄迥，賞幽万壑通。","目皓沙上月，心清松下风。","玉斗橫網戶，銀河耿花宮。","兴在趣方逸，歡餘情未終。","鳳駕憶王子，虎溪懷远公。","桂枝坐蕭瑟，棣华不复同。","流恨寄伊水，盈盈焉可窮。"]', '诗', 'shi', '', NULL, '秋夜宿龍門香山寺奉寄王方城十七丈奉國瑩上人從弟幼成令問 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a25fa0eb-d488-4fae-b528-820545fbb06a', '春日獨坐寄鄭明府', '春日独坐寄鄭明府', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["燕麥青青遊子悲，河堤弱柳鬱金枝。","長條一拂春風去，盡日飄揚無定時。","我在河南別離久，那堪坐此對窻牖。","情人道來竟不來，何人共醉新豐酒。"]', '["燕麦青青游子悲，河堤弱柳鬱金枝。","长條一拂春风去，尽日飄揚無定时。","我在河南別離久，那堪坐此对窻牖。","情人道来竟不来，何人共醉新豐酒。"]', '诗', 'shi', '', NULL, '春日獨坐寄鄭明府 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('298dce1e-06ee-40c7-8ba4-8880c4936ad8', '寄淮南友人', '寄淮南友人', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["紅顏悲舊國，青歲歇芳洲。","不待金門詔，空持寶劒遊。","海雲迷驛道，江月隱鄉樓。","復作淮南客，因逢桂樹留。"]', '["紅顏悲旧国，青歲歇芳洲。","不待金门詔，空持寶劒游。","海云迷驛道，江月隐乡楼。","复作淮南客，因逢桂樹留。"]', '诗', 'shi', '', NULL, '寄淮南友人 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceaabade-da26-45b9-adb0-9b5193b2c187', '沙丘城下寄杜甫', '沙丘城下寄杜甫', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我來竟何事，高臥沙丘城。","城邊有古樹，日夕連秋聲。","魯酒不可醉，齊歌空復情。","思君若汶水，浩蕩寄南征。"]', '["我来竟何事，高臥沙丘城。","城邊有古樹，日夕連秋声。","魯酒不可醉，齊歌空复情。","思君若汶水，浩蕩寄南征。"]', '诗', 'shi', '', NULL, '沙丘城下寄杜甫 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18447fa7-c2b3-4d8a-9327-d146752305f3', '聞丹丘子於城北營石門幽居中有高鳳遺跡僕離羣遠懷亦有棲遁之志因敘舊以寄之', '闻丹丘子於城北營石门幽居中有高鳳遺跡僕離羣远懷亦有棲遁之志因敘旧以寄之', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["春華滄江月，秋色碧海雲。","離居盈寒暑，對此長思君。","思君楚水南，望君淮山北。","夢魂雖飛來，會面不可得。","疇昔在嵩陽，同衾臥羲皇。","綠蘿笑簪紱，丹壑賤巖廊。","晚途各分析，乘興任所適。","僕在雁門關，君爲峨眉客。","心懸萬里外，影滯兩鄉隔。","長劒復歸來，相逢洛陽陌。","陌上何喧喧，都令心意煩。","迷津覺路失，託勢隨風飜。","以茲謝朝列，長嘯歸故園。","故園恣閑逸，求古散縹帙。","久欲入名山，婚娶殊未畢。","人生信多故，世事豈惟一。","念此憂如焚，悵然若有失。","聞君臥石門，宿昔契彌敦。","方從桂樹隱，不羨桃花源。","高風起遐曠，幽人跡復存。","松風清瑤瑟，溪月湛芳樽。","安居偶佳賞，丹心期此論。"]', '["春华滄江月，秋色碧海云。","離居盈寒暑，对此长思君。","思君楚水南，望君淮山北。","梦魂雖飞来，會面不可得。","疇昔在嵩陽，同衾臥羲皇。","綠蘿笑簪紱，丹壑賤巖廊。","晚途各分析，乘兴任所適。","僕在雁门关，君爲峨眉客。","心懸万里外，影滯兩乡隔。","长劒复归来，相逢洛陽陌。","陌上何喧喧，都令心意煩。","迷津覺路失，託勢隨风飜。","以茲謝朝列，长嘯归故园。","故园恣闲逸，求古散縹帙。","久欲入名山，婚娶殊未畢。","人生信多故，世事豈惟一。","念此憂如焚，悵然若有失。","闻君臥石门，宿昔契彌敦。","方從桂樹隐，不羨桃花源。","高风起遐曠，幽人跡复存。","松风清瑤瑟，溪月湛芳樽。","安居偶佳賞，丹心期此論。"]', '诗', 'shi', '', NULL, '聞丹丘子於城北營石門幽居中有高鳳遺跡僕離羣遠懷亦有棲遁之志因敘舊以寄之 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5223cc8b-73be-4823-95f5-77e7ab0a2e48', '淮陰書懷寄王宗成', '淮陰书懷寄王宗成', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["沙墩至梁苑，二十五長亭。","大舶夾雙艣，中流鵝鸛鳴。","雲天掃空碧，川嶽涵餘清。","飛鳧從西來，適與佳興幷。","眷言王喬舃，婉孌故人情。","復此親懿會，而增交道榮。","沿洄且不定，飄忽悵徂征。","暝投淮陰宿，欣得漂母迎。","斗酒烹黃雞，一餐感素誠。","予爲楚壯士，不是魯諸生。","有德必報之，千金恥爲輕。","緬書羇孤意，遠寄櫂歌聲。"]', '["沙墩至梁苑，二十五长亭。","大舶夾雙艣，中流鵝鸛鳴。","云天掃空碧，川嶽涵餘清。","飞鳧從西来，適與佳兴幷。","眷言王喬舃，婉孌故人情。","复此親懿會，而增交道榮。","沿洄且不定，飄忽悵徂征。","暝投淮陰宿，欣得漂母迎。","斗酒烹黄雞，一餐感素誠。","予爲楚壯士，不是魯諸生。","有德必報之，千金恥爲轻。","緬书羇孤意，远寄櫂歌声。"]', '诗', 'shi', '', NULL, '淮陰書懷寄王宗成 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('143d4c2b-89ef-4b8a-b6bd-462e0ee80571', '聞王昌齡左遷龍標遙有此寄', '闻王昌齡左遷龙標遙有此寄', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["楊花落盡子規啼，聞道龍標過五溪。","我寄愁心與明月，隨風直到夜郎西。"]', '["楊花落尽子規啼，闻道龙標過五溪。","我寄愁心與明月，隨风直到夜郎西。"]', '诗', 'shi', '', NULL, '聞王昌齡左遷龍標遙有此寄 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf5c6aa6-64e8-4d4d-b2d3-24904860d660', '寄王屋山人孟大融', '寄王屋山人孟大融', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我昔東海上，勞山餐紫霞。","親見安期公，食棗大如瓜。","中年謁漢主，不愜還歸家。","朱顏謝春輝，白髮見生涯。","所期就金液，飛步登雲車。","願隨夫子天壇上，閑與仙人掃落花。"]', '["我昔东海上，勞山餐紫霞。","親见安期公，食棗大如瓜。","中年謁漢主，不愜還归家。","朱顏謝春輝，白髮见生涯。","所期就金液，飞步登云车。","願隨夫子天壇上，闲與仙人掃落花。"]', '诗', 'shi', '', NULL, '寄王屋山人孟大融 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd2d4808-fd20-4f70-816d-1fcde61bf1b5', '憶舊遊寄譙郡元參軍', '憶旧游寄譙郡元參軍', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["憶昔洛陽董糟丘，爲余天津橋南造酒樓。","黃金白璧買歌笑，一醉累月輕王侯。","海內賢豪青雲客，就中與君心莫逆。","迥山轉海不作難，傾情倒意無所惜。","我向淮南攀桂枝，君留洛北愁夢思。","不忍別，還相隨，相隨迢迢訪仙城。","三十六曲水迴縈，一溪初入千花明。","萬壑度盡松風聲，銀鞍金絡倒平地，漢東太守來相迎。","紫陽之真人，邀我吹玉笙。","餐霞樓上動仙樂，嘈然宛似鸞鳳鳴。","袖長管催欲輕舉，漢中太守醉起舞。","手持錦袍覆我身，我醉橫眠枕其股。","當筵意氣凌九霄，星離雨散不終朝，分飛楚關山水遙。","余既還山尋故巢，君亦歸家渡渭橋。","君家嚴君勇貔虎，作尹幷州遏戎虜。","五月相呼度太行，摧輪不道羊腸苦。","行來北涼歲月深，感君貴義輕黃金。","瓊杯綺食青玉案，使我醉飽無歸心。","時時出向城西曲，晉祠流水如碧玉。","浮舟弄水簫鼓鳴，微波龍鱗莎草綠。","興來攜妓恣經過，其若楊花似雪何。","紅粧欲醉宜斜日，百尺清潭寫翠娥。","翠娥嬋娟初月輝，美人更唱舞羅衣。","清風吹歌人空去，歌曲自繞行雲飛。","此時行樂難再遇，西遊因獻長楊賦。","北闕青雲不可期，東山白首還歸去。","渭橋南頭一遇君，酇臺之北又離羣。","問余別恨知多少，落花春暮爭紛紛。","言亦不可盡，情亦不可極。","呼兒長跪緘此辭，寄君千里遙相憶。"]', '["憶昔洛陽董糟丘，爲余天津橋南造酒楼。","黄金白璧買歌笑，一醉累月轻王侯。","海內賢豪青云客，就中與君心莫逆。","迥山轉海不作难，傾情倒意無所惜。","我向淮南攀桂枝，君留洛北愁梦思。","不忍別，還相隨，相隨迢迢訪仙城。","三十六曲水迴縈，一溪初入千花明。","万壑度尽松风声，銀鞍金絡倒平地，漢东太守来相迎。","紫陽之真人，邀我吹玉笙。","餐霞楼上动仙乐，嘈然宛似鸾鳳鳴。","袖长管催欲轻舉，漢中太守醉起舞。","手持錦袍覆我身，我醉橫眠枕其股。","當筵意氣凌九霄，星離雨散不終朝，分飞楚关山水遙。","余既還山尋故巢，君亦归家渡渭橋。","君家嚴君勇貔虎，作尹幷州遏戎虜。","五月相呼度太行，摧輪不道羊腸苦。","行来北涼歲月深，感君貴義轻黄金。","瓊杯綺食青玉案，使我醉飽無归心。","时时出向城西曲，晉祠流水如碧玉。","浮舟弄水簫鼓鳴，微波龙鱗莎草綠。","兴来携妓恣經過，其若楊花似雪何。","紅粧欲醉宜斜日，百尺清潭寫翠娥。","翠娥嬋娟初月輝，美人更唱舞羅衣。","清风吹歌人空去，歌曲自繞行云飞。","此时行乐难再遇，西游因獻长楊賦。","北闕青云不可期，东山白首還归去。","渭橋南头一遇君，酇台之北又離羣。","问余別恨知多少，落花春暮爭紛紛。","言亦不可尽，情亦不可極。","呼兒长跪緘此辞，寄君千里遙相憶。"]', '诗', 'shi', '', NULL, '憶舊遊寄譙郡元參軍 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a0533d8-6508-48ab-9cfa-384bd1308de1', '月夜江行寄崔員外宗之', '月夜江行寄崔員外宗之', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["飄飄江風起，蕭颯海樹秋。","登艫美清夜，挂席移輕舟。","月隨碧山轉，水合青天流。","杳如星河上，但覺雲林幽。","歸路方浩浩，徂川去悠悠。","徒悲蕙草歇，復聽菱歌愁。","岸曲迷後浦，沙明瞰前洲。","懷君不可見，望遠增離憂。"]', '["飄飄江风起，蕭颯海樹秋。","登艫美清夜，挂席移轻舟。","月隨碧山轉，水合青天流。","杳如星河上，但覺云林幽。","归路方浩浩，徂川去悠悠。","徒悲蕙草歇，复听菱歌愁。","岸曲迷後浦，沙明瞰前洲。","懷君不可见，望远增離憂。"]', '诗', 'shi', '', NULL, '月夜江行寄崔員外宗之 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fde2b52d-15c3-4d98-98bf-7e4af7853ede', '宿白鷺洲寄楊江寧', '宿白鷺洲寄楊江寧', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["朝別朱雀門，暮棲白鷺洲。","波光搖海月，星影入城樓。","望美金陵宰，如思瓊樹憂。","徒令魂入夢，飜覺夜成秋。","綠水解人意，爲余西北流。","因聲玉琴裏，蕩漾寄君愁。"]', '["朝別朱雀门，暮棲白鷺洲。","波光搖海月，星影入城楼。","望美金陵宰，如思瓊樹憂。","徒令魂入梦，飜覺夜成秋。","綠水解人意，爲余西北流。","因声玉琴裏，蕩漾寄君愁。"]', '诗', 'shi', '', NULL, '宿白鷺洲寄楊江寧 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('991e28f2-1ddb-4e26-9733-2bba76386fdd', '新林浦阻風寄友人', '新林浦阻风寄友人', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["潮水定可信，天風難與期。","清晨西北轉，薄暮東南吹。","以此難挂席，佳期益相思。","海月破圓影，菰蔣生綠池。","昨日北湖梅，開花已滿枝。","今朝東門柳，夾道垂青絲。","歲物忽如此，我來定幾時。","紛紛江上雪，草草客中悲。","明發新林浦，空吟謝朓詩。"]', '["潮水定可信，天风难與期。","清晨西北轉，薄暮东南吹。","以此难挂席，佳期益相思。","海月破圓影，菰蔣生綠池。","昨日北湖梅，开花已满枝。","今朝东门柳，夾道垂青絲。","歲物忽如此，我来定幾时。","紛紛江上雪，草草客中悲。","明發新林浦，空吟謝朓诗。"]', '诗', 'shi', '', NULL, '新林浦阻風寄友人 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7850fc8-4941-4c5e-b282-2853bbe3e70d', '寄韋南陵冰余江上乘興訪之遇尋顏尚書笑有此贈', '寄韋南陵冰余江上乘兴訪之遇尋顏尚书笑有此贈', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["南船正東風，北船來自緩。","江上相逢借問君，語笑未了風吹斷。","聞君攜伎訪情人，應爲尚書不顧身。","堂上三千珠履客，甕中百斛金陵春。","恨我阻此樂，淹留楚江濱。","月色醉遠客，山花開欲然。","春風狂殺人，一日劇三年。","乘興嫌太遲，焚却子猷船。","夢見五柳枝，已堪挂馬鞭。","何日到彭澤，長歌陶令前。"]', '["南船正东风，北船来自緩。","江上相逢借问君，語笑未了风吹斷。","闻君携伎訪情人，應爲尚书不顧身。","堂上三千珠履客，甕中百斛金陵春。","恨我阻此乐，淹留楚江濱。","月色醉远客，山花开欲然。","春风狂殺人，一日劇三年。","乘兴嫌太遲，焚却子猷船。","梦见五柳枝，已堪挂马鞭。","何日到彭澤，长歌陶令前。"]', '诗', 'shi', '', NULL, '寄韋南陵冰余江上乘興訪之遇尋顏尚書笑有此贈 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cf2626d-5277-4bc9-afb5-6d0d2562cdad', '題情深樹寄象公', '題情深樹寄象公', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["腸斷枝上猨，淚添山下樽。","白雲見我去，亦爲我飛翻。"]', '["腸斷枝上猨，泪添山下樽。","白云见我去，亦爲我飞翻。"]', '诗', 'shi', '', NULL, '題情深樹寄象公 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('370f0a3c-5b12-4cc8-a40e-697fb9c5590e', '北山獨酌寄韋六', '北山独酌寄韋六', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["巢父將許由，未聞買山隱。","道存跡自高，何憚去人近。","紛吾下茲嶺，地閑喧亦泯。","門橫羣岫開，水鑿衆泉引。","屏高而在雲，竇深莫能準。","川光晝昏凝，林氣夕淒緊。","於焉摘朱果，兼得養玄牝。","坐月觀寶書，拂霜弄瑤軫。","傾壺事幽酌，顧影還獨盡。","念君風塵游，傲爾令自哂。"]', '["巢父將許由，未闻買山隐。","道存跡自高，何憚去人近。","紛吾下茲嶺，地闲喧亦泯。","门橫羣岫开，水鑿衆泉引。","屏高而在云，竇深莫能準。","川光晝昏凝，林氣夕淒緊。","於焉摘朱果，兼得養玄牝。","坐月观寶书，拂霜弄瑤軫。","傾壺事幽酌，顧影還独尽。","念君风塵游，傲爾令自哂。"]', '诗', 'shi', '', NULL, '北山獨酌寄韋六 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a33174f-965c-4636-8f9b-8fb94b858c0f', '寄當塗趙少府炎', '寄當塗趙少府炎', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["晚登高樓望，木落雙江清。","寒山饒積翠，秀色連州城。","目送楚雲盡，心悲胡雁聲。","相思不可見，迴首故人情。"]', '["晚登高楼望，木落雙江清。","寒山饒積翠，秀色連州城。","目送楚云尽，心悲胡雁声。","相思不可见，迴首故人情。"]', '诗', 'shi', '', NULL, '寄當塗趙少府炎 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3638c98b-8b8e-4847-a0b9-9c54e2ce6e5e', '寄東魯二稚子', '寄东魯二稚子', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["吳地桑葉綠，吳蠶已三眠。","我家寄東魯，誰種龜陰田。","春事已不及，江行復茫然。","南風吹歸心，飛墮酒樓前。","樓東一株桃，枝葉拂青煙。","此樹我所種，別來向三年。","桃今與樓齊，我行尚未旋。","嬌女字平陽，折花倚桃邊。","折花不見我，淚下如流泉。","小兒名伯禽，與姊亦齊肩。","雙行桃樹下，撫背復誰憐。","念此失次第，肝腸日憂煎。","裂素寫遠意，因之汶陽川。"]', '["吳地桑葉綠，吳蠶已三眠。","我家寄东魯，誰種龟陰田。","春事已不及，江行复茫然。","南风吹归心，飞墮酒楼前。","楼东一株桃，枝葉拂青煙。","此樹我所種，別来向三年。","桃今與楼齊，我行尚未旋。","嬌女字平陽，折花倚桃邊。","折花不见我，泪下如流泉。","小兒名伯禽，與姊亦齊肩。","雙行桃樹下，撫背复誰怜。","念此失次第，肝腸日憂煎。","裂素寫远意，因之汶陽川。"]', '诗', 'shi', '', NULL, '寄東魯二稚子 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08e81f11-6bc9-4416-bf6e-55d770d4fb92', '獨酌清溪江石上寄權昭夷', '独酌清溪江石上寄權昭夷', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我攜一樽酒，獨上江祖石。","自從天地開，更長幾千尺。","舉杯向天笑，天迴日西照。","永願坐此石，長垂嚴陵釣。","寄謝山中人，可與爾同調。"]', '["我携一樽酒，独上江祖石。","自從天地开，更长幾千尺。","舉杯向天笑，天迴日西照。","永願坐此石，长垂嚴陵釣。","寄謝山中人，可與爾同調。"]', '诗', 'shi', '', NULL, '獨酌清溪江石上寄權昭夷 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbabd3ac-79d7-4c55-a602-0ef317bea2f9', '禪房懷友人岑倫', '禪房懷友人岑倫', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["嬋娟羅浮月，搖豔桂水雲。","美人竟獨往，而我安得羣。","一朝語笑隔，萬里懽情分。","沈吟綵霞沒，夢寐羣芳歇。","歸鴻渡三湘，遊子在百粵。","邊塵染衣劒，白日彫華髮。","春風變楚關，秋聲落吳山。","草木結悲緒，風沙淒苦顏。","朅來已永久，頹思如循環。","飄飄限江裔，想像空留滯。","離憂每醉心，別淚徒盈袂。","坐愁青天末，出望黃雲蔽。","目極何悠悠，梅花南嶺頭。","空長滅征鳥，水闊無還舟。","寶劒終難託，金囊非易求。","歸來儻有問，桂樹山之幽。"]', '["嬋娟羅浮月，搖豔桂水云。","美人竟独往，而我安得羣。","一朝語笑隔，万里懽情分。","沈吟綵霞沒，梦寐羣芳歇。","归鴻渡三湘，游子在百粵。","邊塵染衣劒，白日彫华髮。","春风变楚关，秋声落吳山。","草木結悲緒，风沙淒苦顏。","朅来已永久，頹思如循环。","飄飄限江裔，想像空留滯。","離憂每醉心，別泪徒盈袂。","坐愁青天末，出望黄云蔽。","目極何悠悠，梅花南嶺头。","空长滅征鸟，水闊無還舟。","寶劒終难託，金囊非易求。","归来儻有问，桂樹山之幽。"]', '诗', 'shi', '', NULL, '禪房懷友人岑倫 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e491c2f-c3c8-487f-8e76-63bd0a811b30', '廬山謠寄盧侍御虛舟', '廬山謠寄盧侍御虛舟', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我本楚狂人，鳳歌笑孔丘。","手持綠玉杖，朝別黃鶴樓。","五嶽尋仙不辭遠，一生好入名山遊。","廬山秀出南斗傍，屏風九疊雲錦張，影落明湖青黛光。","金闕前開二峰長，銀河倒挂三石梁。","香爐瀑布遙相望，迴厓沓嶂凌蒼蒼。","翠影紅霞映朝日，鳥飛不到吳天長。","登高壯觀天地間，大江茫茫去不還。","黃雲萬里動風色，白波九道流雪山。","好爲廬山謠，興因廬山發。","閑窺石鏡清我心，謝公行處蒼苔沒。","早服還丹無世情，琴心三疊道初成。","遙見仙人綵雲裏，手把芙蓉朝玉京。","先期汗漫九垓上，願接盧敖遊太清。"]', '["我本楚狂人，鳳歌笑孔丘。","手持綠玉杖，朝別黄鹤楼。","五嶽尋仙不辞远，一生好入名山游。","廬山秀出南斗傍，屏风九叠云錦張，影落明湖青黛光。","金闕前开二峰长，銀河倒挂三石梁。","香爐瀑布遙相望，迴厓沓嶂凌蒼蒼。","翠影紅霞映朝日，鸟飞不到吳天长。","登高壯观天地间，大江茫茫去不還。","黄云万里动风色，白波九道流雪山。","好爲廬山謠，兴因廬山發。","闲窺石镜清我心，謝公行处蒼苔沒。","早服還丹無世情，琴心三叠道初成。","遙见仙人綵云裏，手把芙蓉朝玉京。","先期汗漫九垓上，願接盧敖游太清。"]', '诗', 'shi', '', NULL, '廬山謠寄盧侍御虛舟 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b191e602-b7d6-4eae-b9b4-600affd2a481', '下尋陽城汎彭蠡寄黃判官', '下尋陽城汎彭蠡寄黄判官', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["浪動灌嬰井，尋陽江上風。","開帆入天鏡，直向彭湖東。","落景轉疎雨，晴雲散遠空。","名山發佳興，清賞亦何窮。","石鏡挂遙月，香爐滅彩虹。","相思俱對此，舉目與君同。"]', '["浪动灌嬰井，尋陽江上风。","开帆入天镜，直向彭湖东。","落景轉疎雨，晴云散远空。","名山發佳兴，清賞亦何窮。","石镜挂遙月，香爐滅彩虹。","相思俱对此，舉目與君同。"]', '诗', 'shi', '', NULL, '下尋陽城汎彭蠡寄黃判官 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90cb58db-fcab-454d-b5fe-178e6d5b4ff6', '書情寄從弟邠州長史昭', '书情寄從弟邠州长史昭', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["自笑客行久，我行定幾時。","綠楊已可折，攀取最長枝。","翩翩弄春色，延佇寄相思。","誰言貴此物，意願重瓊蕤。","昨夢見惠連，朝吟謝公詩。","東風引碧草，不覺生華池。","臨翫忽云夕，杜鵑夜鳴悲。","懷君芳歲歇，庭樹落紅滋。"]', '["自笑客行久，我行定幾时。","綠楊已可折，攀取最长枝。","翩翩弄春色，延佇寄相思。","誰言貴此物，意願重瓊蕤。","昨梦见惠連，朝吟謝公诗。","东风引碧草，不覺生华池。","臨翫忽云夕，杜鵑夜鳴悲。","懷君芳歲歇，庭樹落紅滋。"]', '诗', 'shi', '', NULL, '書情寄從弟邠州長史昭 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64b4d54f-cfac-4f5c-bdfa-60063975a47f', '寄王漢陽', '寄王漢陽', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["南湖秋月白，王宰夜相邀。","錦帳郎官醉，羅衣舞女嬌。","笛聲喧沔鄂，歌曲上雲霄。","別後空愁我，相思一水遙。"]', '["南湖秋月白，王宰夜相邀。","錦帳郎官醉，羅衣舞女嬌。","笛声喧沔鄂，歌曲上云霄。","別後空愁我，相思一水遙。"]', '诗', 'shi', '', NULL, '寄王漢陽 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b3e2250-6bfc-4ade-b89c-f3df7c622586', '春日歸山寄孟浩然', '春日归山寄孟浩然', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["朱紱遺塵境，青山謁梵筵。","金繩開覺路，寶筏度迷川。","嶺樹攢飛栱，嵒花覆谷泉。","墖形標海月，樓勢出江煙。","香氣三天下，鐘聲萬壑連。","荷秋珠已滿，松密蓋初圓。","鳥聚疑聞法，龍參若護禪。","媿非流水韻，叨入伯牙弦。"]', '["朱紱遺塵境，青山謁梵筵。","金繩开覺路，寶筏度迷川。","嶺樹攢飞栱，嵒花覆谷泉。","墖形標海月，楼勢出江煙。","香氣三天下，鐘声万壑連。","荷秋珠已满，松密蓋初圓。","鸟聚疑闻法，龙參若護禪。","媿非流水韻，叨入伯牙弦。"]', '诗', 'shi', '', NULL, '春日歸山寄孟浩然 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7269d2d6-e426-4083-8869-2a12dedf9f95', '流夜郎永華寺寄尋陽羣官', '流夜郎永华寺寄尋陽羣官', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["朝別凌煙樓，賢豪滿行舟。","暝投永華寺，賓散予獨醉。","願結九江流，添成萬行淚。","寫意寄廬嶽，何當來此地。","天命有所懸，安得苦愁思。"]', '["朝別凌煙楼，賢豪满行舟。","暝投永华寺，賓散予独醉。","願結九江流，添成万行泪。","寫意寄廬嶽，何當来此地。","天命有所懸，安得苦愁思。"]', '诗', 'shi', '', NULL, '流夜郎永華寺寄尋陽羣官 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e3ca5d2-67e8-4fc9-9294-350c16699678', '流夜郎至西塞驛寄裴隱', '流夜郎至西塞驛寄裴隐', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["揚帆借天風，水驛苦不緩。","平明及西塞，已先投沙伴。","迴巒引羣峰，橫蹙楚山斷。","砯衝萬壑會，震沓百川滿。","龍怪潛溟波，俟時救炎旱。","我行望雷雨，安得霑枯散。","鳥去天路長，人愁春光短。","空將澤畔吟，寄爾江南管。"]', '["揚帆借天风，水驛苦不緩。","平明及西塞，已先投沙伴。","迴巒引羣峰，橫蹙楚山斷。","砯衝万壑會，震沓百川满。","龙怪潛溟波，俟时救炎旱。","我行望雷雨，安得霑枯散。","鸟去天路长，人愁春光短。","空將澤畔吟，寄爾江南管。"]', '诗', 'shi', '', NULL, '流夜郎至西塞驛寄裴隱 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf60c55c-69c4-45e8-a07c-a13a39619aa3', '自漢陽病酒歸寄王明府', '自漢陽病酒归寄王明府', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["去歲左遷夜郎道，琉璃硯水長枯槁。","今年敕放巫山陽，蛟龍筆翰生輝光。","聖主還聽子虛賦，相如却與論文章。","願掃鸚鵡洲，與君醉百場。","嘯起白雲飛七澤，歌吟淥水動三湘。","莫惜連船沽美酒，千金一擲買春芳。"]', '["去歲左遷夜郎道，琉璃硯水长枯槁。","今年敕放巫山陽，蛟龙笔翰生輝光。","聖主還听子虛賦，相如却與論文章。","願掃鸚鵡洲，與君醉百場。","嘯起白云飞七澤，歌吟淥水动三湘。","莫惜連船沽美酒，千金一擲買春芳。"]', '诗', 'shi', '', NULL, '自漢陽病酒歸寄王明府 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be77ebcd-07a2-48f3-8ac9-8290a154dbe6', '望漢陽柳色寄王宰', '望漢陽柳色寄王宰', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["漢陽江上柳，望客引東枝。","樹樹花如雪，紛紛亂若絲。","春風傳我意，草木別前知。","寄謝弦歌宰，西來定未遲。"]', '["漢陽江上柳，望客引东枝。","樹樹花如雪，紛紛亂若絲。","春风傳我意，草木別前知。","寄謝弦歌宰，西来定未遲。"]', '诗', 'shi', '', NULL, '望漢陽柳色寄王宰 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7a8ab10-7d41-4091-9f86-0e4b3bde6196', '江夏寄漢陽輔錄事', '江夏寄漢陽輔錄事', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["誰道此水廣，狹如一匹練。","江夏黃鶴樓，青山漢陽縣。","大語猶可聞，故人難可見。","君草陳琳檄，我書魯連箭。","報國有壯心，龍顏不迴眷。","西飛精衛鳥，東海何由填。","鼓角徒悲鳴，樓船習征戰。","抽劒步霜月，夜行空庭徧。","長呼結浮雲，埋沒顧榮扇。","他日觀軍容，投壺接高宴。"]', '["誰道此水廣，狹如一匹練。","江夏黄鹤楼，青山漢陽縣。","大語猶可闻，故人难可见。","君草陳琳檄，我书魯連箭。","報国有壯心，龙顏不迴眷。","西飞精衛鸟，东海何由填。","鼓角徒悲鳴，楼船習征戰。","抽劒步霜月，夜行空庭徧。","长呼結浮云，埋沒顧榮扇。","他日观軍容，投壺接高宴。"]', '诗', 'shi', '', NULL, '江夏寄漢陽輔錄事 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('423c1905-c138-41b5-8eb8-33a6a41171f3', '早春寄王漢陽', '早春寄王漢陽', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["聞道春還未相識，走傍寒梅訪消息。","昨夜東風入武陽，陌頭楊柳黃金色。","碧水浩浩雲茫茫，美人不來空斷腸。","預拂青山一片石，與君連日醉壺觴。"]', '["闻道春還未相識，走傍寒梅訪消息。","昨夜东风入武陽，陌头楊柳黄金色。","碧水浩浩云茫茫，美人不来空斷腸。","預拂青山一片石，與君連日醉壺觴。"]', '诗', 'shi', '', NULL, '早春寄王漢陽 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c88243f-1960-4e49-895d-0e2398b973e6', '江上寄巴東故人', '江上寄巴东故人', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["漢水波浪遠，巫山雲雨飛。","東風吹客夢，西落此中時。","覺後思白帝，佳人與我違。","瞿塘饒賈客，音信莫令稀。"]', '["漢水波浪远，巫山云雨飞。","东风吹客梦，西落此中时。","覺後思白帝，佳人與我違。","瞿塘饒賈客，音信莫令稀。"]', '诗', 'shi', '', NULL, '江上寄巴東故人 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3496ba9e-7d59-4027-b052-887c6f54825f', '江上寄元六林宗', '江上寄元六林宗', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["霜落江始寒，楓葉綠未脫。","客行悲清秋，永路苦不達。","滄波眇川汜，白日隱天末。","停櫂依林巒，驚猿相呌聒。","夜分河漢轉，起視溟漲闊。","涼風何蕭蕭，流水鳴活活。","浦沙淨如洗，海月明可掇。","蘭交空懷思，瓊樹詎解渴。","勗哉滄洲心，歲晚庶不奪。","幽賞頗自得，興遠與誰豁。"]', '["霜落江始寒，楓葉綠未脫。","客行悲清秋，永路苦不達。","滄波眇川汜，白日隐天末。","停櫂依林巒，驚猿相呌聒。","夜分河漢轉，起視溟漲闊。","涼风何蕭蕭，流水鳴活活。","浦沙淨如洗，海月明可掇。","蘭交空懷思，瓊樹詎解渴。","勗哉滄洲心，歲晚庶不奪。","幽賞頗自得，兴远與誰豁。"]', '诗', 'shi', '', NULL, '江上寄元六林宗 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff73ae4f-014f-4779-9c70-abf1a7614dd8', '寄從弟宣州長史昭', '寄從弟宣州长史昭', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["爾佐宣州郡，守官清且閑。","常誇雲月好，邀我敬亭山。","五落洞庭葉，三江遊未還。","相思不可見，歎息損朱顏。"]', '["爾佐宣州郡，守官清且闲。","常誇云月好，邀我敬亭山。","五落洞庭葉，三江游未還。","相思不可见，歎息損朱顏。"]', '诗', 'shi', '', NULL, '寄從弟宣州長史昭 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c172189d-9be5-467f-a258-3e15ca56c884', '涇溪東亭寄鄭少府諤', '涇溪东亭寄鄭少府諤', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我遊東亭不見君，沙上行將白鷺羣。","白鷺行時散飛去，又如雪點青山雲。","欲往涇溪不辭遠，龍門蹙波虎眼轉。","杜鵑花開春已闌，歸向陵陽釣魚晚。"]', '["我游东亭不见君，沙上行將白鷺羣。","白鷺行时散飞去，又如雪点青山云。","欲往涇溪不辞远，龙门蹙波虎眼轉。","杜鵑花开春已闌，归向陵陽釣鱼晚。"]', '诗', 'shi', '', NULL, '涇溪東亭寄鄭少府諤 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30994057-c0f7-4839-aff6-4d912a65e415', '宣州九日聞崔四侍御與宇文太守遊敬亭余時登響山不同此賞醉後寄崔侍御二首 一', '宣州九日闻崔四侍御與宇文太守游敬亭余时登响山不同此賞醉後寄崔侍御二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["九日茱萸熟，插鬢傷早白。","登高望山海，滿目悲古昔。","遠訪投沙人，因爲逃名客。","故交竟誰在，獨有崔亭伯。","重陽不相知，載酒任所適。","手持一枝菊，調笑二千石。","日暮岸幘歸，傳呼隘阡陌。","彤襜雙白鹿，賓從何輝赫。","夫子在其間，遂成雲霄隔。","良辰與美景，兩地方虛擲。","晚從南峰歸，蘿月下水壁。","却登郡樓望，松色寒轉碧。","咫尺不可親，棄我如遺舃。"]', '["九日茱萸熟，插鬢傷早白。","登高望山海，满目悲古昔。","远訪投沙人，因爲逃名客。","故交竟誰在，独有崔亭伯。","重陽不相知，載酒任所適。","手持一枝菊，調笑二千石。","日暮岸幘归，傳呼隘阡陌。","彤襜雙白鹿，賓從何輝赫。","夫子在其间，遂成云霄隔。","良辰與美景，兩地方虛擲。","晚從南峰归，蘿月下水壁。","却登郡楼望，松色寒轉碧。","咫尺不可親，棄我如遺舃。"]', '诗', 'shi', '', NULL, '宣州九日聞崔四侍御與宇文太守遊敬亭余時登響山不同此賞醉後寄崔侍御二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d086ca66-0649-4b3b-9349-c5ce12825d78', '宣州九日聞崔四侍御與宇文太守遊敬亭余時登響山不同此賞醉後寄崔侍御二首 二', '宣州九日闻崔四侍御與宇文太守游敬亭余时登响山不同此賞醉後寄崔侍御二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["九卿天上落，五馬道傍來。","列戟朱門曉，褰幃碧嶂開。","登高望遠海，召客得英才。","紫綬懽情洽，黃花逸興催。","山從圖上見，溪即鏡中迴。","遙羨重陽作，應過戲馬臺。"]', '["九卿天上落，五马道傍来。","列戟朱门晓，褰幃碧嶂开。","登高望远海，召客得英才。","紫綬懽情洽，黄花逸兴催。","山從圖上见，溪即镜中迴。","遙羨重陽作，應過戲马台。"]', '诗', 'shi', '', NULL, '宣州九日聞崔四侍御與宇文太守遊敬亭余時登響山不同此賞醉後寄崔侍御二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa6cab85-4f83-4345-af8a-7ffeb0447ae9', '寄崔侍御', '寄崔侍御', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["宛溪霜夜聽猿愁，去國長爲不繫舟。","獨憐一雁飛南海，却羨雙溪解北流。","高人屢解陳蕃榻，過客難登謝朓樓。","此處別離同落葉，朝朝分散敬亭秋。"]', '["宛溪霜夜听猿愁，去国长爲不繫舟。","独怜一雁飞南海，却羨雙溪解北流。","高人屢解陳蕃榻，過客难登謝朓楼。","此处別離同落葉，朝朝分散敬亭秋。"]', '诗', 'shi', '', NULL, '寄崔侍御 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('107b5580-f95e-4803-865c-5b6c6e25c90a', '涇溪南藍山下有落星潭可以卜築余泊舟石上寄何判官昌浩', '涇溪南藍山下有落星潭可以卜築余泊舟石上寄何判官昌浩', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["藍岑竦天壁，突兀如鯨額。","奔蹙橫澄潭，勢吞落星石。","沙帶秋月明，水搖寒山碧。","佳鏡宜緩櫂，清輝能留客。","恨君阻歡遊，使我自驚惕。","所期俱卜築，結茅鍊金液。"]', '["藍岑竦天壁，突兀如鯨額。","奔蹙橫澄潭，勢吞落星石。","沙带秋月明，水搖寒山碧。","佳镜宜緩櫂，清輝能留客。","恨君阻歡游，使我自驚惕。","所期俱卜築，結茅鍊金液。"]', '诗', 'shi', '', NULL, '涇溪南藍山下有落星潭可以卜築余泊舟石上寄何判官昌浩 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c270f72-0b5b-47b2-a940-9084b117c9c1', '早過漆林渡寄萬巨', '早過漆林渡寄万巨', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["西經大藍山，南來漆林渡。","水色倒空青，林煙橫積素。","漏流昔吞翕，沓浪競奔注。","潭落天上星，龍開水中霧。","嶢巖注公柵，突兀陳焦墓。","嶺峭紛上干，川明屢迴顧。","因思萬夫子，解渴同瓊樹。","何日覩清光，相歡詠佳句。"]', '["西經大藍山，南来漆林渡。","水色倒空青，林煙橫積素。","漏流昔吞翕，沓浪競奔注。","潭落天上星，龙开水中霧。","嶢巖注公柵，突兀陳焦墓。","嶺峭紛上干，川明屢迴顧。","因思万夫子，解渴同瓊樹。","何日覩清光，相歡詠佳句。"]', '诗', 'shi', '', NULL, '早過漆林渡寄萬巨 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('005b52e9-ee73-494b-b318-734b7278bd8a', '遊敬亭寄崔侍御', '游敬亭寄崔侍御', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我家敬亭下，輙繼謝公作。","相去數百年，風期宛如昨。","登高素秋月，下望青山郭。","俯視鴛鴦羣，飲啄自鳴躍。","夫子雖蹭蹬，瑤臺雪中鶴。","獨立窺浮雲，其心在寥廓。","時來顧我笑，一飯葵與藿。","世路如秋風，相逢盡蕭索。","腰間玉具劒，意許無遺諾。","壯士不可輕，相期在雲閣。"]', '["我家敬亭下，輙繼謝公作。","相去數百年，风期宛如昨。","登高素秋月，下望青山郭。","俯視鴛鴦羣，饮啄自鳴躍。","夫子雖蹭蹬，瑤台雪中鹤。","独立窺浮云，其心在寥廓。","时来顧我笑，一飯葵與藿。","世路如秋风，相逢尽蕭索。","腰间玉具劒，意許無遺諾。","壯士不可轻，相期在云閣。"]', '诗', 'shi', '', NULL, '遊敬亭寄崔侍御 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7ee6c92-bb81-420a-bd3a-d9b9392ee2d5', '三山望金陵寄殷淑', '三山望金陵寄殷淑', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["三山懷謝朓，水澹望長安。","蕪沒河陽縣，秋江正北看。","盧龍霜氣冷，鳷鵲月光寒。","耿耿憶瓊樹，天涯寄一懽。"]', '["三山懷謝朓，水澹望长安。","蕪沒河陽縣，秋江正北看。","盧龙霜氣冷，鳷鵲月光寒。","耿耿憶瓊樹，天涯寄一懽。"]', '诗', 'shi', '', NULL, '三山望金陵寄殷淑 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('330102f7-2088-43aa-b5b3-573c1e00688d', '自金陵泝流過白璧山翫月達天門寄句容王主簿', '自金陵泝流過白璧山翫月達天门寄句容王主簿', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["滄江泝流歸，白璧見秋月。","秋月照白璧，皓如山陰雪。","幽人停宵征，賈客忘早發。","進帆天門山，迴首牛渚沒。","川長信風來，日出宿霧歇。","故人在咫尺，新賞成胡越。","寄君青蘭花，惠好庶不絕。"]', '["滄江泝流归，白璧见秋月。","秋月照白璧，皓如山陰雪。","幽人停宵征，賈客忘早發。","進帆天门山，迴首牛渚沒。","川长信风来，日出宿霧歇。","故人在咫尺，新賞成胡越。","寄君青蘭花，惠好庶不絕。"]', '诗', 'shi', '', NULL, '自金陵泝流過白璧山翫月達天門寄句容王主簿 李白 shi');
